  function normalizeSourceSha256(value) {
    const token = String(value || "").trim().toUpperCase();
    return /^[0-9A-F]{64}$/.test(token) ? token : null;
  }

  function isCurrentImportRequestSequence(requestSequence, currentSequence = importSequence) {
    if (requestSequence === null || requestSequence === undefined || requestSequence === "") return true;
    const normalized = Number(requestSequence);
    return Number.isInteger(normalized) && normalized === Number(currentSequence);
  }

  function getSourceBoundProjectItems(currentProject) {
    const review = isPlainObject(currentProject?.pdfReviewObjects) ? currentProject.pdfReviewObjects : {};
    return []
      .concat(Array.isArray(currentProject?.walls) ? currentProject.walls : [])
      .concat(Array.isArray(currentProject?.openings) ? currentProject.openings : [])
      .concat(Array.isArray(currentProject?.structures) ? currentProject.structures : [])
      .concat(Array.isArray(currentProject?.zones) ? currentProject.zones : [])
      .concat(Array.isArray(currentProject?.furniture) ? currentProject.furniture : [])
      .concat(Array.isArray(review.text) ? review.text : [])
      .concat(Array.isArray(review.lines) ? review.lines : [])
      .concat(Array.isArray(review.lineGroups) ? review.lineGroups : [])
      .concat(Array.isArray(review.shapes) ? review.shapes : []);
  }

  function isPdfSourceBoundProjectItem(item) {
    const id = String(item?.id || "");
    return item && (
      item.source_kind === "pdf" ||
      item.provenance?.source_kind === "pdf" ||
      normalizeSourceSha256(item.sourcePdfSha256 || item.pdfSha256) !== null ||
      id.startsWith("pdf-") ||
      item.sourceType === "vector_pdf" ||
      item.source === "pdf-vector" ||
      Boolean(
        item.source_object_id ||
        item.sourceWallId ||
        item.sourceColumnId ||
        item.sourceRegionId ||
        item.importGroupId ||
        item.referenceGroupId
      )
    );
  }

  function firstDraftScopeValue(values, fallback) {
    const match = values.find((value) => value !== null && value !== undefined && String(value).trim());
    return match === undefined ? fallback : String(match).trim();
  }

  function resolveWorkingDraftScope(currentProject, sourceBinding = null) {
    const binding = isPlainObject(sourceBinding) ? sourceBinding : {};
    const receipt = currentProject?.r6Review?.importReceipt || {};
    const source = receipt.source || {};
    const importSource = currentProject?.importSource || {};
    const underlay = currentProject?.underlay || {};
    const sceneImport = currentProject?.lastPdfObjectizationSceneImport || {};
    return {
      caseId: firstDraftScopeValue([
        binding.caseId,
        currentProject?.r6Review?.caseId,
        receipt.caseId,
        importSource.caseId
      ], "case-unresolved"),
      pageRef: firstDraftScopeValue([
        binding.pageRef,
        source.page,
        source.pageNumber,
        importSource.page,
        importSource.pageNumber,
        underlay.page,
        sceneImport.page
      ], "page-unresolved"),
      floorRef: firstDraftScopeValue([
        binding.floorRef,
        importSource.floorId,
        importSource.floorLabel,
        underlay.floorId,
        underlay.floorLabel,
        sceneImport.floorId,
        sceneImport.floorLabel
      ], "floor-unresolved"),
      sourceSha256: normalizeSourceSha256(
        binding.sourceSha256 ||
        importSource.sourceSha256 ||
        importSource.sourcePdfSha256 ||
        underlay.sourcePdfSha256 ||
        underlay.sourceSha256 ||
        receipt.file?.sha256 ||
        sceneImport.sourcePdfSha256
      ) || "manual-source"
    };
  }

  function normalizeWorkingDraftStorageKeyPart(value) {
    return encodeURIComponent(String(value || "unresolved").trim());
  }

  function createScopedWorkingDraftStorageKey(currentProject, sourceBinding = null) {
    const scope = resolveWorkingDraftScope(currentProject, sourceBinding);
    return WORKING_DRAFT_STORAGE_KEY_PREFIX + [
      scope.caseId,
      scope.sourceSha256,
      scope.pageRef,
      scope.floorRef
    ].map(normalizeWorkingDraftStorageKeyPart).join(":");
  }

  function auditProjectSourceBinding(currentProject, persistedBinding = null) {
    if (!isPlainObject(currentProject)) {
      return { pass: false, reason: "invalid_project", binding: null, observedSha256: [] };
    }
    const observedSha256 = new Set();
    const addSha = (value) => {
      const sha = normalizeSourceSha256(value);
      if (sha) observedSha256.add(sha);
      return sha;
    };
    const projectBinding = isPlainObject(currentProject.sourceBinding) ? currentProject.sourceBinding : null;
    const storedBinding = isPlainObject(persistedBinding) ? persistedBinding : null;
    const underlaySha256 = addSha(currentProject.underlay?.sourcePdfSha256 || currentProject.underlay?.sourceSha256);
    addSha(currentProject.importSource?.sourcePdfSha256 || currentProject.importSource?.sourceSha256);
    addSha(currentProject.lastPdfObjectizationSceneImport?.sourcePdfSha256);
    addSha(currentProject.r6Review?.importReceipt?.file?.sha256);
    addSha(projectBinding?.sourceSha256);
    addSha(storedBinding?.sourceSha256);

    const items = getSourceBoundProjectItems(currentProject);
    const pdfItems = items.filter(isPdfSourceBoundProjectItem);
    const missingPdfItemSourceIds = [];
    const missingPdfItemImportSessionIds = [];
    const observedImportSessionIds = new Set();
    pdfItems.forEach((item) => {
      const itemSha256 = addSha(item.sourcePdfSha256 || item.pdfSha256);
      if (!itemSha256) missingPdfItemSourceIds.push(String(item.id || item.sourceId || "unknown-pdf-object"));
      const itemImportSessionId = String(
        item.importSessionId ||
        item.sourceImportSessionId ||
        item.provenance?.importSessionId ||
        ""
      ).trim();
      if (itemImportSessionId) {
        observedImportSessionIds.add(itemImportSessionId);
      } else {
        missingPdfItemImportSessionIds.push(String(item.id || item.sourceId || "unknown-pdf-object"));
      }
    });

    const hashes = Array.from(observedSha256).sort();
    if (hashes.length > 1) {
      return { pass: false, reason: "cross_source_sha_mismatch", binding: null, observedSha256: hashes };
    }
    if (missingPdfItemSourceIds.length > 0) {
      return {
        pass: false,
        reason: "pdf_object_source_identity_missing",
        binding: null,
        observedSha256: hashes,
        missingPdfItemSourceIds: missingPdfItemSourceIds.sort()
      };
    }
    if (missingPdfItemImportSessionIds.length > 0) {
      return {
        pass: false,
        reason: "pdf_object_import_session_missing",
        binding: null,
        observedSha256: hashes,
        missingPdfItemImportSessionIds: missingPdfItemImportSessionIds.sort()
      };
    }
    const projectImportSessionId = String(
      currentProject.lastPdfObjectizationSceneImport?.importSessionId ||
      currentProject.r6Review?.importReceipt?.importSessionId ||
      currentProject.importSource?.importSessionId ||
      projectBinding?.importSessionId ||
      ""
    ).trim();
    const persistedImportSessionId = String(storedBinding?.importSessionId || "").trim();
    if (projectImportSessionId) observedImportSessionIds.add(projectImportSessionId);
    if (persistedImportSessionId) observedImportSessionIds.add(persistedImportSessionId);
    const importSessionIds = Array.from(observedImportSessionIds).sort();
    if (importSessionIds.length > 1) {
      return {
        pass: false,
        reason: "cross_source_import_session_mismatch",
        binding: null,
        observedSha256: hashes,
        observedImportSessionIds: importSessionIds
      };
    }
    const vectorUnderlay = currentProject.underlay?.renderMode === "pdf-vector-context" || currentProject.underlay?.sourceType === "vector_pdf";
    if ((vectorUnderlay || (pdfItems.length > 0 && hashes.length > 0)) && !underlaySha256) {
      return { pass: false, reason: "pdf_underlay_source_identity_missing", binding: null, observedSha256: hashes };
    }
    const expectedSha256 = hashes[0] || null;
    const persistedSha256 = normalizeSourceSha256(storedBinding?.sourceSha256);
    if (persistedSha256 && expectedSha256 && persistedSha256 !== expectedSha256) {
      return { pass: false, reason: "persisted_source_binding_mismatch", binding: null, observedSha256: hashes };
    }
    const sourceKind = String(
      storedBinding?.sourceKind ||
      projectBinding?.sourceKind ||
      (vectorUnderlay || pdfItems.length ? "pdf" : currentProject.importSource?.normalizedAs || currentProject.importSource?.kind || "manual")
    );
    const normalizedImportKind = String(
      currentProject.importSource?.normalizedAs ||
      currentProject.importSource?.kind ||
      ""
    );
    const explicitManualDraft = normalizedImportKind === "blank-mm-draft" || normalizedImportKind === "reference-underlay";
    if (!expectedSha256 && !explicitManualDraft && (currentProject.importSource || currentProject.underlay)) {
      return {
        pass: false,
        reason: "imported_source_identity_missing",
        binding: null,
        observedSha256: hashes,
        observedImportSessionIds: importSessionIds
      };
    }
    const draftScope = resolveWorkingDraftScope(currentProject, storedBinding || projectBinding);
    const binding = expectedSha256 ? {
      schema: "laibe.planPuzzle.sourceBinding.v2",
      sourceKind,
      sourceSha256: expectedSha256,
      importSessionId: String(
        importSessionIds[0] ||
        ""
      ) || null,
      fileName: String(
        currentProject.importSource?.fileName ||
        currentProject.importSource?.originalFileName ||
        currentProject.underlay?.fileName ||
        storedBinding?.fileName ||
        projectBinding?.fileName ||
        ""
      ) || null,
      caseId: draftScope.caseId,
      pageRef: draftScope.pageRef,
      floorRef: draftScope.floorRef
    } : null;
    return {
      pass: true,
      reason: null,
      binding,
      observedSha256: hashes,
      observedImportSessionIds: importSessionIds,
      pdfItemCount: pdfItems.length
    };
  }

  function runSourceIsolationContractFixtures() {
    const sourceA = "A".repeat(64);
    const sourceB = "B".repeat(64);
    const createFixtureProject = (sourceSha256) => ({
      sourceBinding: {
        schema: "laibe.planPuzzle.sourceBinding.v1",
        sourceKind: "pdf",
        sourceSha256,
        importSessionId: `fixture-${sourceSha256.slice(0, 4)}`,
        fileName: `${sourceSha256.slice(0, 1)}.pdf`
      },
      importSource: { kind: "preprocessed-objectization-scene", sourceSha256, importSessionId: `fixture-${sourceSha256.slice(0, 4)}` },
      underlay: { renderMode: "pdf-vector-context", sourceType: "vector_pdf", sourcePdfSha256: sourceSha256 },
      lastPdfObjectizationSceneImport: { sourcePdfSha256: sourceSha256, importSessionId: `fixture-${sourceSha256.slice(0, 4)}` },
      walls: [{ id: `pdf-wall-${sourceSha256.slice(0, 1)}`, sourceType: "vector_pdf", sourcePdfSha256: sourceSha256, importSessionId: `fixture-${sourceSha256.slice(0, 4)}` }],
      openings: [], structures: [], zones: [], furniture: [], caseEvents: [],
      pdfReviewObjects: { text: [], lines: [], shapes: [] }
    });
    const projectA = createFixtureProject(sourceA);
    const projectB = createFixtureProject(sourceB);
    const mixed = createFixtureProject(sourceB);
    mixed.walls = cloneJson(projectA.walls);
    const missingUnderlayIdentity = createFixtureProject(sourceA);
    delete missingUnderlayIdentity.underlay.sourcePdfSha256;
    const missingObjectIdentity = createFixtureProject(sourceA);
    delete missingObjectIdentity.walls[0].sourcePdfSha256;
    const missingObjectImportSession = createFixtureProject(sourceA);
    delete missingObjectImportSession.walls[0].importSessionId;
    const legacyVectorObjectMissingIdentity = createFixtureProject(sourceA);
    legacyVectorObjectMissingIdentity.walls = [{
      id: "legacy-source-wall-row",
      sourceType: "vector_pdf",
      sourceWallId: "legacy-source-wall",
      source_object_id: "legacy-source-wall"
    }];
    const mixedImportSession = createFixtureProject(sourceA);
    mixedImportSession.walls[0].importSessionId = "fixture-other-session";
    const persistedMismatch = auditProjectSourceBinding(projectA, { sourceSha256: sourceB, sourceKind: "pdf" });
    const scopedBindingA = {
      ...auditProjectSourceBinding(projectA, projectA.sourceBinding).binding,
      caseId: "fixture-case-a",
      pageRef: "1",
      floorRef: "3f"
    };
    const scopedBindingASecondSession = { ...scopedBindingA, importSessionId: "fixture-new-session" };
    const scopedBindingB = { ...scopedBindingA, sourceSha256: sourceB };
    const scopedBindingOtherCase = { ...scopedBindingA, caseId: "fixture-case-b" };
    const scopedBindingOtherPage = { ...scopedBindingA, pageRef: "2" };
    const scopedBindingOtherFloor = { ...scopedBindingA, floorRef: "rf" };
    const scopedKeyA = createScopedWorkingDraftStorageKey(projectA, scopedBindingA);
    const results = {
      sourceAPass: auditProjectSourceBinding(projectA, projectA.sourceBinding).pass === true,
      sourceBPass: auditProjectSourceBinding(projectB, projectB.sourceBinding).pass === true,
      mixedSourceRejected: auditProjectSourceBinding(mixed, mixed.sourceBinding).reason === "cross_source_sha_mismatch",
      missingUnderlayIdentityRejected: auditProjectSourceBinding(missingUnderlayIdentity, missingUnderlayIdentity.sourceBinding).reason === "pdf_underlay_source_identity_missing",
      missingObjectIdentityRejected: auditProjectSourceBinding(missingObjectIdentity, missingObjectIdentity.sourceBinding).reason === "pdf_object_source_identity_missing",
      missingObjectImportSessionRejected: auditProjectSourceBinding(missingObjectImportSession, missingObjectImportSession.sourceBinding).reason === "pdf_object_import_session_missing",
      legacyVectorObjectMissingIdentityRejected: auditProjectSourceBinding(legacyVectorObjectMissingIdentity, legacyVectorObjectMissingIdentity.sourceBinding).reason === "pdf_object_source_identity_missing",
      mixedImportSessionRejected: auditProjectSourceBinding(mixedImportSession, mixedImportSession.sourceBinding).reason === "cross_source_import_session_mismatch",
      persistedMismatchRejected: persistedMismatch.pass === false && persistedMismatch.reason === "cross_source_sha_mismatch",
      currentImportSequenceAccepted: isCurrentImportRequestSequence(7, 7) === true,
      staleImportSequenceRejected: isCurrentImportRequestSequence(6, 7) === false,
      unboundQaImportAccepted: isCurrentImportRequestSequence(null, 7) === true,
      scopedDraftKeyStableAcrossImportSessions: scopedKeyA === createScopedWorkingDraftStorageKey(projectA, scopedBindingASecondSession),
      scopedDraftKeySeparatesSourceSha: scopedKeyA !== createScopedWorkingDraftStorageKey(projectB, scopedBindingB),
      scopedDraftKeySeparatesCase: scopedKeyA !== createScopedWorkingDraftStorageKey(projectA, scopedBindingOtherCase),
      scopedDraftKeySeparatesPage: scopedKeyA !== createScopedWorkingDraftStorageKey(projectA, scopedBindingOtherPage),
      scopedDraftKeySeparatesFloor: scopedKeyA !== createScopedWorkingDraftStorageKey(projectA, scopedBindingOtherFloor)
    };
    return { pass: Object.values(results).every(Boolean), results };
  }

  function getCachedSourceIsolationContractFixtures() {
    if (!getCachedSourceIsolationContractFixtures.cache) {
      getCachedSourceIsolationContractFixtures.cache = runSourceIsolationContractFixtures();
    }
    return getCachedSourceIsolationContractFixtures.cache;
  }

  window.laibePlanGetSourceIsolationAudit = () => cloneJson(auditProjectSourceBinding(project, project.sourceBinding));
  window.laibePlanRunSourceIsolationContractFixtures = runSourceIsolationContractFixtures;
  window.laibePlanGetWorkingDraftStorageState = () => ({
    activeStorageKey: activeWorkingDraftStorageKey,
    activePointer: activeWorkingDraftPointerJson ? JSON.parse(activeWorkingDraftPointerJson) : null,
    sourceScope: resolveWorkingDraftScope(project, project.sourceBinding),
    persistenceBlocked: workingDraftPersistenceBlocked || sourceImportCommitInProgress
  });

  function normalizePersistedWorkingDraftProject(value) {
    if (!isPlainObject(value)) {
      return null;
    }
    const initial = createInitialProject();
    const restored = { ...initial, ...value };
    ["walls", "openings", "structures", "zones", "furniture", "caseEvents"].forEach((key) => {
      restored[key] = Array.isArray(value[key]) ? value[key] : [];
    });
    restored.structuralObjects = restored.structures;
    restored.scale = { ...initial.scale, ...(isPlainObject(value.scale) ? value.scale : {}) };
    restored.wallGraph = isPlainObject(value.wallGraph) ? value.wallGraph : createInitialWallGraph();
    restored.nodeGraph = isPlainObject(value.nodeGraph) ? value.nodeGraph : createInitialNodeGraph();
    restored.pdfReviewObjects = {
      ...createInitialPdfReviewObjects(),
      ...(isPlainObject(value.pdfReviewObjects) ? value.pdfReviewObjects : {})
    };
    restored.guide = {
      ...createInitialGuideState(),
      ...(isPlainObject(value.guide) ? value.guide : {})
    };
    restored.guideLog = Array.isArray(value.guideLog) ? value.guideLog : [];
    restored.underlay = isPlainObject(value.underlay) ? value.underlay : null;
    restored.importSource = isPlainObject(value.importSource) ? value.importSource : null;
    restored.r4b1Review = isPlainObject(value.r4b1Review) ? value.r4b1Review : null;
    restored.r6Review = isPlainObject(value.r6Review) ? value.r6Review : null;
    const underlayMigrated = migratePersistedAcceptedPdfVectorUnderlay(restored);
    const openingsMigrated = migratePersistedAcceptedPdfOpeningMetrics(restored);
    const openingSourceAlignmentMigrated = migratePersistedPdfOpeningSourceAlignment(restored);
    const stairLineOnlyMigrated = migratePersistedStairLineOnly(restored);
    if (underlayMigrated || openingsMigrated || openingSourceAlignmentMigrated || stairLineOnlyMigrated) restored.r6AcceptedGeometryMigrationPending = true;
    restored.zones.forEach((zone) => migratePersistedAcceptedZonePolygon(zone, restored));
    return restored;
  }

  function migratePersistedStairLineOnly(currentProject) {
    if (!isPlainObject(currentProject)) return false;
    let changed = false;
    const review = currentProject.pdfReviewObjects;
    if (isPlainObject(review) && Array.isArray(review.shapes)) {
      const retainedShapes = review.shapes.filter((shape) => {
        const category = String(shape && (shape.category || shape.groupKind || shape.kind) || "");
        return category !== "stairGroup" && category !== "stairVoidReview";
      });
      if (retainedShapes.length !== review.shapes.length) {
        review.shapes = retainedShapes;
        changed = true;
      }
    }
    if (isPlainObject(review) && Array.isArray(review.lines)) {
      review.lines.forEach((line) => {
        const category = String(line && (line.category || line.groupKind || line.kind) || "");
        if ((category === "stairReference" || category === "stairGroup" || category === "pdf_stair_line") && line.selectable !== false) {
          line.selectable = false;
          changed = true;
        }
      });
    }
    if (isPlainObject(review) && Array.isArray(review.lineGroups)) {
      review.lineGroups.forEach((group) => {
        const category = String(group && (group.category || group.groupKind || group.kind) || "");
        if ((category === "stairGroup" || category === "pdf_stair_reference_group") && group.selectable !== false) {
          group.selectable = false;
          changed = true;
        }
      });
    }
    if (Array.isArray(currentProject.structures)) {
      const retainedStructures = currentProject.structures.filter((structure) => structure && structure.kind !== "stair" && structure.structureType !== "stair" && !String(structure.id || "").startsWith("pdf-stair-"));
      if (retainedStructures.length !== currentProject.structures.length) {
        currentProject.structures = retainedStructures;
        currentProject.structuralObjects = currentProject.structures;
        changed = true;
      }
    }
    return changed;
  }

  function migratePersistedAcceptedPdfVectorUnderlay(currentProject) {
    const underlay = currentProject && currentProject.underlay;
    const acceptedTransformId = acceptedScaleTransformId(currentProject);
    const factor = Number(underlay && underlay.r6AppliedGeometryScaleFactor || currentProject?.scale?.geometryScaleFactor);
    const acceptedWorldMmPerPt = Number(underlay && underlay.acceptedWorldMmPerPt || currentProject?.scale?.acceptedWorldMmPerPt);
    const isLegacyAcceptedPdfUnderlay = Boolean(
      underlay &&
      underlay.sourceType === "vector_pdf" &&
      underlay.renderMode === "pdf-vector-context" &&
      acceptedTransformId &&
      underlay.r6AppliedTransformId === acceptedTransformId &&
      !underlay.r6AppliedFrameTransformId
    );
    if (!isLegacyAcceptedPdfUnderlay || !Number.isFinite(factor) || factor <= 0 || !Number.isFinite(acceptedWorldMmPerPt) || acceptedWorldMmPerPt <= 0) {
      return false;
    }
    const migration = r6ScalePdfUnderlayFrameMetrics(underlay, factor, acceptedTransformId, acceptedWorldMmPerPt);
    if (!migration.pass) {
      return false;
    }
    return true;
  }

  function r6AcceptedOpeningMetricKeys() {
    return ["offset", "offsetMm", "positionOnWallMm", "sillHeight", "sillHeightMm", "planSymbolDepthMm", "sourceSymbolWidthMm"];
  }

  function r6OpeningHostWall(currentProject, opening) {
    return (currentProject?.walls || []).find((wall) => wall && (
      wall.id === opening.wallId ||
      wall.id === opening.hostWallId ||
      wall.sourceWallId === opening.sourceWallId ||
      wall.source_object_id === opening.sourceWallId
    )) || null;
  }

  function r6OpeningEdgesForWall(currentProject, wall) {
    const baseId = wall && `edge-${wall.id}`;
    const graphEdges = (currentProject?.nodeGraph?.edges || [])
      .filter((edge) => edge && baseId && (edge.id === baseId || String(edge.id || "").startsWith(`${baseId}-s`)))
      .sort((left, right) => String(left.id).localeCompare(String(right.id), undefined, { numeric: true }));
    const sourceHostEdge = createOpeningHostEdgeForWall(wall);
    return sourceHostEdge ? [sourceHostEdge, ...graphEdges] : graphEdges;
  }

  function createOpeningHostEdgeId(wall) {
    return wall && wall.id ? `edge-${wall.id}-opening-host` : null;
  }

  function createOpeningHostEdgeForWall(wall) {
    if (!wall || !r6FinitePoint(wall.from) || !r6FinitePoint(wall.to)) return null;
    const length = r6PointDistance(wall.from, wall.to);
    if (!(length > 0)) return null;
    return {
      id: createOpeningHostEdgeId(wall),
      sourceWallId: wall.sourceWallId || wall.source_object_id || wall.id,
      from: { x: Number(wall.from.x), y: Number(wall.from.y) },
      to: { x: Number(wall.to.x), y: Number(wall.to.y) },
      length,
      thickness: Number(wall.thickness) || DEFAULT_WALL_THICKNESS,
      status: normalizeWallStatus(wall.status),
      wallType: normalizeWallType(wall.wallType),
      layer: wall.layer || "walls",
      openingHostOnly: true
    };
  }

  function createPdfSourceOpeningHostEdgeId(opening) {
    return opening && opening.id ? `edge-${opening.id}-source-gap-host` : null;
  }

  function getPdfSourceOpeningHostEdge(opening) {
    const stored = opening?.pdfSourceHostEdge;
    if (!stored || stored.id !== createPdfSourceOpeningHostEdgeId(opening) || !r6FinitePoint(stored.from) || !r6FinitePoint(stored.to)) {
      return null;
    }
    const length = r6PointDistance(stored.from, stored.to);
    if (!(length > 0)) return null;
    return {
      ...stored,
      from: { x: Number(stored.from.x), y: Number(stored.from.y) },
      to: { x: Number(stored.to.x), y: Number(stored.to.y) },
      length,
      sourceOpeningHostOnly: true
    };
  }

  function getPdfOpeningHostEvidenceSourceIds(opening) {
    const evidence = opening?.candidateEvidence || opening?.evidence || {};
    return uniqueIds([].concat(
      Array.isArray(evidence.hostWallSourceIds) ? evidence.hostWallSourceIds : [],
      Array.isArray(evidence.hostWallIds) ? evidence.hostWallIds : [],
      evidence.hostWallId ? [evidence.hostWallId] : [],
      Array.isArray(evidence.hostWallGap?.hostWallSourceIds) ? evidence.hostWallGap.hostWallSourceIds : [],
      Array.isArray(evidence.hostWallGap?.wallIds) ? evidence.hostWallGap.wallIds : [],
      opening?.sourceWallId ? [opening.sourceWallId] : []
    ));
  }

  function projectPointToInfiniteLine(point, from, to) {
    if (!point || !from || !to) return null;
    const dx = Number(to.x) - Number(from.x);
    const dy = Number(to.y) - Number(from.y);
    const length = Math.hypot(dx, dy);
    if (!(length > 0)) return null;
    const unit = { x: dx / length, y: dy / length };
    const distanceAlong = (Number(point.x) - Number(from.x)) * unit.x + (Number(point.y) - Number(from.y)) * unit.y;
    const projected = {
      x: Number(from.x) + unit.x * distanceAlong,
      y: Number(from.y) + unit.y * distanceAlong
    };
    return { point: projected, unit, distanceAlong, distance: pointDistance(point, projected), length };
  }

  function resolvePdfOpeningCanonicalHostBinding(opening, currentProject) {
    if (!opening || !isPdfDerivedExistingObject(opening)) return null;
    const acceptedTransformId = acceptedScaleTransformId(currentProject);
    const acceptedWorldMmPerPt = getPdfAcceptedWorldMmPerPt(currentProject);
    const openingSourceId = String(opening.source_object_id || opening.sourceOpeningId || "");
    const openingSourcePathIds = new Set(Array.isArray(opening.sourcePathIds) ? opening.sourcePathIds.map(String) : []);
    const sourceEvidenceCandidates = [].concat(
      currentProject?.pdfReviewObjects?.shapes || [],
      currentProject?.pdfReviewObjects?.lines || []
    ).filter((item) => {
      const itemSourceId = String(item?.source_object_id || item?.sourceOpeningId || item?.sourceId || "");
      if (openingSourceId && itemSourceId === openingSourceId) return true;
      const itemPaths = Array.isArray(item?.sourcePathIds) ? item.sourcePathIds.map(String) : [];
      const category = String(item?.category || item?.sourceCategory || "");
      return openingSourcePathIds.size > 0 && itemPaths.some((id) => openingSourcePathIds.has(id)) && /opening|door|window/i.test(category);
    });
    const sourceEvidenceItem = sourceEvidenceCandidates.length === 1 ? sourceEvidenceCandidates[0] : null;
    const sourceGeometryOwner = getPdfObjectSourceBoxTopLeft(opening, currentProject) ? opening : (sourceEvidenceItem || opening);
    const sourceBox = getPdfObjectSourceBoxTopLeft(sourceGeometryOwner, currentProject);
    if (!acceptedTransformId || !(acceptedWorldMmPerPt > 0)) return null;
    const hostGap = opening?.candidateEvidence?.hostWallGap || opening?.evidence?.hostWallGap || sourceEvidenceItem?.candidateEvidence?.hostWallGap || sourceEvidenceItem?.evidence?.hostWallGap || null;
    const sourceFrame = getPdfObjectSourceFrame(sourceGeometryOwner, currentProject);
    const existingSourceHostEdge = getPdfSourceOpeningHostEdge(opening);
    const legacySourceCenterPt = existingSourceHostEdge?.sourceExpectedCenterPt &&
      r6FinitePoint(existingSourceHostEdge.sourceExpectedCenterPt) &&
      String(opening.pdfSourceAlignmentTransformId || "").startsWith(`${acceptedTransformId}:source-gap-host-`)
      ? { x: Number(existingSourceHostEdge.sourceExpectedCenterPt.x), y: Number(existingSourceHostEdge.sourceExpectedCenterPt.y) }
      : null;
    let sourceGapEndpoints = null;
    const directSourceP1 = sourceGeometryOwner?.sourceGeometryPdfPt?.p1;
    const directSourceP2 = sourceGeometryOwner?.sourceGeometryPdfPt?.p2;
    const mappedDirectP1 = pdfSourcePointToTopLeft(directSourceP1, sourceFrame.coordinateFrame, sourceFrame.sourcePageHeightPt);
    const mappedDirectP2 = pdfSourcePointToTopLeft(directSourceP2, sourceFrame.coordinateFrame, sourceFrame.sourcePageHeightPt);
    if (mappedDirectP1 && mappedDirectP2 && pointDistance(mappedDirectP1, mappedDirectP2) > 0) {
      sourceGapEndpoints = [mappedDirectP1, mappedDirectP2];
    }
    if (hostGap?.candidateFitPass === true && Number.isFinite(Number(hostGap.gapMainStartPdf)) && Number.isFinite(Number(hostGap.gapMainEndPdf)) && Number.isFinite(Number(hostGap.hostAxisPerpendicularPdf))) {
      const rawStart = hostGap.orientation === "vertical"
        ? { x: Number(hostGap.hostAxisPerpendicularPdf), y: Number(hostGap.gapMainStartPdf) }
        : { x: Number(hostGap.gapMainStartPdf), y: Number(hostGap.hostAxisPerpendicularPdf) };
      const rawEnd = hostGap.orientation === "vertical"
        ? { x: Number(hostGap.hostAxisPerpendicularPdf), y: Number(hostGap.gapMainEndPdf) }
        : { x: Number(hostGap.gapMainEndPdf), y: Number(hostGap.hostAxisPerpendicularPdf) };
      const mappedStart = pdfSourcePointToTopLeft(rawStart, sourceFrame.coordinateFrame, sourceFrame.sourcePageHeightPt);
      const mappedEnd = pdfSourcePointToTopLeft(rawEnd, sourceFrame.coordinateFrame, sourceFrame.sourcePageHeightPt);
      if (mappedStart && mappedEnd && pointDistance(mappedStart, mappedEnd) > 0) sourceGapEndpoints = [mappedStart, mappedEnd];
    }
    if (!sourceBox && !sourceGapEndpoints && !legacySourceCenterPt) return null;
    const sourceCenter = sourceGapEndpoints
      ? { x: (sourceGapEndpoints[0].x + sourceGapEndpoints[1].x) / 2, y: (sourceGapEndpoints[0].y + sourceGapEndpoints[1].y) / 2 }
      : (sourceBox
        ? { x: (sourceBox.x0 + sourceBox.x1) / 2, y: (sourceBox.y0 + sourceBox.y1) / 2 }
        : legacySourceCenterPt);
    const evidenceSourceIds = uniqueIds(getPdfOpeningHostEvidenceSourceIds(opening).concat(getPdfOpeningHostEvidenceSourceIds(sourceEvidenceItem)));
    const evidenceSet = new Set(evidenceSourceIds);
    const pdfWalls = (currentProject?.walls || []).filter(isPdfDerivedExistingObject);
    let candidateWalls = evidenceSourceIds.length
      ? pdfWalls.filter((wall) => evidenceSet.has(String(wall.source_object_id || wall.sourceWallId || "")))
      : [];
    if (!candidateWalls.length) {
      candidateWalls = pdfWalls.filter((wall) => wall.id === opening.wallId || wall.id === opening.hostWallId);
    }
    const projectedCandidates = candidateWalls.map((wall) => {
      const expected = getPdfWallExpectedSourceEndpoints(wall, currentProject);
      const projection = expected ? projectPointToInfiniteLine(sourceCenter, expected.from, expected.to) : null;
      return projection ? { wall, expected, projection } : null;
    }).filter(Boolean).sort((left, right) =>
      left.projection.distance - right.projection.distance || String(left.wall.id).localeCompare(String(right.wall.id))
    );
    const chosen = projectedCandidates[0];
    if (!chosen) return null;
    let unit = { ...chosen.projection.unit };
    if (unit.x < -1e-9 || (Math.abs(unit.x) <= 1e-9 && unit.y < 0)) {
      unit = { x: -unit.x, y: -unit.y };
    }
    const normal = { x: -unit.y, y: unit.x };
    const axisCoordinate = (point) => Number(point.x) * unit.x + Number(point.y) * unit.y;
    const normalCoordinate = (point) => Number(point.x) * normal.x + Number(point.y) * normal.y;
    const chosenWallNormal = normalCoordinate(chosen.expected.from);
    const sourceAxisNormal = sourceGapEndpoints ? normalCoordinate(sourceCenter) : chosenWallNormal;
    const collinearTolerancePt = PDF_FULL_GEOMETRY_RESIDUAL_TOLERANCE_PT;
    const compatible = projectedCandidates.filter(({ expected }) => {
      const dx = Number(expected.to.x) - Number(expected.from.x);
      const dy = Number(expected.to.y) - Number(expected.from.y);
      const length = Math.hypot(dx, dy);
      if (!(length > 0)) return false;
      const parallel = Math.abs((dx / length) * unit.y - (dy / length) * unit.x);
      const fromDistance = Math.abs(normalCoordinate(expected.from) - chosenWallNormal);
      const toDistance = Math.abs(normalCoordinate(expected.to) - chosenWallNormal);
      return parallel <= 0.002 && Math.max(fromDistance, toDistance) <= collinearTolerancePt;
    });
    const wallProjections = compatible.flatMap(({ expected }) => [axisCoordinate(expected.from), axisCoordinate(expected.to)]);
    const boxCorners = sourceBox ? [
      { x: sourceBox.x0, y: sourceBox.y0 }, { x: sourceBox.x1, y: sourceBox.y0 },
      { x: sourceBox.x0, y: sourceBox.y1 }, { x: sourceBox.x1, y: sourceBox.y1 }
    ] : [];
    const legacyGapPoints = !sourceGapEndpoints && !boxCorners.length && legacySourceCenterPt
      ? (() => {
          const halfWidthPt = Number(opening.widthMm ?? opening.width) / acceptedWorldMmPerPt / 2;
          return Number.isFinite(halfWidthPt) && halfWidthPt > 0 ? [
            { x: legacySourceCenterPt.x - unit.x * halfWidthPt, y: legacySourceCenterPt.y - unit.y * halfWidthPt },
            { x: legacySourceCenterPt.x + unit.x * halfWidthPt, y: legacySourceCenterPt.y + unit.y * halfWidthPt }
          ] : [];
        })()
      : [];
    const openingProjections = (sourceGapEndpoints || (boxCorners.length ? boxCorners : legacyGapPoints)).map(axisCoordinate);
    if (!wallProjections.length || !openingProjections.length) return null;
    const wallMin = Math.min(...wallProjections, ...openingProjections);
    const wallMax = Math.max(...wallProjections, ...openingProjections);
    const openingMin = Math.min(...openingProjections);
    const openingMax = Math.max(...openingProjections);
    const sourceWallLengthPt = wallMax - wallMin;
    const expectedStartOffsetPt = openingMin - wallMin;
    const expectedEndOffsetPt = openingMax - wallMin;
    const expectedCenterOffsetPt = (expectedStartOffsetPt + expectedEndOffsetPt) / 2;
    const expectedWidthPt = expectedEndOffsetPt - expectedStartOffsetPt;
    if (!(sourceWallLengthPt > 0) || !(expectedWidthPt > 0)) return null;
    const sourceAxisOriginPt = {
      x: unit.x * wallMin + normal.x * sourceAxisNormal,
      y: unit.y * wallMin + normal.y * sourceAxisNormal
    };
    const expectedCenterPt = {
      x: sourceAxisOriginPt.x + unit.x * expectedCenterOffsetPt,
      y: sourceAxisOriginPt.y + unit.y * expectedCenterOffsetPt
    };
    const sourceBinding = auditProjectSourceBinding(currentProject, currentProject?.sourceBinding || null);
    const compatibleSourceIds = uniqueIds(compatible.map(({ wall }) => wall.source_object_id || wall.sourceWallId));
    const missingEvidenceSourceIds = evidenceSourceIds.filter((sourceId) => !compatibleSourceIds.includes(sourceId));
    const primaryWall = compatible.find(({ wall }) => wall.id === opening.wallId || wall.id === opening.hostWallId)?.wall || compatible[0]?.wall || chosen.wall;
    const sourceWallId = String(primaryWall?.source_object_id || primaryWall?.sourceWallId || "") || null;
    const ambiguousCandidates = projectedCandidates.filter(({ expected, projection }) => {
      if (projection.distance > chosen.projection.distance + collinearTolerancePt) return false;
      const dx = Number(expected.to.x) - Number(expected.from.x);
      const dy = Number(expected.to.y) - Number(expected.from.y);
      const length = Math.hypot(dx, dy);
      return length > 0 && Math.abs((dx / length) * unit.y - (dy / length) * unit.x) > 0.002;
    });
    return {
      schema: "laibe.planPuzzle.pdfOpeningCanonicalHostBinding.v1",
      acceptedTransformId,
      sourceSha256: sourceBinding?.binding?.sourceSha256 || normalizeSourceSha256(opening.sourcePdfSha256 || primaryWall?.sourcePdfSha256),
      importSessionId: sourceBinding?.binding?.importSessionId || opening.importSessionId || primaryWall?.importSessionId || null,
      hostWallId: primaryWall?.id || null,
      hostWallSourceId: sourceWallId,
      hostWallSourceIds: compatibleSourceIds,
      evidenceHostWallSourceIds: evidenceSourceIds,
      missingEvidenceSourceIds,
      sourceHostEvidenceStatus: evidenceSourceIds.length && compatibleSourceIds.length ? "source_bound" : "source_not_proven",
      ambiguous: ambiguousCandidates.length > 0,
      axisUnit: { x: r6RoundNumber(unit.x), y: r6RoundNumber(unit.y) },
      sourceAxisOriginPt: { x: r6RoundNumber(sourceAxisOriginPt.x), y: r6RoundNumber(sourceAxisOriginPt.y) },
      sourceWallLengthPt: r6RoundNumber(sourceWallLengthPt),
      sourceWallLengthMm: r6RoundNumber(sourceWallLengthPt * acceptedWorldMmPerPt),
      expectedOpeningStartOffsetPt: r6RoundNumber(expectedStartOffsetPt),
      expectedOpeningCenterOffsetPt: r6RoundNumber(expectedCenterOffsetPt),
      expectedOpeningEndOffsetPt: r6RoundNumber(expectedEndOffsetPt),
      expectedOpeningStartOffsetMm: r6RoundNumber(expectedStartOffsetPt * acceptedWorldMmPerPt),
      expectedOpeningCenterOffsetMm: r6RoundNumber(expectedCenterOffsetPt * acceptedWorldMmPerPt),
      expectedOpeningEndOffsetMm: r6RoundNumber(expectedEndOffsetPt * acceptedWorldMmPerPt),
      expectedOpeningWidthPt: r6RoundNumber(expectedWidthPt),
      expectedOpeningWidthMm: r6RoundNumber(expectedWidthPt * acceptedWorldMmPerPt),
      sourceGapEvidenceStatus: sourceGapEndpoints ? (hostGap?.candidateFitPass === true ? "source_gap_proven" : "source_endpoint_span_proven") : (sourceBox ? "source_bbox_projection_only" : "accepted_transform_legacy_gap_receipt"),
      expectedCenterPt: { x: r6RoundNumber(expectedCenterPt.x), y: r6RoundNumber(expectedCenterPt.y) },
      sourcePerpendicularDistancePt: r6RoundNumber(Math.abs(normalCoordinate(sourceCenter) - sourceAxisNormal)),
      containmentPass: expectedStartOffsetPt >= -collinearTolerancePt && expectedEndOffsetPt <= sourceWallLengthPt + collinearTolerancePt
    };
  }

  function getOpeningCanonicalWallPositionMm(opening) {
    const binding = opening?.pdfCanonicalHostBinding;
    const value = Number(opening?.pdfCanonicalWallStartOffsetMm ?? opening?.positionOnWallMm ?? binding?.expectedOpeningStartOffsetMm);
    return Number.isFinite(value) ? value : Number(opening?.offset) || 0;
  }

  function syncPdfOpeningCanonicalGeometry(opening) {
    const binding = opening?.pdfCanonicalHostBinding;
    if (!binding) return opening;
    const start = getOpeningCanonicalWallPositionMm(opening);
    const width = Number(opening?.width);
    if (!Number.isFinite(start) || !(width > 0)) return opening;
    opening.offset = r6RoundNumber(start);
    opening.offsetMm = r6RoundNumber(start);
    opening.positionOnWallMm = r6RoundNumber(start);
    opening.width = r6RoundNumber(width);
    opening.widthMm = r6RoundNumber(width);
    opening.pdfCanonicalWallStartOffsetMm = r6RoundNumber(start);
    opening.pdfCanonicalWallCenterOffsetMm = r6RoundNumber(start + width / 2);
    return opening;
  }

  function applyPdfOpeningCanonicalWallPositionMm(opening, nextPositionMm, options = {}) {
    const binding = opening?.pdfCanonicalHostBinding;
    const hostEdge = getPdfSourceOpeningHostEdge(opening);
    const next = Number(nextPositionMm);
    const current = getOpeningCanonicalWallPositionMm(opening);
    const unit = binding?.axisUnit;
    const maximum = Number(binding?.sourceWallLengthMm) - Number(opening?.widthMm ?? opening?.width);
    if (!binding || !hostEdge || !Number.isFinite(next) || !Number.isFinite(current) || !unit || !(maximum >= 0) || next < 0 || next > maximum) {
      return false;
    }
    opening.pdfCanonicalWallStartOffsetMm = r6RoundNumber(next);
    opening.positionOnWallMm = r6RoundNumber(next);
    opening.offset = r6RoundNumber(next);
    opening.offsetMm = r6RoundNumber(next);
    syncPdfOpeningCanonicalGeometry(opening);
    if (options.userEdited !== false) {
      opening.pdfSourcePositionUserEdited = true;
      opening.pdfSourceUserEditProvenance = { ...(opening.pdfSourceUserEditProvenance || {}), position: true };
    }
    return true;
  }

  function r6OpeningCenterOnWall(wall, opening) {
    if (!wall || !r6FinitePoint(wall.from) || !r6FinitePoint(wall.to)) return null;
    const length = r6PointDistance(wall.from, wall.to);
    const width = Number(opening.widthMm ?? opening.width);
    const offset = Number(opening.offsetMm ?? opening.offset ?? opening.positionOnWallMm);
    if (!(length > 0) || !(width > 0) || !Number.isFinite(offset)) return null;
    const distance = Math.max(0, Math.min(length, offset + width / 2));
    return {
      x: wall.from.x + (wall.to.x - wall.from.x) * distance / length,
      y: wall.from.y + (wall.to.y - wall.from.y) * distance / length
    };
  }

  function r6DistanceToEdge(point, edge) {
    if (!r6FinitePoint(point) || !edge || !r6FinitePoint(edge.from) || !r6FinitePoint(edge.to)) return Infinity;
    const dx = edge.to.x - edge.from.x;
    const dy = edge.to.y - edge.from.y;
    const lengthSquared = dx * dx + dy * dy;
    if (!(lengthSquared > 0)) return Infinity;
    const t = Math.max(0, Math.min(1, ((point.x - edge.from.x) * dx + (point.y - edge.from.y) * dy) / lengthSquared));
    return Math.hypot(point.x - (edge.from.x + dx * t), point.y - (edge.from.y + dy * t));
  }

  function r6BindOpeningToCurrentWallEdge(currentProject, opening) {
    const wall = r6OpeningHostWall(currentProject, opening);
    const sourceHost = getPdfSourceOpeningHostEdge(opening);
    const sourceHostWidth = Number(opening.widthMm ?? opening.width);
    if (wall && sourceHost && sourceHost.id === opening.edgeId && Number(sourceHost.length) >= sourceHostWidth) {
      opening.wallId = wall.id;
      opening.hostWallId = wall.id;
      return true;
    }
    const edges = r6OpeningEdgesForWall(currentProject, wall);
    const width = Number(opening.widthMm ?? opening.width);
    if (!wall || !edges.length || !(width > 0)) return false;
    const current = edges.find((edge) => edge.id === opening.edgeId && Number(edge.length) >= width);
    if (current) {
      opening.wallId = wall.id;
      opening.hostWallId = wall.id;
      return true;
    }
    const center = r6OpeningCenterOnWall(wall, opening);
    if (!center) return false;
    const candidates = edges
      .filter((edge) => Number(edge.length) >= width)
      .map((edge) => ({ edge, distance: r6DistanceToEdge(center, edge) }))
      .sort((left, right) => left.distance - right.distance || String(left.edge.id).localeCompare(String(right.edge.id), undefined, { numeric: true }));
    const chosen = candidates[0];
    if (!chosen || chosen.distance > 1) return false;
    const along = Math.max(0, Math.min(Number(chosen.edge.length), projectPointDistanceOnEdge(center, chosen.edge)));
    const offset = Math.max(0, Math.min(Number(chosen.edge.length) - width, along - width / 2));
    opening.edgeId = chosen.edge.id;
    opening.wallId = wall.id;
    opening.hostWallId = wall.id;
    opening.offset = r6RoundNumber(offset);
    opening.offsetMm = r6RoundNumber(offset);
    opening.positionOnWallMm = r6RoundNumber(offset);
    return true;
  }

  function migratePersistedAcceptedPdfOpeningMetrics(currentProject) {
    const acceptedTransformId = acceptedScaleTransformId(currentProject);
    const factor = Number(currentProject?.scale?.geometryScaleFactor);
    if (!acceptedTransformId || !Number.isFinite(factor) || factor <= 0) return false;
    let changed = false;
    (currentProject.openings || []).forEach((opening) => {
      if (!isPlainObject(opening) || !isExistingPdfObject(opening) || opening.r6AppliedTransformId !== acceptedTransformId) return;
      if (opening.r6AppliedOpeningMetricTransformId !== acceptedTransformId) {
        r6AcceptedOpeningMetricKeys().forEach((key) => {
          if (Object.prototype.hasOwnProperty.call(opening, key) && Number.isFinite(Number(opening[key]))) {
            opening[key] = r6RoundNumber(Number(opening[key]) * factor);
          }
        });
        opening.r6AppliedOpeningMetricTransformId = acceptedTransformId;
        changed = true;
      }
      const bindingBefore = JSON.stringify({ edgeId: opening.edgeId || null, wallId: opening.wallId || null, hostWallId: opening.hostWallId || null, offset: opening.offset ?? null, offsetMm: opening.offsetMm ?? null, positionOnWallMm: opening.positionOnWallMm ?? null });
      const rebound = r6BindOpeningToCurrentWallEdge(currentProject, opening);
      const bindingAfter = JSON.stringify({ edgeId: opening.edgeId || null, wallId: opening.wallId || null, hostWallId: opening.hostWallId || null, offset: opening.offset ?? null, offsetMm: opening.offsetMm ?? null, positionOnWallMm: opening.positionOnWallMm ?? null });
      if (rebound && bindingAfter !== bindingBefore) changed = true;
    });
    return changed;
  }

  function migratePersistedPdfOpeningSourceAlignment(currentProject) {
    const acceptedTransformId = acceptedScaleTransformId(currentProject);
    const alignmentTransformId = acceptedTransformId ? `${acceptedTransformId}:source-gap-host-v14-full-source-wall` : null;
    const acceptedWorldMmPerPt = getPdfAcceptedWorldMmPerPt(currentProject);
    if (!alignmentTransformId || !Number.isFinite(acceptedWorldMmPerPt) || acceptedWorldMmPerPt <= 0) return false;
    const walls = (currentProject?.walls || []).filter(isPdfDerivedExistingObject);
    if (!walls.length) return false;
    let changed = false;
    (currentProject?.openings || []).filter(isPdfDerivedExistingObject).forEach((opening) => {
      if (opening.pdfSourceAlignmentTransformId === alignmentTransformId) return;
      const binding = resolvePdfOpeningCanonicalHostBinding(opening, currentProject);
      if (!binding || binding.ambiguous || binding.sourceHostEvidenceStatus !== "source_bound") return;
      let width = Number(opening.width ?? opening.widthMm);
      const expectedWidth = Number(binding.expectedOpeningWidthMm);
      const explicitWidthEdit = opening?.pdfSourceUserEditProvenance?.width === true ||
        opening.pdfSourceDimensionUserEdited === true;
      const explicitPositionEdit = opening?.pdfSourceUserEditProvenance?.position === true ||
        opening.pdfSourcePositionUserEdited === true;
      if (!(width > 0) && expectedWidth > 0) {
        width = r6RoundNumber(expectedWidth);
      }
      if (!(width > 0)) return;
      if (
        !explicitWidthEdit &&
        expectedWidth > 0 &&
        Math.abs(width - expectedWidth) > Math.max(0.01, acceptedWorldMmPerPt * 0.001)
      ) {
        width = r6RoundNumber(expectedWidth);
      }
      opening.width = width;
      opening.widthMm = width;
      if (explicitWidthEdit) opening.pdfSourceDimensionUserEdited = true;
      const unit = binding.axisUnit;
      // PDF wall vectors may be split at door/window gaps. Keep a dedicated
      // source-bound virtual edge, but span the proven full source wall so valid
      // position and width edits are not clamped to the original gap width.
      const hostLength = Number(binding.sourceWallLengthMm);
      const sourceHostFrom = {
        x: Number(binding.sourceAxisOriginPt.x) * acceptedWorldMmPerPt,
        y: Number(binding.sourceAxisOriginPt.y) * acceptedWorldMmPerPt
      };
      const sourceHostEdge = {
        id: createPdfSourceOpeningHostEdgeId(opening),
        sourceWallId: binding.hostWallSourceId,
        from: {
          x: r6RoundNumber(sourceHostFrom.x),
          y: r6RoundNumber(sourceHostFrom.y)
        },
        to: {
          x: r6RoundNumber(sourceHostFrom.x + unit.x * hostLength),
          y: r6RoundNumber(sourceHostFrom.y + unit.y * hostLength)
        },
        length: r6RoundNumber(hostLength),
        thickness: Number(walls.find((wall) => wall.id === binding.hostWallId)?.thickness) || DEFAULT_WALL_THICKNESS,
        status: normalizeWallStatus(walls.find((wall) => wall.id === binding.hostWallId)?.status),
        wallType: normalizeWallType(walls.find((wall) => wall.id === binding.hostWallId)?.wallType),
        layer: walls.find((wall) => wall.id === binding.hostWallId)?.layer || "walls",
        sourceOpeningHostOnly: true,
        sourceExpectedCenterPt: {
          x: r6RoundNumber(binding.expectedCenterPt.x),
          y: r6RoundNumber(binding.expectedCenterPt.y)
        }
      };
      const sourceDefaultOffset = Number(binding.expectedOpeningStartOffsetMm);
      const userOffset = getOpeningCanonicalWallPositionMm(opening);
      const maximumOffset = Math.max(0, hostLength - width);
      const selectedOffset = explicitPositionEdit && Number.isFinite(userOffset)
        ? userOffset
        : sourceDefaultOffset;
      const offset = r6RoundNumber(Math.min(Math.max(selectedOffset, 0), maximumOffset));
      opening.pdfSourceHostEdge = sourceHostEdge;
      opening.edgeId = sourceHostEdge.id;
      opening.wallId = binding.hostWallId;
      opening.hostWallId = binding.hostWallId;
      opening.sourceWallId = binding.hostWallSourceId;
      opening.offset = offset;
      opening.offsetMm = offset;
      opening.positionOnWallMm = offset;
      opening.pdfCanonicalWallStartOffsetMm = offset;
      opening.pdfCanonicalHostBinding = binding;
      syncPdfOpeningCanonicalGeometry(opening);
      opening.pdfSourceDimensionUserEdited = explicitWidthEdit;
      opening.pdfSourcePositionUserEdited = explicitPositionEdit;
      if (explicitWidthEdit || explicitPositionEdit) {
        opening.pdfSourceUserEditProvenance = {
          ...(opening.pdfSourceUserEditProvenance || {}),
          ...(explicitWidthEdit ? { width: true } : {}),
          ...(explicitPositionEdit ? { position: true } : {})
        };
      }
      opening.pdfSourceAlignmentTransformId = alignmentTransformId;
      changed = true;
    });
    return changed;
  }

  function migratePersistedAcceptedZonePolygon(zone, currentProject) {
    if (!isPlainObject(zone) || !isExistingPdfObject(zone) || zone.sourcePolygonProven !== true) {
      return;
    }
    const acceptedTransformId = acceptedScaleTransformId(currentProject);
    const appliedTransformId = String(zone.r6AppliedTransformId || "");
    const polygonTransformId = String(zone.r6AppliedPolygonTransformId || "");
    const factor = Number(zone.r6AppliedGeometryScaleFactor || currentProject?.scale?.geometryScaleFactor);
    if (!acceptedTransformId || appliedTransformId !== acceptedTransformId || polygonTransformId === acceptedTransformId || !Number.isFinite(factor) || factor <= 0) {
      return;
    }
    if (!Array.isArray(zone.polygon) || zone.polygon.length < 3 || !zone.polygon.every(r6FinitePoint)) {
      return;
    }
    zone.polygon = zone.polygon.map((point) => r6ScalePointValue(point, factor));
    zone.r6AppliedPolygonTransformId = acceptedTransformId;
    zone.polygonCoordinateFrame = "accepted-live-mm";
    invalidateZoneAreaConfirmation(zone);
  }

  function parsePersistedWorkingDraftRecord(raw, storageKey, allowLegacyStorageKey = false) {
    const record = JSON.parse(raw);
    const schemaSupported = record && (
      record.schema === WORKING_DRAFT_STORAGE_SCHEMA ||
      LEGACY_WORKING_DRAFT_STORAGE_SCHEMAS.has(record.schema)
    );
    if (!schemaSupported) return null;
    const restoredProject = normalizePersistedWorkingDraftProject(record.project);
    if (!restoredProject) return null;
    const sourceAudit = auditProjectSourceBinding(restoredProject, record.sourceBinding);
    if (!sourceAudit.pass) {
      workingDraftRestoreBlockedReason = sourceAudit.reason;
      return null;
    }
    restoredProject.sourceBinding = sourceAudit.binding;
    const scopedStorageKey = createScopedWorkingDraftStorageKey(restoredProject, sourceAudit.binding);
    if (!allowLegacyStorageKey && storageKey !== scopedStorageKey) {
      workingDraftRestoreBlockedReason = "working_draft_scope_key_mismatch";
      return null;
    }
    return {
      project: restoredProject,
      savedAt: typeof record.savedAt === "string" ? record.savedAt : null,
      sourceBinding: sourceAudit.binding,
      scopedStorageKey,
      migratedSourceBinding: record.schema !== WORKING_DRAFT_STORAGE_SCHEMA,
      record
    };
  }

  function createActiveWorkingDraftPointer(storageKey, sourceBinding, updatedAt = new Date().toISOString()) {
    return {
      schema: "laibe.planPuzzle.activeWorkingDraft.v1",
      storageKey,
      sourceBinding: sourceBinding ? cloneJson(sourceBinding) : null,
      updatedAt
    };
  }

  function loadPersistedWorkingDraft() {
    try {
      const pointerRaw = window.localStorage.getItem(ACTIVE_WORKING_DRAFT_POINTER_KEY);
      if (pointerRaw) {
        const pointer = JSON.parse(pointerRaw);
        const storageKey = String(pointer?.storageKey || "");
        if (pointer?.schema !== "laibe.planPuzzle.activeWorkingDraft.v1" || !storageKey.startsWith(WORKING_DRAFT_STORAGE_KEY_PREFIX)) {
          workingDraftRestoreBlockedReason = "working_draft_pointer_invalid";
          return null;
        }
        const scopedRaw = window.localStorage.getItem(storageKey);
        if (!scopedRaw) {
          workingDraftRestoreBlockedReason = "working_draft_pointer_target_missing";
          return null;
        }
        const restored = parsePersistedWorkingDraftRecord(scopedRaw, storageKey, false);
        if (!restored) return null;
        const pointerScope = resolveWorkingDraftScope(restored.project, pointer.sourceBinding);
        const recordScope = resolveWorkingDraftScope(restored.project, restored.sourceBinding);
        if (
          createScopedWorkingDraftStorageKey(restored.project, pointer.sourceBinding) !== storageKey ||
          JSON.stringify(pointerScope) !== JSON.stringify(recordScope)
        ) {
          workingDraftRestoreBlockedReason = "working_draft_pointer_scope_mismatch";
          return null;
        }
        activeWorkingDraftStorageKey = storageKey;
        activeWorkingDraftPointerJson = pointerRaw;
        return restored;
      }

      // The legacy global slot is inspected at most once. Its bytes are copied
      // into the source-scoped store and intentionally left untouched.
      if (window.localStorage.getItem(LEGACY_WORKING_DRAFT_MIGRATION_KEY)) {
        return null;
      }
      const attemptedAt = new Date().toISOString();
      const legacyRaw = window.localStorage.getItem(LEGACY_WORKING_DRAFT_STORAGE_KEY);
      if (!legacyRaw) {
        window.localStorage.setItem(LEGACY_WORKING_DRAFT_MIGRATION_KEY, JSON.stringify({
          schema: "laibe.planPuzzle.workingDraftLegacyMigration.v1",
          status: "legacy_slot_empty",
          attemptedAt
        }));
        return null;
      }
      const restored = parsePersistedWorkingDraftRecord(legacyRaw, LEGACY_WORKING_DRAFT_STORAGE_KEY, true);
      if (!restored) {
        window.localStorage.setItem(LEGACY_WORKING_DRAFT_MIGRATION_KEY, JSON.stringify({
          schema: "laibe.planPuzzle.workingDraftLegacyMigration.v1",
          status: "legacy_record_rejected",
          reason: workingDraftRestoreBlockedReason || "legacy_record_invalid",
          attemptedAt
        }));
        return null;
      }
      const migratedAt = new Date().toISOString();
      const existingScopedRaw = window.localStorage.getItem(restored.scopedStorageKey);
      if (existingScopedRaw) {
        const existingScoped = parsePersistedWorkingDraftRecord(existingScopedRaw, restored.scopedStorageKey, false);
        if (!existingScoped) {
          window.localStorage.setItem(LEGACY_WORKING_DRAFT_MIGRATION_KEY, JSON.stringify({
            schema: "laibe.planPuzzle.workingDraftLegacyMigration.v1",
            status: "existing_scoped_record_conflict",
            storageKey: restored.scopedStorageKey,
            attemptedAt: migratedAt
          }));
          return null;
        }
        const pointer = createActiveWorkingDraftPointer(restored.scopedStorageKey, existingScoped.sourceBinding, migratedAt);
        const pointerJson = JSON.stringify(pointer);
        window.localStorage.setItem(ACTIVE_WORKING_DRAFT_POINTER_KEY, pointerJson);
        window.localStorage.setItem(LEGACY_WORKING_DRAFT_MIGRATION_KEY, JSON.stringify({
          schema: "laibe.planPuzzle.workingDraftLegacyMigration.v1",
          status: "existing_scoped_record_preserved",
          storageKey: restored.scopedStorageKey,
          migratedAt
        }));
        activeWorkingDraftStorageKey = restored.scopedStorageKey;
        activeWorkingDraftPointerJson = pointerJson;
        return existingScoped;
      }
      const migratedRecord = {
        schema: WORKING_DRAFT_STORAGE_SCHEMA,
        savedAt: restored.savedAt || migratedAt,
        sourceBinding: restored.sourceBinding,
        storageScope: resolveWorkingDraftScope(restored.project, restored.sourceBinding),
        migratedFromLegacyGlobalKey: true,
        migratedAt,
        project: restored.project,
        budgetDecisionFacts: restored.record.budgetDecisionFacts || createConfirmedBudgetDecisionFacts(restored.project, migratedAt)
      };
      const migratedJson = JSON.stringify(migratedRecord);
      const pointer = createActiveWorkingDraftPointer(restored.scopedStorageKey, restored.sourceBinding, migratedAt);
      const pointerJson = JSON.stringify(pointer);
      window.localStorage.setItem(restored.scopedStorageKey, migratedJson);
      window.localStorage.setItem(ACTIVE_WORKING_DRAFT_POINTER_KEY, pointerJson);
      window.localStorage.setItem(LEGACY_WORKING_DRAFT_MIGRATION_KEY, JSON.stringify({
        schema: "laibe.planPuzzle.workingDraftLegacyMigration.v1",
        status: "migrated_without_deleting_legacy",
        storageKey: restored.scopedStorageKey,
        legacyByteLength: new TextEncoder().encode(legacyRaw).byteLength,
        migratedAt
      }));
      activeWorkingDraftStorageKey = restored.scopedStorageKey;
      activeWorkingDraftPointerJson = pointerJson;
      return restored;
    } catch (error) {
      workingDraftRestoreBlockedReason = "working_draft_storage_unavailable";
      return null;
    }
  }

  function compactR6ImportReceiptForWorkingDraft(receipt) {
    if (!isPlainObject(receipt)) {
      return null;
    }
    return {
      status: receipt.status || null,
      importSessionId: receipt.importSessionId || null,
      caseId: receipt.caseId || null,
      actorId: receipt.actorId || null,
      file: isPlainObject(receipt.file) ? cloneJson(receipt.file) : null,
      source: isPlainObject(receipt.source) ? cloneJson(receipt.source) : null,
      runtime: isPlainObject(receipt.runtime) ? cloneJson(receipt.runtime) : null,
      importer: isPlainObject(receipt.importer) ? cloneJson(receipt.importer) : null,
      dimensionScale: isPlainObject(receipt.dimensionScale) ? cloneJson(receipt.dimensionScale) : null,
      regions: isPlainObject(receipt.regions) ? {
        coordinateTransform: isPlainObject(receipt.regions.coordinateTransform)
          ? cloneJson(receipt.regions.coordinateTransform)
          : null
      } : null,
      restoredFromWorkingDraft: true
    };
  }

  function createWorkingDraftProjectSnapshot(currentProject = project) {
    const snapshot = cloneJson(currentProject);
    if (isPlainObject(snapshot.r6Review)) {
      snapshot.r6Review.importReceipt = compactR6ImportReceiptForWorkingDraft(snapshot.r6Review.importReceipt);
      if (isPlainObject(snapshot.r6Review.calibrationReceipt?.application)) {
        snapshot.r6Review.calibrationReceipt.application = compactR6CalibrationApplication(snapshot.r6Review.calibrationReceipt.application);
      }
      delete snapshot.r6Review.calibrationPredicateFixtures;
      delete snapshot.r6Review.typedCalibrationApplicationFixtures;
      delete snapshot.r6Review.atomicCalibrationApplicationFixtures;
      delete snapshot.r6Review.r7DimensionScaleFixtures;
    }
    (snapshot.caseEvents || []).forEach((event) => {
      if (isPlainObject(event?.evidence?.application)) {
        event.evidence.application = compactR6CalibrationApplication(event.evidence.application);
      }
    });
    return snapshot;
  }

  function compactR6CalibrationApplication(application) {
    if (!isPlainObject(application)) return null;
    return {
      pass: application.pass === true,
      reason: application.reason || null,
      appliedCount: Number(application.appliedCount || 0),
      applicableCount: Number(application.applicableCount || 0),
      appliedTransformId: application.appliedTransformId || null,
      geometryScaleFactor: Number(application.geometryScaleFactor) || null,
      acceptedWorldMmPerPt: Number(application.acceptedWorldMmPerPt) || null,
      underlayStatus: application.underlayStatus || null,
      graphIntegrity: isPlainObject(application.graphIntegrity) ? {
        pass: application.graphIntegrity.pass === true,
        edgeCount: Number(application.graphIntegrity.edgeCount || 0),
        failureCount: Array.isArray(application.graphIntegrity.failures) ? application.graphIntegrity.failures.length : 0,
        noStalePreScaleEndpoints: application.graphIntegrity.noStalePreScaleEndpoints === true
      } : null,
      metadataClosure: isPlainObject(application.metadataClosure) ? {
        pass: application.metadataClosure.pass === true,
        surfaceClosure: application.metadataClosure.surfaceClosure === true,
        itemClosure: application.metadataClosure.itemClosure === true
      } : null
    };
  }

  function persistWorkingDraft() {
    workingDraftPersistTimer = 0;
    if (uiState.importPhase === "loading" || sourceImportCommitInProgress || workingDraftPersistenceBlocked) {
      return;
    }
    try {
      const projectSnapshot = createWorkingDraftProjectSnapshot(project);
      const sourceAudit = auditProjectSourceBinding(projectSnapshot, projectSnapshot.sourceBinding);
      if (!sourceAudit.pass) {
        throw new Error("目前圖面與物件來源不一致，草稿未儲存。");
      }
      projectSnapshot.sourceBinding = sourceAudit.binding;
      const projectJson = JSON.stringify(projectSnapshot);
      if (projectJson === lastPersistedWorkingDraftJson) {
        return;
      }
      const savedAt = new Date().toISOString();
      const storageKey = createScopedWorkingDraftStorageKey(projectSnapshot, sourceAudit.binding);
      const record = {
        schema: WORKING_DRAFT_STORAGE_SCHEMA,
        savedAt,
        sourceBinding: sourceAudit.binding,
        storageScope: resolveWorkingDraftScope(projectSnapshot, sourceAudit.binding),
        project: projectSnapshot,
        budgetDecisionFacts: createConfirmedBudgetDecisionFacts(projectSnapshot, savedAt)
      };
      const pointer = createActiveWorkingDraftPointer(storageKey, sourceAudit.binding, savedAt);
      const pointerJson = JSON.stringify(pointer);
      // Commit the scoped record before moving the active pointer. A failed
      // record write therefore cannot redirect boot to a partial draft.
      window.localStorage.setItem(storageKey, JSON.stringify(record));
      window.localStorage.setItem(ACTIVE_WORKING_DRAFT_POINTER_KEY, pointerJson);
      activeWorkingDraftStorageKey = storageKey;
      activeWorkingDraftPointerJson = pointerJson;
      lastPersistedWorkingDraftJson = projectJson;
      workingDraftPersistenceFailureReported = false;
    } catch (error) {
      if (!workingDraftPersistenceFailureReported) {
        workingDraftPersistenceFailureReported = true;
        showLoop74Toast("本機草稿尚未儲存，請先匯出備份後再繼續。", "error");
      }
    }
  }

  function restoreWorkingDraftFromProductControl() {
    const restored = loadPersistedWorkingDraft();
    if (!restored?.project) {
      uiState.error = "找不到可恢復的本機草稿，請先完成一次儲存。";
      uiState.message = "";
      render();
      return { ok: false, error: "working draft unavailable" };
    }
    clearSourceBoundPendingTimers();
    project = restored.project;
    invalidateNativeWallGeometryV3();
    uiState = createInitialUIState();
    uiState.layerVisibility = normalizeLayerVisibility(project.viewPreferences?.layerVisibility);
    uiState.importPhase = project.importSource ? "imported" : "idle";
    uiState.inspectorTab = project.nativePdfScaleConfirmation?.status === "waiting_for_confirmation"
      ? "overview"
      : "properties";
    uiState.message = "已恢復本機草稿，可繼續檢查與編輯。";
    uiState.error = "";
    undoStack = [];
    redoStack = [];
    workingDraftPersistenceBlocked = false;
    workingDraftRestoreBlockedReason = null;
    sourceImportCommitInProgress = false;
    resetTransientPointerState();
    rebuildWallGraph();
    rebuildNodeGraph();
    if (project.underlay && uiState.layerVisibility.underlay === false) {
      fitPlanContentToView({ message: false, render: false });
    }
    render();
    return {
      ok: true,
      savedAt: restored.savedAt || null,
      sourceBinding: cloneJson(restored.sourceBinding || project.sourceBinding || null)
    };
  }

  function scheduleWorkingDraftPersistence() {
    window.clearTimeout(workingDraftPersistTimer);
    workingDraftPersistTimer = window.setTimeout(persistWorkingDraft, 250);
  }

  function acceptedScaleTransformId(currentProject = project) {
    const candidates = [
      currentProject?.scale?.acceptedTransformId,
      currentProject?.importSource?.acceptedTransformId,
      currentProject?.r6Review?.calibrationReceipt?.acceptedTransformId,
      currentProject?.r4b1Review?.calibrationReceipt?.acceptedTransformId,
      currentProject?.lastPdfObjectizationSceneImport?.acceptedTransformId,
      currentProject?.pdfReviewObjects?.importMetrics?.scalePolicy?.acceptedTransformId
    ];
    const accepted = candidates.find((value) => typeof value === "string" && value.trim());
    return accepted ? accepted.trim() : null;
  }

  function createConfirmedBudgetDecisionFacts(currentProject = project, generatedAt = new Date().toISOString()) {
    const sourceProject = currentProject || project;
    const acceptedTransformId = acceptedScaleTransformId(sourceProject);
    const zones = Array.isArray(sourceProject?.zones) ? sourceProject.zones : [];
    const areaEvents = (Array.isArray(sourceProject?.caseEvents) ? sourceProject.caseEvents : [])
      .filter((event) => event && event.action === "zone_area_confirmation" && event.decision_status === "confirmed_existing_zone_area");
    const findAreaEvent = (zone) => areaEvents
      .filter((event) => event?.evidence?.editableObjectId === zone.id)
      .sort((left, right) => String(right.occurred_at || "").localeCompare(String(left.occurred_at || "")))[0] || null;
    const confirmedAreas = zones
      .filter((zone) => Boolean(
        zone &&
        zone.userSemanticConfirmed === true &&
        zone.boundaryStatus === "closed" &&
        zone.areaConfirmed === true &&
        Number.isFinite(Number(zone.area)) &&
        Number(zone.area) > 0 &&
        acceptedTransformId &&
        zone.areaConfirmedTransformId === acceptedTransformId
      ))
      .map((zone) => {
        const areaMm2 = Math.round(Number(zone.area));
        const event = findAreaEvent(zone);
        return {
          zoneId: zone.id,
          displayName: String(zone.name || "已確認空間").trim() || "已確認空間",
          areaMm2,
          areaM2: roundQuantityFactNumber(areaMm2 / 1000000, 3),
          sourceLabel: "實際匯入圖面",
          basisLabel: "已確認比例＋封閉邊界＋使用者明確確認",
          semanticConfirmed: true,
          boundaryConfirmed: true,
          areaConfirmed: true,
          areaConfirmedAt: zone.areaConfirmedAt || event?.occurred_at || null,
          acceptedTransformId,
          traceEventId: event?.event_id || null,
          traceRecorded: Boolean(event),
          reviewerRequiredForAreaValue: false,
          remainingReviewLabel: "材質、工法、單價與現場條件仍需人工確認"
        };
      })
      .sort((left, right) => String(left.zoneId).localeCompare(String(right.zoneId)));
    const totalAreaMm2 = confirmedAreas.reduce((sum, item) => sum + item.areaMm2, 0);
    return {
      schema: "laibe.planPuzzle.confirmedBudgetDecisionFacts.v1",
      generatedAt,
      planId: sourceProject?.id || sourceProject?.planId || "plan-puzzle-local",
      acceptedTransformId,
      sourceZoneCount: zones.length,
      confirmedAreaCount: confirmedAreas.length,
      pendingAreaCount: Math.max(0, zones.length - confirmedAreas.length),
      confirmedAreaTotalMm2: totalAreaMm2,
      confirmedAreaTotalM2: roundQuantityFactNumber(totalAreaMm2 / 1000000, 3),
      confirmedAreas,
      confirmedQuantityValuesOnly: true,
      unconfirmedAreaValuesIncluded: false,
      formalEstimate: false,
      budgetEngineCalled: false,
      pricingIncluded: false,
      remainingReviewRequired: true
    };
  }

  function derivePlanWorkflowState(currentProject = project, currentUiState = uiState, importBusy = r6ImportInFlight) {
    const source = currentProject?.importSource || null;
    const blankDraft = source?.normalizedAs === "blank-mm-draft";
    const sourceImported = Boolean(source && !blankDraft);
    const sourcePresentationWaiting = source?.normalizedAs === "pdf-source-presentation";
    const importPhase = String(currentUiState?.importPhase || "idle");
    const acceptedTransformId = acceptedScaleTransformId(currentProject);
    const evidence = currentProject?.r6Review?.importReceipt?.dimensionScale || currentProject?.r6Review?.dimensionScaleEvidence || null;
    const evidenceStatus = String(evidence?.status || "");
    const automaticScaleReady = Boolean(
      evidence &&
      evidenceStatus === "ready_for_scale_acceptance" &&
      evidence?.consensus?.pass === true &&
      evidence?.unitProposal?.conclusive === true &&
      evidence?.unitProposal?.survivingHypothesisCount === 1
    );
    const dimensionScaleReviewAction = (() => {
      const candidates = Array.isArray(evidence?.candidates) ? evidence.candidates : [];
      const consensus = evidence?.consensus || {};
      if (candidates.length < 3) return "至少需要三組可相互核對的尺寸線與尺寸數字";
      if (evidence?.unitProposal?.conclusive !== true || evidence?.unitProposal?.survivingHypothesisCount !== 1) return "確認圖面上的尺寸單位是否清楚且一致";
      if (consensus.coveragePass !== true) return "補足圖面中缺少的水平或垂直尺寸依據";
      if (!(Number(consensus.coefficientOfVariation) <= 0.005)) return "檢查彼此換算比例不一致的尺寸標註";
      if (Array.isArray(consensus.deviations) && consensus.deviations.some((row) => Number(row?.relativeDeviation) > 0.0075)) return "檢查偏離其他尺寸標註的數字或尺寸線";
      if (consensus.residualPass !== true) {
        const worst = candidates.slice().sort((left, right) => Number(right?.residualPt || 0) - Number(left?.residualPt || 0))[0];
        return worst?.rawLabel
          ? `檢查標註「${worst.rawLabel}」與其尺寸線端點是否正確對應`
          : "檢查無法準確回推到原尺寸線的標註";
      }
      if (Array.isArray(evidence?.pairingRejections) && evidence.pairingRejections.length) return "檢查缺少端點、延伸線或箭頭依據的尺寸標註";
      return "重新檢查尺寸線與尺寸數字的對應";
    })();

    let key = "no_source";
    if (importBusy || importPhase === "loading") key = "loading";
    else if (importPhase === "failed" || currentUiState?.importError) key = "import_failed";
    else if (acceptedTransformId) key = "scale_accepted";
    else if (!sourceImported) key = "no_source";
    else if (sourcePresentationWaiting) key = "source_presentation_waiting";
    else if (!evidence) key = "automatic_analysis_pending";
    else if (automaticScaleReady) key = "automatic_dimension_scale_ready";
    else key = "manual_fallback";

    const states = {
      no_source: {
        workflowStep: 1,
        importLabel: "尚未匯入圖面",
        scaleLabel: "尚未建立比例",
        summary: "匯入底圖，或直接使用空白毫米草稿。",
        nextAction: "匯入底圖"
      },
      loading: {
        workflowStep: 1,
        importLabel: "正在匯入圖面",
        scaleLabel: "等待圖面匯入完成",
        summary: "正在整理圖面，完成前不會套用比例或建立物件。",
        nextAction: "等待匯入完成"
      },
      import_failed: {
        workflowStep: 1,
        importLabel: "圖面匯入未完成",
        scaleLabel: "尚未建立比例",
        summary: "請確認檔案格式後重新選擇圖面。",
        nextAction: "重新選擇圖面"
      },
      source_presentation_waiting: {
        workflowStep: 2,
        importLabel: "PDF 底圖已匯入",
        scaleLabel: "比例待人工確認",
        summary: "目前只顯示選取的 PDF 頁面，尚未建立可編輯物件。",
        nextAction: "等待圖面辨識資料，並由使用者確認比例"
      },
      automatic_analysis_pending: {
        workflowStep: 2,
        importLabel: "圖面已匯入",
        scaleLabel: "正在整理尺寸依據",
        summary: "圖面已匯入，正在整理可用的尺寸依據。",
        nextAction: "等待尺寸分析"
      },
      automatic_dimension_scale_ready: {
        workflowStep: 2,
        importLabel: "圖面已匯入",
        scaleLabel: "已取得一致尺寸依據",
        summary: "系統已依圖面標註尺寸取得一致比例，正在套用到圖面物件。",
        nextAction: "查看自動比例結果"
      },
      manual_fallback: {
        workflowStep: 2,
        importLabel: "圖面已匯入",
        scaleLabel: "自動比例尚未確認",
        summary: "圖面標註尺寸不足、互相衝突或單位不明，系統不會套用猜測比例。",
        nextAction: dimensionScaleReviewAction
      },
      scale_accepted: {
        workflowStep: 3,
        importLabel: "圖面已匯入",
        scaleLabel: "比例已確認",
        summary: "比例已確認，可以整理牆線、門窗、空間與物件。",
        nextAction: "整理圖面物件"
      }
    };
    return {
      key,
      ...states[key],
      sourceImported,
      blankDraft,
      acceptedTransformId,
      scaleAccepted: Boolean(acceptedTransformId),
      automaticScaleReady,
      showUnitConfirmation: false,
      showManualFallback: key === "source_presentation_waiting",
      evidenceStatus
    };
  }

