  function createInitialLayerVisibility() {
    return {
      underlay: true,
      walls: true,
      openings: true,
      structures: true,
      review: false,
      zones: true,
      zoneReview: false,
      furniture: true,
      diagnostics: false
    };
  }

  function normalizeLayerVisibility(value) {
    const defaults = createInitialLayerVisibility();
    if (!isPlainObject(value)) return defaults;
    return Object.keys(defaults).reduce((result, key) => {
      result[key] = typeof value[key] === "boolean" ? value[key] : defaults[key];
      return result;
    }, {});
  }

  function cloneJson(value) {
    return JSON.parse(JSON.stringify(value));
  }

  function isR6ReviewActive() {
    return Boolean(project.r6Review && project.r6Review.importReceipt);
  }

  function r6StableToken(value) {
    return r4b1StableHash(value);
  }

  const R6_SOURCE_POINT_FRAME = "page-bottom-left-pdf-pt";
  const R6_PROVISIONAL_LIVE_FRAME = "plan-puzzle-provisional-live-mm";
  const R6_ACCEPTED_LIVE_FRAME = "plan-puzzle-accepted-live-mm";
  const R6_DISPLAY_POINT_FRAME = "canvas-local-display-px";
  const R6_CALIBRATION_RESIDUAL_TOLERANCE_PT = 0.25;
  const r6CapturedCalibrationEvents = new WeakSet();

  function r6FinitePoint(value) {
    return Boolean(value && Number.isFinite(value.x) && Number.isFinite(value.y));
  }

  function r6RoundPoint(value, precision = 6) {
    if (!r6FinitePoint(value)) return null;
    const multiplier = 10 ** precision;
    return {
      x: Math.round(value.x * multiplier) / multiplier,
      y: Math.round(value.y * multiplier) / multiplier
    };
  }

  function r6PointDistance(from, to) {
    if (!r6FinitePoint(from) || !r6FinitePoint(to)) return NaN;
    return Math.hypot(to.x - from.x, to.y - from.y);
  }

  function r6ProvisionalWorldMmPerPt(sourceProject = project) {
    const candidates = [
      sourceProject && sourceProject.lastPdfObjectizationSceneImport && sourceProject.lastPdfObjectizationSceneImport.scalePolicy && sourceProject.lastPdfObjectizationSceneImport.scalePolicy.worldMmPerPt,
      sourceProject && sourceProject.pdfReviewObjects && sourceProject.pdfReviewObjects.importMetrics && sourceProject.pdfReviewObjects.importMetrics.scalePolicy && sourceProject.pdfReviewObjects.importMetrics.scalePolicy.worldMmPerPt,
      sourceProject && sourceProject.scale && sourceProject.scale.provisionalWorldMmPerPt
    ];
    const value = candidates.map(Number).find((item) => Number.isFinite(item) && item > 0);
    return Number.isFinite(value) && value > 0 ? value : null;
  }

  function r6DisplayPxPerMm(sourceProject = project) {
    const value = Number(sourceProject && sourceProject.scale && sourceProject.scale.pxPerMm);
    return Number.isFinite(value) && value > 0 ? value : null;
  }

  function r6SourcePageHeightPt(review = project.r6Review) {
    const candidates = [
      review?.importReceipt?.regions?.coordinateTransform?.pageHeightPt,
      project?.lastPdfObjectizationSceneImport?.scalePolicy?.sourcePageHeightPt,
      project?.pdfReviewObjects?.importMetrics?.scalePolicy?.sourcePageHeightPt,
      project?.underlay?.sourcePageHeight
    ].map(Number);
    const value = candidates.find((item) => Number.isFinite(item) && item > 0);
    return Number.isFinite(value) && value > 0 ? value : null;
  }

  function r6CreateTypedCalibrationAnchor(canvasPointPx, context = {}) {
    const displayPxPerMm = Number(context.displayPxPerMm);
    const provisionalWorldMmPerPt = Number(context.provisionalWorldMmPerPt);
    if (!r6FinitePoint(canvasPointPx) || !Number.isFinite(displayPxPerMm) || displayPxPerMm <= 0 || !Number.isFinite(provisionalWorldMmPerPt) || provisionalWorldMmPerPt <= 0) {
      return null;
    }
    const provisionalLivePointMm = r6RoundPoint({
      x: canvasPointPx.x / displayPxPerMm,
      y: canvasPointPx.y / displayPxPerMm
    });
    const sourcePageHeightPt = Number(context.sourcePageHeightPt);
    const topLeftSourcePointPt = {
      x: provisionalLivePointMm.x / provisionalWorldMmPerPt,
      y: provisionalLivePointMm.y / provisionalWorldMmPerPt
    };
    const sourcePointPdfPt = r6RoundPoint({
      x: topLeftSourcePointPt.x,
      y: Number.isFinite(sourcePageHeightPt) && sourcePageHeightPt > 0
        ? sourcePageHeightPt - topLeftSourcePointPt.y
        : topLeftSourcePointPt.y
    });
    return {
      schema: "laibe.planPuzzle.r6.calibrationAnchor.v2",
      canvasPointPx: r6RoundPoint(canvasPointPx),
      // Canvas renderers still consume x/y; all R6 calibration rules use the typed fields below.
      x: r6RoundPoint(canvasPointPx).x,
      y: r6RoundPoint(canvasPointPx).y,
      provisionalLivePointMm,
      sourcePointPdfPt,
      coordinateFrames: {
        canvasPointPx: R6_DISPLAY_POINT_FRAME,
        provisionalLivePointMm: R6_PROVISIONAL_LIVE_FRAME,
        sourcePointPdfPt: R6_SOURCE_POINT_FRAME
      },
      conversionProvenance: {
        viewZoom: Number(context.viewZoom),
        canvasPanOffsetPx: r6RoundPoint(context.canvasPanOffsetPx || { x: 0, y: 0 }),
        panAndZoomRemoved: context.panAndZoomRemoved === true,
        displayPxPerMm,
        provisionalWorldMmPerPt,
        importSessionId: String(context.importSessionId || ""),
        sourceSha256: String(context.sourceSha256 || ""),
        sourcePageHeightPt: Number.isFinite(sourcePageHeightPt) && sourcePageHeightPt > 0 ? sourcePageHeightPt : null,
        sourceAxisMapping: Number.isFinite(sourcePageHeightPt) && sourcePageHeightPt > 0
          ? "canvas-top-left-to-pdf-bottom-left"
          : "scene-aligned-x-right-y-up"
      }
    };
  }

  function r6SnapCalibrationAnchorToDimensionEndpoint(anchor, review = project.r6Review) {
    if (!anchor || !r6FinitePoint(anchor.sourcePointPdfPt)) return anchor;
    const pairs = Array.isArray(review?.importReceipt?.dimensionScale?.pairs)
      ? review.importReceipt.dimensionScale.pairs
      : [];
    const endpoints = [];
    pairs.forEach((pair) => {
      const pairEndpoints = pair?.endpointsPdfPt || {};
      ["from", "to"].forEach((role) => {
        if (r6FinitePoint(pairEndpoints[role])) {
          endpoints.push({ pair, role, point: pairEndpoints[role] });
        }
      });
    });
    const nearest = endpoints
      .map((entry) => ({ ...entry, distancePt: r6PointDistance(anchor.sourcePointPdfPt, entry.point) }))
      .sort((left, right) => left.distancePt - right.distancePt || String(left.pair?.id || "").localeCompare(String(right.pair?.id || "")))[0];
    if (!nearest || !(nearest.distancePt <= 12)) return anchor;
    const provenance = anchor.conversionProvenance || {};
    const provisionalWorldMmPerPt = Number(provenance.provisionalWorldMmPerPt);
    const displayPxPerMm = Number(provenance.displayPxPerMm);
    const sourcePageHeightPt = Number(provenance.sourcePageHeightPt);
    if (!(provisionalWorldMmPerPt > 0) || !(displayPxPerMm > 0) || !(sourcePageHeightPt > 0)) return anchor;
    const snappedSourcePoint = r6RoundPoint(nearest.point);
    const snappedProvisionalLivePoint = r6RoundPoint({
      x: snappedSourcePoint.x * provisionalWorldMmPerPt,
      y: (sourcePageHeightPt - snappedSourcePoint.y) * provisionalWorldMmPerPt
    });
    return {
      ...anchor,
      sourcePointPdfPt: snappedSourcePoint,
      provisionalLivePointMm: snappedProvisionalLivePoint,
      dimensionEvidenceId: nearest.pair.id || null,
      dimensionEndpointRole: nearest.role,
      dimensionEndpointSnapped: true,
      conversionProvenance: {
        ...provenance,
        dimensionEndpointSnapDistancePt: r6RoundNumber(nearest.distancePt),
        dimensionEndpointSnapThresholdPt: 12
      }
    };
  }

  function r6IsTypedCalibrationAnchor(anchor) {
    if (!anchor || anchor.schema !== "laibe.planPuzzle.r6.calibrationAnchor.v2") return false;
    const frames = anchor.coordinateFrames || {};
    const provenance = anchor.conversionProvenance || {};
    return r6FinitePoint(anchor.canvasPointPx) &&
      r6FinitePoint(anchor.provisionalLivePointMm) &&
      r6FinitePoint(anchor.sourcePointPdfPt) &&
      frames.canvasPointPx === R6_DISPLAY_POINT_FRAME &&
      frames.provisionalLivePointMm === R6_PROVISIONAL_LIVE_FRAME &&
      frames.sourcePointPdfPt === R6_SOURCE_POINT_FRAME &&
      Number.isFinite(Number(provenance.displayPxPerMm)) && Number(provenance.displayPxPerMm) > 0 &&
      Number.isFinite(Number(provenance.provisionalWorldMmPerPt)) && Number(provenance.provisionalWorldMmPerPt) > 0 &&
      Boolean(String(provenance.importSessionId || "")) &&
      Boolean(String(provenance.sourceSha256 || ""));
  }

  function r6TransformSourcePointToLiveMm(sourcePointPdfPt, worldMmPerPt) {
    const scale = Number(worldMmPerPt);
    if (!r6FinitePoint(sourcePointPdfPt) || !Number.isFinite(scale) || scale <= 0) return null;
    return r6RoundPoint({ x: sourcePointPdfPt.x * scale, y: sourcePointPdfPt.y * scale });
  }

  function r6TransformLivePointToSourcePdfPt(livePointMm, worldMmPerPt) {
    const scale = Number(worldMmPerPt);
    if (!r6FinitePoint(livePointMm) || !Number.isFinite(scale) || scale <= 0) return null;
    return r6RoundPoint({ x: livePointMm.x / scale, y: livePointMm.y / scale });
  }

  function r9TransformSourcePointToLiveMm(sourcePointPdfPt, worldMmPerPtX, worldMmPerPtY) {
    const scaleX = Number(worldMmPerPtX);
    const scaleY = Number(worldMmPerPtY);
    if (!r6FinitePoint(sourcePointPdfPt) || !Number.isFinite(scaleX) || scaleX <= 0 || !Number.isFinite(scaleY) || scaleY <= 0) return null;
    return r6RoundPoint({ x: sourcePointPdfPt.x * scaleX, y: sourcePointPdfPt.y * scaleY });
  }

  function r9TransformLivePointToSourcePdfPt(livePointMm, worldMmPerPtX, worldMmPerPtY) {
    const scaleX = Number(worldMmPerPtX);
    const scaleY = Number(worldMmPerPtY);
    if (!r6FinitePoint(livePointMm) || !Number.isFinite(scaleX) || scaleX <= 0 || !Number.isFinite(scaleY) || scaleY <= 0) return null;
    return r6RoundPoint({ x: livePointMm.x / scaleX, y: livePointMm.y / scaleY });
  }

  function r6BuildTypedCalibrationTransform(selection, normalizedMillimetres) {
    const anchors = Array.isArray(selection && selection.points) ? selection.points : [];
    const from = anchors[0] || null;
    const to = anchors[1] || null;
    const sourceFrom = from && from.sourcePointPdfPt;
    const sourceTo = to && to.sourcePointPdfPt;
    const provisionalWorldMmPerPt = Number(from && from.conversionProvenance && from.conversionProvenance.provisionalWorldMmPerPt);
    const displayPxPerMm = Number(from && from.conversionProvenance && from.conversionProvenance.displayPxPerMm);
    const sourcePageHeightPt = Number(from && from.conversionProvenance && from.conversionProvenance.sourcePageHeightPt) || null;
    const sourceDistancePt = r6PointDistance(sourceFrom, sourceTo);
    const acceptedWorldMmPerPt = Number(normalizedMillimetres) / sourceDistancePt;
    const geometryScaleFactor = acceptedWorldMmPerPt / provisionalWorldMmPerPt;
    const acceptedFrom = r6TransformSourcePointToLiveMm(sourceFrom, acceptedWorldMmPerPt);
    const acceptedTo = r6TransformSourcePointToLiveMm(sourceTo, acceptedWorldMmPerPt);
    const sourceRoundTripFrom = r6TransformLivePointToSourcePdfPt(acceptedFrom, acceptedWorldMmPerPt);
    const sourceRoundTripTo = r6TransformLivePointToSourcePdfPt(acceptedTo, acceptedWorldMmPerPt);
    const residualsPt = {
      from: r6PointDistance(sourceFrom, sourceRoundTripFrom),
      to: r6PointDistance(sourceTo, sourceRoundTripTo)
    };
    const maxPt = Math.max(residualsPt.from, residualsPt.to);
    return {
      schema: "laibe.planPuzzle.r6.sourceLiveCalibrationTransform.v1",
      sourceFrame: R6_SOURCE_POINT_FRAME,
      provisionalLiveFrame: R6_PROVISIONAL_LIVE_FRAME,
      acceptedLiveFrame: R6_ACCEPTED_LIVE_FRAME,
      displayFrame: R6_DISPLAY_POINT_FRAME,
      sourceEndpointsPdfPt: { from: sourceFrom ? r6RoundPoint(sourceFrom) : null, to: sourceTo ? r6RoundPoint(sourceTo) : null },
      provisionalLiveEndpointsMm: { from: from && r6RoundPoint(from.provisionalLivePointMm), to: to && r6RoundPoint(to.provisionalLivePointMm) },
      acceptedLiveEndpointsMm: { from: acceptedFrom, to: acceptedTo },
      sourceDistancePt,
      provisionalWorldMmPerPt,
      acceptedWorldMmPerPt,
      geometryScaleFactor,
      displayPxPerMm,
      sourcePageHeightPt,
      forward: { sourcePdfPtToLiveMm: { scale: acceptedWorldMmPerPt, sourceFrame: R6_SOURCE_POINT_FRAME, sourceUnit: "pt", targetFrame: R6_ACCEPTED_LIVE_FRAME, targetUnit: "mm", sourcePageHeightPt } },
      inverse: { liveMmToSourcePdfPt: { scale: acceptedWorldMmPerPt > 0 ? 1 / acceptedWorldMmPerPt : null, sourceFrame: R6_ACCEPTED_LIVE_FRAME, sourceUnit: "mm", targetFrame: R6_SOURCE_POINT_FRAME, targetUnit: "pt", sourcePageHeightPt } },
      residualsPt: { ...residualsPt, max: maxPt, tolerance: R6_CALIBRATION_RESIDUAL_TOLERANCE_PT }
    };
  }

  function r6ProjectFingerprint(currentProject = project) {
    const summary = {
      scale: currentProject.scale || null,
      walls: (currentProject.walls || []).map((wall) => ({ id: wall.id, source: wall.source_object_id || wall.sourceWallId || null, from: wall.from, to: wall.to, thickness: wall.thickness })).sort((a, b) => String(a.id).localeCompare(String(b.id))),
      structures: (currentProject.structures || []).map((item) => ({ id: item.id, source: item.source_object_id || item.sourceColumnId || null, x: item.x, y: item.y, from: item.from || null, to: item.to || null, widthMm: item.widthMm, depthMm: item.depthMm })).sort((a, b) => String(a.id).localeCompare(String(b.id))),
      openings: (currentProject.openings || []).map((item) => ({ id: item.id, source: item.source_object_id || null, kind: item.kind, edgeId: item.edgeId || null })).sort((a, b) => String(a.id).localeCompare(String(b.id))),
      r6: currentProject.r6Review ? {
        decisions: currentProject.r6Review.records.map((record) => ({ sourceId: record.sourceId, decision: record.userDecision, editableObjectId: record.editableObjectId || null })).sort((a, b) => String(a.sourceId).localeCompare(String(b.sourceId))),
        calibration: currentProject.r6Review.calibrationReceipt ? { id: currentProject.r6Review.calibrationReceipt.receiptId, status: currentProject.r6Review.calibrationReceipt.status, acceptedTransformId: currentProject.r6Review.calibrationReceipt.acceptedTransformId || null, application: currentProject.r6Review.calibrationReceipt.application || null } : null
      } : null
    };
    const serialized = JSON.stringify(summary);
    return { schema: "laibe.planPuzzle.r6.projectFingerprint.v1", sha256: r6StableToken(serialized), utf8ByteLength: new TextEncoder().encode(serialized).byteLength };
  }

  function createR6CalibrationSelection() {
    return {
      schema: "laibe.planPuzzle.r6.canvasTwoPointSelection.v2",
      status: "waiting_first_point",
      points: [],
      endpointSelectionMethod: null,
      dimensionTextUsedAsProof: false,
      logicalClickCount: 0,
      capturedAt: null
    };
  }

  function r6CalibrationStatusLabel(selection, receipt) {
    if (receipt?.status === "accepted_for_existing_object_review" && acceptedScaleTransformId()) return "比例已接受";
    if (receipt?.status === "accepted_for_existing_object_review") return "比例資料待重新確認";
    if (receipt?.status === "submitted_for_acceptance") return "已送出，等待接受";
    if (!selection || selection.status === "waiting_first_point") return "等待第一點";
    if (selection.status === "waiting_second_point") return "等待第二點";
    if (selection.status === "two_points_captured") return "已捕捉兩點，等待實際長度與單位";
    return "等待比例校正";
  }

  function evaluateR6CalibrationReceiptEligibility(input) {
    const source = input || {};
    const selection = source.selection || {};
    const points = Array.isArray(selection.points) ? selection.points : [];
    const from = points[0] || null;
    const to = points[1] || null;
    const enteredLength = Number(source.enteredLength);
    const multipliers = { mm: 1, cm: 10, m: 1000 };
    const failedRules = [];
    const hasCanvasTwoPointSelection = selection.endpointSelectionMethod === "canvas_two_point_user_action" && points.length === 2;
    const pointsAreTyped = Boolean(from && to) && r6IsTypedCalibrationAnchor(from) && r6IsTypedCalibrationAnchor(to);
    const sourceFrom = from && from.sourcePointPdfPt;
    const sourceTo = to && to.sourcePointPdfPt;
    const pointsAreDistinct = pointsAreTyped && r6PointDistance(sourceFrom, sourceTo) > 0;
    const transform = pointsAreTyped && enteredLength > 0 && multipliers[source.unit]
      ? r6BuildTypedCalibrationTransform(selection, enteredLength * multipliers[source.unit])
      : null;
    const transformIsFinite = Boolean(transform) && [
      transform.sourceDistancePt,
      transform.provisionalWorldMmPerPt,
      transform.acceptedWorldMmPerPt,
      transform.geometryScaleFactor,
      transform.displayPxPerMm,
      transform.residualsPt && transform.residualsPt.max
    ].every(Number.isFinite);
    const evaluatedResidualMaxPt = Number.isFinite(Number(source.residualOverridePt)) ? Number(source.residualOverridePt) : transform && transform.residualsPt.max;
    const residualWithinTolerance = transformIsFinite && evaluatedResidualMaxPt <= R6_CALIBRATION_RESIDUAL_TOLERANCE_PT;
    if (!hasCanvasTwoPointSelection) failedRules.push("canvas_two_point_user_action_required");
    if (!pointsAreTyped) failedRules.push("typed_source_and_live_endpoints_required");
    if (!pointsAreDistinct) failedRules.push("two_distinct_canvas_points_required");
    if (!(enteredLength > 0)) failedRules.push("positive_real_length_required");
    if (!multipliers[source.unit]) failedRules.push("explicit_unit_required");
    if (!String(source.actor || "").trim() || !String(source.reviewer || "").trim()) failedRules.push("actor_and_reviewer_required");
    if (!String(source.caseId || "").trim() || !String(source.sourceSha256 || "").trim()) failedRules.push("case_and_source_binding_required");
    if (source.acceptedTransformId) failedRules.push("accepted_transform_id_must_be_null_before_acceptance");
    if (source.genericScaleCalibrated && !hasCanvasTwoPointSelection) failedRules.push("generic_scale_state_is_not_r6_receipt");
    if (!transformIsFinite || !residualWithinTolerance) failedRules.push("typed_transform_and_residual_required");
    if (source.requireApplicationGuard === true && source.applicationGuard !== true) failedRules.push("calibration_application_guard_required");
    return {
      schema: "laibe.planPuzzle.r6.scaleCalibrationEligibility.v2",
      pass: failedRules.length === 0,
      failedRules,
      transform,
      evaluatedResidualMaxPt,
      rules: {
        canvasTwoPointUserAction: hasCanvasTwoPointSelection,
        typedEndpoints: pointsAreTyped,
        distinctEndpoints: pointsAreDistinct,
        positiveRealLength: enteredLength > 0,
        explicitUnit: Boolean(multipliers[source.unit]),
        actorAndReviewer: Boolean(String(source.actor || "").trim() && String(source.reviewer || "").trim()),
        receiptBinding: Boolean(String(source.caseId || "").trim() && String(source.sourceSha256 || "").trim()),
        acceptedTransformIdUnset: !source.acceptedTransformId,
        typedTransformAndResidual: transformIsFinite && residualWithinTolerance,
        applicationGuard: source.requireApplicationGuard !== true || source.applicationGuard === true
      }
    };
  }

  function r6FixtureAnchor(sourcePointPdfPt, options = {}) {
    const provisionalWorldMmPerPt = Number(options.provisionalWorldMmPerPt || 10);
    const displayPxPerMm = Number(options.displayPxPerMm || 1);
    const sourcePageHeightPt = Number(options.sourcePageHeightPt || 1191);
    const provisionalLivePointMm = {
      x: sourcePointPdfPt.x * provisionalWorldMmPerPt,
      y: (sourcePageHeightPt - sourcePointPdfPt.y) * provisionalWorldMmPerPt
    };
    return r6CreateTypedCalibrationAnchor({
      x: provisionalLivePointMm.x * displayPxPerMm,
      y: provisionalLivePointMm.y * displayPxPerMm
    }, {
      displayPxPerMm,
      provisionalWorldMmPerPt,
      viewZoom: Number(options.viewZoom || 1),
      canvasPanOffsetPx: options.canvasPanOffsetPx || { x: 0, y: 0 },
      panAndZoomRemoved: true,
      importSessionId: options.importSessionId || "fixture-import-session",
      sourceSha256: options.sourceSha256 || "fixture-source-sha256",
      sourcePageHeightPt
    });
  }

  function createR6CalibrationPredicateFixtures() {
    const first = r6FixtureAnchor({ x: 100, y: 200 });
    const second = r6FixtureAnchor({ x: 500, y: 200 });
    const base = {
      selection: { endpointSelectionMethod: "canvas_two_point_user_action", points: [first, second] },
      enteredLength: 3000,
      unit: "mm",
      actor: "fixture-owner",
      reviewer: "fixture-reviewer",
      caseId: "fixture-case",
      sourceSha256: "fixture-source-sha256",
      acceptedTransformId: null,
      genericScaleCalibrated: false
    };
    const cases = [
      { id: "prefilled_bbox_without_canvas_clicks", input: { ...base, selection: { endpointSelectionMethod: "prefilled_source_bbox", points: base.selection.points } }, expectedPass: false, expectedRule: "canvas_two_point_user_action_required" },
      { id: "one_canvas_click", input: { ...base, selection: { endpointSelectionMethod: "canvas_two_point_user_action", points: [base.selection.points[0]] } }, expectedPass: false, expectedRule: "canvas_two_point_user_action_required" },
      { id: "same_canvas_endpoint_twice", input: { ...base, selection: { endpointSelectionMethod: "canvas_two_point_user_action", points: [base.selection.points[0], base.selection.points[0]] } }, expectedPass: false, expectedRule: "two_distinct_canvas_points_required" },
      { id: "missing_real_length", input: { ...base, enteredLength: 0 }, expectedPass: false, expectedRule: "positive_real_length_required" },
      { id: "missing_unit", input: { ...base, unit: "" }, expectedPass: false, expectedRule: "explicit_unit_required" },
      { id: "missing_actor_or_reviewer", input: { ...base, actor: "", reviewer: "" }, expectedPass: false, expectedRule: "actor_and_reviewer_required" },
      { id: "generic_scale_without_r6_receipt", input: { ...base, selection: { endpointSelectionMethod: null, points: [] }, genericScaleCalibrated: true }, expectedPass: false, expectedRule: "generic_scale_state_is_not_r6_receipt" },
      { id: "accepted_transform_before_acceptance", input: { ...base, acceptedTransformId: "premature-transform" }, expectedPass: false, expectedRule: "accepted_transform_id_must_be_null_before_acceptance" },
      { id: "two_distinct_canvas_points_positive", input: base, expectedPass: true, expectedRule: null }
    ];
    const rows = cases.map((fixture) => {
      const result = evaluateR6CalibrationReceiptEligibility(fixture.input);
      return { id: fixture.id, pass: result.pass === fixture.expectedPass && (!fixture.expectedRule || result.failedRules.includes(fixture.expectedRule)), result };
    });
    return { schema: "laibe.planPuzzle.r6.scaleCalibrationPredicateFixtures.v1", pass: rows.every((row) => row.pass), rows };
  }

  function createR6TypedCalibrationApplicationFixtures() {
    const first = r6FixtureAnchor({ x: 100, y: 200 }, { provisionalWorldMmPerPt: 10, displayPxPerMm: 1 });
    const second = r6FixtureAnchor({ x: 400, y: 200 }, { provisionalWorldMmPerPt: 10, displayPxPerMm: 1 });
    const selection = { endpointSelectionMethod: "canvas_two_point_user_action", points: [first, second] };
    const baseEligibilityInput = {
      selection,
      enteredLength: 6000,
      unit: "mm",
      actor: "fixture-owner",
      reviewer: "fixture-reviewer",
      caseId: "fixture-case",
      sourceSha256: "fixture-source-sha256",
      acceptedTransformId: null,
      genericScaleCalibrated: false,
      requireApplicationGuard: true,
      applicationGuard: true
    };
    const transform = r6BuildTypedCalibrationTransform(selection, 6000);
    const localPoint = { x: 1000, y: 2000 };
    const firstClient = r6ClientPointToCanvasPointPx({ x: 1000, y: 2000 }, { left: 0, top: 0 }, 1, { x: 0, y: 0 });
    const secondClient = r6ClientPointToCanvasPointPx({ x: 2100, y: 4050 }, { left: 0, top: 0 }, 2, { x: 100, y: 50 });
    const panZoomAnchorOne = r6CreateTypedCalibrationAnchor(firstClient, {
      displayPxPerMm: 1,
      provisionalWorldMmPerPt: 10,
      viewZoom: 1,
      canvasPanOffsetPx: { x: 0, y: 0 },
      panAndZoomRemoved: true,
      importSessionId: "fixture-import-session",
      sourceSha256: "fixture-source-sha256",
      sourcePageHeightPt: 1191
    });
    const panZoomAnchorTwo = r6CreateTypedCalibrationAnchor(secondClient, {
      displayPxPerMm: 1,
      provisionalWorldMmPerPt: 10,
      viewZoom: 2,
      canvasPanOffsetPx: { x: 100, y: 50 },
      panAndZoomRemoved: true,
      importSessionId: "fixture-import-session",
      sourceSha256: "fixture-source-sha256",
      sourcePageHeightPt: 1191
    });
    const fixtureProject = {
      scale: { pxPerMm: 1, calibrated: false },
      r6Review: { calibrationApplication: null },
      walls: [{ id: "fixture-wall", source_kind: "pdf", object_status: "existing", work_action: "none", budget_trigger: "none", dbspec_projection: "excluded", from: { x: 1000, y: 2000 }, to: { x: 4000, y: 2000 }, thickness: 120 }],
      structures: [], structuralObjects: [], openings: [], zones: [], furniture: [],
      pdfReviewObjects: { lines: [], shapes: [], text: [] }
    };
    const beforeGeometry = cloneJson(fixtureProject.walls[0]);
    const fixtureReceipt = {
      geometryScaleFactor: transform.geometryScaleFactor,
      provisionalWorldMmPerPt: transform.provisionalWorldMmPerPt,
      acceptedWorldMmPerPt: transform.acceptedWorldMmPerPt
    };
    const firstApplication = r6ApplyAcceptedCalibrationTransform(fixtureProject, fixtureReceipt, "fixture-transform");
    const secondApplication = r6ApplyAcceptedCalibrationTransform(fixtureProject, fixtureReceipt, "fixture-transform");
    const traceLiveFrom = r6TransformSourcePointToLiveMm({ x: 50, y: 40 }, transform.acceptedWorldMmPerPt);
    const traceLiveTo = r6TransformSourcePointToLiveMm({ x: 150, y: 40 }, transform.acceptedWorldMmPerPt);
    const badFrameAnchor = cloneJson(first);
    badFrameAnchor.coordinateFrames.sourcePointPdfPt = "unknown-frame";
    const fixtureRows = [
      {
        id: "pan_zoom_variants_preserve_source_point",
        observed: { localPoint, firstClient, secondClient, firstSource: panZoomAnchorOne && panZoomAnchorOne.sourcePointPdfPt, secondSource: panZoomAnchorTwo && panZoomAnchorTwo.sourcePointPdfPt },
        pass: JSON.stringify(panZoomAnchorOne && panZoomAnchorOne.sourcePointPdfPt) === JSON.stringify(panZoomAnchorTwo && panZoomAnchorTwo.sourcePointPdfPt) && JSON.stringify(firstClient) === JSON.stringify(localPoint) && JSON.stringify(secondClient) === JSON.stringify(localPoint)
      },
      {
        id: "accepted_scale_and_inverse_residual",
        observed: transform,
        pass: transform.provisionalWorldMmPerPt === 10 && transform.acceptedWorldMmPerPt === 20 && transform.geometryScaleFactor === 2 && JSON.stringify(transform.acceptedLiveEndpointsMm) === JSON.stringify({ from: { x: 2000, y: 4000 }, to: { x: 8000, y: 4000 } }) && r6PointDistance(transform.acceptedLiveEndpointsMm.from, transform.acceptedLiveEndpointsMm.to) === 6000 && transform.residualsPt.max === 0
      },
      {
        id: "display_scale_is_not_world_scale",
        observed: { pxPerMm: fixtureProject.scale.pxPerMm, acceptedWorldMmPerPt: transform.acceptedWorldMmPerPt },
        pass: fixtureProject.scale.pxPerMm === 1 && fixtureProject.scale.pxPerMm !== transform.acceptedWorldMmPerPt
      },
      {
        id: "before_acceptance_preserves_geometry_and_null_transform",
        observed: { beforeGeometry, transformIdBeforeAcceptance: null },
        pass: JSON.stringify(beforeGeometry) === JSON.stringify({ id: "fixture-wall", source_kind: "pdf", object_status: "existing", work_action: "none", budget_trigger: "none", dbspec_projection: "excluded", from: { x: 1000, y: 2000 }, to: { x: 4000, y: 2000 }, thickness: 120 })
      },
      {
        id: "acceptance_applies_geometry_once",
        observed: { firstApplication, secondApplication, wall: fixtureProject.walls[0] },
        pass: firstApplication.pass === true && fixtureProject.walls[0].from.x === 2000 && fixtureProject.walls[0].to.x === 8000 && secondApplication.pass === false && secondApplication.reason === "transform_already_applied"
      },
      {
        id: "manual_trace_uses_accepted_source_to_live_transform",
        observed: { traceLiveFrom, traceLiveTo },
        pass: JSON.stringify(traceLiveFrom) === JSON.stringify({ x: 1000, y: 800 }) && JSON.stringify(traceLiveTo) === JSON.stringify({ x: 3000, y: 800 })
      },
      {
        id: "capture_phase_routing_blocks_ordinary_selection",
        observed: r6CaptureRoutingDecision({ r6ReviewActive: true, mode: "r6-calibrate", isCanvasTarget: true, isProductControl: false }),
        pass: r6CaptureRoutingDecision({ r6ReviewActive: true, mode: "r6-calibrate", isCanvasTarget: true, isProductControl: false }).capture === true && r6CaptureRoutingDecision({ r6ReviewActive: true, mode: "r6-calibrate", isCanvasTarget: true, isProductControl: false }).logicalClickCount === 1 && r6CaptureRoutingDecision({ r6ReviewActive: true, mode: "r6-calibrate", isCanvasTarget: true, isProductControl: false }).ordinarySelectionSideEffect === false
      },
      {
        id: "typed_endpoint_frame_unit_residual_and_application_guards_reject",
        observed: {
          missingTypedEndpoint: evaluateR6CalibrationReceiptEligibility({ ...baseEligibilityInput, selection: { ...selection, points: [badFrameAnchor, second] } }),
          missingUnit: evaluateR6CalibrationReceiptEligibility({ ...baseEligibilityInput, unit: "" }),
          excessiveResidual: evaluateR6CalibrationReceiptEligibility({ ...baseEligibilityInput, residualOverridePt: 0.251 }),
          missingApplicationGuard: evaluateR6CalibrationReceiptEligibility({ ...baseEligibilityInput, applicationGuard: false })
        },
        pass: true
      },
      {
        id: "prior_r6_3_predicate_fixtures_remain_passing",
        observed: createR6CalibrationPredicateFixtures(),
        pass: createR6CalibrationPredicateFixtures().pass === true
      }
    ];
    const invalidRow = fixtureRows.find((row) => row.id === "typed_endpoint_frame_unit_residual_and_application_guards_reject");
    invalidRow.pass = [
      invalidRow.observed.missingTypedEndpoint,
      invalidRow.observed.missingUnit,
      invalidRow.observed.excessiveResidual,
      invalidRow.observed.missingApplicationGuard
    ].every((result) => result.pass === false && Array.isArray(result.failedRules) && result.failedRules.length > 0);
    return {
      schema: "laibe.planPuzzle.r6.typedCalibrationApplicationFixtures.v1",
      pass: fixtureRows.every((row) => row.pass),
      rows: fixtureRows
    };
  }

  function r6AtomicFixturePolicyFields() {
    return {
      source_kind: "pdf",
      object_status: "existing",
      work_action: "none",
      budget_trigger: "none",
      dbspec_projection: "excluded"
    };
  }

  function r6CreateAtomicApplicationFixtureProject() {
    const pdfPolicy = r6AtomicFixturePolicyFields();
    return {
      scale: { pxPerMm: 1.5, calibrated: false },
      importSource: { sourceSha256: "fixture-pdf" },
      lastPdfObjectizationSceneImport: { importSessionId: "fixture-import" },
      r6Review: { calibrationApplication: null },
      underlay: {
        id: "fixture-pdf-underlay",
        sourceType: "vector_pdf",
        renderMode: "pdf-vector-context",
        coordinateFrame: "plan-puzzle-provisional-live-mm",
        x: 0,
        y: 0,
        coordinateWidthMm: 1000,
        coordinateHeightMm: 1400,
        pageFrame: { xMm: 0, yMm: 0, widthMm: 1000, heightMm: 1400 },
        visibleFrame: { xMm: 100, yMm: 200, widthMm: 700, heightMm: 900 },
        worldFrame: { xMm: 100, yMm: 200, widthMm: 700, heightMm: 900 },
        cropOffset: { xMm: 100, yMm: 200 }
      },
      walls: [
        { id: "fixture-pdf-wall-a", ...pdfPolicy, from: { x: 100, y: 200 }, to: { x: 400, y: 200 }, thickness: 12 },
        { id: "fixture-pdf-wall-b", ...pdfPolicy, from: { x: 400, y: 200 }, to: { x: 400, y: 500 }, thickness: 12 },
        { id: "fixture-user-wall", source_kind: "user", object_status: "new", from: { x: 10, y: 20 }, to: { x: 60, y: 20 }, thickness: 10 }
      ],
      structures: [{ id: "fixture-pdf-column", category: "column", ...pdfPolicy, x: 2500, y: 3000, widthMm: 80, depthMm: 80 }],
      structuralObjects: [],
      openings: [],
      zones: [],
      furniture: [],
      pdfReviewObjects: {
        lines: [{ id: "fixture-review-line", ...pdfPolicy, from: { x: 120, y: 240 }, to: { x: 220, y: 240 } }],
        shapes: [],
        text: [],
        importMetrics: { scalePolicy: { status: "not_established" } }
      },
      nodeGraph: {
        edges: [{ id: "stale-fixture-edge", sourceWallId: "fixture-pdf-wall-a", from: { x: 100, y: 200 }, to: { x: 400, y: 200 } }]
      }
    };
  }

  function r6RunAtomicFixtureApplication(fixtureProject, receipt, transformId) {
    const activeProject = project;
    const selectedNodeId = uiState.selectedNodeId;
    project = fixtureProject;
    try {
      return r6ApplyAcceptedCalibrationTransform(fixtureProject, receipt, transformId);
    } finally {
      project = activeProject;
      uiState.selectedNodeId = selectedNodeId;
    }
  }

  function createR6AtomicGeometryApplicationFixtures() {
    const receipt = { geometryScaleFactor: 2, provisionalWorldMmPerPt: 10, acceptedWorldMmPerPt: 20 };
    const transformId = "fixture-r6-atomic-transform";
    const fixtureProject = r6CreateAtomicApplicationFixtureProject();
    const beforeUserWall = cloneJson(fixtureProject.walls[2]);
    const beforePdfWall = cloneJson(fixtureProject.walls[0]);
    const first = r6RunAtomicFixtureApplication(fixtureProject, receipt, transformId);
    const second = r6RunAtomicFixtureApplication(fixtureProject, receipt, transformId);
    const graphEdges = fixtureProject.nodeGraph && fixtureProject.nodeGraph.edges || [];
    const emptyProject = r6CreateAtomicApplicationFixtureProject();
    emptyProject.walls = emptyProject.walls.filter((wall) => wall.source_kind !== "pdf");
    emptyProject.structures = [];
    emptyProject.pdfReviewObjects = { lines: [], shapes: [], text: [], importMetrics: { scalePolicy: {} } };
    const emptyBefore = JSON.stringify(emptyProject);
    const emptyResult = r6RunAtomicFixtureApplication(emptyProject, receipt, transformId);
    const conflictProject = r6CreateAtomicApplicationFixtureProject();
    conflictProject.walls[0].r6AppliedTransformId = "conflicting-transform";
    const conflictBefore = JSON.stringify(conflictProject);
    const conflictResult = r6RunAtomicFixtureApplication(conflictProject, receipt, transformId);
    const invalidProject = r6CreateAtomicApplicationFixtureProject();
    invalidProject.walls[0].from = { x: "not-a-number", y: 200 };
    const invalidBefore = JSON.stringify(invalidProject);
    const invalidResult = r6RunAtomicFixtureApplication(invalidProject, receipt, transformId);
    const legacyUnderlayProject = r6CreateAtomicApplicationFixtureProject();
    legacyUnderlayProject.scale = { ...legacyUnderlayProject.scale, calibrated: true, acceptedTransformId: transformId, geometryScaleFactor: 2, acceptedWorldMmPerPt: 20 };
    legacyUnderlayProject.underlay.r6AppliedTransformId = transformId;
    legacyUnderlayProject.underlay.r6AppliedGeometryScaleFactor = 2;
    legacyUnderlayProject.underlay.acceptedWorldMmPerPt = 20;
    legacyUnderlayProject.underlay.coordinateFrame = "plan-puzzle-accepted-live-mm";
    const legacyMigrationFirst = migratePersistedAcceptedPdfVectorUnderlay(legacyUnderlayProject);
    const legacyMigrationSecond = migratePersistedAcceptedPdfVectorUnderlay(legacyUnderlayProject);
    const metadataClosure = first.metadataClosure || {};
    const rows = [
      {
        id: "inventory_scales_all_pdf_geometry_once_and_preserves_non_pdf",
        observed: { first, pdfWall: fixtureProject.walls[0], column: fixtureProject.structures[0], reviewLine: fixtureProject.pdfReviewObjects.lines[0], userWall: fixtureProject.walls[2], underlay: fixtureProject.underlay },
        pass: first.pass === true && first.applicableCount === 4 && first.appliedCount === 4 && first.inventory.categoryCounts.walls === 2 && first.inventory.categoryCounts.structures === 1 && first.inventory.categoryCounts.reviewLines === 1 && fixtureProject.walls[0].from.x === 200 && fixtureProject.walls[0].to.x === 800 && fixtureProject.structures[0].x === 5000 && fixtureProject.pdfReviewObjects.lines[0].from.x === 240 && fixtureProject.underlay.coordinateWidthMm === 2000 && fixtureProject.underlay.coordinateHeightMm === 2800 && fixtureProject.underlay.worldFrame.widthMm === 1400 && fixtureProject.underlay.r6AppliedFrameTransformId === transformId && JSON.stringify(fixtureProject.walls[2]) === JSON.stringify(beforeUserWall)
      },
      {
        id: "legacy_accepted_underlay_frame_migrates_once_without_double_scaling",
        observed: { legacyMigrationFirst, legacyMigrationSecond, underlay: legacyUnderlayProject.underlay },
        pass: legacyMigrationFirst === true && legacyMigrationSecond === false && legacyUnderlayProject.underlay.coordinateWidthMm === 2000 && legacyUnderlayProject.underlay.coordinateHeightMm === 2800 && legacyUnderlayProject.underlay.visibleFrame.widthMm === 1400 && legacyUnderlayProject.underlay.r6AppliedFrameTransformId === transformId
      },
      {
        id: "node_graph_rebuilt_from_scaled_walls_without_stale_endpoints",
        observed: { graphIntegrity: first.graphIntegrity, graphEdges, beforePdfWall, afterPdfWall: fixtureProject.walls[0] },
        pass: first.graphIntegrity && first.graphIntegrity.pass === true && first.graphIntegrity.noStalePreScaleEndpoints === true && graphEdges.some((edge) => edge.sourceWallId === "fixture-pdf-wall-a" && edge.from.x === 200 && edge.to.x === 800) && graphEdges.every((edge) => !(edge.sourceWallId === "fixture-pdf-wall-a" && (edge.from.x === 100 || edge.to.x === 400)))
      },
      {
        id: "empty_inventory_rejects_before_mutation",
        observed: { emptyResult, beforeEqualsAfter: emptyBefore === JSON.stringify(emptyProject) },
        pass: emptyResult.pass === false && emptyResult.reason === "empty_applicable_pdf_existing_inventory" && emptyBefore === JSON.stringify(emptyProject)
      },
      {
        id: "conflicting_item_transform_rejects_before_mutation",
        observed: { conflictResult, beforeEqualsAfter: conflictBefore === JSON.stringify(conflictProject) },
        pass: conflictResult.pass === false && conflictResult.reason === "conflicting_item_transform" && conflictBefore === JSON.stringify(conflictProject)
      },
      {
        id: "invalid_geometry_rejects_before_mutation",
        observed: { invalidResult, beforeEqualsAfter: invalidBefore === JSON.stringify(invalidProject) },
        pass: invalidResult.pass === false && invalidResult.reason === "invalid_required_geometry" && invalidBefore === JSON.stringify(invalidProject)
      },
      {
        id: "second_acceptance_is_rejected_without_double_scaling",
        observed: { second, wall: fixtureProject.walls[0] },
        pass: second.pass === false && second.reason === "transform_already_applied" && fixtureProject.walls[0].from.x === 200 && fixtureProject.walls[0].to.x === 800
      },
      {
        id: "display_px_per_mm_is_preserved_separately_from_world_scale",
        observed: { pxPerMm: fixtureProject.scale.pxPerMm, acceptedWorldMmPerPt: fixtureProject.scale.acceptedWorldMmPerPt },
        pass: fixtureProject.scale.pxPerMm === 1.5 && fixtureProject.scale.acceptedWorldMmPerPt === 20 && fixtureProject.scale.pxPerMm !== fixtureProject.scale.acceptedWorldMmPerPt
      },
      {
        id: "accepted_metadata_closes_across_required_state_surfaces",
        observed: { metadataClosure, scale: fixtureProject.scale, importSource: fixtureProject.importSource, sceneImport: fixtureProject.lastPdfObjectizationSceneImport, scalePolicy: fixtureProject.pdfReviewObjects.importMetrics.scalePolicy },
        pass: metadataClosure.pass === true && fixtureProject.scale.acceptedTransformId === transformId && fixtureProject.importSource.acceptedTransformId === transformId && fixtureProject.lastPdfObjectizationSceneImport.acceptedTransformId === transformId && fixtureProject.pdfReviewObjects.importMetrics.scalePolicy.acceptedTransformId === transformId
      },
      {
        id: "prior_r6_3_and_r6_3_1_fixtures_remain_passing",
        observed: createR6TypedCalibrationApplicationFixtures(),
        pass: createR6TypedCalibrationApplicationFixtures().pass === true
      }
    ];
    return { schema: "laibe.planPuzzle.r6.atomicCalibrationApplicationFixtures.v1", pass: rows.every((row) => row.pass), rows };
  }

  function r6StartCanvasCalibration() {
    if (!isR6ReviewActive()) return;
    const before = r6ProjectFingerprint(project);
    project.r6Review.calibrationSelection = createR6CalibrationSelection();
    // A fresh two-point capture must not inherit a submitted receipt whose
    // endpoints belong to an earlier attempt.  Keeping it would expose an
    // unusable Accept action and prevent the user from submitting the new
    // points through the normal inspector.
    project.r6Review.calibrationReceipt = null;
    uiState.mode = "r6-calibrate";
    uiState.calibrationPoints = [];
    uiState.error = "";
    uiState.message = "請在畫布上點選比例校正的第一個端點。";
    r6Record(null, "calibration_points_selection_started", "waiting_first_point", { kind: "canvas_two_point_user_action" }, "owner_or_designated_reviewer", before);
    r6Publish();
  }

  function r6CaptureRoutingDecision(input = {}) {
    const capture = input.r6ReviewActive === true && input.mode === "r6-calibrate" && input.isCanvasTarget === true && input.isProductControl !== true;
    return {
      schema: "laibe.planPuzzle.r6.capturePhaseRouting.v1",
      capture,
      logicalClickCount: capture ? 1 : 0,
      ordinarySelectionSideEffect: false,
      reason: capture ? "r6_capture_phase_canvas_point" : "not_r6_calibration_canvas_target"
    };
  }

  function r6ClientPointToCanvasPointPx(clientPoint, canvasRect, zoom, panOffsetPx) {
    const safeZoom = Number(zoom);
    const pan = panOffsetPx || { x: 0, y: 0 };
    if (!r6FinitePoint(clientPoint) || !canvasRect || !Number.isFinite(safeZoom) || safeZoom <= 0 || !Number.isFinite(Number(pan.x)) || !Number.isFinite(Number(pan.y))) {
      return null;
    }
    return r6RoundPoint({
      x: (clientPoint.x - Number(canvasRect.left) - Number(pan.x)) / safeZoom,
      y: (clientPoint.y - Number(canvasRect.top) - Number(pan.y)) / safeZoom
    });
  }

  function r6IsProductControlTarget(target) {
    return Boolean(target && typeof target.closest === "function" && target.closest("button,input,select,textarea,[data-action],#laibeTopTools,#loop70ToolBasketPanel,.selection-mini-toolbar,.loop99-quick-choice-panel,#laibeCalPrompt,.drawing-legend,.toolbar-boundary-note"));
  }

  function r6CaptureCanvasPointPx(event) {
    const rect = canvas.getBoundingClientRect();
    return r6ClientPointToCanvasPointPx({ x: Number(event.clientX), y: Number(event.clientY) }, rect, Number(viewZoom) || 1, canvasPanOffset);
  }

  function r6CaptureCanvasCalibrationAnchor(event) {
    const review = project.r6Review;
    const canvasPointPx = r6CaptureCanvasPointPx(event);
    const anchor = r6CreateTypedCalibrationAnchor(canvasPointPx, {
      displayPxPerMm: r6DisplayPxPerMm(project),
      provisionalWorldMmPerPt: r6ProvisionalWorldMmPerPt(project),
      viewZoom: Number(viewZoom) || 1,
      canvasPanOffsetPx: canvasPanOffset,
      panAndZoomRemoved: true,
      importSessionId: review && review.importReceipt && review.importReceipt.importSessionId,
      sourceSha256: review && review.importReceipt && review.importReceipt.file && review.importReceipt.file.sha256,
      sourcePageHeightPt: r6SourcePageHeightPt(review)
    });
    return r6SnapCalibrationAnchorToDimensionEndpoint(anchor, review);
  }

  function handleR6CalibrationCapturePointerDown(event) {
    const routing = r6CaptureRoutingDecision({
      r6ReviewActive: isR6ReviewActive(),
      mode: uiState.mode,
      isCanvasTarget: canvas.contains(event.target),
      isProductControl: r6IsProductControlTarget(event.target)
    });
    if (routing.capture) {
      event.stopImmediatePropagation();
    }
  }

  function handleR6CalibrationCaptureClick(event) {
    const routing = r6CaptureRoutingDecision({
      r6ReviewActive: isR6ReviewActive(),
      mode: uiState.mode,
      isCanvasTarget: canvas.contains(event.target),
      isProductControl: r6IsProductControlTarget(event.target)
    });
    if (!routing.capture || r6CapturedCalibrationEvents.has(event)) return;
    r6CapturedCalibrationEvents.add(event);
    event.preventDefault();
    event.stopImmediatePropagation();
    r6CaptureCanvasCalibrationPoint(event, { capturedBy: "capture_phase" });
  }

  function r6CaptureCanvasCalibrationPoint(event, options = {}) {
    if (!isR6ReviewActive()) return;
    event.preventDefault();
    const selection = project.r6Review.calibrationSelection || createR6CalibrationSelection();
    const anchor = r6CaptureCanvasCalibrationAnchor(event);
    const before = r6ProjectFingerprint(project);
    if (!anchor) {
      uiState.error = "目前無法建立比例校正點，請確認圖面已完成匯入後再試一次。";
      render();
      return;
    }
    if (selection.points.length >= 2) {
      uiState.error = "已捕捉兩個校正端點。若要重新選取，請使用審查面板的重新選取按鈕。";
      render();
      return;
    }
    if (selection.points.length === 1 && r6PointDistance(selection.points[0].sourcePointPdfPt, anchor.sourcePointPdfPt) === 0) {
      uiState.error = "第二個端點必須與第一個端點不同。";
      render();
      return;
    }
    selection.points = selection.points.concat([anchor]);
    selection.endpointSelectionMethod = "canvas_two_point_user_action";
    selection.status = selection.points.length === 1 ? "waiting_second_point" : "two_points_captured";
    selection.dimensionTextUsedAsProof = false;
    selection.logicalClickCount = Number(selection.logicalClickCount || 0) + 1;
    selection.capturedAt = new Date().toISOString();
    project.r6Review.calibrationSelection = selection;
    uiState.error = "";
    uiState.message = selection.points.length === 1 ? "已捕捉第一個端點，請在畫布上點選第二個端點。" : "已捕捉兩個端點，請回到審查面板輸入實際長度與單位。";
    if (selection.points.length === 2) {
      uiState.mode = "select";
      r6Record(null, "calibration_points_selected", "two_points_captured", {
        kind: "canvas_two_point_user_action",
        capturedBy: options.capturedBy || "canvas_click",
        logicalClickCount: selection.logicalClickCount,
        sourceEndpointsPdfPt: selection.points.map((item) => item.sourcePointPdfPt),
        provisionalLiveEndpointsMm: selection.points.map((item) => item.provisionalLivePointMm)
      }, "owner_or_designated_reviewer", before);
    }
    r6Publish();
  }

  function r6Record(sourceId, action, decisionStatus, evidence, nextActor, beforeFingerprint) {
    if (!isR6ReviewActive()) return null;
    const before = beforeFingerprint || r6ProjectFingerprint(project);
    const sourceRecord = (project.r6Review.records || []).find((record) => record.sourceId === sourceId) || null;
    const event = {
      event_id: `r6-event-${r6StableToken({ action, sourceId: sourceId || null, sequence: (project.caseEvents || []).length + 1, importSessionId: project.r6Review.importReceipt.importSessionId })}`,
      case_id: project.r6Review.caseId,
      actor_id: project.r6Review.actorId,
      actor_role: "owner_or_designated_reviewer",
      action,
      source_sha256: project.r6Review.importReceipt.file.sha256,
      source_object_ids: sourceRecord ? [sourceRecord.sourceId] : [],
      before_fingerprint: before,
      after_fingerprint: null,
      decision_status: decisionStatus,
      occurred_at: new Date().toISOString(),
      next_actor: nextActor || "owner_or_designated_reviewer",
      evidence: evidence || null,
      policy: { source_kind: "pdf", object_status: "existing", work_action: "none", budget_trigger: "none", dbspec_projection: "excluded" }
    };
    project.caseEvents = Array.isArray(project.caseEvents) ? project.caseEvents : [];
    project.caseEvents.push(event);
    event.after_fingerprint = r6ProjectFingerprint(project);
    project.r6Review.caseEvents = project.caseEvents;
    return event;
  }

  function isExistingPdfObject(object) {
    const hasPdfSource = object?.source_kind === "pdf" || Boolean(object?.source_object_id) || object?.provenance?.source_kind === "pdf" || String(object?.id || "").startsWith("pdf-");
    const isExisting = object?.object_status === "existing" || object?.status === "existing" || object?.candidateStatus === "existing_candidate";
    return Boolean(hasPdfSource && isExisting);
  }

  function recordExistingPdfObjectEvent(object, action, decisionStatus, evidence, beforeFingerprint) {
    if (!isExistingPdfObject(object)) {
      return null;
    }
    const sourceId = object.source_object_id || object.id;
    if (isR6ReviewActive()) {
      return r6Record(sourceId, action, decisionStatus, evidence, "owner_or_designated_reviewer", beforeFingerprint);
    }
    const occurredAt = new Date().toISOString();
    const previousCaseEvent = [...(project.caseEvents || [])].reverse().find((event) => event?.case_id || event?.caseId) || null;
    const event = {
      event_id: `case-event-${r6StableToken({ action, sourceId, occurredAt, sequence: (project.caseEvents || []).length + 1 })}`,
      case_id: previousCaseEvent?.case_id || previousCaseEvent?.caseId || project.importSource?.caseId || "plan-puzzle-local-case",
      actor_id: "current_plan_editor",
      actor_role: "owner_or_designated_reviewer",
      action,
      source_sha256: project.importSource?.sha256 || project.importSource?.sourceSha256 || project.lastPdfObjectizationSceneImport?.sourceSha256 || null,
      source_object_ids: [sourceId],
      before_fingerprint: beforeFingerprint || r6ProjectFingerprint(project),
      after_fingerprint: null,
      decision_status: decisionStatus,
      occurred_at: occurredAt,
      next_actor: "owner_or_designated_reviewer",
      evidence: evidence || null,
      policy: { source_kind: "pdf", object_status: "existing", work_action: "none", budget_trigger: "none", dbspec_projection: "excluded" }
    };
    project.caseEvents = Array.isArray(project.caseEvents) ? project.caseEvents : [];
    project.caseEvents.push(event);
    event.after_fingerprint = r6ProjectFingerprint(project);
    return event;
  }

  function scheduleStructurePropertyEvent(structure, field, beforeFingerprint) {
    const samePendingObject = pendingStructurePropertyEvent?.structureId === structure.id;
    pendingStructurePropertyEvent = {
      structureId: structure.id,
      field,
      beforeFingerprint: samePendingObject ? pendingStructurePropertyEvent.beforeFingerprint : beforeFingerprint
    };
    window.clearTimeout(structurePropertyEventTimer);
    structurePropertyEventTimer = window.setTimeout(() => flushPendingStructurePropertyEvent(true), 450);
  }

  function flushPendingStructurePropertyEvent(syncAfter = false) {
    window.clearTimeout(structurePropertyEventTimer);
    structurePropertyEventTimer = 0;
    const pending = pendingStructurePropertyEvent;
    pendingStructurePropertyEvent = null;
    const current = (project.structures || []).find((item) => item.id === pending?.structureId);
    if (!current || !pending) return false;
    recordExistingPdfObjectEvent(current, "property_edit", "edited_existing_object_review", {
      kind: "structure_property_edit",
      editableObjectId: current.id,
      field: pending.field
    }, pending.beforeFingerprint);
    if (syncAfter) {
      syncBridge();
      renderInspector();
    }
    return true;
  }

  function scheduleOpeningPropertyEvent(opening, field, beforeFingerprint, sourceReviewReopened = false) {
    const samePendingObject = pendingOpeningPropertyEvent?.openingId === opening.id;
    pendingOpeningPropertyEvent = {
      openingId: opening.id,
      field,
      beforeFingerprint: samePendingObject ? pendingOpeningPropertyEvent.beforeFingerprint : beforeFingerprint,
      sourceReviewReopened: Boolean(sourceReviewReopened || (samePendingObject && pendingOpeningPropertyEvent.sourceReviewReopened))
    };
    window.clearTimeout(openingPropertyEventTimer);
    openingPropertyEventTimer = window.setTimeout(() => flushPendingOpeningPropertyEvent(true), 450);
  }

  function flushPendingOpeningPropertyEvent(syncAfter = false) {
    window.clearTimeout(openingPropertyEventTimer);
    openingPropertyEventTimer = 0;
    const pending = pendingOpeningPropertyEvent;
    pendingOpeningPropertyEvent = null;
    const current = (project.openings || []).find((item) => item.id === pending?.openingId);
    if (!current || !pending) return false;
    recordExistingPdfObjectEvent(current, "property_edit", "edited_existing_object_review", {
      kind: "opening_property_edit",
      editableObjectId: current.id,
      field: pending.field,
      sourceReviewReopened: pending.sourceReviewReopened,
      sourceReviewStatus: current.sourceReviewStatus
    }, pending.beforeFingerprint);
    if (syncAfter) {
      syncBridge();
      renderInspector();
    }
    return true;
  }

  function scheduleZonePropertyEvent(zone, field, beforeFingerprint) {
    const samePendingObject = pendingZonePropertyEvent?.zoneId === zone.id;
    pendingZonePropertyEvent = {
      zoneId: zone.id,
      field,
      beforeFingerprint: samePendingObject ? pendingZonePropertyEvent.beforeFingerprint : beforeFingerprint
    };
    window.clearTimeout(zonePropertyEventTimer);
    zonePropertyEventTimer = window.setTimeout(() => flushPendingZonePropertyEvent(true), 450);
  }

  function flushPendingZonePropertyEvent(syncAfter = false) {
    window.clearTimeout(zonePropertyEventTimer);
    zonePropertyEventTimer = 0;
    const pending = pendingZonePropertyEvent;
    pendingZonePropertyEvent = null;
    const current = (project.zones || []).find((item) => item.id === pending?.zoneId);
    if (!current || !pending) return false;
    recordExistingPdfObjectEvent(current, "zone_property_edit", "edited_existing_object_review", {
      kind: "zone_property_edit",
      editableObjectId: current.id,
      field: pending.field,
      name: current.name,
      type: current.type,
      pendingSemanticType: current.pendingSemanticType || null,
      semanticStatus: current.userSemanticConfirmed ? "user_confirmed" : "pending_confirmation"
    }, pending.beforeFingerprint);
    if (syncAfter) {
      syncBridge();
      renderInspector();
    }
    return true;
  }

  function scheduleFurniturePropertyEvent(item, field, beforeFingerprint) {
    const samePendingObject = pendingFurniturePropertyEvent?.furnitureId === item.id;
    pendingFurniturePropertyEvent = {
      furnitureId: item.id,
      field,
      beforeFingerprint: samePendingObject ? pendingFurniturePropertyEvent.beforeFingerprint : beforeFingerprint
    };
    window.clearTimeout(furniturePropertyEventTimer);
    furniturePropertyEventTimer = window.setTimeout(() => flushPendingFurniturePropertyEvent(true), 450);
  }

  function flushPendingFurniturePropertyEvent(syncAfter = false) {
    window.clearTimeout(furniturePropertyEventTimer);
    furniturePropertyEventTimer = 0;
    const pending = pendingFurniturePropertyEvent;
    pendingFurniturePropertyEvent = null;
    const current = (project.furniture || []).find((entry) => entry.id === pending?.furnitureId);
    if (!current || !pending) return false;
    recordExistingPdfObjectEvent(current, "property_edit", "edited_existing_object_review", {
      kind: "furniture_property_edit",
      editableObjectId: current.id,
      field: pending.field,
      name: current.name || current.label || null,
      type: current.type || current.subtype || null,
      semanticStatus: current.semanticStatus || "pending_confirmation"
    }, pending.beforeFingerprint);
    if (syncAfter) {
      syncBridge();
      renderInspector();
    }
    return true;
  }

  function flushPendingSourceBoundPropertyEvents() {
    const changed = [
      flushPendingStructurePropertyEvent(false),
      flushPendingZonePropertyEvent(false),
      flushPendingFurniturePropertyEvent(false)
    ].some(Boolean);
    if (changed) syncBridge();
    return changed;
  }

  function r6Publish() {
    if (!isR6ReviewActive()) return;
    project.r6Review.currentFingerprint = r6ProjectFingerprint(project);
    render();
    r6WriteLocatorReceipt();
  }

  function r6WriteLocatorReceipt() {
    if (!isR6ReviewActive()) return;
    const review = project.r6Review;
    const nodeId = "laibe-pdf-r6-user-review-receipt";
    let node = document.getElementById(nodeId);
    if (!node) {
      node = document.createElement("script");
      node.id = nodeId;
      node.type = "application/json";
      node.hidden = true;
      node.setAttribute("data-status", "active");
      document.body.appendChild(node);
    }
    const records = review.records || [];
    const policy = { source_kind: "pdf", object_status: "existing", work_action: "none", budget_trigger: "none", dbspec_projection: "excluded" };
    const receipt = {
      schema: "laibe.planPuzzle.r6.userGovernedReviewReceipt.v1",
      status: "active_user_governed_review",
      import: {
        importSessionId: review.importReceipt.importSessionId,
        sourceSha256: review.importReceipt.file.sha256,
        page: review.importReceipt.source?.page || 1,
        route: review.importReceipt.file.route,
        runtimeVersion: review.importReceipt.runtime?.version || null
      },
      review: {
        machineCandidateCount: records.length,
        confirmedCount: records.filter((record) => record.userDecision === "confirmed").length,
        rejectedCount: records.filter((record) => record.userDecision === "rejected").length,
        manualTraceDraftCount: records.filter((record) => record.trace && record.trace.status === "source_local_trace_draft").length,
        promotedExistingObjectCount: records.filter((record) => record.editableObjectId).length,
        uncertainEvidenceOnlyCount: (review.uncertainRecords || []).length,
        ambiguousWallBodyReviewSetCount: (review.wallBodyReviewSets || []).length
      },
      calibration: {
        selectionStatus: review.calibrationSelection?.status || "waiting_first_point",
        endpointSelectionMethod: review.calibrationSelection?.endpointSelectionMethod || null,
        endpointCount: Array.isArray(review.calibrationSelection?.points) ? review.calibrationSelection.points.length : 0,
        logicalClickCount: Number(review.calibrationSelection?.logicalClickCount || 0),
        selectedEndpointFrames: (review.calibrationSelection?.points || []).map((point) => point && point.coordinateFrames || null),
        dimensionTextUsedAsProof: review.calibrationSelection?.dimensionTextUsedAsProof === true,
        receipt: review.calibrationReceipt ? {
          receiptId: review.calibrationReceipt.receiptId,
          status: review.calibrationReceipt.status,
          endpointSelectionMethod: review.calibrationReceipt.endpointSelectionMethod,
          dimensionTextUsedAsProof: review.calibrationReceipt.dimensionTextUsedAsProof === true,
          unit: review.calibrationReceipt.unit,
          normalizedMillimetres: review.calibrationReceipt.normalizedMillimetres,
          sourceEndpointsPdfPt: review.calibrationReceipt.sourceEndpointsPdfPt,
          provisionalLiveEndpointsMm: review.calibrationReceipt.provisionalLiveEndpointsMm,
          acceptedLiveEndpointsMm: review.calibrationReceipt.acceptedLiveEndpointsMm,
          sourceDistancePt: review.calibrationReceipt.sourceDistancePt,
          provisionalWorldMmPerPt: review.calibrationReceipt.provisionalWorldMmPerPt,
          acceptedWorldMmPerPt: review.calibrationReceipt.acceptedWorldMmPerPt,
          geometryScaleFactor: review.calibrationReceipt.geometryScaleFactor,
          displayPxPerMm: review.calibrationReceipt.displayPxPerMm,
          transforms: review.calibrationReceipt.transforms,
          residualsPt: review.calibrationReceipt.residualsPt,
          application: review.calibrationReceipt.application,
          acceptedTransformId: review.calibrationReceipt.acceptedTransformId
        } : null,
        predicateFixturesPass: review.calibrationPredicateFixtures?.pass === true,
        typedApplicationFixturesPass: review.typedCalibrationApplicationFixtures?.pass === true,
        atomicApplicationFixturesPass: review.atomicCalibrationApplicationFixtures?.pass === true
      },
      dimensionScale: review.dimensionScaleEvidence ? {
        status: review.dimensionScaleEvidence.status,
        labelsDetected: review.dimensionScaleEvidence.labelsDetected,
        axesDetected: review.dimensionScaleEvidence.axesDetected,
        pairCount: Array.isArray(review.dimensionScaleEvidence.pairs) ? review.dimensionScaleEvidence.pairs.length : 0,
        candidateCount: review.dimensionScaleEvidence.consensus?.candidateCount || 0,
        proposedUnit: review.dimensionScaleEvidence.unitProposal?.unit || null,
        unitConfirmationRequired: review.dimensionScaleEvidence.unitProposal?.requiresUserConfirmation === true,
        medianWorldMmPerPt: review.dimensionScaleEvidence.consensus?.medianWorldMmPerPt || null,
        consensusPass: review.dimensionScaleEvidence.consensus?.pass === true,
        assistedConsensusPass: review.dimensionScaleEvidence.consensus?.assistedPass === true,
        rejectedCandidateCount: review.dimensionScaleEvidence.consensus?.rejectedCandidateCount || 0,
        coveragePass: review.dimensionScaleEvidence.consensus?.coveragePass === true,
        automaticEligibility: review.automaticDimensionScaleEligibility || null,
        fixturesPass: review.r7DimensionScaleFixtures?.pass === true
      } : null,
      policy,
      automaticCounters: { pdf_derived_new_object_count: 0, automatic_budget_candidate_count: 0, automatic_dbspec_projection_count: 0, budgetEngineCalled: false },
      caseEventCount: (project.caseEvents || []).length,
      projectFingerprint: review.currentFingerprint
    };
    node.textContent = JSON.stringify(receipt);
  }

  function initializeR6Review(receipt) {
    const baseline = r6ProjectFingerprint(project);
    project.r6Review = {
      schema: "laibe.planPuzzle.r6.userGovernedExistingObjectReview.v1",
      caseId: receipt.caseId,
      actorId: receipt.actorId,
      importReceipt: receipt,
      records: (receipt.review && receipt.review.semanticRows || []).map((record) => ({ ...cloneJson(record), userDecision: "pending", trace: null, editableObjectId: null })),
      uncertainRecords: (receipt.review && receipt.review.uncertainRows || []).map((record) => cloneJson(record)),
      wallBodyReviewSets: (receipt.review && receipt.review.ambiguousWallBodyReviewSets || []).map((set) => cloneJson(set)),
      dimensionScaleEvidence: cloneJson(receipt.dimensionScale || null),
      automaticScaleDecision: cloneJson(receipt.scaleDecision || null),
      calibrationSelection: createR6CalibrationSelection(),
      calibrationReceipt: null,
      calibrationPredicateFixtures: createR6CalibrationPredicateFixtures(),
      typedCalibrationApplicationFixtures: createR6TypedCalibrationApplicationFixtures(),
      atomicCalibrationApplicationFixtures: createR6AtomicGeometryApplicationFixtures(),
      r7DimensionScaleFixtures: createR7DimensionScaleFixtures(),
      caseEvents: [],
      baselineFingerprint: baseline,
      currentFingerprint: baseline,
      importedAt: new Date().toISOString()
    };
    project.sourceBinding = {
      schema: "laibe.planPuzzle.sourceBinding.v1",
      sourceKind: "pdf",
      sourceSha256: normalizeSourceSha256(receipt.file?.sha256),
      importSessionId: receipt.importSessionId || null,
      fileName: receipt.file?.name || null
    };
    project.caseEvents = [];
    r6Record(null, "import", "imported_for_user_review", { kind: "genuine_user_file_selection", fileName: receipt.file.name, byteLength: receipt.file.byteLength, importSessionId: receipt.importSessionId }, "owner_or_designated_reviewer");
    if (
      receipt.scaleDecision?.status === "passed" &&
      Number(receipt.scaleDecision?.confidence) >= 0.98 &&
      receipt.scaleDecision?.audit?.pass === true
    ) {
      r6Record(null, "automatic_scale_confirmed", "accepted_automatic_dimension_scale", {
        kind: "automatic_pdf_dimension_scale",
        decisionHash: receipt.scaleDecisionHash || null,
        selectedRegionId: receipt.scaleDecision.selectedRegionId || null,
        acceptedWorldMmPerPt: Number(receipt.scaleDecision.acceptedWorldMmPerPt),
        acceptedWorldMmPerPtX: Number(receipt.scaleDecision.worldMmPerPtX),
        acceptedWorldMmPerPtY: Number(receipt.scaleDecision.worldMmPerPtY),
        confidence: Number(receipt.scaleDecision.confidence),
        evidenceIds: (receipt.scaleDecision.axes || []).flatMap((axis) => [
          axis.dimensionTextSourceId,
          axis.dimensionLineSourceId,
          ...(axis.witnessLineSourceIds || [])
        ]).filter(Boolean)
      }, "owner_or_designated_reviewer");
    }
    r6Publish();
  }

  function showPdfRecognitionOverlay(receipt) {
    const existing = document.getElementById("laibe-pdf-recognition-review");
    if (existing) existing.remove();
    const api = window.LaibePdfPlanExactSource;
    let workingManifest = receipt && receipt.manifest;
    let automaticImportStarted = false;
    const initialRegions = Array.isArray(workingManifest?.selection?.regions)
      ? workingManifest.selection.regions
      : [];
    const requiresPlanSelection = initialRegions.length > 1;
    const shell = document.createElement("div");
    shell.id = "laibe-pdf-recognition-review";
    shell.setAttribute("role", "dialog");
    shell.setAttribute("aria-modal", "true");
    shell.setAttribute("aria-label", "PDF 圖面辨識結果");
    shell.style.cssText = "position:fixed;inset:0;z-index:100001;background:rgba(7,13,18,.82);backdrop-filter:blur(8px);display:grid;place-items:center;padding:24px;font-family:system-ui,'Noto Sans TC',sans-serif";
    shell.innerHTML = `
      <div style="width:min(1180px,96vw);height:min(900px,92vh);background:#F7FAFC;border:1px solid rgba(255,255,255,.25);border-radius:18px;box-shadow:0 28px 90px rgba(0,0,0,.45);display:grid;grid-template-rows:auto 1fr;overflow:hidden">
        <header style="display:flex;align-items:flex-start;gap:18px;padding:18px 20px;background:#10212B;color:#fff">
          <div style="flex:1;min-width:0"><div style="font-size:12px;color:#8EDFF4;margin-bottom:5px">正在辨識圖面</div><h2 style="margin:0 0 6px;font-size:19px">${requiresPlanSelection ? "選擇要使用的平面圖" : "系統正在確認圖面比例"}</h2><p style="margin:0;color:#C9D7DE;font-size:13px;line-height:1.55">${requiresPlanSelection ? "請從縮圖選擇平面圖，系統會依尺寸標註確認比例。" : "系統會依尺寸標註確認比例，通過後直接建立可編輯物件。"}</p></div>
          <button type="button" data-recognition-close style="border:1px solid rgba(255,255,255,.25);background:transparent;color:#fff;border-radius:10px;padding:8px 12px;cursor:pointer">關閉</button>
        </header>
        <div style="display:grid;grid-template-columns:minmax(0,1fr) 300px;min-height:0">
          <div style="position:relative;min-height:0;overflow:auto;background:#DDE5E9;padding:18px">
            <div style="position:relative;width:min(100%,760px);margin:auto;background:white;box-shadow:0 8px 28px rgba(20,36,45,.18)">
              <canvas data-recognition-preview aria-label="來源 PDF 平面圖預覽" style="display:block;width:100%;height:auto"></canvas>
              <img data-recognition-source alt="" hidden/>
              <div data-recognition-overlay aria-label="辨識分類覆蓋圖" style="position:absolute;inset:0;pointer-events:none"></div>
            </div>
          </div>
	          <aside style="padding:18px;border-left:1px solid #D5E0E5;background:#fff;overflow:auto">
	            <div data-recognition-selection-panel ${requiresPlanSelection ? "" : "hidden"}>
	              <strong style="display:block;color:#10212B;margin-bottom:8px">選擇圖面</strong>
	              <div data-recognition-regions style="display:grid;gap:8px"></div>
	              <div data-recognition-selection-note style="margin-top:8px;color:#5B6E78;font-size:12px;line-height:1.5">請先選擇本次要使用的平面圖。</div>
	              <div style="height:1px;background:#E1E8EC;margin:18px 0"></div>
	            </div>
	            <strong style="display:block;color:#10212B;margin-bottom:6px">系統正在依尺寸標註確認比例</strong>
	            <div data-recognition-scale-state role="status" aria-live="polite" style="margin-top:8px;padding:10px;border-radius:9px;background:#EEF7FA;color:#35535F;font-size:12px;line-height:1.55">選擇圖面後，系統會自動確認比例並建立可編輯物件。</div>
          </aside>
        </div>
      </div>`;
    const sourceImage = shell.querySelector("[data-recognition-source]");
    const previewCanvas = shell.querySelector("[data-recognition-preview]");
    const overlayNode = shell.querySelector("[data-recognition-overlay]");
    const regionNode = shell.querySelector("[data-recognition-regions]");
    const selectionNote = shell.querySelector("[data-recognition-selection-note]");
    const scaleStateNode = shell.querySelector("[data-recognition-scale-state]");

    function renderSelectedRecognitionPreview() {
      if (!sourceImage.complete || !sourceImage.naturalWidth || !sourceImage.naturalHeight) return;
      const selectedRegion = Array.isArray(workingManifest?.selection?.regions)
        ? workingManifest.selection.regions.find((region) =>
            region.sourceRegionId === workingManifest?.selection?.selectedRegionId
          )
        : null;
      const pageWidth = Math.max(1, Number(workingManifest?.source?.pageWidthPt) || sourceImage.naturalWidth);
      const pageHeight = Math.max(1, Number(workingManifest?.source?.pageHeightPt) || sourceImage.naturalHeight);
      const bounds = selectedRegion?.previewBoundsPt
        ? selectedRegion.previewBoundsPt
        : { x0: 0, y0: 0, x1: pageWidth, y1: pageHeight };
      const x0 = Math.max(0, Math.min(pageWidth, Number(bounds.x0) || 0));
      const x1 = Math.max(x0 + 1, Math.min(pageWidth, Number(bounds.x1) || pageWidth));
      const y0 = Math.max(0, Math.min(pageHeight, Number(bounds.y0) || 0));
      const y1 = Math.max(y0 + 1, Math.min(pageHeight, Number(bounds.y1) || pageHeight));
      const scaleX = sourceImage.naturalWidth / pageWidth;
      const scaleY = sourceImage.naturalHeight / pageHeight;
      const sourceX = Math.round(x0 * scaleX);
      const sourceY = Math.round((pageHeight - y1) * scaleY);
      const sourceWidth = Math.max(1, Math.round((x1 - x0) * scaleX));
      const sourceHeight = Math.max(1, Math.round((y1 - y0) * scaleY));
      const recommendedRotationDegrees = Number(
        selectedRegion?.orientation?.recommendedRotationDegrees
      ) || 0;
      const quarterTurn = Math.abs(recommendedRotationDegrees) === 90;
      previewCanvas.width = quarterTurn ? sourceHeight : sourceWidth;
      previewCanvas.height = quarterTurn ? sourceWidth : sourceHeight;
      const context = previewCanvas.getContext("2d", { alpha: false });
      if (!context) return;
      context.save();
      context.fillStyle = "#FFFFFF";
      context.fillRect(0, 0, previewCanvas.width, previewCanvas.height);
      if (recommendedRotationDegrees === 90) {
        context.translate(sourceHeight, 0);
        context.rotate(Math.PI / 2);
      } else if (recommendedRotationDegrees === -90) {
        context.translate(0, sourceWidth);
        context.rotate(-Math.PI / 2);
      } else if (Math.abs(recommendedRotationDegrees) === 180) {
        context.translate(sourceWidth, sourceHeight);
        context.rotate(Math.PI);
      }
      context.drawImage(
        sourceImage,
        sourceX,
        sourceY,
        sourceWidth,
        sourceHeight,
        0,
        0,
        sourceWidth,
        sourceHeight
      );
      context.restore();
    }

    function renderRecognitionRegionThumbnails() {
      if (!requiresPlanSelection || !sourceImage.complete || !sourceImage.naturalWidth) return;
      const regions = Array.isArray(workingManifest?.selection?.regions)
        ? workingManifest.selection.regions
        : [];
      const pageWidth = Math.max(1, Number(workingManifest?.source?.pageWidthPt) || sourceImage.naturalWidth);
      const pageHeight = Math.max(1, Number(workingManifest?.source?.pageHeightPt) || sourceImage.naturalHeight);
      regionNode.querySelectorAll("[data-recognition-region-thumbnail]").forEach((canvas) => {
        const region = regions[Number(canvas.getAttribute("data-recognition-region-thumbnail"))];
        const bounds = region?.previewBoundsPt || region?.boundsPt;
        if (!bounds) return;
        const x0 = Math.max(0, Math.min(pageWidth, Number(bounds.x0) || 0));
        const x1 = Math.max(x0 + 1, Math.min(pageWidth, Number(bounds.x1) || pageWidth));
        const y0 = Math.max(0, Math.min(pageHeight, Number(bounds.y0) || 0));
        const y1 = Math.max(y0 + 1, Math.min(pageHeight, Number(bounds.y1) || pageHeight));
        const sourceX = x0 * sourceImage.naturalWidth / pageWidth;
        const sourceY = (pageHeight - y1) * sourceImage.naturalHeight / pageHeight;
        const sourceWidth = (x1 - x0) * sourceImage.naturalWidth / pageWidth;
        const sourceHeight = (y1 - y0) * sourceImage.naturalHeight / pageHeight;
        const context = canvas.getContext("2d", { alpha: false });
        if (!context) return;
        context.fillStyle = "#FFFFFF";
        context.fillRect(0, 0, canvas.width, canvas.height);
        const fit = Math.min(canvas.width / sourceWidth, canvas.height / sourceHeight);
        const width = sourceWidth * fit;
        const height = sourceHeight * fit;
        context.drawImage(
          sourceImage,
          sourceX,
          sourceY,
          sourceWidth,
          sourceHeight,
          (canvas.width - width) / 2,
          (canvas.height - height) / 2,
          width,
          height
        );
      });
    }

    function renderRecognitionReview() {
      const regions = Array.isArray(workingManifest?.selection?.regions)
        ? workingManifest.selection.regions
        : [];
      regionNode.innerHTML = requiresPlanSelection ? regions.map((region, index) => {
        const selected = region.sourceRegionId === workingManifest?.selection?.selectedRegionId;
        return `<button type="button" data-recognition-region-choice="${index}" aria-pressed="${selected ? "true" : "false"}" style="border:1px solid ${selected ? "#0D7B94" : "#CBD8DE"};background:${selected ? "#E8F7FA" : "#fff"};color:#17313D;border-radius:9px;padding:8px;text-align:left;cursor:pointer"><canvas data-recognition-region-thumbnail="${index}" width="240" height="112" aria-hidden="true" style="display:block;width:100%;height:84px;object-fit:contain;background:#fff;border-radius:6px;margin-bottom:7px"></canvas><span>${String(region.publicLabel || `圖面 ${index + 1}`)}</span></button>`;
      }).join("") : "";
      regionNode.querySelectorAll("[data-recognition-region-choice]").forEach((button) => {
        button.addEventListener("click", async () => {
          const index = Number(button.getAttribute("data-recognition-region-choice"));
          const region = regions[index];
          if (!region || !api || typeof api.selectRecognitionRegion !== "function") return;
          workingManifest = api.selectRecognitionRegion(workingManifest, region.sourceRegionId);
          automaticImportStarted = false;
          receipt.manifest = workingManifest;
          receipt.overlaySvg = typeof api.createRecognitionOverlaySvg === "function"
            ? api.createRecognitionOverlaySvg(workingManifest)
            : "";
          renderRecognitionReview();
          await beginAutomaticImport();
        });
      });

      const selectedLabel = String(workingManifest?.selection?.selectedRegionLabel || "");
      selectionNote.textContent = selectedLabel
        ? `目前選擇：${selectedLabel}`
        : "請先選擇本次要使用的平面圖。";
      overlayNode.innerHTML = selectedLabel
        ? String(receipt.overlaySvg || "")
        : "";
      renderSelectedRecognitionPreview();
      renderRecognitionRegionThumbnails();
      scaleStateNode.textContent = selectedLabel
        ? "系統正在依尺寸標註確認比例，通過後會直接建立可編輯物件。"
        : "選擇圖面後，系統會自動確認比例並建立可編輯物件。";
    }

    async function beginAutomaticImport() {
      if (
        automaticImportStarted ||
        !workingManifest?.selection?.selectedRegionId ||
        !api ||
        typeof api.approveRecognitionManifest !== "function"
      ) return;
      automaticImportStarted = true;
      scaleStateNode.style.color = "#35535F";
      scaleStateNode.textContent = "系統正在依尺寸標註確認比例，請稍候。";
      const scaleDecision = typeof api.createScaleDecisionFromRecognitionReceipt === "function"
        ? api.createScaleDecisionFromRecognitionReceipt(receipt, workingManifest)
        : null;
      if (
        !scaleDecision ||
        scaleDecision.status !== "passed" ||
        scaleDecision.confidence < 0.98 ||
        scaleDecision.audit?.pass !== true
      ) {
        automaticImportStarted = false;
        scaleStateNode.style.color = "#7C351C";
        scaleStateNode.textContent = "這份圖面的尺寸標註不足，尚未建立物件。請改用含完整尺寸標註的 PDF。";
        return;
      }
      const approvedManifest = api.approveRecognitionManifest(workingManifest, {
        reviewerId: "automatic-recognition-gate",
        mode: "automatic_candidate_conservation",
        preserveUnresolvedAsLocked: true
      });
      if (approvedManifest?.conversionGate?.status !== "passed") {
        automaticImportStarted = false;
        scaleStateNode.style.color = "#7C351C";
        scaleStateNode.textContent = "圖面內容尚未完整保留，這次沒有建立物件。";
        return;
      }
      workingManifest = approvedManifest;
      receipt.manifest = approvedManifest;
      scaleStateNode.style.color = "#176B4D";
      scaleStateNode.textContent = "比例已確認，正在建立可編輯物件。";
      const imported = await completePendingPdfRecognitionImport(approvedManifest, scaleDecision);
      if (imported) {
        shell.remove();
      } else {
        automaticImportStarted = false;
        scaleStateNode.style.color = "#7C351C";
        scaleStateNode.textContent = "這次尚未建立物件，請重新選擇圖面後再試。";
      }
    }
    shell.querySelector("[data-recognition-close]").addEventListener("click", () => shell.remove());
    document.body.appendChild(shell);
    sourceImage.addEventListener("load", () => {
      renderSelectedRecognitionPreview();
      renderRecognitionRegionThumbnails();
    }, { once: true });
    if (receipt.referenceRaster && /^data:image\//.test(String(receipt.referenceRaster.dataUrl || ""))) {
      sourceImage.src = receipt.referenceRaster.dataUrl;
    }
    renderRecognitionReview();
    if (workingManifest?.selection?.selectedRegionId) {
      window.setTimeout(() => beginAutomaticImport(), 0);
    }
  }

  async function completePendingPdfRecognitionImport(approvedManifest, scaleDecision) {
    const pending = pendingPdfRecognition;
    const api = window.LaibePdfPlanExactSource;
    if (!pending || !api || typeof api.importSelectedPdfFile !== "function") return false;
    const { sequence, rollbackSnapshot, convertSelectedFile } = pending;
    if (sequence !== importSequence) return false;
    activeR6ImportSequences.add(sequence);
    r6ImportInFlight = true;
    uiState.importPhase = "loading";
    uiState.message = "正在依確認結果建立可編輯物件。";
    render();
    try {
      const receipt = await convertSelectedFile(approvedManifest, scaleDecision);
      if (sequence !== importSequence) return false;
      if (!receipt || receipt.status !== "imported_for_user_review") {
        throw new Error("PDF 匯入未完成。");
      }
      initializeR6Review(receipt);
      const automaticScaleResult = project.scale?.autoScaleApplied === true &&
        project.scale?.acceptedTransformStatus === "accepted_automatic_dimension_scale"
        ? {
            pass: true,
            acceptedTransformId: project.scale.acceptedTransformId,
            source: "bound_automatic_dimension_decision"
          }
        : r7TryAutomaticDimensionScale();
      if (automaticScaleResult.pass) {
        uiState.layerVisibility = {
          ...uiState.layerVisibility,
          underlay: false,
          structures: true,
          review: false,
          zones: false,
          zoneReview: false,
          furniture: false,
          diagnostics: false
        };
        project.viewPreferences = isPlainObject(project.viewPreferences) ? project.viewPreferences : {};
        project.viewPreferences.layerVisibility = normalizeLayerVisibility(uiState.layerVisibility);
        fitPlanContentToView({ message: false, render: false });
      }
      finalizeFreshSourceProjectCommit({ completeImportTransaction: true });
      pendingPdfRecognition = null;
      uiState.importPhase = "imported";
      uiState.inspectorTab = "overview";
      uiState.message = automaticScaleResult.pass
        ? "圖面已匯入，並已依一致的尺寸標註自動套用比例。請檢查牆線與門窗位置。"
        : "圖面已匯入，但尺寸標註不足、互相衝突或單位無法唯一判定。系統不會套用猜測比例。";
      return true;
    } catch (error) {
      if (sequence === importSequence) {
        restoreSourceImportRollbackSnapshot(rollbackSnapshot, "新 PDF 未完成匯入；目前草稿保持不變。請確認檔案後再試。");
      }
      return false;
    } finally {
      activeR6ImportSequences.delete(sequence);
      r6ImportInFlight = activeR6ImportSequences.size > 0;
      if (sequence === importSequence && uiState.importPhase === "imported") syncBridge();
      if (sequence === importSequence) render();
    }
  }

  async function importSelectedR6Pdf(file, importedAt, sequence, rollbackSnapshot) {
    const api = window.LaibePdfPlanExactSource;
    if (!api || typeof api.presentSelectedPdfFile !== "function") {
      if (sequence === importSequence) {
        restoreSourceImportRollbackSnapshot(rollbackSnapshot, "PDF 底圖呈現功能正在整理中，請稍後再試。");
      }
      return;
    }
    activeR6ImportSequences.add(sequence);
    r6ImportInFlight = true;
    if (sequence === importSequence) {
      uiState.importPhase = "loading";
      uiState.importError = "";
      uiState.error = "";
      uiState.message = "正在讀取 PDF 頁面與來源資訊…";
      render();
    }
    try {
      const presentation = await api.presentSelectedPdfFile(file, { pageNumber: 1 });
      if (sequence !== importSequence) return;
      if (!presentation || presentation.status !== "source_presentation_ready") {
        throw new Error("PDF 來源頁面尚未準備完成。");
      }
      const sourceSha256 = normalizeSourceSha256(presentation.selectedSha256);
      const selectedPageNumber = Number(presentation.selectedPageNumber);
      const pageCount = Number(presentation.pageCount);
      const referenceRaster = presentation.referenceRaster;
      if (
        !sourceSha256 ||
        !Number.isInteger(selectedPageNumber) ||
        selectedPageNumber < 1 ||
        !Number.isInteger(pageCount) ||
        pageCount < selectedPageNumber ||
        !referenceRaster ||
        !/^data:image\//.test(String(referenceRaster.dataUrl || ""))
      ) {
        throw new Error("PDF 來源識別或頁面底圖不完整。");
      }

      beginFreshSourceProjectCommit();
      const importSessionId = `pdf-presentation-${sequence}`;
      project.importSource = {
        ...createImportSource(file, "pdf", true, "pdf-source-presentation", importedAt, sourceSha256),
        sourceDocumentSha256: sourceSha256,
        sourcePageNumber: selectedPageNumber,
        pageCount,
        presentationStatus: presentation.status
      };
      project.underlay = {
        id: createId("underlay"),
        fileName: file.name,
        fileType: "pdf",
        dataUrl: referenceRaster.dataUrl,
        naturalWidth: Number(referenceRaster.naturalWidth) || null,
        naturalHeight: Number(referenceRaster.naturalHeight) || null,
        displayWidth: Number(presentation.displayWidth),
        displayHeight: Number(presentation.displayHeight),
        sourceRotationDegrees: Number(presentation.rotation),
        x: 0,
        y: 0,
        scale: 1,
        rotation: 0,
        opacity: DEFAULT_UNDERLAY_OPACITY,
        calibratedBy: null,
        renderMode: "pdf-background-presentation",
        sourceType: "pdf",
        source: referenceRaster.source || "browser-pdfjs-selected-page-render",
        sourceSha256,
        sourcePdfSha256: sourceSha256,
        sourcePageNumber: selectedPageNumber,
        pageCount,
        presentationOnly: true
      };
      project.sourceBinding = {
        schema: "laibe.planPuzzle.sourceBinding.v1",
        sourceKind: "pdf",
        sourceSha256,
        importSessionId,
        fileName: file.name,
        pageNumber: selectedPageNumber
      };
      project.sourcePresentation = {
        schema: "laibe.planPuzzle.pdfSourcePresentationState.v1",
        status: "awaiting_a11_bundle_and_user_scale_confirmation",
        sourceDocumentSha256: sourceSha256,
        pageNumber: selectedPageNumber,
        pageCount,
        a11BundleId: null,
        userScaleConfirmationStatus: "pending",
        importedAt
      };
      pendingPdfRecognition = null;
      resetScaleAndInteraction("PDF 底圖已匯入。下一步：等待圖面辨識資料，並由使用者確認比例。");
      finalizeFreshSourceProjectCommit({ completeImportTransaction: true });
      fitUnderlayToCanvas("pdf-source-presentation-fit", false);
      uiState.importPhase = "source_presentation_ready";
      uiState.importError = "";
      uiState.inspectorTab = "overview";
      syncBridge();
    } catch (error) {
      if (sequence === importSequence) {
        restoreSourceImportRollbackSnapshot(rollbackSnapshot, "PDF 底圖匯入失敗，原案件內容已保留。");
      }
    } finally {
      activeR6ImportSequences.delete(sequence);
      r6ImportInFlight = activeR6ImportSequences.size > 0;
      if (sequence === importSequence && (
        uiState.importPhase === "imported" ||
        uiState.importPhase === "source_presentation_ready"
      )) {
        syncBridge();
      }
      if (sequence === importSequence) render();
    }
  }

  function r6SelectedRecord() {
    return (project.r6Review?.records || []).find((record) => record.sourceId === uiState.r6SelectedSourceId) || null;
  }

  function r6FindReviewShapeForSourceId(sourceId) {
    return (project.pdfReviewObjects?.shapes || []).find((shape) =>
      shape && (shape.source_object_id === sourceId || shape.sourceId === sourceId || shape.id === sourceId)) || null;
  }

  function r6FindNativeCandidateForSourceId(sourceId) {
    return [].concat(project.openings || [], project.zones || []).find((item) => (
      item && item.candidateOnly === true && (item.source_object_id === sourceId || item.sourceId === sourceId)
    )) || null;
  }

  function r6FocusSourceCandidate(sourceId) {
    const shape = r6FindReviewShapeForSourceId(sourceId);
    uiState.r6SelectedSourceId = sourceId || null;
    if (shape) uiState.selectedPdfReviewRef = { kind: "shape", id: shape.id };
    return Boolean(shape);
  }

  function r6CanPromoteNativeCandidate(record) {
    if (!record || record.userDecision !== "confirmed_pending_calibration") return false;
    if (record.category === "stair") return false;
    if (project.r6Review?.calibrationReceipt?.status !== "accepted_for_existing_object_review") return false;
    const shape = r6FindReviewShapeForSourceId(record.sourceId);
    if (!shape) return false;
    const nativeCandidate = r6FindNativeCandidateForSourceId(record.sourceId);
    if (nativeCandidate) return true;
    if (record.category !== "opening") return false;
    const hostSourceIds = Array.isArray(shape.candidateEvidence?.hostWallSourceIds) ? shape.candidateEvidence.hostWallSourceIds : [];
    return hostSourceIds.some((sourceId) => (project.walls || []).some((wall) => wall.source_object_id === sourceId || wall.sourceWallId === sourceId));
  }

  function r6SetDecision(sourceId, decision) {
    const record = (project.r6Review?.records || []).find((item) => item.sourceId === sourceId);
    if (!record) return;
    const before = r6ProjectFingerprint(project);
    record.userDecision = decision;
    r6FocusSourceCandidate(sourceId);
    r6Record(sourceId, decision === "rejected" ? "reject" : "review", decision, { kind: "user_review", sourceRegionId: record.sourceRegionId }, decision === "rejected" ? "case_record" : "scale_reviewer", before);
    r6Publish();
  }

  function r6PromoteReviewedCandidate(sourceId) {
    const record = (project.r6Review?.records || []).find((item) => item.sourceId === sourceId);
    const receipt = project.r6Review?.calibrationReceipt;
    const shape = r6FindReviewShapeForSourceId(sourceId);
    if (record?.category === "stair") {
      uiState.error = "樓梯會保留為來源圖面線條，不建立可編輯圖塊。";
      render();
      return;
    }
    if (!r6CanPromoteNativeCandidate(record) || !receipt || !shape) {
      uiState.error = "請先完成比例確認，並選擇具有完整來源依據的候選項目。";
      render();
      return;
    }
    const before = r6ProjectFingerprint(project);
    const now = new Date().toISOString();
    const nativeCandidate = r6FindNativeCandidateForSourceId(sourceId);
    if (nativeCandidate) {
      nativeCandidate.candidateOnly = false;
      nativeCandidate.reviewRequired = false;
      nativeCandidate.objectState = "existing_object";
      nativeCandidate.mapping_state = "accepted_existing_object_review";
      nativeCandidate.editable_object_id = nativeCandidate.id;
      nativeCandidate.acceptedTransformId = receipt.acceptedTransformId;
      nativeCandidate.acceptedTransformStatus = "accepted_for_existing_object_review";
      nativeCandidate.r6AppliedTransformId = receipt.acceptedTransformId;
      nativeCandidate.updatedAt = now;
      shape.promotionEditableObjectId = nativeCandidate.id;
      shape.hiddenByUser = true;
      record.editableObjectId = nativeCandidate.id;
      record.userDecision = "accepted_existing_object_review";
      record.editablePolicy = { source_kind: "pdf", object_status: "existing", work_action: "none", budget_trigger: "none", dbspec_projection: "excluded" };
      if (nativeCandidate.edgeId) {
        uiState.selectedOpeningId = nativeCandidate.id;
        uiState.selectedWallId = nativeCandidate.wallId || null;
        uiState.selectedEdgeId = nativeCandidate.edgeId;
      } else {
        uiState.selectedZoneId = nativeCandidate.id;
      }
      r6Record(sourceId, "accept_existing_object", "accepted_existing_object_review", {
        kind: "native_pdf_existing_candidate_promotion", editableObjectId: nativeCandidate.id,
        nativeCollection: nativeCandidate.edgeId ? "project.openings" : "project.zones",
        acceptedTransformId: receipt.acceptedTransformId
      }, "owner_or_designated_reviewer", before);
      r6Publish();
      return;
    }
    let editable = null;
    const kind = record.subtype === "hinged_door" ? "door" : (record.subtype === "window" ? "window" : null);
      const hostSourceIds = Array.isArray(shape.candidateEvidence?.hostWallSourceIds) ? shape.candidateEvidence.hostWallSourceIds : [];
      const hostWall = (project.walls || []).find((wall) => hostSourceIds.includes(wall.source_object_id) || hostSourceIds.includes(wall.sourceWallId));
      const edge = hostWall ? getEdgeForWall(hostWall.id) : null;
      if (!kind || !edge) {
        uiState.error = "這個候選項目缺少可驗證的牆體關係，尚不能建立既有物件。";
        render();
        return;
      }
      const candidateWidth = Math.max(300, Math.round(Math.max(shape.widthMm, shape.heightMm)));
      const width = Math.min(Math.max(300, edge.length - 20), candidateWidth);
      if (!(width > 0) || width > edge.length) {
        uiState.error = "候選開口尺寸與來源牆體不相容，尚不能建立既有物件。";
        render();
        return;
      }
      const center = { x: Number(shape.position.x) + Number(shape.widthMm) / 2, y: Number(shape.position.y) + Number(shape.heightMm) / 2 };
      const offset = clamp(Math.round(projectPointDistanceOnEdge(center, edge) - width / 2), 0, Math.max(0, edge.length - width));
      const preset = createOpeningPresetFields({ kind, width, openingType: kind === "door" ? "swing_door" : "fixed_window" });
      editable = syncOpeningContractFields({
        id: `pdf-existing-${kind}-${r6StableToken({ sourceId, acceptedTransformId: receipt.acceptedTransformId })}`,
        edgeId: edge.id, sourceWallId: hostWall.sourceWallId || hostWall.source_object_id, wallId: hostWall.id,
        kind: preset.kind, openingType: preset.openingType, openingPreset: preset.openingPreset, openingLabel: preset.openingLabel,
        width: preset.width, widthMm: preset.width, offset, offsetMm: offset,
        height: kind === "door" ? 2100 : 1200, heightMm: kind === "door" ? 2100 : 1200,
        source_kind: "pdf", object_status: "existing", work_action: "none", budget_trigger: "none", dbspec_projection: "excluded",
        source_object_id: sourceId, source_object_ids: [sourceId], sourceRegionId: record.sourceRegionId, sourceBBox: record.sourceBBox,
        sourcePdfSha256: project.r6Review.importReceipt.file.sha256, importSessionId: project.r6Review.importReceipt.importSessionId,
        acceptedTransformId: receipt.acceptedTransformId, r6AppliedTransformId: receipt.acceptedTransformId,
        mapping_state: "not_accepted", candidateOnly: false, reviewRequired: true, editable_object_id: null,
        budgetExcluded: true, noBudgetTrigger: true, formalOutput: false, createdAt: now, updatedAt: now
      }, edge);
      const validation = validateOpening(editable, edge);
      if (!validation.valid) {
        uiState.error = validation.error || "候選開口未通過既有物件驗證。";
        render();
        return;
      }
      project.openings.push(editable);
      uiState.selectedOpeningId = editable.id;
      uiState.selectedWallId = hostWall.id;
      uiState.selectedEdgeId = edge.id;
    shape.promotionEditableObjectId = editable.id;
    shape.hiddenByUser = true;
    record.editableObjectId = editable.id;
    record.userDecision = "accepted_existing_object_review";
    record.editablePolicy = { source_kind: "pdf", object_status: "existing", work_action: "none", budget_trigger: "none", dbspec_projection: "excluded" };
    r6Record(sourceId, "accept_existing_object", "accepted_existing_object_review", {
      kind: "native_pdf_existing_object_promotion", editableObjectId: editable.id,
      nativeCollection: "project.openings",
      acceptedTransformId: receipt.acceptedTransformId
    }, "owner_or_designated_reviewer", before);
    r6Publish();
  }

  function r6SubmitCalibration() {
    if (!isR6ReviewActive()) return;
    const field = (name) => document.querySelector(`[data-field='${name}']`);
    const selection = project.r6Review.calibrationSelection || createR6CalibrationSelection();
    const enteredLength = Number(field("r6-known-length")?.value);
    const unit = String(field("r6-unit")?.value || "");
    const multipliers = { mm: 1, cm: 10, m: 1000 };
    const actor = String(field("r6-calibration-actor")?.value || "").trim();
    const reviewer = String(field("r6-calibration-reviewer")?.value || "").trim();
    const eligibility = evaluateR6CalibrationReceiptEligibility({
      selection,
      enteredLength,
      unit,
      actor,
      reviewer,
      caseId: project.r6Review.caseId,
      sourceSha256: project.r6Review.importReceipt.file.sha256,
      acceptedTransformId: null,
      genericScaleCalibrated: Boolean(project.scale?.calibrated)
    });
    if (!eligibility.pass) {
      uiState.error = "請先在畫布上選取兩個不同端點，再填寫正確的實際長度、單位、操作人與審閱人。";
      render();
      return;
    }
    const normalizedMillimetres = Number((enteredLength * multipliers[unit]).toFixed(3));
    const transform = r6BuildTypedCalibrationTransform(selection, normalizedMillimetres);
    if (!transform || !Number.isFinite(transform.sourceDistancePt) || transform.sourceDistancePt <= 0 || transform.residualsPt.max > R6_CALIBRATION_RESIDUAL_TOLERANCE_PT) {
      uiState.error = "比例校正點尚未建立可驗證的座標轉換，請重新選取兩個點。";
      render();
      return;
    }
    const before = r6ProjectFingerprint(project);
    project.r6Review.calibrationReceipt = {
      schema: "laibe.planPuzzle.r6.scaleCalibrationReceipt.v2",
      receiptId: `r6-calibration-${r6StableToken({ sourceSha256: project.r6Review.importReceipt.file.sha256, sourceEndpointsPdfPt: transform.sourceEndpointsPdfPt, normalizedMillimetres, unit, caseId: project.r6Review.caseId })}`,
      sourceSha256: project.r6Review.importReceipt.file.sha256,
      source: {
        page: project.r6Review.importReceipt.source?.page || 1,
        regionId: "user-selected-source-region",
        coordinateFrame: R6_SOURCE_POINT_FRAME,
        sourcePageHeightPt: r6SourcePageHeightPt(project.r6Review)
      },
      sourceEndpointsPdfPt: transform.sourceEndpointsPdfPt,
      provisionalLiveEndpointsMm: transform.provisionalLiveEndpointsMm,
      acceptedLiveEndpointsMm: null,
      endpointSelectionMethod: "canvas_two_point_user_action",
      dimensionTextUsedAsProof: false,
      userEnteredRealLength: enteredLength,
      unit,
      normalizedMillimetres,
      actor,
      reviewer,
      caseId: project.r6Review.caseId,
      time: new Date().toISOString(),
      sourceDistancePt: transform.sourceDistancePt,
      provisionalWorldMmPerPt: transform.provisionalWorldMmPerPt,
      acceptedWorldMmPerPt: transform.acceptedWorldMmPerPt,
      geometryScaleFactor: transform.geometryScaleFactor,
      displayPxPerMm: transform.displayPxPerMm,
      transforms: { forward: transform.forward, inverse: transform.inverse },
      residualsPt: transform.residualsPt,
      beforeProjectFingerprint: before,
      afterProjectFingerprint: null,
      acceptedTransformId: null,
      status: "submitted_for_acceptance",
      application: { status: "not_applied", appliedTransformId: null, geometryScaleFactor: transform.geometryScaleFactor, appliedOnce: false },
      evidence: { source: "canvas_two_point_user_action_and_entered_length", logicalClickCount: selection.logicalClickCount },
      eligibility
    };
    selection.status = "submitted_for_acceptance";
    project.r6Review.calibrationSelection = selection;
    r6Record(null, "calibration_submitted", "submitted_for_acceptance", {
      kind: "known_length_and_unit",
      unit,
      enteredLength,
      normalizedMillimetres,
      endpointSelectionMethod: selection.endpointSelectionMethod,
      sourceEndpointsPdfPt: transform.sourceEndpointsPdfPt,
      provisionalLiveEndpointsMm: transform.provisionalLiveEndpointsMm,
      acceptedWorldMmPerPt: transform.acceptedWorldMmPerPt,
      geometryScaleFactor: transform.geometryScaleFactor
    }, reviewer, before);
    r6Publish();
  }

  function r6ScalePointValue(point, factor) {
    const factors = typeof factor === "object" && factor
      ? { x: Number(factor.x), y: Number(factor.y) }
      : { x: Number(factor), y: Number(factor) };
    return r6FinitePoint(point) && Number.isFinite(factors.x) && factors.x > 0 && Number.isFinite(factors.y) && factors.y > 0
      ? r6RoundPoint({ x: point.x * factors.x, y: point.y * factors.y })
      : point;
  }

  function r9GeometryFactors(receipt) {
    const uniform = Number(receipt?.geometryScaleFactor);
    const x = Number(receipt?.geometryScaleFactorX || uniform);
    const y = Number(receipt?.geometryScaleFactorY || uniform);
    return { x, y, uniform: (x + y) / 2 };
  }

  function r9DirectionalFactor(item, factors) {
    const edge = r6FinitePoint(item?.from) && r6FinitePoint(item?.to)
      ? { from: item.from, to: item.to }
      : r6FinitePoint(item?.sourceHostEdge?.from) && r6FinitePoint(item?.sourceHostEdge?.to)
        ? item.sourceHostEdge
        : null;
    if (!edge) return factors.uniform;
    const dx = Number(edge.to.x) - Number(edge.from.x);
    const dy = Number(edge.to.y) - Number(edge.from.y);
    const length = Math.hypot(dx, dy);
    return length > 0 ? Math.hypot(dx * factors.x, dy * factors.y) / length : factors.uniform;
  }

  function r9PerpendicularFactor(item, factors) {
    if (!r6FinitePoint(item?.from) || !r6FinitePoint(item?.to)) return factors.uniform;
    const dx = Number(item.to.x) - Number(item.from.x);
    const dy = Number(item.to.y) - Number(item.from.y);
    const length = Math.hypot(dx, dy);
    return length > 0 ? Math.hypot(dy * factors.x, dx * factors.y) / length : factors.uniform;
  }

  function r6RoundNumber(value) {
    return Math.round(Number(value) * 1000) / 1000;
  }

  function r6GeometryDescriptor(item, category) {
    const pointKeys = ["from", "to", "position", "labelPosition", "center"].filter((key) => Object.prototype.hasOwnProperty.call(item || {}, key));
    const numericKeys = ["x", "y", "widthMm", "heightMm", "depthMm", "width", "height", "depth", "lengthMm", "thickness", "fontSizeMm", "radiusMm", "radius", "offset", "offsetMm", "positionOnWallMm", "sillHeight", "sillHeightMm", "planSymbolDepthMm", "sourceSymbolWidthMm"].filter((key) => Object.prototype.hasOwnProperty.call(item || {}, key));
    const pointArrayKeys = ["points", "polygon", "polygonMm"].filter((key) => Array.isArray(item && item[key]));
    const hasPoints = pointArrayKeys.includes("points");
    const hasPointArrays = pointArrayKeys.length > 0;
    const invalidPointKeys = pointKeys.filter((key) => !r6FinitePoint(item[key]));
    const invalidNumericKeys = numericKeys.filter((key) => !Number.isFinite(Number(item[key])));
    const invalidPointArray = pointArrayKeys.some((key) => !item[key].every(r6FinitePoint));
    const hasGeometry = pointKeys.length > 0 || numericKeys.length > 0 || hasPointArrays;
    const invalidWallLine = category === "walls" && (!r6FinitePoint(item.from) || !r6FinitePoint(item.to) || r6PointDistance(item.from, item.to) <= 0);
    return {
      pointKeys,
      numericKeys,
      pointArrayKeys,
      hasPoints,
      hasPointArrays,
      hasGeometry,
      invalidPointKeys,
      invalidNumericKeys,
      invalidPointArray,
      invalidWallLine,
      valid: hasGeometry && invalidPointKeys.length === 0 && invalidNumericKeys.length === 0 && !invalidPointArray && !invalidWallLine
    };
  }

  function r6BuildCalibrationGeometryInventory(targetProject) {
    const collections = [
      ["walls", targetProject && targetProject.walls],
      ["structures", targetProject && targetProject.structures],
      ["structuralObjects", targetProject && targetProject.structuralObjects],
      ["openings", targetProject && targetProject.openings],
      ["zones", targetProject && targetProject.zones],
      ["furniture", targetProject && targetProject.furniture],
      ["reviewLines", targetProject && targetProject.pdfReviewObjects && targetProject.pdfReviewObjects.lines],
      ["reviewShapes", targetProject && targetProject.pdfReviewObjects && targetProject.pdfReviewObjects.shapes],
      ["reviewText", targetProject && targetProject.pdfReviewObjects && targetProject.pdfReviewObjects.text]
    ];
    const seen = new Set();
    const ids = new Set();
    const duplicates = [];
    const invalid = [];
    const conflicts = [];
    const items = [];
    const categoryCounts = {};

    collections.forEach(([category, collection]) => {
      (collection || []).forEach((item, index) => {
        if (!item || seen.has(item) || !isPdfDerivedExistingObject(item)) return;
        seen.add(item);
        const itemId = String(item.id || item.source_object_id || item.sourceWallId || item.sourceColumnId || `${category}-${index + 1}`);
        const inventoryId = `${category}:${itemId}`;
        const descriptor = r6GeometryDescriptor(item, category);
        const row = { inventoryId, itemId, category, item, descriptor };
        items.push(row);
        categoryCounts[category] = (categoryCounts[category] || 0) + 1;
        if (ids.has(inventoryId)) duplicates.push(inventoryId);
        ids.add(inventoryId);
        if (!descriptor.valid) invalid.push({ inventoryId, category, descriptor });
        if (item.r6AppliedTransformId) conflicts.push({ inventoryId, appliedTransformId: item.r6AppliedTransformId });
      });
    });

    const underlay = targetProject && targetProject.underlay;
    const vectorUnderlay = underlay && underlay.sourceType === "vector_pdf" &&
      ["plan-puzzle-provisional-live-mm", "provisional-live-mm"].includes(String(underlay.coordinateFrame || underlay.worldCoordinateFrame || ""));
    const underlayDescriptor = vectorUnderlay ? r6GeometryDescriptor(underlay, "pdfVectorUnderlay") : null;
    if (vectorUnderlay && !underlayDescriptor.valid) invalid.push({ inventoryId: "pdfVectorUnderlay", category: "pdfVectorUnderlay", descriptor: underlayDescriptor });

    return {
      schema: "laibe.planPuzzle.r6.calibrationGeometryInventory.v1",
      items,
      categoryCounts,
      total: items.length,
      duplicateInventoryIds: duplicates,
      invalid,
      conflicts,
      vectorUnderlay: vectorUnderlay ? { applicable: true, underlay, descriptor: underlayDescriptor } : { applicable: false, reason: "underlayNotApplicable" }
    };
  }

  function r6ScalePdfExistingGeometryItem(item, descriptor, factor, acceptedTransformId, receipt, category) {
    if (!item || !descriptor || !descriptor.valid || !isPdfDerivedExistingObject(item)) return { pass: false, reason: "invalid_pdf_existing_geometry" };
    if (item.r6AppliedTransformId) return { pass: false, reason: "conflicting_item_transform" };
    const factors = typeof factor === "object" && factor ? factor : { x: Number(factor), y: Number(factor), uniform: Number(factor) };
    const directionalFactor = r9DirectionalFactor(item, factors);
    const perpendicularFactor = r9PerpendicularFactor(item, factors);
    descriptor.pointKeys.forEach((key) => { item[key] = r6ScalePointValue(item[key], factors); });
    descriptor.numericKeys.forEach((key) => {
      let numericFactor = factors.uniform;
      if (key === "x") numericFactor = factors.x;
      else if (key === "y") numericFactor = factors.y;
      else if (["lengthMm", "offset", "offsetMm", "positionOnWallMm", "width", "widthMm", "sourceSymbolWidthMm"].includes(key)) numericFactor = directionalFactor;
      else if (["thickness", "planSymbolDepthMm"].includes(key)) numericFactor = perpendicularFactor;
      else if (["height", "heightMm"].includes(key) && category !== "openings") numericFactor = factors.y;
      item[key] = r6RoundNumber(item[key] * numericFactor);
    });
    (descriptor.pointArrayKeys || (descriptor.hasPoints ? ["points"] : [])).forEach((key) => {
      item[key] = item[key].map((point) => r6ScalePointValue(point, factor));
    });
    if ((descriptor.pointArrayKeys || []).some((key) => key === "polygon" || key === "polygonMm")) {
      item.r6AppliedPolygonTransformId = acceptedTransformId;
      item.polygonCoordinateFrame = "accepted-live-mm";
      invalidateZoneAreaConfirmation(item);
    }
    item.r6AppliedTransformId = acceptedTransformId;
    item.r6AppliedGeometryScaleFactor = factors.uniform;
    item.r6AppliedGeometryScaleFactorX = factors.x;
    item.r6AppliedGeometryScaleFactorY = factors.y;
    item.acceptedTransformId = acceptedTransformId;
    item.acceptedWorldMmPerPt = Number(receipt.acceptedWorldMmPerPt);
    item.acceptedWorldMmPerPtX = Number(receipt.acceptedWorldMmPerPtX || receipt.acceptedWorldMmPerPt);
    item.acceptedWorldMmPerPtY = Number(receipt.acceptedWorldMmPerPtY || receipt.acceptedWorldMmPerPt);
    item.r6CalibrationStatus = "accepted_for_existing_object_review";
    item.coordinateFrame = item.coordinateFrame || "plan-puzzle-live-mm";
    if (category === "openings") item.r6AppliedOpeningMetricTransformId = acceptedTransformId;
    return { pass: true };
  }

  function r6ScalePdfUnderlayFrame(frame, factor) {
    if (!isPlainObject(frame)) return frame;
    const scaled = { ...frame };
    const factors = typeof factor === "object" && factor ? factor : { x: Number(factor), y: Number(factor), uniform: Number(factor) };
    ["xMm", "yMm", "widthMm", "heightMm", "x", "y", "width", "height"].forEach((key) => {
      if (Object.prototype.hasOwnProperty.call(scaled, key) && Number.isFinite(Number(scaled[key]))) {
        const axisFactor = ["xMm", "widthMm", "x", "width"].includes(key) ? factors.x : factors.y;
        scaled[key] = r6RoundNumber(Number(scaled[key]) * axisFactor);
      }
    });
    return scaled;
  }

  function r6ScalePdfUnderlayFrameMetrics(underlay, factor, acceptedTransformId, acceptedWorldMmPerPt, acceptedWorldMmPerPtX = acceptedWorldMmPerPt, acceptedWorldMmPerPtY = acceptedWorldMmPerPt) {
    const factors = typeof factor === "object" && factor ? factor : { x: Number(factor), y: Number(factor), uniform: Number(factor) };
    if (!underlay || !acceptedTransformId || !Number.isFinite(factors.x) || factors.x <= 0 || !Number.isFinite(factors.y) || factors.y <= 0 || !Number.isFinite(acceptedWorldMmPerPt) || acceptedWorldMmPerPt <= 0) {
      return { pass: false, reason: "invalid_pdf_underlay_frame_transform" };
    }
    if (underlay.r6AppliedFrameTransformId) {
      return {
        pass: underlay.r6AppliedFrameTransformId === acceptedTransformId,
        reason: underlay.r6AppliedFrameTransformId === acceptedTransformId ? null : "conflicting_pdf_underlay_frame_transform",
        status: "underlayFrameAlreadyTransformed"
      };
    }
    const coordinateWidthMm = Number(underlay.coordinateWidthMm);
    const coordinateHeightMm = Number(underlay.coordinateHeightMm);
    if (!(coordinateWidthMm > 0) || !(coordinateHeightMm > 0)) {
      return { pass: false, reason: "invalid_pdf_underlay_coordinate_extent" };
    }
    underlay.coordinateWidthMm = r6RoundNumber(coordinateWidthMm * factors.x);
    underlay.coordinateHeightMm = r6RoundNumber(coordinateHeightMm * factors.y);
    ["pageFrame", "visibleFrame", "worldFrame", "visibleWorldFrame", "pdfVectorFrame"].forEach((key) => {
      if (isPlainObject(underlay[key])) underlay[key] = r6ScalePdfUnderlayFrame(underlay[key], factor);
    });
    if (isPlainObject(underlay.cropOffset)) underlay.cropOffset = r6ScalePdfUnderlayFrame(underlay.cropOffset, factor);
    underlay.mmPerPt = acceptedWorldMmPerPt;
    underlay.mmPerPtX = acceptedWorldMmPerPtX;
    underlay.mmPerPtY = acceptedWorldMmPerPtY;
    underlay.coordinateFrame = "plan-puzzle-accepted-live-mm";
    underlay.r6AppliedFrameTransformId = acceptedTransformId;
    underlay.r6AppliedFrameScaleFactor = factors.uniform;
    underlay.r6AppliedFrameScaleFactorX = factors.x;
    underlay.r6AppliedFrameScaleFactorY = factors.y;
    return { pass: true, status: "transformed_pdf_underlay_frame" };
  }

  function r6ScalePdfVectorUnderlay(vectorUnderlay, factor, acceptedTransformId, receipt) {
    if (!vectorUnderlay || !vectorUnderlay.applicable) return { pass: true, status: "underlayNotApplicable" };
    const underlay = vectorUnderlay.underlay;
    const descriptor = vectorUnderlay.descriptor;
    if (!descriptor || !descriptor.valid || underlay.r6AppliedTransformId) return { pass: false, reason: "invalid_or_conflicting_pdf_vector_underlay" };
    const factors = typeof factor === "object" && factor ? factor : { x: Number(factor), y: Number(factor), uniform: Number(factor) };
    descriptor.pointKeys.forEach((key) => { underlay[key] = r6ScalePointValue(underlay[key], factors); });
    descriptor.numericKeys.forEach((key) => {
      const numericFactor = ["x", "width", "widthMm"].includes(key) ? factors.x : ["y", "height", "heightMm"].includes(key) ? factors.y : factors.uniform;
      underlay[key] = r6RoundNumber(underlay[key] * numericFactor);
    });
    if (descriptor.hasPoints) underlay.points = underlay.points.map((point) => r6ScalePointValue(point, factors));
    const frameResult = r6ScalePdfUnderlayFrameMetrics(
      underlay,
      factors,
      acceptedTransformId,
      Number(receipt.acceptedWorldMmPerPt),
      Number(receipt.acceptedWorldMmPerPtX || receipt.acceptedWorldMmPerPt),
      Number(receipt.acceptedWorldMmPerPtY || receipt.acceptedWorldMmPerPt)
    );
    if (!frameResult.pass) return frameResult;
    underlay.coordinateFrame = "plan-puzzle-accepted-live-mm";
    underlay.r6AppliedTransformId = acceptedTransformId;
    underlay.r6AppliedGeometryScaleFactor = factors.uniform;
    underlay.r6AppliedGeometryScaleFactorX = factors.x;
    underlay.r6AppliedGeometryScaleFactorY = factors.y;
    underlay.acceptedWorldMmPerPt = Number(receipt.acceptedWorldMmPerPt);
    underlay.acceptedWorldMmPerPtX = Number(receipt.acceptedWorldMmPerPtX || receipt.acceptedWorldMmPerPt);
    underlay.acceptedWorldMmPerPtY = Number(receipt.acceptedWorldMmPerPtY || receipt.acceptedWorldMmPerPt);
    return { pass: true, status: "transformed_pdf_vector_underlay", frameStatus: frameResult.status };
  }

  function r6BuildFixtureNodeGraph(targetProject) {
    const edges = (targetProject.walls || [])
      .filter((wall) => wall && r6FinitePoint(wall.from) && r6FinitePoint(wall.to) && wall.closureEligible !== false)
      .map((wall) => ({
        id: `r6-fixture-edge-${wall.id}`,
        sourceWallId: wall.sourceWallId || wall.id,
        from: r6RoundPoint(wall.from),
        to: r6RoundPoint(wall.to)
      }));
    return { nodes: [], edges, closureDiagnostics: { sourceWallCount: (targetProject.walls || []).length, edgeCount: edges.length } };
  }

  function r6PointMatchesCurrentWall(wall, point, tolerance = 0.5) {
    if (!wall || !r6FinitePoint(wall.from) || !r6FinitePoint(wall.to) || !r6FinitePoint(point)) return false;
    const dx = wall.to.x - wall.from.x;
    const dy = wall.to.y - wall.from.y;
    const length = Math.hypot(dx, dy);
    if (length <= 0) return false;
    const cross = Math.abs((point.x - wall.from.x) * dy - (point.y - wall.from.y) * dx) / length;
    const dot = (point.x - wall.from.x) * dx + (point.y - wall.from.y) * dy;
    const projectedDistance = dot / length;
    return cross <= tolerance && projectedDistance >= -tolerance && projectedDistance <= length + tolerance;
  }

  function r6PointMatchesCurrentColumnClosure(targetProject, point, tolerance = 0.5) {
    return (targetProject.structures || []).some((structure) => structure && structure.category === "column" && Number.isFinite(Number(structure.x)) && Number.isFinite(Number(structure.y)) && Math.abs(Number(point.x) - Number(structure.x)) <= tolerance && Math.abs(Number(point.y) - Number(structure.y)) <= tolerance);
  }

  function r6ValidateScaledNodeGraph(targetProject, preScaleWallEndpoints) {
    const wallBySourceId = new Map();
    const addWallLookup = (key, wall) => {
      if (!key) return;
      const normalized = String(key);
      const matches = wallBySourceId.get(normalized) || [];
      if (!matches.includes(wall)) matches.push(wall);
      wallBySourceId.set(normalized, matches);
    };
    (targetProject.walls || []).forEach((wall) => {
      if (!wall || !r6FinitePoint(wall.from) || !r6FinitePoint(wall.to)) return;
      addWallLookup(wall.id, wall);
      addWallLookup(wall.sourceWallId, wall);
    });
    const graph = targetProject.nodeGraph;
    const graphNodeById = new Map((graph && Array.isArray(graph.nodes) ? graph.nodes : [])
      .filter((node) => node && node.id)
      .map((node) => [String(node.id), node]));
    const edgeEndpointMatchesClosureNode = (edge, endpointKey, wall) => {
      const nodeId = edge && edge[endpointKey + "NodeId"];
      const point = edge && edge[endpointKey];
      const node = nodeId ? graphNodeById.get(String(nodeId)) : null;
      return Boolean(node
        && r6FinitePoint(node)
        && r6FinitePoint(point)
        && isSamePoint(node, point)
        && Array.isArray(node.wallIds)
        && node.wallIds.some((wallId) => String(wallId) === String(wall && wall.id)));
    };
    const failures = [];
    (graph && Array.isArray(graph.edges) ? graph.edges : []).forEach((edge) => {
      const matchingWalls = wallBySourceId.get(String(edge && edge.sourceWallId)) || [];
      const wall = matchingWalls.find((candidate) => {
        const fromMatches = r6PointMatchesCurrentWall(candidate, edge.from)
          || r6PointMatchesCurrentColumnClosure(targetProject, edge.from)
          || edgeEndpointMatchesClosureNode(edge, "from", candidate);
        const toMatches = r6PointMatchesCurrentWall(candidate, edge.to)
          || r6PointMatchesCurrentColumnClosure(targetProject, edge.to)
          || edgeEndpointMatchesClosureNode(edge, "to", candidate);
        return fromMatches && toMatches;
      });
      if (!wall) {
        const firstCandidate = matchingWalls[0] || null;
        failures.push({
          edgeId: edge && edge.id || null,
          sourceWallId: edge && edge.sourceWallId || null,
          candidateWallCount: matchingWalls.length,
          edgeFrom: edge && edge.from || null,
          edgeTo: edge && edge.to || null,
          candidateWallId: firstCandidate && firstCandidate.id || null,
          candidateFrom: firstCandidate && firstCandidate.from || null,
          candidateTo: firstCandidate && firstCandidate.to || null,
          edgeFromOnCandidate: Boolean(firstCandidate && r6PointMatchesCurrentWall(firstCandidate, edge.from)),
          edgeToOnCandidate: Boolean(firstCandidate && r6PointMatchesCurrentWall(firstCandidate, edge.to)),
          edgeFromOnClosureNode: Boolean(firstCandidate && edgeEndpointMatchesClosureNode(edge, "from", firstCandidate)),
          edgeToOnClosureNode: Boolean(firstCandidate && edgeEndpointMatchesClosureNode(edge, "to", firstCandidate)),
          edgeFromOnColumn: r6PointMatchesCurrentColumnClosure(targetProject, edge && edge.from),
          edgeToOnColumn: r6PointMatchesCurrentColumnClosure(targetProject, edge && edge.to),
          reason: "edge_not_on_current_scaled_wall"
        });
        return;
      }
      const before = preScaleWallEndpoints.get(String(wall.id)) || preScaleWallEndpoints.get(String(edge.sourceWallId));
      const staleFrom = before && (!isSamePoint(before.from, wall.from) || !isSamePoint(before.to, wall.to)) && (isSamePoint(edge.from, before.from) || isSamePoint(edge.from, before.to));
      const staleTo = before && (!isSamePoint(before.from, wall.from) || !isSamePoint(before.to, wall.to)) && (isSamePoint(edge.to, before.from) || isSamePoint(edge.to, before.to));
      if (staleFrom || staleTo) failures.push({ edgeId: edge.id || null, reason: "stale_pre_scale_edge_endpoint" });
    });
    return {
      pass: Boolean(graph && Array.isArray(graph.edges) && failures.length === 0),
      edgeCount: graph && Array.isArray(graph.edges) ? graph.edges.length : 0,
      failures,
      noStalePreScaleEndpoints: failures.every((failure) => failure.reason !== "stale_pre_scale_edge_endpoint")
    };
  }

  function r6RebuildAndValidateScaledGraph(targetProject, preScaleWallEndpoints) {
    if (targetProject === project) {
      rebuildWallGraph();
      rebuildNodeGraph();
    } else {
      targetProject.wallGraph = { nodes: [], issues: [], rebuiltForAcceptedTransform: true };
      targetProject.nodeGraph = r6BuildFixtureNodeGraph(targetProject);
    }
    return r6ValidateScaledNodeGraph(targetProject, preScaleWallEndpoints);
  }

  function r9ScaleDerivationMetadata(receipt) {
    const automatic = receipt && receipt.acceptanceMode === "automatic_dimension_evidence";
    return {
      acceptanceMode: automatic ? "automatic_dimension_evidence" : "manual_calibration",
      scaleDerivationMode: automatic ? "automatic_dimension_axis_consensus" : "user_calibration",
      unitsProvenByUserCalibration: !automatic,
      autoScaleApplied: automatic
    };
  }

  function r6ApplyAcceptedTransformMetadata(targetProject, inventory, receipt, acceptedTransformId) {
    const factors = r9GeometryFactors(receipt);
    const derivation = r9ScaleDerivationMetadata(receipt);
    const factor = factors.uniform;
    const acceptedWorldMmPerPt = Number(receipt.acceptedWorldMmPerPt);
    const acceptedWorldMmPerPtX = Number(receipt.acceptedWorldMmPerPtX || acceptedWorldMmPerPt);
    const acceptedWorldMmPerPtY = Number(receipt.acceptedWorldMmPerPtY || acceptedWorldMmPerPt);
    const status = "accepted_for_existing_object_review";
    const pxPerMm = Number(targetProject.scale && targetProject.scale.pxPerMm);
    targetProject.scale = {
      ...(targetProject.scale || {}),
      pxPerMm: Number.isFinite(pxPerMm) && pxPerMm > 0 ? pxPerMm : r6DisplayPxPerMm(targetProject),
      calibrated: true,
      provisionalWorldMmPerPt: Number(receipt.provisionalWorldMmPerPt),
      acceptedWorldMmPerPt,
      geometryScaleFactor: factor,
      geometryScaleFactorX: factors.x,
      geometryScaleFactorY: factors.y,
      acceptedWorldMmPerPtX,
      acceptedWorldMmPerPtY,
      acceptedTransformId,
      acceptedTransformStatus: status,
      calibrationUnits: "mm",
      ...derivation
    };
    targetProject.importSource = {
      ...(targetProject.importSource || {}),
      acceptedTransformId,
      acceptedTransformStatus: status,
      geometryScaleFactor: factor,
      acceptedWorldMmPerPt,
      geometryScaleFactorX: factors.x,
      geometryScaleFactorY: factors.y,
      acceptedWorldMmPerPtX,
      acceptedWorldMmPerPtY,
      calibrationUnits: "mm",
      ...derivation,
      budgetReadiness: "blocked_pdf_existing_policy"
    };
    targetProject.lastPdfObjectizationSceneImport = {
      ...(targetProject.lastPdfObjectizationSceneImport || {}),
      acceptedTransformId,
      acceptedTransformStatus: status,
      geometryScaleFactor: factor,
      acceptedWorldMmPerPt,
      geometryScaleFactorX: factors.x,
      geometryScaleFactorY: factors.y,
      acceptedWorldMmPerPtX,
      acceptedWorldMmPerPtY,
      calibrationUnits: "mm",
      ...derivation
    };
    targetProject.pdfReviewObjects = targetProject.pdfReviewObjects || {};
    targetProject.pdfReviewObjects.importMetrics = targetProject.pdfReviewObjects.importMetrics || {};
    targetProject.pdfReviewObjects.importMetrics.scalePolicy = {
      ...(targetProject.pdfReviewObjects.importMetrics.scalePolicy || {}),
      acceptedTransformId,
      status,
      geometryScaleFactor: factor,
      acceptedWorldMmPerPt,
      geometryScaleFactorX: factors.x,
      geometryScaleFactorY: factors.y,
      acceptedWorldMmPerPtX,
      acceptedWorldMmPerPtY,
      calibrationUnits: "mm",
      ...derivation
    };
    inventory.items.forEach(({ item }) => {
      item.acceptedTransformId = acceptedTransformId;
      item.r6AppliedTransformId = acceptedTransformId;
      item.r6AppliedGeometryScaleFactor = factor;
      item.r6AppliedGeometryScaleFactorX = factors.x;
      item.r6AppliedGeometryScaleFactorY = factors.y;
      item.acceptedWorldMmPerPt = acceptedWorldMmPerPt;
      item.acceptedWorldMmPerPtX = acceptedWorldMmPerPtX;
      item.acceptedWorldMmPerPtY = acceptedWorldMmPerPtY;
      item.r6CalibrationStatus = status;
      item.acceptanceMode = derivation.acceptanceMode;
      item.scaleDerivationMode = derivation.scaleDerivationMode;
      item.unitsProvenByUserCalibration = derivation.unitsProvenByUserCalibration;
      item.autoScaleApplied = derivation.autoScaleApplied;
    });
  }

  function r6VerifyAcceptedTransformMetadata(targetProject, inventory, receipt, acceptedTransformId) {
    const factors = r9GeometryFactors(receipt);
    const derivation = r9ScaleDerivationMetadata(receipt);
    const factor = factors.uniform;
    const acceptedWorldMmPerPt = Number(receipt.acceptedWorldMmPerPt);
    const acceptedWorldMmPerPtX = Number(receipt.acceptedWorldMmPerPtX || acceptedWorldMmPerPt);
    const acceptedWorldMmPerPtY = Number(receipt.acceptedWorldMmPerPtY || acceptedWorldMmPerPt);
    const status = "accepted_for_existing_object_review";
    const surfaces = [
      targetProject.scale,
      targetProject.importSource,
      targetProject.lastPdfObjectizationSceneImport,
      targetProject.pdfReviewObjects && targetProject.pdfReviewObjects.importMetrics && targetProject.pdfReviewObjects.importMetrics.scalePolicy
    ];
    const surfaceClosure = surfaces.every((surface) => surface
      && surface.acceptedTransformId === acceptedTransformId
      && Number(surface.geometryScaleFactor) === factor
      && Number(surface.geometryScaleFactorX || factor) === factors.x
      && Number(surface.geometryScaleFactorY || factor) === factors.y
      && Number(surface.acceptedWorldMmPerPt) === acceptedWorldMmPerPt
      && Number(surface.acceptedWorldMmPerPtX || acceptedWorldMmPerPt) === acceptedWorldMmPerPtX
      && Number(surface.acceptedWorldMmPerPtY || acceptedWorldMmPerPt) === acceptedWorldMmPerPtY
      && surface.acceptanceMode === derivation.acceptanceMode
      && surface.scaleDerivationMode === derivation.scaleDerivationMode
      && surface.unitsProvenByUserCalibration === derivation.unitsProvenByUserCalibration
      && surface.autoScaleApplied === derivation.autoScaleApplied
      && (surface.acceptedTransformStatus === status || surface.status === status));
    const itemClosure = inventory.items.every(({ item }) => item.acceptedTransformId === acceptedTransformId
      && item.r6AppliedTransformId === acceptedTransformId
      && Number(item.r6AppliedGeometryScaleFactor) === factor
      && Number(item.r6AppliedGeometryScaleFactorX || factor) === factors.x
      && Number(item.r6AppliedGeometryScaleFactorY || factor) === factors.y
      && Number(item.acceptedWorldMmPerPt) === acceptedWorldMmPerPt
      && item.acceptanceMode === derivation.acceptanceMode
      && item.scaleDerivationMode === derivation.scaleDerivationMode
      && item.unitsProvenByUserCalibration === derivation.unitsProvenByUserCalibration
      && item.autoScaleApplied === derivation.autoScaleApplied
      && item.r6CalibrationStatus === status);
    return { pass: surfaceClosure && itemClosure, surfaceClosure, itemClosure };
  }

  function r6RestoreProjectSnapshot(targetProject, snapshot) {
    Object.keys(targetProject || {}).forEach((key) => { delete targetProject[key]; });
    Object.assign(targetProject, cloneJson(snapshot));
  }

  function r6ApplyAcceptedCalibrationTransform(targetProject, receipt, acceptedTransformId) {
    const applicationHost = targetProject && targetProject.r6Review
      ? targetProject.r6Review
      : targetProject;
    const factors = r9GeometryFactors(receipt);
    const factor = factors.uniform;
    const acceptedWorldMmPerPt = Number(receipt && receipt.acceptedWorldMmPerPt);
    const acceptedWorldMmPerPtX = Number(receipt && (receipt.acceptedWorldMmPerPtX || acceptedWorldMmPerPt));
    const acceptedWorldMmPerPtY = Number(receipt && (receipt.acceptedWorldMmPerPtY || acceptedWorldMmPerPt));
    if (!targetProject || !applicationHost || !Number.isFinite(factors.x) || factors.x <= 0 || !Number.isFinite(factors.y) || factors.y <= 0 || !Number.isFinite(acceptedWorldMmPerPt) || acceptedWorldMmPerPt <= 0 || !acceptedTransformId) {
      return { pass: false, reason: "missing_typed_transform_or_application_guard", appliedCount: 0 };
    }
    if (applicationHost.calibrationApplication && applicationHost.calibrationApplication.appliedTransformId) {
      return {
        pass: false,
        reason: applicationHost.calibrationApplication.appliedTransformId === acceptedTransformId ? "transform_already_applied" : "different_transform_already_applied",
        appliedCount: 0,
        appliedTransformId: applicationHost.calibrationApplication.appliedTransformId
      };
    }

    const inventory = r6BuildCalibrationGeometryInventory(targetProject);
    if (inventory.total === 0) return { pass: false, reason: "empty_applicable_pdf_existing_inventory", inventory, appliedCount: 0 };
    if (inventory.duplicateInventoryIds.length > 0) return { pass: false, reason: "duplicate_inventory_identity", inventory, appliedCount: 0 };
    if (inventory.conflicts.length > 0) return { pass: false, reason: "conflicting_item_transform", inventory, appliedCount: 0 };
    if (inventory.invalid.length > 0) return { pass: false, reason: "invalid_required_geometry", inventory, appliedCount: 0 };

    const snapshot = cloneJson(targetProject);
    const selectedNodeId = targetProject === project ? uiState.selectedNodeId : null;
    const preScaleWallEndpoints = new Map();
    (targetProject.walls || []).filter((wall) => wall && r6FinitePoint(wall.from) && r6FinitePoint(wall.to)).forEach((wall) => {
      const endpoints = { from: cloneJson(wall.from), to: cloneJson(wall.to) };
      preScaleWallEndpoints.set(String(wall.id), endpoints);
      if (wall.sourceWallId && !preScaleWallEndpoints.has(String(wall.sourceWallId))) {
        preScaleWallEndpoints.set(String(wall.sourceWallId), endpoints);
      }
    });
    let graphIntegrity = null;
    try {
      const itemResults = inventory.items.map(({ item, descriptor, category }) => r6ScalePdfExistingGeometryItem(item, descriptor, factors, acceptedTransformId, receipt, category));
      const appliedCount = itemResults.filter((result) => result.pass).length;
      if (appliedCount !== inventory.total || itemResults.some((result) => !result.pass)) throw new Error("incomplete_geometry_application");

      const underlayResult = r6ScalePdfVectorUnderlay(inventory.vectorUnderlay, factors, acceptedTransformId, receipt);
      if (!underlayResult.pass) throw new Error(underlayResult.reason || "pdf_vector_underlay_application_failed");

      graphIntegrity = r6RebuildAndValidateScaledGraph(targetProject, preScaleWallEndpoints);
      if (!graphIntegrity.pass) throw new Error("derived_wall_graph_integrity_failed");

      r6ApplyAcceptedTransformMetadata(targetProject, inventory, receipt, acceptedTransformId);
      // 先建立來源縫 host edge，再驗證開口綁定：跨在牆縫上的門窗
      // （寬度大於相鄰牆段）必須以來源縫作為母邊，綁定檢查才反映最終狀態。
      migratePersistedPdfOpeningSourceAlignment(targetProject);
      const openingBindingFailures = (targetProject.openings || [])
        .filter((opening) => isPdfDerivedExistingObject(opening) && !r6BindOpeningToCurrentWallEdge(targetProject, opening))
        .map((opening) => opening.id || null);
      window.__laibeOpeningBindingFailures = openingBindingFailures;
      if (openingBindingFailures.length) throw new Error("derived_opening_host_binding_failed");
      const metadataClosure = r6VerifyAcceptedTransformMetadata(targetProject, inventory, receipt, acceptedTransformId);
      if (!metadataClosure.pass) throw new Error("accepted_transform_metadata_closure_failed");

      applicationHost.calibrationApplication = {
        schema: "laibe.planPuzzle.r6.calibrationApplication.v2",
        status: "applied_once",
        appliedTransformId: acceptedTransformId,
        geometryScaleFactor: factor,
        geometryScaleFactorX: factors.x,
        geometryScaleFactorY: factors.y,
        acceptedWorldMmPerPt,
        acceptedWorldMmPerPtX,
        acceptedWorldMmPerPtY,
        calibrationUnits: "mm",
        ...r9ScaleDerivationMetadata(receipt),
        applicableCount: inventory.total,
        appliedCount,
        categoryCounts: inventory.categoryCounts,
        underlayStatus: underlayResult.status,
        graphIntegrity,
        metadataClosure,
        appliedOnce: true
      };
      return { pass: true, appliedCount, applicableCount: inventory.total, inventory, graphIntegrity, metadataClosure, underlayStatus: underlayResult.status, appliedTransformId: acceptedTransformId, geometryScaleFactor: factor, geometryScaleFactorX: factors.x, geometryScaleFactorY: factors.y, acceptedWorldMmPerPt, acceptedWorldMmPerPtX, acceptedWorldMmPerPtY };
    } catch (error) {
      r6RestoreProjectSnapshot(targetProject, snapshot);
      if (targetProject === project) uiState.selectedNodeId = selectedNodeId;
      return { pass: false, reason: error && error.message || "atomic_geometry_application_failed", inventory, graphIntegrity, appliedCount: 0, rolledBack: true };
    }
  }

  function r6AcceptCalibration() {
    const receipt = project.r6Review?.calibrationReceipt;
    if (!receipt || receipt.status !== "submitted_for_acceptance") return;
    const eligibility = evaluateR6CalibrationReceiptEligibility({
      selection: project.r6Review.calibrationSelection,
      enteredLength: receipt.userEnteredRealLength,
      unit: receipt.unit,
      actor: receipt.actor,
      reviewer: receipt.reviewer,
      caseId: receipt.caseId,
      sourceSha256: receipt.sourceSha256,
      acceptedTransformId: null,
      genericScaleCalibrated: Boolean(project.scale?.calibrated),
      requireApplicationGuard: true,
      applicationGuard: typeof r6ApplyAcceptedCalibrationTransform === "function"
    });
    if (!eligibility.pass || receipt.endpointSelectionMethod !== "canvas_two_point_user_action" || receipt.dimensionTextUsedAsProof !== false || receipt.acceptedTransformId !== null) {
      uiState.error = "這筆比例資料尚未符合接受條件，請重新確認畫布端點與填寫資料。";
      render();
      return;
    }
    const transform = r6BuildTypedCalibrationTransform(project.r6Review.calibrationSelection, receipt.normalizedMillimetres);
    const transformMatchesReceipt = Boolean(transform) &&
      JSON.stringify(transform.sourceEndpointsPdfPt) === JSON.stringify(receipt.sourceEndpointsPdfPt) &&
      Number(transform.acceptedWorldMmPerPt) === Number(receipt.acceptedWorldMmPerPt) &&
      Number(transform.geometryScaleFactor) === Number(receipt.geometryScaleFactor) &&
      transform.residualsPt.max <= R6_CALIBRATION_RESIDUAL_TOLERANCE_PT;
    if (!transformMatchesReceipt) {
      uiState.error = "比例校正資料未通過座標與誤差驗證，請重新提交。";
      render();
      return;
    }
    const before = r6ProjectFingerprint(project);
    const acceptedTransformId = r6StableToken({
      sourceSha256: receipt.sourceSha256,
      sourceEndpointsPdfPt: receipt.sourceEndpointsPdfPt,
      normalizedMillimetres: receipt.normalizedMillimetres,
      unit: receipt.unit,
      caseId: receipt.caseId,
      acceptedWorldMmPerPt: receipt.acceptedWorldMmPerPt,
      provisionalWorldMmPerPt: receipt.provisionalWorldMmPerPt
    });
    const application = r6ApplyAcceptedCalibrationTransform(project, receipt, acceptedTransformId);
    if (!application.pass) {
      uiState.error = "此比例校正已套用或無法安全套用，請重新檢查目前圖面狀態。";
      render();
      return;
    }
    receipt.acceptedTransformId = acceptedTransformId;
    receipt.status = "accepted_for_existing_object_review";
    receipt.eligibility = eligibility;
    receipt.acceptedLiveEndpointsMm = transform.acceptedLiveEndpointsMm;
    receipt.transforms = { forward: transform.forward, inverse: transform.inverse };
    receipt.residualsPt = transform.residualsPt;
    const applicationReceipt = compactR6CalibrationApplication(application);
    receipt.application = applicationReceipt;
    project.r6Review.calibrationSelection.status = "accepted_for_existing_object_review";
    receipt.afterProjectFingerprint = r6ProjectFingerprint(project);
    r6Record(null, "calibration_accepted", "accepted_for_existing_object_review", {
      kind: "accepted_calibration",
      acceptedTransformId,
      unit: receipt.unit,
      sourceEndpointsPdfPt: receipt.sourceEndpointsPdfPt,
      acceptedLiveEndpointsMm: receipt.acceptedLiveEndpointsMm,
      geometryScaleFactor: receipt.geometryScaleFactor,
      application: applicationReceipt
    }, "owner_or_designated_reviewer", before);
    // Acceptance mutates the authoritative project transform and geometry.
    // Persist it immediately; r6Publish only renders the review receipt.
    syncBridge();
    r6Publish();
  }

  function r7DimensionEvidence(review = project.r6Review) {
    const evidence = review && review.importReceipt && review.importReceipt.dimensionScale;
    return evidence && evidence.schema === "laibe.planPuzzle.r7.dimensionScaleEvidence.v1" ? evidence : null;
  }

  function r7MedianFinite(values) {
    const rows = (values || []).map(Number).filter(Number.isFinite).sort((left, right) => left - right);
    if (!rows.length) return null;
    const middle = Math.floor(rows.length / 2);
    return rows.length % 2 ? rows[middle] : (rows[middle - 1] + rows[middle]) / 2;
  }

  function r7DimensionPlausibleUnitOptions(evidence) {
    return (Array.isArray(evidence?.unitHypotheses) ? evidence.unitHypotheses : [])
      .filter((option) => option && option.plausible === true)
      .map((option) => ({
        unit: option.unit || null,
        medianWorldMmPerPt: Number(option.medianWorldMmPerPt),
        plausible: true,
        rejectionReasons: []
      }));
  }

  function evaluateR7AutomaticDimensionScaleEvidence(evidence) {
    const candidates = Array.isArray(evidence?.candidates) ? evidence.candidates : [];
    const consensus = evidence?.consensus || {};
    const proposal = evidence?.unitProposal || {};
    const plausibleUnits = r7DimensionPlausibleUnitOptions(evidence);
    const failedRules = [];
    const candidateIds = new Set(candidates.map((candidate) => candidate?.id).filter(Boolean));
    const axisIds = new Set(candidates.map((candidate) => candidate?.axisId).filter(Boolean));
    const labelIds = new Set(candidates.map((candidate) => candidate?.labelId).filter(Boolean));
    const orientations = new Set(candidates.map((candidate) => candidate?.orientation).filter(Boolean));
    const strictConsensus = consensus.pass === true && consensus.mode === "strict_auto_consensus";
    const candidateQuality = candidates.every((candidate) => (
      Number(candidate?.pairScore) >= 0.8 &&
      Number(candidate?.runnerUpMargin) >= 0.12 &&
      candidate?.chainCompatible === true &&
      Array.isArray(candidate?.witnessLineIds) && candidate.witnessLineIds.length >= 2 &&
      Number(candidate?.residualPt) <= 0.25
    ));
    const deviationQuality = Array.isArray(consensus.deviations) && consensus.deviations.length === candidates.length &&
      consensus.deviations.every((entry) => Number(entry?.relativeDeviation) <= Number(consensus?.tolerance?.maxRelativeDeviation ?? 0.0075));
    const unambiguousUnit = proposal.conclusive === true
      && proposal.requiresUserConfirmation === false
      && proposal.survivingHypothesisCount === 1
      && plausibleUnits.length === 1
      && plausibleUnits[0].unit === proposal.unit;
    if (!strictConsensus) failedRules.push("strict_dimension_consensus_required");
    if (candidates.length < 3 || candidateIds.size < 3 || axisIds.size < 3 || labelIds.size < 3) failedRules.push("three_independent_dimension_pairs_required");
    if (consensus.cardinalityPass !== true) failedRules.push("dimension_orientation_cardinality_required");
    if (consensus.coveragePass !== true) failedRules.push("dimension_region_orientation_coverage_required");
    if (consensus.residualPass !== true || !candidateQuality || !deviationQuality) failedRules.push("dimension_pair_quality_or_residual_failed");
    if (!(Number(consensus.coefficientOfVariation) <= Number(consensus?.tolerance?.maxCoefficientOfVariation ?? 0.005))) failedRules.push("dimension_scale_variation_exceeded");
    if (!unambiguousUnit) failedRules.push("single_unambiguous_dimension_unit_required");
    if (!proposal.unit || !(Number(consensus.medianWorldMmPerPt) > 0)) failedRules.push("finite_dimension_transform_required");
    return {
      schema: "laibe.planPuzzle.r8.automaticDimensionScaleEligibility.v1",
      pass: failedRules.length === 0,
      failedRules,
      candidateCount: candidates.length,
      candidateIds: Array.from(candidateIds).sort(),
      candidateValues: candidates.map((candidate) => ({
        id: candidate.id || null,
        rawLabel: candidate.rawLabel || null,
        numericValue: Number(candidate.numericValue),
        axisSpanPt: Number(candidate.axisSpanPt),
        orientation: candidate.orientation || null,
        worldMmPerPt: Number(candidate.worldMmPerPt),
        residualPt: Number(candidate.residualPt)
      })),
      axisIds: Array.from(axisIds).sort(),
      labelIds: Array.from(labelIds).sort(),
      orientations: Array.from(orientations).sort(),
      coveragePass: consensus.coveragePass === true,
      residualPass: consensus.residualPass === true,
      coefficientOfVariation: Number.isFinite(Number(consensus.coefficientOfVariation)) ? Number(consensus.coefficientOfVariation) : null,
      maximumRelativeDeviation: Array.isArray(consensus.deviations) && consensus.deviations.length
        ? Math.max(...consensus.deviations.map((entry) => Number(entry?.relativeDeviation)).filter(Number.isFinite))
        : null,
      rejectedCandidateCount: Array.isArray(evidence?.rejectedCandidates) ? evidence.rejectedCandidates.length : 0,
      rejectedCandidates: (Array.isArray(evidence?.rejectedCandidates) ? evidence.rejectedCandidates : []).map((candidate) => ({
        id: candidate.id || null,
        rawLabel: candidate.rawLabel || null,
        orientation: candidate.orientation || null,
        worldMmPerPt: Number(candidate.worldMmPerPt),
        residualPt: Number(candidate.residualPt),
        reason: candidate.reason || null
      })),
      plausibleUnits,
      selectedUnit: proposal.unit || null,
      availableOrientations: Array.isArray(consensus.availableOrientations) ? consensus.availableOrientations.slice() : [],
      coveredOrientations: Array.isArray(consensus.coveredOrientations) ? consensus.coveredOrientations.slice() : Array.from(orientations).sort(),
      mode: unambiguousUnit ? "strict_automatic_dimension_consensus" : "fail_closed"
    };
  }

  function evaluateR7DimensionScaleAcceptance(input) {
    const source = input || {};
    const evidence = source.evidence || {};
    const consensus = evidence.consensus || {};
    const proposal = evidence.unitProposal || {};
    const failedRules = [];
    const candidates = Array.isArray(evidence.candidates) ? evidence.candidates : [];
    const unit = String(source.unit || "").trim();
    const sourceSha256 = String(source.sourceSha256 || "").trim().toUpperCase();
    const actor = String(source.actor || "").trim();
    const reviewer = String(source.reviewer || "").trim();
    const roundedResidual = Number(source.roundTripResidualPt);
    const consensusSatisfied = consensus.pass === true
      && consensus.mode === "strict_auto_consensus"
      && candidates.length >= 3;
    if (!consensusSatisfied) failedRules.push("strict_dimension_consensus_required");
    if (!proposal.unit || unit !== proposal.unit || proposal.conclusive !== true || proposal.survivingHypothesisCount !== 1 || proposal.requiresUserConfirmation !== false) {
      failedRules.push("automatic_unit_hypothesis_must_be_unique_and_conclusive");
    }
    if (!sourceSha256 || !String(source.caseId || "").trim()) failedRules.push("source_and_case_binding_required");
    if (!actor || !reviewer) failedRules.push("actor_and_reviewer_required");
    if (!Number.isFinite(roundedResidual) || roundedResidual < 0 || roundedResidual > R6_CALIBRATION_RESIDUAL_TOLERANCE_PT) failedRules.push("round_trip_residual_out_of_tolerance");
    if (source.acceptedTransformId) failedRules.push("accepted_transform_id_must_be_null_before_acceptance");
    if (source.genericScaleCalibrated === true) failedRules.push("generic_scale_state_is_not_dimension_receipt");
    return {
      schema: "laibe.planPuzzle.r7.dimensionScaleAcceptanceEligibility.v1",
      pass: failedRules.length === 0,
      failedRules,
      rules: {
        consensus: consensusSatisfied,
        automaticUnitResolution: Boolean(proposal.unit
          && unit === proposal.unit
          && proposal.conclusive === true
          && proposal.survivingHypothesisCount === 1
          && proposal.requiresUserConfirmation === false),
        sourceAndCaseBinding: Boolean(sourceSha256 && String(source.caseId || "").trim()),
        actorAndReviewer: Boolean(actor && reviewer),
        residualWithinTolerance: Number.isFinite(roundedResidual) && roundedResidual >= 0 && roundedResidual <= R6_CALIBRATION_RESIDUAL_TOLERANCE_PT,
        acceptedTransformUnset: !source.acceptedTransformId,
        genericScaleNotAccepted: source.genericScaleCalibrated !== true
      }
    };
  }

  function r7DimensionTransformContentId(review, evidence, unit) {
    return r6StableToken({
      sourceSha256: review.importReceipt.file.sha256,
      page: review.importReceipt.source?.page || 1,
      floorId: project.importSource?.floorId || review.importReceipt.source?.floorId || "floor-unresolved",
      unit,
      pairs: (evidence.candidates || []).map((candidate) => ({
        id: candidate.id,
        region: candidate.sourceRegionId,
        rawLabel: candidate.rawLabel,
        numericValue: candidate.numericValue,
        endpointsPdfPt: candidate.endpointsPdfPt,
        axisSpanPt: candidate.axisSpanPt,
        worldMmPerPt: candidate.worldMmPerPt,
        witnessLineIds: Array.isArray(candidate.witnessLineIds) ? candidate.witnessLineIds.slice().sort() : []
      })).sort((a, b) => a.id.localeCompare(b.id)),
      medianWorldMmPerPt: evidence.consensus?.medianWorldMmPerPt,
      medianWorldMmPerPtX: evidence.consensus?.medianWorldMmPerPtX,
      medianWorldMmPerPtY: evidence.consensus?.medianWorldMmPerPtY,
      transformMode: evidence.consensus?.transformMode || "uniform",
      tolerances: evidence.consensus?.tolerance || null,
      unitHypotheses: (evidence.unitHypotheses || []).map((hypothesis) => ({
        unit: hypothesis.unit,
        plausible: hypothesis.plausible === true,
        rejectionReasons: Array.isArray(hypothesis.rejectionReasons) ? hypothesis.rejectionReasons.slice().sort() : []
      })),
      method: "strict_dimension_axis_witness_consensus"
    });
  }

  function r7BuildDimensionReceipt(review, unit, actor, reviewer) {
    const evidence = r7DimensionEvidence(review);
    const candidates = evidence && evidence.candidates || [];
    const first = candidates[0] || null;
    const sourceFrom = first && first.endpointsPdfPt && first.endpointsPdfPt.from;
    const sourceTo = first && first.endpointsPdfPt && first.endpointsPdfPt.to;
    const acceptedWorldMmPerPtX = Number(evidence && evidence.consensus && (evidence.consensus.medianWorldMmPerPtX || evidence.consensus.medianWorldMmPerPt));
    const acceptedWorldMmPerPtY = Number(evidence && evidence.consensus && (evidence.consensus.medianWorldMmPerPtY || evidence.consensus.medianWorldMmPerPt));
    const acceptedWorldMmPerPt = (acceptedWorldMmPerPtX + acceptedWorldMmPerPtY) / 2;
    const provisionalWorldMmPerPt = r6ProvisionalWorldMmPerPt(project);
    const geometryScaleFactorX = acceptedWorldMmPerPtX / provisionalWorldMmPerPt;
    const geometryScaleFactorY = acceptedWorldMmPerPtY / provisionalWorldMmPerPt;
    const geometryScaleFactor = (geometryScaleFactorX + geometryScaleFactorY) / 2;
    const acceptedFrom = r9TransformSourcePointToLiveMm(sourceFrom, acceptedWorldMmPerPtX, acceptedWorldMmPerPtY);
    const acceptedTo = r9TransformSourcePointToLiveMm(sourceTo, acceptedWorldMmPerPtX, acceptedWorldMmPerPtY);
    const roundTripFrom = r9TransformLivePointToSourcePdfPt(acceptedFrom, acceptedWorldMmPerPtX, acceptedWorldMmPerPtY);
    const roundTripTo = r9TransformLivePointToSourcePdfPt(acceptedTo, acceptedWorldMmPerPtX, acceptedWorldMmPerPtY);
    const residualsPt = {
      from: r6PointDistance(sourceFrom, roundTripFrom),
      to: r6PointDistance(sourceTo, roundTripTo)
    };
    residualsPt.max = Math.max(residualsPt.from, residualsPt.to);
    residualsPt.tolerance = R6_CALIBRATION_RESIDUAL_TOLERANCE_PT;
    const transformContentId = r7DimensionTransformContentId(review, evidence, unit);
    return {
      schema: "laibe.planPuzzle.r7.dimensionScaleReceipt.v1",
      receiptId: "r7-dimension-" + transformContentId,
      sourceSha256: review.importReceipt.file.sha256,
      caseId: review.caseId,
      actor,
      reviewer,
      source: {
        page: review.importReceipt.source?.page || 1,
        floorId: project.importSource?.floorId || review.importReceipt.source?.floorId || "floor-unresolved",
        regions: Array.from(new Set(candidates.map((candidate) => candidate.sourceRegionId))).sort(),
        coordinateFrame: R6_SOURCE_POINT_FRAME
      },
      method: "strict_dimension_axis_witness_consensus",
      transformContentId,
      evidenceIds: candidates.map((candidate) => candidate.id).sort(),
      sourceEndpointsPdfPt: { from: sourceFrom || null, to: sourceTo || null },
      provisionalLiveEndpointsMm: { from: r6TransformSourcePointToLiveMm(sourceFrom, provisionalWorldMmPerPt), to: r6TransformSourcePointToLiveMm(sourceTo, provisionalWorldMmPerPt) },
      acceptedLiveEndpointsMm: { from: acceptedFrom, to: acceptedTo },
      sourceDistancePt: r6PointDistance(sourceFrom, sourceTo),
      unit,
      unitSource: evidence.unitProposal?.source || null,
      unitConfirmationRequired: false,
      dimensionTextUsedAsProof: true,
      endpointSelectionMethod: "automatic_dimension_axis_witness_consensus",
      provisionalWorldMmPerPt,
      acceptedWorldMmPerPt,
      acceptedWorldMmPerPtX,
      acceptedWorldMmPerPtY,
      geometryScaleFactor,
      geometryScaleFactorX,
      geometryScaleFactorY,
      displayPxPerMm: r6DisplayPxPerMm(project),
      transforms: {
        forward: { sourcePdfPtToLiveMm: { scaleX: acceptedWorldMmPerPtX, scaleY: acceptedWorldMmPerPtY, sourceFrame: R6_SOURCE_POINT_FRAME, sourceUnit: "pt", targetFrame: R6_ACCEPTED_LIVE_FRAME, targetUnit: "mm" } },
        inverse: { liveMmToSourcePdfPt: { scaleX: acceptedWorldMmPerPtX > 0 ? 1 / acceptedWorldMmPerPtX : null, scaleY: acceptedWorldMmPerPtY > 0 ? 1 / acceptedWorldMmPerPtY : null, sourceFrame: R6_ACCEPTED_LIVE_FRAME, sourceUnit: "mm", targetFrame: R6_SOURCE_POINT_FRAME, targetUnit: "pt" } }
      },
      residualsPt,
      consensus: evidence.consensus,
      acceptedTransformId: null,
      status: "submitted_for_acceptance",
      application: { status: "not_applied", appliedTransformId: null, appliedOnce: false }
    };
  }

  function r7CommitDimensionScale(review, evidence, draft, eligibility, acceptanceMode) {
    if (!review || !evidence || !eligibility?.pass || !Number.isFinite(draft?.geometryScaleFactor) || draft.geometryScaleFactor <= 0) {
      return { pass: false, reason: "dimension_scale_not_eligible" };
    }
    const automatic = acceptanceMode === "automatic_dimension_evidence";
    draft.acceptanceMode = acceptanceMode;
    draft.scaleDerivationMode = automatic ? "automatic_dimension_axis_consensus" : "user_calibration";
    draft.unitsProvenByUserCalibration = !automatic;
    draft.autoScaleApplied = automatic;
    const before = r6ProjectFingerprint(project);
    const acceptedTransformId = r6StableToken({
      transformContentId: draft.transformContentId,
      unit: draft.unit,
      sourceSha256: draft.sourceSha256,
      acceptedWorldMmPerPt: draft.acceptedWorldMmPerPt,
      acceptedWorldMmPerPtX: draft.acceptedWorldMmPerPtX,
      acceptedWorldMmPerPtY: draft.acceptedWorldMmPerPtY
    });
    const application = r6ApplyAcceptedCalibrationTransform(project, draft, acceptedTransformId);
    window.__laibeLastScaleApplication = application;
    if (!application.pass) {
      return { pass: false, reason: application.reason || "dimension_scale_application_failed", application };
    }
    draft.acceptedTransformId = acceptedTransformId;
    draft.status = "accepted_for_existing_object_review";
    draft.application = application;
    draft.eligibility = eligibility;
    draft.sourceUnitConfirmationRequired = evidence.unitProposal?.requiresUserConfirmation === true;
    draft.unitConfirmationRequired = false;
    draft.endpointSelectionMethod = automatic
      ? "dimension_axis_evidence_automatic_unit_acceptance"
      : "dimension_axis_evidence_user_unit_confirmation";
    draft.beforeProjectFingerprint = before;
    draft.afterProjectFingerprint = r6ProjectFingerprint(project);
    review.calibrationReceipt = draft;
    review.calibrationSelection = {
      ...createR6CalibrationSelection(),
      status: "accepted_for_existing_object_review",
      endpointSelectionMethod: draft.endpointSelectionMethod,
      dimensionTextUsedAsProof: true
    };
    r6Record(null, "dimension_scale_accepted", "accepted_for_existing_object_review", {
      transformContentId: draft.transformContentId,
      acceptedTransformId,
      unit: draft.unit,
      evidenceIds: draft.evidenceIds,
      geometryScaleFactor: draft.geometryScaleFactor,
      acceptanceMode
    }, "owner_or_designated_reviewer", before);
    r6Publish();
    return { pass: true, acceptedTransformId, application, draft };
  }

  function r7TryAutomaticDimensionScale() {
    const review = project.r6Review;
    const evidence = r7DimensionEvidence(review);
    if (!review || !evidence || acceptedScaleTransformId()) return { pass: false, reason: "automatic_scale_not_applicable" };
    const automaticEligibility = evaluateR7AutomaticDimensionScaleEvidence(evidence);
    review.automaticDimensionScaleEligibility = automaticEligibility;
    if (!automaticEligibility.pass) {
      r6Publish();
      return { pass: false, reason: "automatic_scale_evidence_not_conclusive", eligibility: automaticEligibility };
    }
    const unit = String(evidence.unitProposal?.unit || "");
    const actor = String(review.actorId || "local-plan-user");
    const reviewer = "尺寸標註自動核對";
    const draft = r7BuildDimensionReceipt(review, unit, actor, reviewer);
    const acceptanceEligibility = evaluateR7DimensionScaleAcceptance({
      evidence,
      unit,
      actor,
      reviewer,
      caseId: review.caseId,
      sourceSha256: draft.sourceSha256,
      roundTripResidualPt: draft.residualsPt.max,
      acceptedTransformId: null,
      genericScaleCalibrated: false
    });
    if (!acceptanceEligibility.pass) {
      return { pass: false, reason: "automatic_scale_acceptance_contract_failed", eligibility: automaticEligibility, acceptanceEligibility };
    }
    const combinedEligibility = {
      ...acceptanceEligibility,
      automaticEvidence: automaticEligibility
    };
    return r7CommitDimensionScale(review, evidence, draft, combinedEligibility, "automatic_dimension_evidence");
  }

  function r7AcceptDimensionScale() {
    const review = project.r6Review;
    const evidence = r7DimensionEvidence(review);
    if (!review || !evidence) return;
    const field = (name) => document.querySelector(`[data-field='${name}']`);
    const unit = String(field("r7-dimension-unit")?.value || evidence.unitProposal?.unit || "");
    const actor = String(field("r7-dimension-actor")?.value || review.actorId || "").trim();
    const reviewer = String(field("r7-dimension-reviewer")?.value || "").trim();
    const draft = r7BuildDimensionReceipt(review, unit, actor, reviewer);
    const eligibility = evaluateR7DimensionScaleAcceptance({
      evidence,
      unit,
      actor,
      reviewer,
      caseId: review.caseId,
      sourceSha256: draft.sourceSha256,
      roundTripResidualPt: draft.residualsPt.max,
      acceptedTransformId: null,
      genericScaleCalibrated: false
    });
    if (!eligibility.pass || !Number.isFinite(draft.geometryScaleFactor) || draft.geometryScaleFactor <= 0) {
      uiState.error = "尺寸資料尚不足以套用比例，請確認單位或改用兩點校正。";
      render();
      return;
    }
    const result = r7CommitDimensionScale(review, evidence, draft, eligibility, "user_confirmed_dimension_unit");
    if (!result.pass) {
      uiState.error = "比例套用未完成，已保留目前圖面狀態。";
      render();
      return;
    }
    uiState.error = "";
    uiState.message = "已依確認的尺寸單位套用比例。請檢查牆線與門窗位置。";
    syncBridge();
    render();
  }

  function createR7DimensionScaleFixtures() {
    const candidate = (id, orientation, index) => ({
      id,
      axisId: `axis-${id}`,
      labelId: `label-${id}`,
      sourceRegionId: "fixture-region",
      rawLabel: orientation === "horizontal" ? "600" : "500",
      numericValue: orientation === "horizontal" ? 600 : 500,
      axisSpanPt: orientation === "horizontal" ? 300 : 250,
      endpointsPdfPt: { from: { x: index * 10, y: index * 10 }, to: orientation === "horizontal" ? { x: index * 10 + 300, y: index * 10 } : { x: index * 10, y: index * 10 + 250 } },
      orientation,
      pairScore: 1,
      runnerUpMargin: 0.2,
      chainCompatible: true,
      witnessLineIds: [`witness-${id}-a`, `witness-${id}-b`],
      residualPt: 0,
      worldMmPerPt: 20
    });
    const candidates = [candidate("a", "horizontal", 0), candidate("b", "vertical", 1), candidate("c", "horizontal", 2)];
    const unitHypotheses = [
      { unit: "mm", plausible: false, medianWorldMmPerPt: 2, rejectionReasons: ["source_plan_span_out_of_bounds"] },
      { unit: "cm", plausible: true, medianWorldMmPerPt: 20, rejectionReasons: [] },
      { unit: "m", plausible: false, medianWorldMmPerPt: 2000, rejectionReasons: ["source_plan_span_out_of_bounds"] }
    ];
    const evidence = {
      schema: "laibe.planPuzzle.r7.dimensionScaleEvidence.v1",
      unitProposal: { unit: "cm", requiresUserConfirmation: false, conclusive: true, survivingHypothesisCount: 1, source: "unique_geometry_bounded_hypothesis" },
      unitHypotheses,
      rejectedCandidates: [],
      consensus: {
        pass: true,
        assistedPass: false,
        mode: "strict_auto_consensus",
        transformMode: "axis_aligned_affine",
        cardinalityPass: true,
        coveragePass: true,
        medianWorldMmPerPtX: 20,
        medianWorldMmPerPtY: 20,
        availableOrientations: ["horizontal", "vertical"],
        coveredOrientations: ["horizontal", "vertical"],
        residualPass: true,
        residualThresholdPt: 0.25,
        coefficientOfVariation: 0,
        medianWorldMmPerPt: 20,
        tolerance: { maxCoefficientOfVariation: 0.005, maxRelativeDeviation: 0.0075, maxRoundTripResidualPt: 0.25 },
        deviations: candidates.map((row) => ({ id: row.id, relativeDeviation: 0 }))
      },
      candidates
    };
    const base = { evidence, unit: "cm", actor: "fixture-owner", reviewer: "fixture-reviewer", caseId: "fixture-case", sourceSha256: "fixture-sha", roundTripResidualPt: 0, acceptedTransformId: null, genericScaleCalibrated: false };
    const cases = [
      { id: "positive_dimension_consensus", input: base, pass: true },
      { id: "wrong_unit", input: { ...base, unit: "mm" }, pass: false, rule: "automatic_unit_hypothesis_must_be_unique_and_conclusive" },
      { id: "generic_scale_without_receipt", input: { ...base, genericScaleCalibrated: true }, pass: false, rule: "generic_scale_state_is_not_dimension_receipt" },
      { id: "premature_transform", input: { ...base, acceptedTransformId: "premature" }, pass: false, rule: "accepted_transform_id_must_be_null_before_acceptance" },
      { id: "residual_over_tolerance", input: { ...base, roundTripResidualPt: 0.26 }, pass: false, rule: "round_trip_residual_out_of_tolerance" }
    ];
    const rows = cases.map((fixture) => {
      const result = evaluateR7DimensionScaleAcceptance(fixture.input);
      return { id: fixture.id, pass: result.pass === fixture.pass && (!fixture.rule || result.failedRules.includes(fixture.rule)), result };
    });
    const automaticCases = [
      { id: "automatic_strict_three_pair_single_unit", evidence, pass: true },
      { id: "automatic_rejects_two_pairs", evidence: { ...evidence, candidates: candidates.slice(0, 2), consensus: { ...evidence.consensus, deviations: evidence.consensus.deviations.slice(0, 2) } }, pass: false, rule: "three_independent_dimension_pairs_required" },
      { id: "automatic_rejects_missing_witness", evidence: { ...evidence, candidates: candidates.map((row, index) => index ? row : { ...row, witnessLineIds: [] }) }, pass: false, rule: "dimension_pair_quality_or_residual_failed" },
      { id: "automatic_rejects_missing_orientation_coverage", evidence: { ...evidence, consensus: { ...evidence.consensus, coveragePass: false, coveredOrientations: ["horizontal"] } }, pass: false, rule: "dimension_region_orientation_coverage_required" },
      { id: "automatic_rejects_assisted_mode", evidence: { ...evidence, consensus: { ...evidence.consensus, pass: false, assistedPass: true, mode: "assisted_user_confirmation_required" } }, pass: false, rule: "strict_dimension_consensus_required" },
      { id: "automatic_rejects_ambiguous_unit", evidence: { ...evidence, unitProposal: { ...evidence.unitProposal, unit: null, conclusive: false, survivingHypothesisCount: 2 }, unitHypotheses: unitHypotheses.map((row, index) => index === 0 ? { ...row, plausible: true, rejectionReasons: [] } : row) }, pass: false, rule: "single_unambiguous_dimension_unit_required" },
      { id: "automatic_rejects_high_cv", evidence: { ...evidence, consensus: { ...evidence.consensus, coefficientOfVariation: 0.006 } }, pass: false, rule: "dimension_scale_variation_exceeded" },
      { id: "automatic_rejects_high_deviation", evidence: { ...evidence, consensus: { ...evidence.consensus, deviations: evidence.consensus.deviations.map((row, index) => index ? row : { ...row, relativeDeviation: 0.008 }) } }, pass: false, rule: "dimension_pair_quality_or_residual_failed" },
      { id: "automatic_rejects_round_trip_over_point_25", evidence: { ...evidence, candidates: candidates.map((row, index) => index ? row : { ...row, residualPt: 0.251 }) }, pass: false, rule: "dimension_pair_quality_or_residual_failed" }
    ];
    const automaticRows = automaticCases.map((fixture) => {
      const result = evaluateR7AutomaticDimensionScaleEvidence(fixture.evidence);
      return { id: fixture.id, pass: result.pass === fixture.pass && (!fixture.rule || result.failedRules.includes(fixture.rule)), result };
    });
    return { schema: "laibe.planPuzzle.r7.dimensionScaleFixtures.v2", pass: rows.concat(automaticRows).every((row) => row.pass), rows: rows.concat(automaticRows) };
  }

  function r6SaveManualTrace(sourceId) {
    const record = (project.r6Review?.records || []).find((item) => item.sourceId === sourceId);
    if (!record) return;
    if (record.userDecision !== "confirmed_pending_calibration") {
      uiState.error = "請先明確確認這筆候選，再保留人工來源描繪。";
      render();
      return;
    }
    const field = (name) => document.querySelector(`[data-field='${name}']`);
    const sourceFrom = { x: Number(field("r6-trace-from-x")?.value), y: Number(field("r6-trace-from-y")?.value) };
    const sourceTo = { x: Number(field("r6-trace-to-x")?.value), y: Number(field("r6-trace-to-y")?.value) };
    if (![sourceFrom.x, sourceFrom.y, sourceTo.x, sourceTo.y].every(Number.isFinite) || sourceFrom.x === sourceTo.x && sourceFrom.y === sourceTo.y) {
      uiState.error = "請輸入兩個不同的來源描繪端點。";
      render();
      return;
    }
    const before = r6ProjectFingerprint(project);
    record.trace = {
      sourceId,
      sourceEndpointsPdfPt: { from: r6RoundPoint(sourceFrom), to: r6RoundPoint(sourceTo) },
      from: r6RoundPoint(sourceFrom),
      to: r6RoundPoint(sourceTo),
      coordinateFrame: R6_SOURCE_POINT_FRAME,
      acceptedLiveEndpointsMm: null,
      status: "source_local_trace_draft",
      policy: { source_kind: "pdf", object_status: "existing", work_action: "none", budget_trigger: "none", dbspec_projection: "excluded" }
    };
    r6Record(sourceId, "manual_existing_trace", "source_local_trace_draft", {
      kind: "user_requested_source_local_trace",
      sourceEndpointsPdfPt: record.trace.sourceEndpointsPdfPt,
      coordinateFrame: R6_SOURCE_POINT_FRAME
    }, "scale_reviewer", before);
    r6Publish();
  }

  function r6PromoteManualTrace(sourceId) {
    const record = (project.r6Review?.records || []).find((item) => item.sourceId === sourceId);
    const receipt = project.r6Review?.calibrationReceipt;
    if (!record || record.userDecision !== "confirmed_pending_calibration" || !record.trace || !receipt || receipt.status !== "accepted_for_existing_object_review") {
      uiState.error = "請先完成比例校正並保留這筆來源描繪。";
      render();
      return;
    }
    if (record.category !== "wall") {
      uiState.error = "這個來源類別目前只會保留在既有物件審查中，需完成對應宿主與類別確認後才能建立可編輯項目。";
      render();
      return;
    }
    const sourceFrom = record.trace.sourceEndpointsPdfPt && record.trace.sourceEndpointsPdfPt.from;
    const sourceTo = record.trace.sourceEndpointsPdfPt && record.trace.sourceEndpointsPdfPt.to;
    const from = r6TransformSourcePointToLiveMm(sourceFrom, receipt.acceptedWorldMmPerPt);
    const to = r6TransformSourcePointToLiveMm(sourceTo, receipt.acceptedWorldMmPerPt);
    if (!r6FinitePoint(from) || !r6FinitePoint(to) || from.x === to.x && from.y === to.y || receipt.application?.appliedTransformId !== receipt.acceptedTransformId) {
      uiState.error = "來源描繪需要兩個不同端點。";
      render();
      return;
    }
    const before = r6ProjectFingerprint(project);
    pushHistory("Promote reviewed PDF existing trace");
    const wallId = `pdf-existing-r6-${r6StableToken({ sourceId, sourceFrom, sourceTo, acceptedTransformId: receipt.acceptedTransformId })}`;
    const wall = {
      id: wallId,
      from: { ...from },
      to: { ...to },
      thickness: 120,
      status: "existing",
      sourceType: "vector_pdf",
      source_object_id: sourceId,
      source_object_ids: [sourceId],
      sourceRegionId: record.sourceRegionId,
      sourceBBox: record.sourceBBox,
      sourceEndpointsPdfPt: { from: r6RoundPoint(sourceFrom), to: r6RoundPoint(sourceTo) },
      liveGeometryFrame: R6_ACCEPTED_LIVE_FRAME,
      source_kind: "pdf",
      object_status: "existing",
      work_action: "none",
      budget_trigger: "none",
      dbspec_projection: "excluded",
      mapping_state: "not_accepted",
      acceptedTransformId: receipt.acceptedTransformId,
      importSessionId: project.r6Review.importReceipt.importSessionId,
      reviewRequired: true,
      formalOutput: false,
      candidateOnly: true,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };
    project.walls.push(wall);
    rebuildWallGraph();
    record.trace.acceptedLiveEndpointsMm = { from: { ...from }, to: { ...to } };
    record.editableObjectId = wallId;
    record.userDecision = "accepted_existing_object_review";
    uiState.selectedWallId = wallId;
    r6Record(sourceId, "accept_existing_object", "accepted_existing_object_review", {
      kind: "manual_trace_promotion",
      editableObjectId: wallId,
      sourceEndpointsPdfPt: record.trace.sourceEndpointsPdfPt,
      acceptedLiveEndpointsMm: record.trace.acceptedLiveEndpointsMm,
      acceptedTransformId: receipt.acceptedTransformId
    }, "owner_or_designated_reviewer", before);
    r6Publish();
  }

  function r6ReviewWallBodySet(reviewSetId) {
    const reviewSet = (project.r6Review?.wallBodyReviewSets || []).find((item) => item.reviewSetId === reviewSetId);
    const calibration = project.r6Review?.calibrationReceipt;
    if (!reviewSet || !calibration || calibration.status !== "accepted_for_existing_object_review") {
      uiState.error = "請先完成比例校正，再確認相連牆體的審查範圍。";
      render();
      return;
    }
    const before = r6ProjectFingerprint(project);
    const liveIds = (project.walls || [])
      .filter((wall) => reviewSet.sourceObjectIds.includes(wall.source_object_id || wall.sourceWallId))
      .map((wall) => wall.id)
      .sort();
    reviewSet.candidateEditableObjectIds = liveIds;
    reviewSet.decision = "user_reviewed_1_to_many";
    r6Record(reviewSet.sourceObjectIds[0] || null, "review_ambiguous_wall_set", "user_reviewed_1_to_many", { kind: "continuity_review_set", sourceObjectIds: reviewSet.sourceObjectIds, editableObjectIds: liveIds }, "owner_or_designated_reviewer", before);
    r6Publish();
  }

  function isR4B1ReviewActive() {
    return Boolean(r4b1Model && project.r4b1Review);
  }

  function r4b1StableHash(value) {
    if (r4b1Model && typeof r4b1Model.stableTransformId === "function") {
      return r4b1Model.stableTransformId(value);
    }
    const text = typeof value === "string" ? value : JSON.stringify(value);
    let h1 = 0x811c9dc5;
    let h2 = 0x01000193;
    for (let index = 0; index < text.length; index += 1) {
      const code = text.charCodeAt(index);
      h1 = Math.imul(h1 ^ code, 16777619);
      h2 = Math.imul(h2 ^ (code + index), 2246822519);
    }
    return `${(h1 >>> 0).toString(16).padStart(8, "0")}${(h2 >>> 0).toString(16).padStart(8, "0")}`.toUpperCase();
  }

  function r4b1Fingerprint(currentProject = project) {
    const value = {
      schema: "laibe.planPuzzle.r4b1.projectFingerprint.v1",
      scale: currentProject.scale || null,
      walls: currentProject.walls || [],
      openings: currentProject.openings || [],
      structures: currentProject.structures || [],
      zones: currentProject.zones || [],
      sourceReview: currentProject.r4b1Review ? {
        calibrationReceipt: currentProject.r4b1Review.calibrationReceipt || null,
        reviewRecords: currentProject.r4b1Review.reviewRecords || {},
        manualTraces: currentProject.r4b1Review.manualTraces || {},
        promotionReview: currentProject.r4b1Review.promotionReview || []
      } : null
    };
    const serialized = JSON.stringify(value);
    return {
      schema: value.schema,
      sha256: r4b1StableHash(serialized),
      utf8ByteLength: new TextEncoder().encode(serialized).length,
      serialization: "stable-project-fingerprint-v1",
      includedSourceFields: ["scale", "walls", "openings", "structures", "zones", "r4b1Review.reviewRecords", "r4b1Review.manualTraces", "r4b1Review.promotionReview"]
    };
  }

  function r4b1Record(sourceId) {
    return project.r4b1Review?.records?.find((record) => record.sourceId === sourceId) || null;
  }

  function r4b1RecordCaseEvent(record, action, status, evidence, nextResponsibleParty) {
    const event = {
      actor: project.r4b1Review?.actor || "owner_review_user",
      time: new Date().toISOString(),
      caseId: project.r4b1Review?.caseId || "laibe-r4b1-case",
      source: record ? { pdfSha256: r4b1Model?.sourceSha256 || null, page: record.page, regionId: record.sourceRegionId, sourceId: record.sourceId } : null,
      action,
      status,
      evidence: evidence || { kind: "user_review_action", references: [], notes: "" },
      nextResponsibleParty: nextResponsibleParty || record?.nextResponsibleParty || "業主或指定圖面審閱者",
      policy: { ...(r4b1Model?.policy || {}) }
    };
    project.caseEvents = Array.isArray(project.caseEvents) ? project.caseEvents : [];
    project.caseEvents.push(event);
    project.r4b1Review.caseEvents = project.caseEvents;
    return event;
  }

  function r4b1QueueCounts() {
    const records = project.r4b1Review?.records || [];
    return {
      total: records.length,
      candidate: records.filter((record) => record.disposition === "candidate_present_unaccepted").length,
      manual: records.filter((record) => record.disposition === "missing_with_exact_reason").length,
      uncertain: records.filter((record) => record.disposition === "ignored_uncertain").length,
      confirmed: records.filter((record) => record.reviewStatus === "confirmed_for_review" || record.reviewStatus === "source_local_draft_reviewed").length,
      traceDrafts: Object.keys(project.r4b1Review?.manualTraces || {}).length,
      promoted: (project.r4b1Review?.promoted || []).length
    };
  }

  function r4b1PublishReceipt(status = "pending", extra = {}) {
    if (!isR4B1ReviewActive()) return;
    window.dispatchEvent(new CustomEvent("laibe-r4b1-state-changed", {
      detail: {
        status,
        reviewQueue: r4b1QueueCounts(),
        calibration: project.r4b1Review.calibrationReceipt || null,
        reviewLedger: project.r4b1Review.records || [],
        manualTraces: project.r4b1Review.manualTraces || {},
        caseEvents: project.caseEvents || [],
        promotion: {
          reviewCount: (project.r4b1Review.promotionReview || []).length,
          promotedCount: (project.r4b1Review.promoted || []).length,
          eligible: Boolean(project.r4b1Review.calibrationReceipt?.status === "accepted_for_promotion_review")
        },
        projectMutation: Boolean(extra.projectMutation),
        projectFingerprints: {
          baseline: project.r4b1Review.baselineFingerprint || null,
          current: r4b1Fingerprint(project)
        },
        ...extra
      }
    }));
  }

  function handleR4B1ModelReady(event) {
    r4b1Model = event.detail || window.LaibeR4B1ReviewModel || null;
    if (!r4b1Model) return;
    uiState.inspectorTab = "overview";
    if (!project.r4b1Review) {
      const baseline = cloneJson(project);
      project.r4b1Review = {
        schema: "laibe.planPuzzle.r4b1.userReviewState.v1",
        caseId: "laibe-r4b1-case",
        actor: "owner_review_user",
        reviewer: "designated_plan_reviewer",
        sourceSha256: r4b1Model.sourceSha256,
        records: cloneJson(r4b1Model.records || []).map((record) => ({ ...record, reviewStatus: record.reviewStatus || "pending_user", traceDraft: null })),
        reviewRecords: {},
        manualTraces: {},
        calibrationReceipt: null,
        promotionReview: [],
        promoted: [],
        caseEvents: [],
        baselineFingerprint: r4b1Fingerprint(baseline),
        baselineProject: baseline
      };
      project.caseEvents = [];
      r4b1RecordCaseEvent(null, "review_queue_opened", "pending_user", { kind: "source_review_queue", references: [], notes: "R4B.1 來源審查隊列已開啟。" }, "業主或指定圖面審閱者");
    }
    render();
    r4b1PublishReceipt("pending");
  }

  function r4b1ConfirmCandidate(sourceId) {
    const record = r4b1Record(sourceId);
    if (!record || record.disposition !== "candidate_present_unaccepted") return;
    pushHistory("confirm source candidate");
    record.reviewStatus = "confirmed_for_review";
    record.reviewRecords = { sourceId, status: "confirmed_for_review", editable_object_id: null, mapping_state: "not_accepted" };
    project.r4b1Review.reviewRecords[sourceId] = record.reviewRecords;
    r4b1RecordCaseEvent(record, "confirm_candidate", "blocked_by_scale", { kind: "source_pdf_or_user_review", references: [record.sourceRegionId], notes: "候選已確認，仍等待比例校正紀錄。" });
    uiState.message = "候選已記錄；完成並接受比例校正紀錄後，才可進入既有物件審查。";
    uiState.error = "";
    r4b1PublishReceipt("pending");
    render();
  }

  function r4b1RequestUncertainReview(sourceId) {
    const record = r4b1Record(sourceId);
    if (!record || record.disposition !== "ignored_uncertain") return;
    pushHistory("request uncertain source review");
    record.reviewStatus = "evidence_only_review_requested";
    r4b1RecordCaseEvent(record, "request_manual_review", "evidence_only", { kind: "new_evidence_request", references: [record.sourceRegionId], notes: "此符號仍為證據；此操作不會建立草稿或物件。" });
    uiState.message = "已記錄人工複核需求；此筆仍只保留證據，不會自動升格。";
    r4b1PublishReceipt("pending");
    render();
  }

  function r4b1SaveManualTrace(sourceId) {
    const record = r4b1Record(sourceId);
    if (!record || record.disposition !== "missing_with_exact_reason") return;
    const note = document.querySelector("[data-field='r4b1-trace-note']")?.value.trim() || "";
    const from = { x: Number(document.querySelector("[data-field='r4b1-trace-from-x']")?.value), y: Number(document.querySelector("[data-field='r4b1-trace-from-y']")?.value) };
    const to = { x: Number(document.querySelector("[data-field='r4b1-trace-to-x']")?.value), y: Number(document.querySelector("[data-field='r4b1-trace-to-y']")?.value) };
    if (![from.x, from.y, to.x, to.y].every(Number.isFinite) || (from.x === to.x && from.y === to.y)) {
      uiState.error = "請填寫兩個不同的來源點，才能保存局部描繪。";
      render();
      return;
    }
    pushHistory("save source-local trace");
    const trace = {
      sourceId: record.sourceId,
      category: record.sourceCategory,
      subtype: record.sourceSubtype,
      source_kind: "pdf",
      object_status: "existing",
      work_action: "none",
      budget_trigger: "none",
      dbspec_projection: "excluded",
      sourceSha256: r4b1Model.sourceSha256,
      page: record.page,
      sourceRegionId: record.sourceRegionId,
      sourceBBox: record.sourceBBox,
      geometry: { from, to, coordinateFrame: "page-top-left-pdf-pt", origin: "user_source_local_trace" },
      note,
      status: "source_local_draft",
      mapping_state: "not_accepted",
      editable_object_id: null,
      acceptedTransformId: null,
      createdAt: new Date().toISOString()
    };
    project.r4b1Review.manualTraces[sourceId] = trace;
    record.reviewStatus = "source_local_draft";
    project.r4b1Review.reviewRecords[sourceId] = { sourceId, status: "source_local_draft", editable_object_id: null, mapping_state: "not_accepted" };
    r4b1RecordCaseEvent(record, "trace_source_local", "source_local_draft", { kind: "user_trace", references: [record.sourceRegionId], notes: note });
    uiState.message = "來源局部草稿已保存；它不會進入一般新增物件流程。";
    uiState.error = "";
    r4b1PublishReceipt("pending");
    render();
  }

  function r4b1SubmitCalibration() {
    if (!isR4B1ReviewActive()) return false;
    if (uiState.calibrationPoints.length < 2) {
      const readPoint = (prefix) => ({
        x: Number(document.querySelector(`[data-field='r4b1-${prefix}-x']`)?.value),
        y: Number(document.querySelector(`[data-field='r4b1-${prefix}-y']`)?.value)
      });
      const typedFrom = readPoint("endpoint-from");
      const typedTo = readPoint("endpoint-to");
      if ([typedFrom.x, typedFrom.y, typedTo.x, typedTo.y].every(Number.isFinite)) {
        uiState.calibrationPoints = [typedFrom, typedTo];
      }
    }
    if (uiState.calibrationPoints.length < 2) {
      uiState.error = "請在底圖上選取兩個不同的校正端點。";
      render();
      return false;
    }
    const [from, to] = uiState.calibrationPoints;
    const distance = getDistance(from, to);
    const entered = Number.parseFloat(uiState.knownLengthInput);
    const unit = uiState.calibrationUnit;
    const multiplier = ({ mm: 1, cm: 10, m: 1000 })[unit];
    if (!Number.isFinite(entered) || entered <= 0 || !multiplier) {
      uiState.error = "請輸入大於 0 的真實長度，並選擇 mm、cm 或 m。";
      render();
      return false;
    }
    const normalizedMillimetres = Number((entered * multiplier).toFixed(3));
    const before = r4b1Fingerprint(project);
    const source = { pdfSha256: r4b1Model.sourceSha256, page: 1, regionId: uiState.calibrationRegionId, coordinateFrame: "page-top-left-pdf-pt" };
    const receipt = {
      schema: "a9.r4b.user-scale-calibration-receipt.v1",
      receiptId: `r4b1-calibration-${r4b1StableHash({ source, from, to, normalizedMillimetres, unit })}`,
      actor: uiState.calibrationActor.trim() || project.r4b1Review.actor,
      reviewer: uiState.calibrationReviewer.trim() || project.r4b1Review.reviewer,
      time: new Date().toISOString(),
      caseId: uiState.calibrationCaseId.trim() || project.r4b1Review.caseId,
      sourceSha256: r4b1Model.sourceSha256,
      source,
      sourceEndpoints: { from: { ...from }, to: { ...to } },
      userEnteredRealLength: entered,
      unit,
      normalizedMillimetres,
      computed: {
        sourceDistance: Number(distance.toFixed(4)),
        scale: Number((distance / normalizedMillimetres).toFixed(8)),
        residual: 0,
        tolerance: 0.5,
        transform: { forward: { sourceToMm: normalizedMillimetres / distance }, inverse: { mmToSource: distance / normalizedMillimetres } }
      },
      acceptedTransformId: null,
      beforeProjectFingerprint: before,
      afterProjectFingerprint: before,
      status: "pending_review",
      evidence: { source: "user_selected_endpoints_and_entered_length", endpointCount: 2, dimensionTextUsedAsProof: false },
      nextResponsibleParty: receiptReviewerLabel(uiState.calibrationReviewer),
      policy: { ...(r4b1Model.policy || {}) }
    };
    project.r4b1Review.calibrationReceipt = receipt;
    r4b1RecordCaseEvent(null, "calibration_submitted", "pending_user", { kind: "calibration_receipt_draft", references: [source.regionId], notes: "使用者輸入長度與單位，等待審閱接受。" }, receipt.nextResponsibleParty);
    uiState.mode = "select";
    resetTransientPointerState();
    uiState.message = "校正資料已送出，請由指定審閱者確認；目前仍不能建立既有物件。";
    uiState.error = "";
    r4b1PublishReceipt("pending");
    render();
    return true;
  }

  function receiptReviewerLabel(value) {
    return value?.trim() || "指定圖面審閱者";
  }

  function r4b1AcceptCalibration() {
    const pending = project.r4b1Review?.calibrationReceipt;
    if (!pending || pending.status !== "pending_review") return;
    const source = pending.source;
    const acceptedTransformId = r4b1StableHash({ sourceSha256: pending.sourceSha256, page: source.page, regionId: source.regionId, from: pending.sourceEndpoints.from, to: pending.sourceEndpoints.to, normalizedMm: pending.normalizedMillimetres, unit: pending.unit });
    const scale = pending.computed.scale;
    const simulatedAfter = cloneJson(project);
    simulatedAfter.scale = { ...(simulatedAfter.scale || {}), pxPerMm: scale, calibrated: true, acceptedTransformId, acceptedTransformStatus: "accepted_for_promotion_review" };
    simulatedAfter.r4b1Review = { ...(simulatedAfter.r4b1Review || {}), calibrationReceipt: { ...pending, status: "accepted_for_promotion_review", acceptedTransformId } };
    const accepted = { ...pending, status: "accepted_for_promotion_review", acceptedTransformId, afterProjectFingerprint: r4b1Fingerprint(simulatedAfter) };
    const predicate = r4b1Model.evaluateCalibrationReceipt(accepted);
    if (!predicate.pass) {
      uiState.error = "比例校正紀錄尚未通過完整檢查，請補齊審閱人、案件與端點資料。";
      project.r4b1Review.calibrationReceipt = { ...pending, validation: predicate };
      r4b1PublishReceipt("error");
      render();
      return;
    }
    pushHistory("接受比例校正紀錄");
    project.scale = { ...(project.scale || {}), pxPerMm: scale, calibrated: true, acceptedTransformId, acceptedTransformStatus: "accepted_for_promotion_review", autoScaleApplied: false };
    project.underlay = project.underlay || {};
    project.underlay.calibratedBy = { from: { ...pending.sourceEndpoints.from }, to: { ...pending.sourceEndpoints.to }, pixelDistance: pending.computed.sourceDistance, knownLength: pending.normalizedMillimetres, unit: "mm", method: "accepted-user-receipt", acceptedTransformId };
    project.r4b1Review.calibrationReceipt = accepted;
    r4b1RecordCaseEvent(null, "calibration_accepted", "accepted_for_promotion_review", { kind: "accepted_calibration_receipt", references: [source.regionId], notes: "只接受使用者輸入的端點、長度與單位。" });
    uiState.message = "比例校正紀錄已接受；現在可逐筆進入既有物件審查，仍不會自動建立全部來源物件。";
    uiState.error = "";
    r4b1PublishReceipt("ok");
    render();
  }

  function r4b1PromoteManualTrace(sourceId) {
    const trace = project.r4b1Review?.manualTraces?.[sourceId];
    const record = r4b1Record(sourceId);
    if (!trace || !record) return;
    const eligibility = r4b1Model.evaluatePromotionEligibility({ calibrationReceipt: project.r4b1Review.calibrationReceipt, reviewRecord: { ...trace, reviewStatus: "source_local_draft_reviewed", disposition: record.disposition }, project });
    if (!eligibility.pass) {
      uiState.error = "目前仍不符合建立條件：請先接受比例校正紀錄，並完成這一筆來源草稿審閱。";
      r4b1PublishReceipt("pending");
      render();
      return;
    }
    const from = trace.geometry.from;
    const to = trace.geometry.to;
    const wallId = `pdf-existing-trace-${r4b1StableHash({ sourceId, from, to })}`;
    if (project.walls.some((wall) => wall.id === wallId)) return;
    pushHistory("promote reviewed source trace");
    const wall = {
      id: wallId,
      from: { x: from.x, y: from.y },
      to: { x: to.x, y: to.y },
      thickness: 120,
      status: "existing",
      wallType: "existing_wall",
      structural: false,
      source_kind: "pdf",
      object_status: "existing",
      work_action: "none",
      budget_trigger: "none",
      dbspec_projection: "excluded",
      source_object_id: sourceId,
      sourceRegionId: record.sourceRegionId,
      sourceSha256: r4b1Model.sourceSha256,
      sourceBBox: record.sourceBBox,
      provenance: { sourceId, sourceSubtype: record.sourceSubtype, calibrationReceiptId: project.r4b1Review.calibrationReceipt.receiptId, acceptedTransformId: project.r4b1Review.calibrationReceipt.acceptedTransformId, mapping_state: "not_accepted", transformStatus: "accepted_for_promotion_review" },
      editable_object_id: wallId,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };
    project.walls.push(wall);
    project.r4b1Review.promotionReview.push({ sourceId, editableObjectId: wallId, status: "promoted_existing_review", mapping_state: "not_accepted" });
    project.r4b1Review.promoted.push(wallId);
    trace.editable_object_id = wallId;
    trace.status = "promoted_existing_review";
    r4b1RecordCaseEvent(record, "promotion", "promoted_existing_review", { kind: "source_local_trace", references: [record.sourceRegionId], notes: "單筆人工來源草稿進入受控的既有物件審查。" });
    selectWall(wallId);
    r4b1PublishReceipt("ok");
  }

  function r4b1RestoreSession() {
    const reviewState = project.r4b1Review;
    const baseline = reviewState?.baselineProject;
    if (!baseline) return;
    const baselineFingerprint = reviewState.baselineFingerprint;
    pushHistory("restore review session");
    const restoredProject = cloneJson(baseline);
    restoredProject.r4b1Review = cloneJson(reviewState);
    restoredProject.caseEvents = Array.isArray(reviewState.caseEvents) ? cloneJson(reviewState.caseEvents) : [];
    project = restoredProject;
    invalidateNativeWallGeometryV3();
    if (project.r4b1Review) {
      project.r4b1Review.restoredFingerprint = baselineFingerprint;
      r4b1RecordCaseEvent(null, "restore", "restored", { kind: "session_restore", references: [], notes: "已還原本輪審查前的專案狀態。" });
    }
    uiState.message = "本輪審查狀態已還原；來源隊列與畫布回到開始前。";
    uiState.error = "";
    render();
    r4b1PublishReceipt("ok");
  }

  function createHistorySnapshot(label) {
    return {
      id: `history-${++historySequence}`,
      label,
      createdAt: new Date().toISOString(),
      project: cloneJson(project),
      uiState: cloneJson(uiState),
      styleVisualRequest: cloneJson(styleVisualRequest),
      styleVisualTask: cloneJson(styleVisualTask)
    };
  }

  function pushHistory(label) {
    undoStack.push(createHistorySnapshot(label));
    if (undoStack.length > HISTORY_LIMIT) {
      undoStack.shift();
    }
    redoStack = [];
  }

  function restoreHistorySnapshot(snapshot, message) {
    project = cloneJson(snapshot.project);
    invalidateNativeWallGeometryV3();
    uiState = cloneJson(snapshot.uiState);
    styleVisualRequest = cloneJson(snapshot.styleVisualRequest);
    styleVisualTask = cloneJson(snapshot.styleVisualTask);
    furniturePointerState = null;
    structurePointerState = null;
    importSequence += 1;
    fileInput.value = "";
    uiState.message = message;
    uiState.error = "";
    clearWallDraft();
    render();
  }

  function undoLastAction() {
    if (!undoStack.length) {
      uiState.error = "";
      uiState.message = "目前沒有可復原的操作。";
      render();
      return;
    }
    const r6Before = isR6ReviewActive() ? r6ProjectFingerprint(project) : null;
    const currentSnapshot = createHistorySnapshot("Current state");
    const previousSnapshot = undoStack.pop();
    redoStack.push(currentSnapshot);
    restoreHistorySnapshot(previousSnapshot, "已復原上一個圖面操作。");
    r6Record(null, "undo", "restored_user_governed_review_state", { kind: "history_restore", label: previousSnapshot.label }, "owner_or_designated_reviewer", r6Before);
    r6Publish();
    syncBridge();
  }

  function redoLastAction() {
    if (!redoStack.length) {
      uiState.error = "";
      uiState.message = "目前沒有可重做的操作。";
      render();
      return;
    }
    const r6Before = isR6ReviewActive() ? r6ProjectFingerprint(project) : null;
    const currentSnapshot = createHistorySnapshot("重做前狀態");
    const nextSnapshot = redoStack.pop();
    undoStack.push(currentSnapshot);
    if (undoStack.length > HISTORY_LIMIT) {
      undoStack.shift();
    }
    restoreHistorySnapshot(nextSnapshot, "已重做上一個圖面操作。");
    r6Record(null, "redo", "reapplied_user_governed_review_state", { kind: "history_restore", label: nextSnapshot.label }, "owner_or_designated_reviewer", r6Before);
    r6Publish();
    syncBridge();
  }

