    clearPrimarySelectionState();
    uiState.annotationAnchor = null;
    clearWallDraft();
    clearStructureDraft();
    clearZoneBoundaryDraft();
    clearProjectGroupIds();
    clearExternalSelectionArtifacts({ clearActiveGroup: true });
    uiState.error = "";
    uiState.message = hadSelection ? "已清除選取。" : "目前沒有選取項目。";
