      depth_mm: Number.isFinite(Number(object.depth_mm)) ? Number(object.depth_mm) : null,
      height_mm: Number.isFinite(Number(object.height_mm)) ? Number(object.height_mm) : null,
      materialTags: Array.isArray(object.materialTags) ? object.materialTags : [],
      materialRules: object.materialRules || null,
      resizePolicy: object.resizePolicy || "free",
      candidateOnly: true,
      noPricingIdentifiers: true,
