  function renderPlanPuzzleGuideCard() {
    ensurePlanPuzzleGuideState();
    const calibrated = derivePlanWorkflowState().scaleAccepted;
    const hasContent = project.walls.length || project.zones.length || project.furniture.length;
    const version = project.budgetDraftVersion || 0;
    const pendingInput = (project.guide && project.guide.pendingInput) ? project.guide.pendingInput : "";
    const pendingPdfReviewCount = getNativePdfOpeningReviewState().pendingCount;
    let text, label, act;
    if (!calibrated) {
      text = "先設定比例，系統才知道長度與面積。";
      label = "設定比例";
      act = (project.underlay && project.importSource && project.importSource.previewSupported) ? "start-calibration" : "start-plan-scale";
    } else if (!hasContent) {
      text = "先畫牆、標空間，或放入固定家具與設備。";
      label = "繼續畫圖"; act = "start-draw-wall";
    } else if (pendingPdfReviewCount > 0) {
      text = "請先核對已建立的門窗位置與保留的圖面依據，再整理預算草稿。";
      label = "檢查門窗與圖面依據";
      act = "review-native-pdf-evidence";
    } else if (version > 0) {
      text = "圖面已更新，可以重新整理預算草稿。";
      label = "更新預算草稿"; act = "generate-budget-draft";
    } else {
      text = "可以先整理一版預算草稿，之後仍可修改。";
      label = "整理預算草稿"; act = "generate-budget-draft";
    }
    const budgetInput = pendingPdfReviewCount > 0
      ? '<div class="inspector-compact-note" style="margin-top:12px">核對門窗與圖面依據時，可選取物件補充尺寸、類型與備註；重要調整會保留在案件紀錄。</div>'
      : [
          '<div class="field-row full" style="margin-top:12px">',
          '<label for="plan-guide-input">補充給預算的說明</label>',
          '<textarea id="plan-guide-input" data-field="plan-guide-input" rows="2" placeholder="例如：冷氣排水沿用原位置、浴室只做明管延伸、保留原有地板。">' + escapeHTML(pendingInput) + '</textarea>',
          '</div>',
          '<div class="inspector-actions" style="margin-top:8px"><button class="secondary-btn" type="button" data-action="record-guide-question" style="width:100%">記錄補充</button></div>',
          '<div class="inspector-compact-note" style="margin-top:12px">這是預算草稿依據，正式數量、工法與位置仍需依場勘與廠商回覆確認。</div>'
        ].join("");
    return [
      '<section class="status-card" aria-label="下一步">',
      '<b>下一步</b>',
      '<div class="inspector-compact-note" style="margin-bottom:10px">' + escapeHTML(text) + '</div>',
      '<div class="inspector-actions"><button class="toolbar-btn primary" type="button" data-action="' + act + '" style="width:100%;min-height:38px">' + escapeHTML(label) + '</button></div>',
      budgetInput,
      '</section>'
    ].join("");
  }
  function getBudgetReadinessMessage() {
    var hasContent = project.walls.length || project.zones.length || project.furniture.length;
    var workflow = derivePlanWorkflowState();
    if (!project.importSource && !hasContent) { return "先匯入底圖，或直接空白開始。"; }
    if (!workflow.scaleAccepted) { return workflow.scaleLabel + "。完成比例確認後，牆面長度與空間面積才會進入預算草稿。"; }
    if (!hasContent) { return "請先標出空間、牆面或固定設備。"; }
    if (getNativePdfOpeningReviewState().pendingCount > 0) { return "請先核對來源門窗的位置、類型與尺寸，再整理預算草稿。"; }
    if ((project.budgetDraftVersion || 0) > 0) { return "已整理本版預算草稿。修改圖面後可更新。"; }
    return "已可整理本版預算草稿。";
  }
  function getBudgetDraftStatusLabel() {
    var estimable = derivePlanWorkflowState().scaleAccepted && (project.walls.length || project.zones.length || project.furniture.length);
    if ((project.budgetDraftVersion || 0) > 0) { return "已產生第 " + project.budgetDraftVersion + " 版"; }
    if (getNativePdfOpeningReviewState().pendingCount > 0) { return "等待核對門窗"; }
    return estimable ? "可產生" : "尚未產生";
  }
  function getPdfObjectizationImportMetrics() {
    return (project.pdfReviewObjects && project.pdfReviewObjects.importMetrics) ||
      project.lastPdfObjectizationSceneImport ||
      null;
  }
  function getNativePdfOpeningReviewState() {
    const openings = (project.openings || []).filter((opening) => isPdfDerivedExistingObject(opening));
    const confirmedCount = openings.filter((opening) => opening.sourceReviewStatus === "confirmed").length;
    return {
      totalCount: openings.length,
      confirmedCount,
      pendingCount: openings.length - confirmedCount
    };
  }
  function getNativePdfOpeningReviewInvalidationReason(field) {
    if (field === "selected-opening-offset" || field === "selected-opening-width") {
      return "position_or_size_changed";
    }
    if (
      field === "selected-opening-kind" ||
      field === "selected-opening-type" ||
      field === "selected-opening-sill-height" ||
      field === "selected-opening-height"
    ) {
      return "details_changed";
    }
    return null;
  }
  function reopenNativePdfOpeningPositionReview(opening, reason = "position_or_size_changed") {
    if (!isPdfDerivedExistingObject(opening) || opening.sourceReviewStatus !== "confirmed") {
      return false;
    }
    const invalidatedAt = new Date().toISOString();
    opening.sourceReviewHistory = Array.isArray(opening.sourceReviewHistory) ? opening.sourceReviewHistory : [];
    opening.sourceReviewHistory.push({
      status: "confirmed",
      reviewedAt: opening.sourceReviewedAt || null,
      reviewedBy: opening.sourceReviewedBy || null,
      reviewer: opening.sourceReviewer || null,
      caseId: opening.sourceReviewCaseId || null,
      invalidatedAt,
      invalidationReason: reason
    });
    opening.sourceReviewStatus = "needs_review";
    opening.sourceReviewInvalidatedAt = invalidatedAt;
    opening.sourceReviewInvalidationReason = reason;
    opening.sourceReviewedAt = null;
    opening.sourceReviewedBy = null;
    opening.sourceReviewer = null;
    opening.sourceReviewCaseId = null;
    return true;
  }
  function renderDraftStatusCard() {
    var row = function(k, v){ return '<div class="status-row"><span>' + k + '</span><span>' + escapeHTML(String(v)) + '</span></div>'; };
    var pdfMetrics = getPdfObjectizationImportMetrics();
    var openingReview = getNativePdfOpeningReviewState();
    var openingReviewCount = openingReview.totalCount || (pdfMetrics ? Number(pdfMetrics.openingReviewCount) || 0 : 0);
    var noteReviewCount = pdfMetrics
      ? (Number(pdfMetrics.dimensionLineCount) || 0) + (Number(pdfMetrics.leaderLineCount) || 0) + (Number(pdfMetrics.glyphClusterCount) || 0)
      : 0;
    var objectizationStatusRows = pdfMetrics
      ? row("來源門窗候選", openingReview.pendingCount > 0
          ? openingReview.pendingCount + " 筆待確認" + (openingReview.confirmedCount ? "（已確認 " + openingReview.confirmedCount + " 筆）" : "")
          : (openingReviewCount ? openingReviewCount + " 筆已確認" : "0 筆")) +
        row("尺寸與註記依據", noteReviewCount
          ? (derivePlanWorkflowState().scaleAccepted ? noteReviewCount + " 筆已保留" : noteReviewCount + " 筆待確認")
          : "0 筆")
      : "";
    var openingStageNote = pdfMetrics
      ? '<div class="inspector-compact-note">來源候選與已建立的可編輯物件屬於不同審查階段，數量可能不同。</div>'
      : "";
    return [
      '<section class="status-card" aria-label="預算依據狀態">',
      '<b>預算依據狀態</b>',
      '<div class="status-grid">',
      objectizationStatusRows,
      row("底圖", getUnderlayStatusLabel()),
      row("比例", derivePlanWorkflowState().scaleLabel),
      row("來源空間候選", getZoneReviewCounts().sourceCandidates + " 筆"),
      row("已確認空間", getZoneReviewCounts().confirmed + " 間"),
      row("牆面", project.walls.length + " 段"),
      row("已建立門窗開口", project.openings.length + " 個"),
      row("家具設備", project.furniture.length + " 件"),
      row("預算草稿", getBudgetDraftStatusLabel()),
      '</div>',
      '<div class="inspector-compact-note">' + escapeHTML(getBudgetReadinessMessage()) + '</div>',
      openingStageNote,
      '</section>'
    ].join("");
  }
