  function renderSelectedStructureCard(structure) {
    const isBeam = structure.category === "beam";
    const isStair = structure.kind === "stair" || structure.structureType === "stair";
    const lengthMm = isBeam ? Math.round(getDistance(structure.from || { x: 0, y: 0 }, structure.to || { x: 0, y: 0 })) : null;
    const typeOptions = STRUCTURE_TYPE_OPTIONS[isBeam ? "beam" : "column"]
      .map((option) => '<option value="' + escapeAttribute(option.value) + '"' + (option.value === structure.kind ? ' selected' : '') + '>' + escapeHTML(option.label) + '</option>')
      .join("");
    const statusLabel = structure.candidateStatus === "existing_candidate" || structure.object_status === "existing" || structure.status === "existing"
      ? "既有物件候選"
      : "新增物件候選";
    const scaleAccepted = selectedScaleAccepted();
    const dimensionDisabled = selectedScaleDisabledAttribute();
    const dimensionText = !scaleAccepted
      ? "比例尚未確認"
      : isBeam
      ? formatNumber(lengthMm) + ' x ' + formatNumber(structure.widthMm) + ' x ' + formatNumber(structure.depthMm) + ' mm'
      : formatNumber(structure.widthMm) + ' x ' + formatNumber(structure.depthMm) + ' mm';
    const fields = isBeam
      ? [
          '<div class="field-row"><label for="selected-structure-from-x">起點 X</label><input id="selected-structure-from-x" data-field="selected-structure-from-x" type="number" value="' + Math.round(structure.from?.x || 0) + '"' + dimensionDisabled + '></div>',
          '<div class="field-row"><label for="selected-structure-from-y">起點 Y</label><input id="selected-structure-from-y" data-field="selected-structure-from-y" type="number" value="' + Math.round(structure.from?.y || 0) + '"' + dimensionDisabled + '></div>',
          '<div class="field-row"><label for="selected-structure-to-x">終點 X</label><input id="selected-structure-to-x" data-field="selected-structure-to-x" type="number" value="' + Math.round(structure.to?.x || 0) + '"' + dimensionDisabled + '></div>',
          '<div class="field-row"><label for="selected-structure-to-y">終點 Y</label><input id="selected-structure-to-y" data-field="selected-structure-to-y" type="number" value="' + Math.round(structure.to?.y || 0) + '"' + dimensionDisabled + '></div>',
          '<div class="field-row"><label for="selected-structure-width">寬度（mm）</label><input id="selected-structure-width" data-field="selected-structure-width" type="number" min="' + MIN_STRUCTURE_SIZE_MM + '" value="' + Math.round(structure.widthMm || 0) + '"' + dimensionDisabled + '></div>',
          '<div class="field-row"><label for="selected-structure-depth">深度（mm）</label><input id="selected-structure-depth" data-field="selected-structure-depth" type="number" min="' + MIN_STRUCTURE_SIZE_MM + '" value="' + Math.round(structure.depthMm || 0) + '"' + dimensionDisabled + '></div>',
          '<div class="field-row full"><label>長度</label><input type="text" value="' + escapeAttribute(selectedPhysicalDimension(lengthMm)) + '" readonly></div>'
        ].join("")
      : [
          '<div class="field-row"><label for="selected-structure-x">X</label><input id="selected-structure-x" data-field="selected-structure-x" type="number" value="' + Math.round(structure.x || 0) + '"' + dimensionDisabled + '></div>',
          '<div class="field-row"><label for="selected-structure-y">Y</label><input id="selected-structure-y" data-field="selected-structure-y" type="number" value="' + Math.round(structure.y || 0) + '"' + dimensionDisabled + '></div>',
          '<div class="field-row"><label for="selected-structure-width">寬度（mm）</label><input id="selected-structure-width" data-field="selected-structure-width" type="number" min="' + MIN_STRUCTURE_SIZE_MM + '" value="' + Math.round(structure.widthMm || 0) + '"' + dimensionDisabled + '></div>',
          '<div class="field-row"><label for="selected-structure-depth">深度（mm）</label><input id="selected-structure-depth" data-field="selected-structure-depth" type="number" min="' + MIN_STRUCTURE_SIZE_MM + '" value="' + Math.round(structure.depthMm || 0) + '"' + dimensionDisabled + '></div>',
          '<div class="field-row full"><label for="selected-structure-height">高度（mm）</label><input id="selected-structure-height" data-field="selected-structure-height" type="number" min="0" value="' + Math.round(structure.heightMm || 0) + '"' + dimensionDisabled + '></div>'
        ].join("");
    return [
      '<section class="status-card selected-object-card" data-testid="selected-structure-card">',
      '<b>' + (isStair ? '樓梯' : isBeam ? '梁' : '柱') + '候選</b>',
      '<div class="status-grid">',
      '<div class="status-row"><span>類型</span><span>' + escapeHTML(getStructureTypeLabel(structure.kind, structure.category)) + '</span></div>',
      '<div class="status-row"><span>尺寸</span><span>' + escapeHTML(dimensionText) + '</span></div>',
      '<div class="status-row"><span>狀態</span><span>' + escapeHTML(statusLabel) + ' / 草稿待確認</span></div>',
      '</div>',
      '<div class="field-grid"><div class="field-row full"><label for="selected-structure-label">\u540d\u7a31</label><input id="selected-structure-label" data-field="selected-structure-label" type="text" value="' + escapeAttribute(structure.label || getStructureTypeLabel(structure.kind, structure.category)) + '"></div><div class="field-row full"><label for="selected-structure-type">類型</label><select id="selected-structure-type" data-field="selected-structure-type">' + typeOptions + '</select></div>' + fields + '</div>',
      renderSelectedScaleNotice(),
      '<div class="inspector-compact-note">此結構物件仍是草稿資料，正式圖說與估價需另行審核。</div>',
      '<div class="inspector-actions"><button class="secondary-btn danger" type="button" data-action="delete-current-selection">刪除</button></div>',
      '</section>'
    ].join("");
  }

  function renderSelectedWallCard(wall) {
    const edge = getEdgeForWall(wall.id);
    const wallType = normalizeWallType(wall.wallType);
    const wallDisplayName = getWallDisplayName(wall.id);
    const length = getDistance(wall.from, wall.to);
    const dimensionDisabled = selectedScaleDisabledAttribute();
    return [
      '<form class="inspector-form" aria-label="選取牆線屬性">',
      '<div class="status-card selected-object-card" data-testid="selected-wall-card">',
      '<b>牆線候選</b>',
      '<div class="status-grid">',
      '<div class="status-row"><span>名稱</span><span>' + escapeHTML(wallDisplayName) + '</span></div>',
      '<div class="status-row"><span>長度</span><span>' + escapeHTML(selectedPhysicalDimension(length)) + '</span></div>',
      '<div class="status-row"><span>狀態</span><span>' + escapeHTML(getWallStatusLabel(wall.status)) + '</span></div>',
      '<div class="status-row"><span>類型</span><span>' + escapeHTML(getWallTypeLabel(wallType)) + '</span></div>',
      '<div class="status-row"><span>說明</span><span>' + escapeHTML(getWallTypeDetail(wallType)) + '</span></div>',
      '<div class="status-row"><span>牆線連結</span><span>' + (edge ? '已連結' : '未連結') + '</span></div>',
      '<div class="status-row"><span>連結長度</span><span>' + (edge ? escapeHTML(selectedPhysicalDimension(edge.length)) : '-') + '</span></div>',
      '<div class="status-row"><span>草稿狀態</span><span>需人工確認後才能作正式依據</span></div>',
      '</div>',
      '<div class="inspector-actions" style="margin-top: 12px;">',
      '<button class="secondary-btn" type="button" data-action="add-opening" data-opening-kind="door">新增門</button>',
      '<button class="secondary-btn" type="button" data-action="add-opening" data-opening-kind="window">新增窗</button>',
      '</div>',
      '</div>',
      '<div class="field-grid">',
      '<div class="field-row full"><label for="selected-wall-status">狀態</label><select id="selected-wall-status" data-field="selected-wall-status">' + renderStatusOption("existing", wall.status) + renderStatusOption("new", wall.status) + renderStatusOption("demolished", wall.status) + '</select></div>',
      '<div class="field-row full"><label for="selected-wall-type">牆面類型</label><select id="selected-wall-type" data-field="selected-wall-type">' + renderHumanWallTypeOptions(wallType) + '</select></div>',
      '<div class="field-row"><label for="selected-wall-thickness">厚度</label><select id="selected-wall-thickness" data-field="selected-wall-thickness"' + dimensionDisabled + '>' + renderWallThicknessOptions(wall.thickness) + '</select></div>',
      '<div class="field-row"><label for="selected-wall-thickness-manual">自訂厚度（mm）</label><input id="selected-wall-thickness-manual" data-field="selected-wall-thickness-manual" type="number" min="' + MIN_WALL_THICKNESS + '" max="' + MAX_WALL_THICKNESS + '" step="1" value="' + wall.thickness + '"' + dimensionDisabled + '></div>',
      '<div class="inline-message full">' + escapeHTML(WALL_THICKNESS_HELP_TEXT) + '</div>',
      '<div class="inline-message full">結構牆提醒：拆除、開口或移位前須由專業人員確認。</div>',
      '<label class="toggle-row" for="selected-wall-structural" style="align-self:end; min-height:42px;"><span>結構牆</span><input id="selected-wall-structural" data-field="selected-wall-structural" type="checkbox" ' + (wall.structural ? 'checked' : '') + '></label>',
      '<div class="field-row"><label for="selected-wall-from-x">起點 X</label><input id="selected-wall-from-x" data-field="selected-wall-from-x" type="number" step="1" value="' + wall.from.x + '"' + dimensionDisabled + '></div>',
      '<div class="field-row"><label for="selected-wall-from-y">起點 Y</label><input id="selected-wall-from-y" data-field="selected-wall-from-y" type="number" step="1" value="' + wall.from.y + '"' + dimensionDisabled + '></div>',
      '<div class="field-row"><label for="selected-wall-to-x">終點 X</label><input id="selected-wall-to-x" data-field="selected-wall-to-x" type="number" step="1" value="' + wall.to.x + '"' + dimensionDisabled + '></div>',
      '<div class="field-row"><label for="selected-wall-to-y">終點 Y</label><input id="selected-wall-to-y" data-field="selected-wall-to-y" type="number" step="1" value="' + wall.to.y + '"' + dimensionDisabled + '></div>',
      '</div>',
      renderSelectedScaleNotice(),
      '<div class="project-readout">牆線位置仍需確認接點與尺寸後，才能作正式圖說依據。</div>',
      '<div class="inspector-actions"><button class="danger-btn" type="button" data-action="delete-wall">刪除牆線</button><button class="secondary-btn" type="button" data-action="clean-wall-endpoints">整理接點</button><button class="secondary-btn" type="button" data-action="clear-selection">清除選取</button></div>',
      '</form>'
    ].join("");
  }

  function renderSelectedZoneCard(zone) {
    ensureZoneBoundaryFields(zone);
    const zoneDisplayName = zone.name || getZoneDisplayName(zone.id);
    const sourceLabel = isExistingPdfObject(zone) ? "實際匯入圖面" : "使用者建立";
    const semanticStatusLabel = zone.userSemanticConfirmed ? "已由使用者確認" : "用途待確認";
    const typeLabel = zone.type === "other" && !zone.userSemanticConfirmed ? "待確認" : getZoneTypeLabel(zone.type);
    const pendingSemanticType = zone.userSemanticConfirmed ? "" : String(zone.pendingSemanticType || "");
    const pendingSemanticLabel = pendingSemanticType ? getZoneTypeLabel(pendingSemanticType) : "尚未選擇";
    const boundaryDraft = getZoneBoundaryState();
    const isEditingBoundary = uiState.mode === "edit-zone-boundary" && boundaryDraft.activeZoneId === zone.id;
    const displayEdgeIds = isEditingBoundary ? boundaryDraft.selectedBoundaryEdgeIds : zone.boundaryEdgeIds;
    const displayDraft = isEditingBoundary ? boundaryDraft : createZoneBoundaryDraft(zone.boundaryEdgeIds || []);
    const boundaryStatus = isEditingBoundary ? "editing" : getZoneBoundaryStatus(zone, displayDraft);
    const boundaryIssues = isEditingBoundary ? displayDraft.issues : zone.boundaryIssues || displayDraft.issues;
    const polygon = isEditingBoundary ? displayDraft.previewPolygon : zone.polygon;
    const issueText = boundaryIssues.length
      ? '<div class="issue-list">' + boundaryIssues.map(renderZoneBoundaryIssue).join("") + '</div>'
      : '<div class="inline-message">空間邊界已整理為草稿，請確認後再作後續依據。</div>';
    const dimensionDisabled = selectedScaleDisabledAttribute();
    const areaReview = getZoneAreaReview(zone, polygon, boundaryStatus);
    const areaDisplay = areaReview.confirmed
      ? areaReview.confirmedLabel
      : (areaReview.candidateLabel ? "待確認（候選 " + areaReview.candidateLabel + "）" : areaReview.blockerLabel);
    return [
      '<form class="inspector-form" aria-label="選取空間標籤屬性">',
      '<div class="status-card selected-object-card" data-testid="selected-zone-card">',
      '<b>' + (isExistingPdfObject(zone) ? '既有空間候選' : '空間標籤') + '</b>',
      '<div class="status-grid">',
      '<div class="status-row"><span>名稱</span><span>' + escapeHTML(zoneDisplayName) + '</span></div>',
      '<div class="status-row"><span>類型</span><span>' + escapeHTML(typeLabel) + '</span></div>',
      '<div class="status-row"><span>來源</span><span>' + escapeHTML(sourceLabel) + '</span></div>',
      '<div class="status-row"><span>語意狀態</span><span>' + escapeHTML(semanticStatusLabel) + '</span></div>',
      '<div class="status-row"><span>邊界線段</span><span>' + displayEdgeIds.length + '</span></div>',
      '<div class="status-row"><span>邊界牆線</span><span>' + zone.boundaryWallIds.length + '</span></div>',
      '<div class="status-row"><span>範圍節點</span><span>' + polygon.length + '</span></div>',
      '<div class="status-row"><span>邊界狀態</span><span>' + escapeHTML(getZoneBoundaryStatusLabel(boundaryStatus)) + '</span></div>',
      '<div class="status-row"><span>面積</span><span>' + escapeHTML(areaDisplay) + '</span></div>',
      '</div></div>',
      '<div class="field-grid">',
      '<div class="field-row full"><label for="selected-zone-name">名稱</label><input id="selected-zone-name" data-field="selected-zone-name" type="text" value="' + escapeAttribute(zone.name) + '"></div>',
      '<div class="field-row full"><label for="selected-zone-type">空間用途</label><select id="selected-zone-type" data-field="selected-zone-type">' + renderZoneTypeOptions(zone.userSemanticConfirmed ? zone.type : pendingSemanticType, { includePending: !zone.userSemanticConfirmed }) + '</select></div>',
      '<div class="field-row"><label for="selected-zone-x">標籤 X</label><input id="selected-zone-x" data-field="selected-zone-x" type="number" min="0" step="1" value="' + zone.labelPosition.x + '"' + dimensionDisabled + '></div>',
      '<div class="field-row"><label for="selected-zone-y">標籤 Y</label><input id="selected-zone-y" data-field="selected-zone-y" type="number" min="0" step="1" value="' + zone.labelPosition.y + '"' + dimensionDisabled + '></div>',
      '</div>',
      '<div class="status-card" aria-label="空間用途確認"><b>空間用途確認</b><div class="status-grid">',
      '<div class="status-row"><span>目前選擇</span><span>' + escapeHTML(zone.userSemanticConfirmed ? getZoneTypeLabel(zone.type) : pendingSemanticLabel) + '</span></div>',
      '<div class="status-row"><span>確認狀態</span><span>' + escapeHTML(zone.userSemanticConfirmed ? "已確認" : "等待使用者確認") + '</span></div>',
      '</div><div class="inspector-compact-note">選擇用途只會暫存；按下確認後，才會列入已確認空間並留下案件紀錄。</div>',
      '<div class="inspector-actions" style="margin-top:10px"><button class="toolbar-btn primary" type="button" data-action="confirm-zone-semantic" ' + (zone.userSemanticConfirmed || !pendingSemanticType ? 'disabled' : '') + '>' + (zone.userSemanticConfirmed ? '用途已確認' : '確認空間用途') + '</button></div></div>',
      renderSelectedScaleNotice(),
      '<div class="status-card" aria-label="空間面積確認"><b>空間面積確認</b><div class="status-grid">',
      '<div class="status-row"><span>計算依據</span><span>' + escapeHTML(areaReview.basisLabel) + '</span></div>',
      '<div class="status-row"><span>候選面積</span><span>' + escapeHTML(areaReview.candidateLabel || areaReview.blockerLabel) + '</span></div>',
      '<div class="status-row"><span>確認狀態</span><span>' + escapeHTML(areaReview.confirmed ? '已確認' : '等待使用者確認') + '</span></div>',
      '</div><div class="inspector-compact-note">面積由已確認比例與封閉邊界計算；按下確認後，才會列入可追溯的空間數量依據。</div>',
      '<div class="inspector-actions" style="margin-top:10px"><button class="toolbar-btn primary" type="button" data-action="confirm-zone-area" ' + (areaReview.canConfirm ? '' : 'disabled') + '>' + (areaReview.confirmed ? '面積已確認' : '確認空間面積') + '</button></div></div>',
      '<div class="project-readout">用途與面積分開確認；未確認的候選值不會被當成正式空間數量。</div>',
      '<div class="status-card"><b>邊界工具</b><div class="status-grid">',
      '<div class="status-row"><span>模式</span><span>' + (isEditingBoundary ? '編輯中' : '已保存') + '</span></div>',
      '<div class="status-row"><span>已選線段</span><span>' + displayEdgeIds.length + '</span></div>',
      '<div class="status-row"><span>參照牆線</span><span>' + zone.boundaryWallIds.length + '</span></div>',
      '<div class="status-row"><span>節點</span><span>' + polygon.length + '</span></div>',
      '</div><div class="inspector-actions" style="margin-top: 12px;">',
      '<button class="secondary-btn" type="button" data-action="start-zone-boundary">編輯邊界</button>',
      '<button class="toolbar-btn primary" type="button" data-action="apply-zone-boundary" ' + (isEditingBoundary ? '' : 'disabled') + '>套用邊界</button>',
      '<button class="secondary-btn" type="button" data-action="clear-zone-boundary">清除邊界</button>',
      '</div>' + issueText + '</div>',
      '<div class="inspector-actions"><button class="danger-btn" type="button" data-action="delete-zone">刪除空間標籤</button><button class="secondary-btn" type="button" data-action="clear-selection">清除選取</button></div>',
      '</form>'
    ].join("");
  }

  function renderZoneReviewSelectorCard() {
    if (!project.zones.length) {
      return "";
    }
    const counts = getZoneReviewCounts();
    const selectedId = getSelectedZone()?.id || "";
    const promptOption = '<option value="" disabled' + (selectedId ? '' : ' selected') + '>請選擇來源空間</option>';
    const options = project.zones.map((zone) => {
      const semantic = zone.userSemanticConfirmed ? getZoneTypeLabel(zone.type) : "用途待確認";
      return '<option value="' + escapeAttribute(zone.id) + '"' + (zone.id === selectedId ? ' selected' : '') + '>' + escapeHTML(getZoneReviewLabel(zone) + '｜' + semantic) + '</option>';
    }).join("");
    return [
      '<section class="status-card" aria-label="來源空間核對">',
      '<b>來源空間核對</b>',
      '<div class="status-grid">',
      '<div class="status-row"><span>來源候選</span><span>' + counts.sourceCandidates + ' 筆</span></div>',
      '<div class="status-row"><span>已確認空間</span><span>' + counts.confirmed + ' 間</span></div>',
      counts.userDrafts ? '<div class="status-row"><span>使用者草稿</span><span>' + counts.userDrafts + ' 筆</span></div>' : '',
      '</div>',
      '<div class="field-row full" style="margin-top:10px"><label for="zone-review-select">選取空間</label><select id="zone-review-select" data-field="zone-review-select">' + promptOption + options + '</select></div>',
      '<div class="inspector-compact-note">候選僅代表來源圖面中可核對的封閉範圍；完成用途確認後，才列入已確認空間。</div>',
      '</section>'
    ].join("");
  }

  function renderOpeningSwingOptions(currentValue) {
    const value = String(currentValue || "left");
    const options = [
      ["left", "左開"],
      ["right", "右開"],
      ["inward", "向內開"],
      ["outward", "向外開"],
      ["sliding", "橫拉"],
      ["fixed", "固定"],
      ["awning", "推射"],
      ["louver", "百葉"],
      ["transom", "橫氣窗"],
      ["none", "無開啟方向"]
    ];
    return options.map(([optionValue, label]) =>
      '<option value="' + escapeAttribute(optionValue) + '"' + (optionValue === value ? ' selected' : '') + '>' + escapeHTML(label) + '</option>'
    ).join("");
  }

  function renderSelectedOpeningCard(opening) {
    const edge = getEdgeById(opening.edgeId);
    const validation = edge ? validateOpening(opening, edge) : { valid: false, error: "Opening has no host wall edge." };
    const sourceWallName = opening.sourceWallId ? getWallDisplayName(opening.sourceWallId) : "-";
    const kind = normalizeOpeningKind(opening.kind);
    const openingLabel = getOpeningHumanLabel(opening);
    const typeFieldLabel = kind === "door" ? "門的類型" : kind === "window" ? "窗的類型" : "開口類型";
    const canonicalWallPositionMm = getOpeningCanonicalWallPositionMm(opening);
    const canonicalWallLengthMm = Number(opening?.pdfCanonicalHostBinding?.sourceWallLengthMm);
    const offsetMax = Number.isFinite(canonicalWallLengthMm)
      ? Math.max(0, Math.round(canonicalWallLengthMm - Number(opening.width || 0)))
      : (edge ? Math.max(0, Math.round(edge.length - Number(opening.width || 0))) : 0);
    const openingTypeHumanLabel = getOpeningTypeLabel(kind, opening.openingType);
    const sourceReviewConfirmed = opening.sourceReviewStatus === "confirmed";
    const reviewStatus = sourceReviewConfirmed ? "位置已確認" : "草稿待確認";
    const typeOptions = renderOpeningTypeOptions(kind, opening.openingType || opening.doorSubtype || opening.windowType);
    const dimensionDisabled = selectedScaleDisabledAttribute();
    return [
      '<form class="inspector-form" aria-label="選取門窗開口屬性">',
      '<div class="status-card selected-object-card" data-testid="selected-opening-card">',
      '<b>' + escapeHTML(openingLabel) + '</b>',
      '<div class="status-grid">',
      '<div class="status-row"><span>種類</span><span>' + escapeHTML(getExternalItemDisplayLabel(kind)) + '</span></div>',
      '<div class="status-row"><span>類型</span><span>' + escapeHTML(openingTypeHumanLabel) + '</span></div>',
      '<div class="status-row"><span>所屬牆線</span><span>' + escapeHTML(sourceWallName) + '</span></div>',
      '<div class="status-row"><span>沿來源牆線位置</span><span>' + escapeHTML(selectedPhysicalDimension(canonicalWallPositionMm)) + '</span></div>',
      '<div class="status-row"><span>寬度</span><span>' + escapeHTML(selectedPhysicalDimension(opening.width)) + '</span></div>',
      '<div class="status-row"><span>開啟方式</span><span>' + escapeHTML(kind === "window" ? getWindowOpeningModeLabel(opening.openingMode || opening.swing) : getOpeningSwingLabel(opening.swing || opening.openingMode)) + '</span></div>',
      '<div class="status-row"><span>審核</span><span>' + escapeHTML(reviewStatus) + '</span></div>',
      '<div class="status-row"><span>檢查結果</span><span>' + (validation.valid ? '通過' : '需人工確認') + '</span></div>',
      '</div></div>',
      '<div class="field-grid">',
      '<div class="field-row full"><label for="selected-opening-type">' + escapeHTML(typeFieldLabel) + '</label><select id="selected-opening-type" data-field="selected-opening-type">' + typeOptions + '</select></div>',
      '<div class="field-row"><label for="selected-opening-offset">沿來源牆線位置（mm）</label><input id="selected-opening-offset" data-field="selected-opening-offset" type="number" min="0" max="' + offsetMax + '" step="1" value="' + Math.round(canonicalWallPositionMm) + '"' + dimensionDisabled + '></div>',
      '<div class="field-row"><label for="selected-opening-width">寬度（mm）</label><input id="selected-opening-width" data-field="selected-opening-width" type="number" min="100" step="1" value="' + Math.round(opening.width || 0) + '"' + dimensionDisabled + '></div>',
      '<div class="field-row"><label for="selected-opening-swing">開啟方式</label><select id="selected-opening-swing" data-field="selected-opening-swing">' + renderOpeningSwingOptions(opening.swing || opening.openingMode) + '</select></div>',
      '<div class="field-row"><label for="selected-opening-sill-height">窗台高度（mm）</label><input id="selected-opening-sill-height" data-field="selected-opening-sill-height" type="number" min="0" step="1" value="' + Math.round(opening.sillHeight || 0) + '"' + dimensionDisabled + '></div>',
      '<div class="field-row"><label for="selected-opening-height">高度（mm）</label><input id="selected-opening-height" data-field="selected-opening-height" type="number" min="0" step="1" value="' + Math.round(opening.height || 0) + '"' + dimensionDisabled + '></div>',
      '</div>',
      renderSelectedScaleNotice(),
      '<div class="project-readout">' + (sourceReviewConfirmed
        ? '此門窗的位置、類型與尺寸已確認並寫入案件紀錄；後續修改會重新待確認並保留變更紀錄。'
        : '請核對門窗開口的類型、寬度、位置與所屬牆線，確認後會寫入案件紀錄。') + '</div>',
      isPdfDerivedExistingObject(opening) && !sourceReviewConfirmed
        ? '<div class="inspector-actions"><button class="primary-btn" type="button" data-action="confirm-native-pdf-opening-review"' + (selectedScaleAccepted() ? '' : ' disabled') + '>確認此門窗位置、類型與尺寸</button></div>'
        : '',
      kind === "door" ? '<div class="inspector-actions"><button class="secondary-btn" type="button" data-action="mirror-opening-horizontal" aria-pressed="' + (opening.mirrorX ? 'true' : 'false') + '">左右鏡射</button><button class="secondary-btn" type="button" data-action="mirror-opening-vertical" aria-pressed="' + (opening.mirrorY ? 'true' : 'false') + '">上下鏡射</button></div>' : '',
      '<div class="inspector-actions"><button class="danger-btn" type="button" data-action="delete-opening">刪除開口</button><button class="secondary-btn" type="button" data-action="clear-selection">清除選取</button></div>',
      '</form>'
    ].join("");
  }

  function renderSelectedFurnitureCard(item) {
    const template = getFurnitureTemplate(item.type || item.subtype || item.category);
    const advice = getFurnitureHelperAdvice(item, "select");
    const material = item.materialTags?.[0] || uiState.currentFurnitureMaterialTag || "unspecified";
    const resizeLocked = !isFurnitureResizable(item);
    const lengthOnlyResize = isFixedFurnitureLengthResizeOnly(item);
    const dimensionDisabled = selectedScaleDisabledAttribute();
    const depthLocked = resizeLocked || lengthOnlyResize;
    const resizeStatus = resizeLocked ? '尺寸固定' : (lengthOnlyResize ? '可調整長度，深度固定' : '可調整尺寸');
    const sourceStatusRows = isExistingPdfObject(item)
      ? '<div class="status-row"><span>來源</span><span>實際匯入圖面</span></div>' +
        '<div class="status-row"><span>辨識狀態</span><span>設備候選，待使用者確認</span></div>' +
        '<div class="status-row"><span>預算狀態</span><span>尚未納入</span></div>'
      : '';
    const materialButtons = FURNITURE_MATERIAL_TAGS.map((tag) =>
      '<button class="secondary-btn" type="button" data-action="apply-furniture-material" data-material-tag="' + escapeAttribute(tag) + '">' + escapeHTML(getFurnitureMaterialLabel(tag)) + '</button>'
    ).join("");
    return [
      '<form class="inspector-form" aria-label="選取家具與設備屬性">',
      '<div class="status-card selected-object-card" data-testid="selected-furniture-card">',
      '<b>' + escapeHTML(getExternalFurnitureDisplayName(item, template)) + '</b>',
      '<div class="status-grid">',
      '<div class="status-row"><span>分類</span><span>' + escapeHTML(getFurnitureCategoryLabel(item.category)) + '</span></div>',
      '<div class="status-row"><span>類型</span><span>' + escapeHTML(getFurnitureTypeLabel(item.type || item.subtype)) + '</span></div>',
      '<div class="status-row"><span>尺寸</span><span>' + (selectedScaleAccepted() ? formatNumber(item.widthMm) + ' x ' + formatNumber(item.depthMm) + ' x ' + formatNumber(item.heightMm || 0) + ' mm' : '比例尚未確認') + '</span></div>',
      '<div class="status-row"><span>旋轉</span><span>' + formatNumber(item.rotation || 0) + ' 度</span></div>',
      '<div class="status-row"><span>材料</span><span>' + escapeHTML(getFurnitureMaterialLabel(material)) + '</span></div>',
      '<div class="status-row"><span>尺寸調整</span><span>' + resizeStatus + '</span></div>',
      sourceStatusRows,
      '<div class="status-row"><span>草稿狀態</span><span>需人工確認後才能作正式依據</span></div>',
      '</div></div>',
      '<div class="field-grid">',
      '<div class="field-row full"><label for="selected-furniture-name">名稱</label><input id="selected-furniture-name" data-field="selected-furniture-name" type="text" value="' + escapeAttribute(item.name || item.label || '') + '"></div>',
      '<div class="field-row"><label for="selected-furniture-x">X</label><input id="selected-furniture-x" data-field="selected-furniture-x" type="number" step="1" value="' + Math.round(item.x || 0) + '"' + dimensionDisabled + '></div>',
      '<div class="field-row"><label for="selected-furniture-y">Y</label><input id="selected-furniture-y" data-field="selected-furniture-y" type="number" step="1" value="' + Math.round(item.y || 0) + '"' + dimensionDisabled + '></div>',
      '<div class="field-row"><label for="selected-furniture-width">寬度（mm）</label><input id="selected-furniture-width" data-field="selected-furniture-width" type="number" min="10" step="10" value="' + Math.round(item.widthMm || 0) + '"' + (resizeLocked ? ' disabled' : dimensionDisabled) + '></div>',
      '<div class="field-row"><label for="selected-furniture-depth">深度（mm）</label><input id="selected-furniture-depth" data-field="selected-furniture-depth" type="number" min="10" step="10" value="' + Math.round(item.depthMm || 0) + '"' + (depthLocked ? ' disabled' : dimensionDisabled) + '></div>',
      '<div class="field-row"><label for="selected-furniture-height">高度（mm）</label><input id="selected-furniture-height" data-field="selected-furniture-height" type="number" min="0" step="10" value="' + Math.round(item.heightMm || 0) + '"' + dimensionDisabled + '></div>',
      '<div class="field-row"><label for="selected-furniture-rotation">旋轉角度</label><input id="selected-furniture-rotation" data-field="selected-furniture-rotation" type="number" step="15" value="' + Math.round(item.rotation || 0) + '"></div>',
      '<div class="field-row full"><label for="selected-furniture-material">材料</label><select id="selected-furniture-material" data-field="selected-furniture-material">' + renderFurnitureMaterialOptions(material, item) + '</select></div>',
      '<div class="field-row full"><label for="selected-furniture-note">備註</label><input id="selected-furniture-note" data-field="selected-furniture-note" type="text" value="' + escapeAttribute(item.note || '') + '" placeholder="補充物件需求或待確認事項"></div>',
      '</div>',
      renderSelectedScaleNotice(),
      '<div class="project-readout">' + escapeHTML(advice.actionText + ' ' + advice.limitText + ' ' + advice.extra) + '</div>',
      '<div class="inspector-actions">' + materialButtons + '<button class="danger-btn" type="button" data-action="delete-furniture">刪除物件</button></div>',
      '</form>'
    ].join("");
  }

  function renderOpeningKindOption(value, currentValue) {
    return '<option value="' + escapeAttribute(value) + '"' + (value === currentValue ? " selected" : "") + '>' + escapeHTML(getOpeningKindLabel(value)) + '</option>';
  }

  function renderOpeningTypeOptions(kind, currentValue) {
    const normalizedKind = normalizeOpeningKind(kind);
    const normalizedType = normalizeOpeningType(normalizedKind, currentValue);
    return getOpeningTypeOptions(normalizedKind).map((option) => (
      '<option value="' + escapeAttribute(option.value) + '"' + (option.value === normalizedType ? " selected" : "") + '>' + escapeHTML(option.label) + '</option>'
    )).join("");
  }

  function renderSwingOption(value, currentValue) {
    return '<option value="' + escapeAttribute(value) + '"' + (value === currentValue ? " selected" : "") + '>' + escapeHTML(getOpeningSwingLabel(value)) + '</option>';
  }

  function renderZoneTypeOptions(currentValue, options = {}) {
    const pendingOption = options.includePending
      ? '<option value="" disabled' + (currentValue ? '' : ' selected') + '>請選擇空間用途</option>'
      : '';
    return pendingOption + Object.entries(ZONE_TYPE_LABELS).map(([value, label]) => (
      '<option value="' + escapeAttribute(value) + '"' + (value === currentValue ? " selected" : "") + '>' + escapeHTML(getExternalItemDisplayLabel(value)) + '</option>'
    )).join("");
  }

  function renderStatusOption(value, currentValue) {
    return '<option value="' + escapeAttribute(value) + '"' + (value === currentValue ? " selected" : "") + '>' + escapeHTML(getWallStatusLabel(value)) + '</option>';
  }

  function renderLayerVisibilityCard() {
    const rows = [
      ["underlay", "參考底圖", "匯入的底圖或空白格線"],
      ["walls", "牆線與牆面標記", "牆的線條與標記"],
      ["openings", "門、窗、開口", "門、窗與通行開口"],
      ["structures", "柱與梁", "柱與梁的線條輪廓"],
      ["review", "尺寸標註", "尺寸數字、標註線與引線參考"],
      ["zones", "空間名稱", "空間名稱與範圍"],
      ["furniture", "家具與設備", "家具、櫃體、廚具與衛浴設備"],
      ["diagnostics", "輔助線", "輔助對位參考線"]
    ];
    return '<section class="status-card" aria-label="顯示內容"><b>顯示內容</b><div class="draft-list">' + rows.map(([key, label, hint]) => {
      const checked = uiState.layerVisibility[key] !== false;
      return '<label class="toggle-row" for="layer-visibility-' + key + '"><span><b>' + escapeHTML(label) + '</b><br><small>' + escapeHTML(hint) + '</small></span><input id="layer-visibility-' + key + '" data-field="layer-visibility-' + key + '" type="checkbox"' + (checked ? ' checked' : '') + '></label>';
    }).join("") + '</div></section>';
  }

  function getUnderlayStatusLabel() {
    if (!project.importSource) {
      return "尚未載入";
    }
    const visibility = { ...createInitialLayerVisibility(), ...uiState.layerVisibility };
    if (project.underlay && !visibility.underlay) {
      return "參考已保留（未顯示）";
    }
    return "已載入";
  }

  function renderImportSourceCard() {
    const loaded = Boolean(project.importSource);
    const visibility = { ...createInitialLayerVisibility(), ...uiState.layerVisibility };
    const hiddenReference = Boolean(loaded && project.underlay && !visibility.underlay);
    const statusText = hiddenReference
      ? "原始圖面參考已保留，可需要時開啟對照"
      : (loaded ? "已載入底圖" : "尚未載入底圖");
    return [
      '<div class="status-card">',
      '<b>底圖來源</b>',
      '<div class="status-grid">',
      '<div class="status-row"><span>狀態</span><span>' + statusText + '</span></div>',
      '</div></div>'
    ].join("");
  }

  function renderUnderlayControls() {
    if (!project.underlay) {
      return "";
    }
    return [
      '<div class="status-card">',
      '<b>底圖</b>',
      '<div class="range-row">',
      '<label for="underlay-opacity">底圖透明度 <span id="opacityValue">' + Math.round(project.underlay.opacity * 100) + '%</span></label>',
      '<input id="underlay-opacity" data-field="underlay-opacity" type="range" min="' + MIN_UNDERLAY_OPACITY + '" max="' + MAX_UNDERLAY_OPACITY + '" step="0.01" value="' + project.underlay.opacity + '">',
      '</div>',
      '<div class="inspector-actions" style="margin-top: 12px;"><button type="button" data-action="remove-underlay-reference">移除原始圖面（只留物件）</button></div>',
      '<div class="inspector-compact-note">物件整理完成後可移除原始圖面，圖面只保留可編輯物件；此操作可用復原取回。</div>',
      '<div class="inspector-actions" style="margin-top: 12px;"><button class="danger-btn" type="button" data-action="reset-project">重設草稿</button></div>',
      '</div>'
    ].join("");
  }

  function renderAutoScaleSuggestionCard() {
    if (!project.underlay || !project.importSource?.previewSupported || isR6ReviewActive() || isR4B1ReviewActive()) {
      return "";
    }
    const suggestion = project.scale?.autoScaleSuggestion;
    if (!suggestion) {
      return '<div class="inline-message">目前沒有可靠的自動尺寸依據，請使用兩點校正。</div>';
    }
    const statusText = suggestion.canApply ? '已找到檔名尺寸線索，仍需兩點校正確認' : '請使用兩點校正';
    return [
      '<div class="inline-message"><strong>比例建議</strong>',
      '<div class="status-grid" style="margin-top: 8px;">',
      '<div class="status-row"><span>狀態</span><span>' + statusText + '</span></div>',
      '<div class="status-row"><span>依據</span><span>' + escapeHTML(suggestion.sourceLabel) + '</span></div>',
      '<div class="status-row"><span>圖面尺寸</span><span>' + (suggestion.imageWidthPx || '-') + ' x ' + (suggestion.imageHeightPx || '-') + ' px</span></div>',
      '<div class="status-row"><span>已知長度</span><span>' + (suggestion.knownLengthMm ? formatNumber(suggestion.knownLengthMm) + ' mm' : '-') + '</span></div>',
      '<div class="status-row"><span>比例</span><span>' + (suggestion.pxPerMm ? formatNumber(suggestion.pxPerMm) + ' px / mm' : '-') + '</span></div>',
      '</div></div>'
    ].join("");
  }

  function renderScaleCard() {
    if (isR6ReviewActive() || isR4B1ReviewActive()) return "";
    const workflow = derivePlanWorkflowState();
    const calibratedBy = workflow.scaleAccepted ? project.underlay?.calibratedBy : null;
    const pointCount = uiState.mode === "calibrate" ? uiState.calibrationPoints.length : getCalibrationPointsForRender().length;
    const scaleMeasurementText = workflow.scaleAccepted ? getScaleMeasurementText() : workflow.scaleLabel;
    const calibrationPointText = pointCount === 0 ? "尚未標記校正點" : Math.min(pointCount, 2) + " / 2";
    const manualControls = workflow.showManualFallback
      ? '<div class="field-row full" style="margin-top: 14px;"><label for="known-length">已知長度（毫米）</label><input id="known-length" data-field="known-length" type="number" min="1" step="1" value="' + escapeAttribute(uiState.knownLengthInput) + '" placeholder="例如 3000"></div><div class="inspector-actions" style="margin-top: 12px;"><button class="toolbar-btn primary" type="button" data-action="start-calibration">使用兩點校正</button></div>'
      : '';
    return [
      '<div class="status-card">',
      '<b>比例</b>',
      '<div class="status-grid">',
      '<div class="status-row"><span>狀態</span><span>' + escapeHTML(workflow.scaleLabel) + '</span></div>',
      workflow.scaleAccepted ? '<div class="status-row"><span>畫布比例</span><span>' + escapeHTML(getScaleMeasurementText()) + '</span></div>' : '',
      '<div class="status-row"><span>校正點</span><span>' + calibrationPointText + '</span></div>',
      '<div class="status-row"><span>校正讀值</span><span>' + escapeHTML(scaleMeasurementText) + '</span></div>',
      calibratedBy ? '<div class="status-row"><span>校正紀錄</span><span>' + formatNumber(calibratedBy.knownLength) + ' mm = ' + formatNumber(calibratedBy.pixelDistance) + ' px</span></div>' : '',
      '</div>',
      manualControls,
      '</div>'
    ].join("");
  }

  function visibleSourceRegionLabel(sourceRegionId) {
    const value = String(sourceRegionId || "").toLowerCase();
    if (value.endsWith("region-3f")) return "3 樓區域";
    if (value.endsWith("region-rf")) return "頂樓區域";
    return "來源區域待確認";
  }

  function visibleSourceObjectLabel(record) {
    const category = String(record?.category || "");
    const subtype = String(record?.subtype || record?.sourceSubtype || "");
    const labels = {
      wall: "牆體",
      opening: subtype === "window" ? "窗戶" : subtype === "door" ? "門" : "門窗開口",
      window: "窗戶",
      door: "門",
      stair: "樓梯",
      stairVoid: "樓梯開口",
      spaceBoundary: "空間邊界",
      space: "空間",
      column: "柱體"
    };
    return labels[category] || labels[subtype] || "既有物件";
  }

  function renderR7DimensionReviewPanel(review) {
    const evidence = r7DimensionEvidence(review) || review.dimensionScaleEvidence || {};
    const consensus = evidence.consensus || {};
    const workflow = derivePlanWorkflowState();
    const ready = workflow.showUnitConfirmation;
    const accepted = workflow.scaleAccepted;
    const records = review.records || [];
    const confirmed = records.filter((record) => record.userDecision === "confirmed_pending_calibration" || record.userDecision === "accepted_existing_object_review").length;
    const rejected = records.filter((record) => record.userDecision === "rejected").length;
    const rows = records.map((record) => {
      const pending = record.userDecision === "pending";
      const status = record.userDecision === "rejected" ? "已駁回" : record.userDecision === "confirmed_pending_calibration" ? "待比例確認" : record.userDecision === "accepted_existing_object_review" ? "可進入編輯審查" : "待確認";
      const canPromote = r6CanPromoteNativeCandidate(record);
      const actions = pending
        ? '<button class="secondary-btn" type="button" data-action="r6-confirm-record" data-source-id="' + escapeAttribute(record.sourceId) + '">確認為既有物件</button><button class="secondary-btn" type="button" data-action="r6-reject-record" data-source-id="' + escapeAttribute(record.sourceId) + '">不採用</button>'
        : (canPromote
          ? '<button class="toolbar-btn primary" type="button" data-action="r6-promote-native-candidate" data-source-id="' + escapeAttribute(record.sourceId) + '">建立可編輯既有物件</button>'
          : '<button class="secondary-btn" type="button" data-action="r6-open-record" data-source-id="' + escapeAttribute(record.sourceId) + '">查看處理</button>');
      return '<div class="r4b1-review-row"><div class="r4b1-review-main"><strong>' + escapeHTML(visibleSourceObjectLabel(record)) + '</strong><span>' + escapeHTML(visibleSourceRegionLabel(record.sourceRegionId)) + ' ・ ' + escapeHTML(status) + '</span><small>確認後仍屬既有物件，不會建立預算或規格項目。</small></div><div class="r4b1-review-action">' + actions + '</div></div>';
    }).join("");
    const scaleStatus = workflow.scaleLabel;
    const manualCalibrationSelection = review.calibrationSelection || createR6CalibrationSelection();
    const manualCalibrationReceipt = review.calibrationReceipt || null;
    const manualCalibrationActive = Boolean(manualCalibrationReceipt || manualCalibrationSelection.points.length === 2);
    const manualCapturedPointText = manualCalibrationSelection.points.length
      ? manualCalibrationSelection.points.map((point, index) => "端點 " + String(index + 1) + "（" + formatNumber(point.x) + "，" + formatNumber(point.y) + "）").join("；")
      : "尚未在畫布上選取端點";
    const manualCalibrationStatus = r6CalibrationStatusLabel(manualCalibrationSelection, manualCalibrationReceipt);
    const manualCalibrationUi = manualCalibrationReceipt
      ? '<div class="r4b1-scale-note">目前狀態：' + escapeHTML(manualCalibrationStatus) + '</div><div class="inspector-compact-note">畫布端點：' + escapeHTML(manualCapturedPointText) + '</div>' + (manualCalibrationReceipt.status === "submitted_for_acceptance" ? '<div class="inspector-actions"><button class="toolbar-btn primary" type="button" data-action="r6-accept-calibration">接受比例校正</button></div>' : '')
      : '<div class="r4b1-scale-note">目前狀態：' + escapeHTML(manualCalibrationStatus) + '</div><div class="inspector-compact-note">畫布端點：' + escapeHTML(manualCapturedPointText) + '</div><div class="inspector-actions"><button class="secondary-btn" type="button" data-action="r6-start-canvas-calibration">重新在畫布選取兩點</button></div><div class="r4b1-calibration-grid"><label>實際長度<input type="number" min="0.001" step="0.001" data-field="r6-known-length" placeholder="例如 525"></label><label>單位<select data-field="r6-unit"><option value="mm">毫米</option><option value="cm">公分</option><option value="m">公尺</option></select></label><label>操作人<input type="text" data-field="r6-calibration-actor" placeholder="例如 業主"></label><label>審閱人<input type="text" data-field="r6-calibration-reviewer" placeholder="例如 圖面審閱者"></label></div><div class="inspector-actions"><button class="toolbar-btn primary" type="button" data-action="r6-submit-calibration">送出比例校正</button></div>';
    const calibration = accepted
      ? '<div class="r4b1-scale-note">比例已確認。下一步由案件負責人逐一核對牆體、門窗與空間；樓梯保留為圖面線條。</div>'
      : manualCalibrationActive
        ? manualCalibrationUi
        : ready
        ? '<div class="r4b1-calibration-grid"><label>尺寸單位<select data-field="r7-dimension-unit"><option value="mm" ' + (evidence.unitProposal?.unit === "mm" ? "selected" : "") + '>毫米</option><option value="cm" ' + (evidence.unitProposal?.unit === "cm" ? "selected" : "") + '>公分</option><option value="m" ' + (evidence.unitProposal?.unit === "m" ? "selected" : "") + '>公尺</option></select></label><label>提出人<input type="text" data-field="r7-dimension-actor" value="' + escapeAttribute(review.actorId || "") + '" placeholder="姓名或角色"></label><label>覆核人<input type="text" data-field="r7-dimension-reviewer" placeholder="姓名或角色"></label></div><div class="inspector-actions"><button class="toolbar-btn primary" type="button" data-action="r7-accept-dimension-scale">確認單位並套用比例</button></div>'
        : workflow.showManualFallback
          ? '<div class="inspector-actions"><button class="secondary-btn" type="button" data-action="r6-start-canvas-calibration">使用兩點校正</button></div>'
          : '<div class="r4b1-scale-note">正在整理尺寸依據，完成前不會要求套用比例。</div>';
    return '<section class="status-card r4b1-review-panel" data-testid="r7-dimension-review-queue" aria-label="既有物件審查"><div class="r4b1-panel-header"><div><b>既有物件審查</b><p>圖面已匯入；先依目前狀態確認比例，再逐一確認既有物件。</p></div><span class="r4b1-status-badge">' + escapeHTML(scaleStatus) + '</span></div><div class="r4b1-progress"><div><strong>' + Number(consensus.candidateCount || 0) + '</strong><span>尺寸配對</span></div><div><strong>' + confirmed + '</strong><span>已確認</span></div><div><strong>' + rejected + '</strong><span>未採用</span></div><div><strong>' + (review.uncertainRecords || []).length + '</strong><span>僅供參考</span></div></div><div class="r4b1-scale-note">目前比例：' + escapeHTML(workflow.scaleLabel) + '。下一步：' + escapeHTML(workflow.nextAction) + '。</div><details class="r4b1-calibration"><summary>查看尺寸依據</summary><div class="status-grid"><div class="status-row"><span>找到的尺寸配對</span><span>' + Number((evidence.pairs || []).length) + '</span></div><div class="status-row"><span>建議單位</span><span>' + escapeHTML(evidence.unitProposal?.unit || "尚未判定") + '</span></div><div class="status-row"><span>一致性</span><span>' + (consensus.pass ? "符合" : "待補足") + '</span></div></div></details>' + calibration + '<div class="r4b1-review-list">' + rows + '</div></section>';
  }

  function renderR6ReviewPanel() {
    if (!isR6ReviewActive()) return "";
    const review = project.r6Review;
    const workflow = derivePlanWorkflowState();
    if (workflow.key === "automatic_analysis_pending") {
      return '<section class="status-card r4b1-review-panel" aria-label="圖面尺寸分析"><div class="r4b1-panel-header"><div><b>圖面已匯入</b><p>正在整理尺寸依據，完成前不會套用比例或建立既有物件。</p></div><span class="r4b1-status-badge">正在分析</span></div></section>';
    }
    if (review.dimensionScaleEvidence) return renderR7DimensionReviewPanel(review);
    const records = review.records || [];
    const counts = records.reduce((out, record) => {
      out.total += 1;
      out[record.userDecision || "pending"] = (out[record.userDecision || "pending"] || 0) + 1;
      return out;
    }, { total: 0, pending: 0, confirmed_pending_calibration: 0, rejected: 0, accepted_existing_object_review: 0, manual_trace_draft: 0 });
    const categoryLabel = (record) => visibleSourceObjectLabel(record) + "候選";
    const decisionLabel = (record) => ({ pending: "等待審查", confirmed_pending_calibration: "已確認，等待比例", rejected: "已拒絕", manual_trace_draft: "已留下來源描繪", accepted_existing_object_review: "既有物件審查中" })[record.userDecision] || "等待審查";
    const rows = records.map((record) => {
      const action = record.userDecision === "pending"
        ? '<button class="secondary-btn" type="button" data-action="r6-confirm-record" data-source-id="' + escapeAttribute(record.sourceId) + '">確認候選</button><button class="secondary-btn" type="button" data-action="r6-reject-record" data-source-id="' + escapeAttribute(record.sourceId) + '">不採用</button>'
        : '<button class="secondary-btn" type="button" data-action="r6-open-record" data-source-id="' + escapeAttribute(record.sourceId) + '">查看處理方式</button>';
      return '<div class="r4b1-review-row"><div class="r4b1-review-main"><strong>' + escapeHTML(categoryLabel(record)) + '</strong><span>' + escapeHTML(visibleSourceRegionLabel(record.sourceRegionId)) + ' · ' + escapeHTML(decisionLabel(record)) + '</span><small>來源資料已保留，會在你的確認後才進入下一步。</small></div><div class="r4b1-review-action">' + action + '</div></div>';
    }).join("");
    const selected = r6SelectedRecord();
    const calibration = review.calibrationReceipt;
    const calibrationAccepted = workflow.scaleAccepted && calibration?.status === "accepted_for_existing_object_review";
    const calibrationSelection = review.calibrationSelection || createR6CalibrationSelection();
    const capturedPointText = calibrationSelection.points.length
      ? calibrationSelection.points.map((point, index) => "端點 " + String(index + 1) + "（" + formatNumber(point.x) + "，" + formatNumber(point.y) + "）").join("；")
      : "尚未在畫布上選取端點";
    const calibrationStatus = r6CalibrationStatusLabel(calibrationSelection, calibration);
    const calibrationUi = calibration
      ? '<div class="r4b1-scale-note">目前狀態：' + escapeHTML(calibrationStatus) + '</div><div class="inspector-compact-note">畫布端點：' + escapeHTML(capturedPointText) + '</div>' + (calibration.status === "submitted_for_acceptance" ? '<div class="inspector-actions"><button class="toolbar-btn primary" type="button" data-action="r6-accept-calibration">接受比例校正</button></div>' : '')
      : '<div class="r4b1-scale-note">目前狀態：' + escapeHTML(calibrationStatus) + '</div><div class="inspector-compact-note">畫布端點：' + escapeHTML(capturedPointText) + '</div><div class="inspector-actions"><button class="secondary-btn" type="button" data-action="r6-start-canvas-calibration">' + (calibrationSelection.points.length ? "重新在畫布選取兩點" : "在畫布選取兩點") + '</button></div><div class="r4b1-calibration-grid"><label>實際長度<input type="number" min="0.001" step="0.001" data-field="r6-known-length" placeholder="例如 300"></label><label>單位<select data-field="r6-unit"><option value="mm">毫米</option><option value="cm">公分</option><option value="m">公尺</option></select></label><label>操作人<input type="text" data-field="r6-calibration-actor" placeholder="例如 業主"></label><label>審閱人<input type="text" data-field="r6-calibration-reviewer" placeholder="例如 圖面審閱者"></label></div><div class="inspector-actions"><button class="toolbar-btn primary" type="button" data-action="r6-submit-calibration">送出比例校正</button></div>';
    const selectedUi = selected
      ? '<div class="r4b1-trace-editor"><div class="r4b1-detail-heading"><strong>' + escapeHTML(categoryLabel(selected)) + '</strong><span>' + escapeHTML(decisionLabel(selected)) + '</span></div><div class="inspector-compact-note">若來源線條仍需人工確認，請以圖面上的兩個端點留下來源局部描繪；此操作不會建立新的工程項目。</div><div class="r4b1-calibration-grid"><label>起點 X<input type="number" step="0.1" data-field="r6-trace-from-x" value="' + escapeAttribute(selected.trace?.from?.x ?? selected.sourceBBox?.[0] ?? 0) + '"></label><label>起點 Y<input type="number" step="0.1" data-field="r6-trace-from-y" value="' + escapeAttribute(selected.trace?.from?.y ?? selected.sourceBBox?.[1] ?? 0) + '"></label><label>終點 X<input type="number" step="0.1" data-field="r6-trace-to-x" value="' + escapeAttribute(selected.trace?.to?.x ?? selected.sourceBBox?.[2] ?? 0) + '"></label><label>終點 Y<input type="number" step="0.1" data-field="r6-trace-to-y" value="' + escapeAttribute(selected.trace?.to?.y ?? selected.sourceBBox?.[3] ?? 0) + '"></label></div><div class="inspector-actions"><button class="secondary-btn" type="button" data-action="r6-save-manual-trace" data-source-id="' + escapeAttribute(selected.sourceId) + '" ' + (selected.userDecision === "confirmed_pending_calibration" ? "" : "disabled") + '>保存來源描繪</button>' + (selected.trace && selected.category === "wall" && calibrationAccepted ? '<button class="toolbar-btn primary" type="button" data-action="r6-promote-manual-trace" data-source-id="' + escapeAttribute(selected.sourceId) + '">進入既有物件審查</button>' : '') + '</div></div>'
      : '';
    const wallSets = (review.wallBodyReviewSets || []).map((set) => '<div class="r4b1-review-row"><div class="r4b1-review-main"><strong>相連牆體審查組</strong><span>' + escapeHTML(visibleSourceRegionLabel(set.sourceRegionId)) + ' · ' + escapeHTML(set.decision === "user_reviewed_1_to_many" ? "已確認多對多關係" : "等待審查") + '</span><small>此組保留所有相連來源，不能以單一最近項目直接決定。</small></div><div class="r4b1-review-action">' + (set.decision === "pending_user_review" ? '<button class="secondary-btn" type="button" data-action="r6-review-wall-set" data-review-set-id="' + escapeAttribute(set.reviewSetId) + '" ' + (calibrationAccepted ? '' : 'disabled') + '>確認審查範圍</button>' : '<span class="r4b1-inline-state">已留下決定</span>') + '</div></div>').join("");
    return '<section class="status-card r4b1-review-panel" data-testid="r6-review-queue" aria-label="既有物件來源審查"><div class="r4b1-panel-header"><div><b>PDF 既有物件審查</b><p>先確認來源與比例，再逐筆決定保留、拒絕或人工描繪。</p></div><span class="r4b1-status-badge">' + escapeHTML(calibrationAccepted ? "可進入審查" : workflow.scaleLabel) + '</span></div><div class="r4b1-progress"><div><strong>' + counts.total + '</strong><span>待處理來源</span></div><div><strong>' + counts.confirmed_pending_calibration + '</strong><span>已確認</span></div><div><strong>' + counts.rejected + '</strong><span>不採用</span></div><div><strong>' + (review.uncertainRecords || []).length + '</strong><span>保留為證據</span></div></div><div class="r4b1-scale-note">自動判讀僅供整理；比例、審查與既有物件決定都必須由使用者明確完成。</div><div class="r4b1-review-list">' + rows + wallSets + '</div>' + selectedUi + '<details class="r4b1-calibration" open><summary>比例校正</summary>' + calibrationUi + '</details></section>';
  }

  function renderR4B1ReviewPanel() {
    if (!isR4B1ReviewActive()) {
      return "";
    }
    const review = project.r4b1Review;
    const counts = r4b1QueueCounts();
    const receipt = review.calibrationReceipt;
    const calibrated = derivePlanWorkflowState().scaleAccepted;
    const statusLabel = calibrated && receipt?.status === "accepted_for_promotion_review" ? "比例已接受，可逐筆進入升格審查" : receipt?.status === "pending_review" ? "等待指定審閱者接受比例" : "尚未完成比例校正";
    const selected = r4b1Record(uiState.r4b1SelectedSourceId);
    const selectedTrace = selected ? review.manualTraces[selected.sourceId] : null;
    const statusText = (record) => record.reviewStatus === "confirmed_for_review"
      ? "已確認候選"
      : record.reviewStatus === "source_local_draft" || record.reviewStatus === "source_local_draft_reviewed"
        ? "來源局部草稿"
        : record.reviewStatus === "evidence_only_review_requested"
          ? "已提出複核需求"
          : record.reviewStatus === "evidence_only"
            ? "僅保留證據"
            : record.disposition === "candidate_present_unaccepted" ? "待確認候選" : record.disposition === "missing_with_exact_reason" ? "待人工描繪" : "僅保留證據";
    const rows = (review.records || []).map((record) => {
      const isCandidate = record.disposition === "candidate_present_unaccepted";
      const isManual = record.disposition === "missing_with_exact_reason";
      const isUncertain = record.disposition === "ignored_uncertain";
    const action = isCandidate
        ? (record.reviewStatus === "confirmed_for_review" ? '<span class="r4b1-inline-state">已記錄，仍受比例鎖定</span>' : '<button class="secondary-btn" type="button" data-action="r4b1-confirm-candidate" data-source-id="' + escapeAttribute(record.sourceId) + '">確認候選</button>')
        : isManual
          ? '<button class="secondary-btn" type="button" data-action="r4b1-open-record" data-source-id="' + escapeAttribute(record.sourceId) + '">開啟來源描繪</button>'
          : (record.reviewStatus === "evidence_only_review_requested" ? '<span class="r4b1-inline-state">等待新證據</span>' : '<button class="secondary-btn" type="button" data-action="r4b1-request-uncertain-review" data-source-id="' + escapeAttribute(record.sourceId) + '">提出人工複核</button>');
      return '<div class="r4b1-review-row ' + (isUncertain ? 'is-uncertain' : '') + '"><div class="r4b1-review-main"><strong>' + escapeHTML(visibleSourceObjectLabel(record)) + '</strong><span>' + escapeHTML(visibleSourceRegionLabel(record.sourceRegionId)) + ' · ' + escapeHTML(statusText(record)) + '</span><small>來源記錄已綁定，請依圖面與證據確認</small></div><div class="r4b1-review-action">' + action + '</div></div>';
    }).join("");
    const traceEditor = selected && selected.disposition === "missing_with_exact_reason" ? [
      '<div class="r4b1-trace-editor">',
      '<div class="r4b1-detail-heading"><strong>來源局部描繪</strong><span>' + escapeHTML(visibleSourceObjectLabel(selected)) + '</span></div>',
      '<p class="inspector-compact-note">這是固定來源類別／子類別的局部草稿，不會走一般新增物件流程。</p>',
      '<div class="r4b1-field-grid">',
      '<label>起點 X<input type="number" step="0.1" data-field="r4b1-trace-from-x" value="' + escapeAttribute(selectedTrace?.geometry?.from?.x ?? selected.sourceBBox?.[0] ?? "") + '"></label>',
      '<label>起點 Y<input type="number" step="0.1" data-field="r4b1-trace-from-y" value="' + escapeAttribute(selectedTrace?.geometry?.from?.y ?? selected.sourceBBox?.[1] ?? "") + '"></label>',
      '<label>終點 X<input type="number" step="0.1" data-field="r4b1-trace-to-x" value="' + escapeAttribute(selectedTrace?.geometry?.to?.x ?? selected.sourceBBox?.[2] ?? "") + '"></label>',
      '<label>終點 Y<input type="number" step="0.1" data-field="r4b1-trace-to-y" value="' + escapeAttribute(selectedTrace?.geometry?.to?.y ?? selected.sourceBBox?.[3] ?? "") + '"></label>',
      '</div>',
      '<label class="r4b1-field-wide">描繪備註<textarea data-field="r4b1-trace-note" rows="2" placeholder="記錄你看到的來源線段或邊界">' + escapeHTML(selectedTrace?.note || uiState.r4b1TraceNote || "") + '</textarea></label>',
      '<div class="inspector-actions"><button class="toolbar-btn primary" type="button" data-action="r4b1-save-trace" data-source-id="' + escapeAttribute(selected.sourceId) + '">保存來源草稿</button>' + (selectedTrace ? '<button class="secondary-btn" type="button" data-action="r4b1-promote-trace" data-source-id="' + escapeAttribute(selected.sourceId) + '" ' + (calibrated ? '' : 'disabled') + '>進入既有物件審查</button>' : '') + '</div>',
      '</div>'
    ].join("") : "";
    return [
      '<section class="status-card r4b1-review-panel" data-testid="r4b1-review-queue" aria-label="來源審查與比例校正">',
      '<div class="r4b1-panel-header"><div><b>圖面審查與比例校正</b><p>先看來源、留下紀錄，再決定下一步；比例未接受前不會產生既有物件。</p></div><span class="r4b1-status-badge">' + escapeHTML(statusLabel) + '</span></div>',
      '<div class="r4b1-progress"><div><strong>' + counts.confirmed + ' / ' + counts.total + '</strong><span>已留下審查動作</span></div><div><strong>' + counts.candidate + '</strong><span>候選</span></div><div><strong>' + counts.manual + '</strong><span>待描繪</span></div><div><strong>' + counts.uncertain + '</strong><span>證據保留</span></div></div>',
      '<div class="r4b1-scale-note">比例來源：必須由使用者選兩點、輸入實際長度與單位。檔名、標註文字與自動建議只能參考。</div>',
      '<div class="r4b1-review-list">' + rows + '</div>',
      traceEditor,
      '<details class="r4b1-calibration" open><summary>比例校正收件</summary>',
      '<div class="r4b1-calibration-grid">',
      '<label>實際長度<input id="r4b1-known-length" data-field="known-length" type="number" min="0.001" step="0.001" value="' + escapeAttribute(uiState.knownLengthInput) + '" placeholder="例如 300"></label>',
      '<label>單位<select data-field="r4b1-calibration-unit"><option value="mm" ' + (uiState.calibrationUnit === "mm" ? 'selected' : '') + '>毫米</option><option value="cm" ' + (uiState.calibrationUnit === "cm" ? 'selected' : '') + '>公分</option><option value="m" ' + (uiState.calibrationUnit === "m" ? 'selected' : '') + '>公尺</option></select></label>',
      '<label>來源區域<select data-field="r4b1-calibration-region"><option value="page-1-region-3f" ' + (uiState.calibrationRegionId === "page-1-region-3f" ? 'selected' : '') + '>3F</option><option value="page-1-region-rf" ' + (uiState.calibrationRegionId === "page-1-region-rf" ? 'selected' : '') + '>RF</option></select></label>',
      '<label>案例代號<input data-field="r4b1-calibration-case" value="' + escapeAttribute(uiState.calibrationCaseId) + '"></label>',
      '<label>操作者<input data-field="r4b1-calibration-actor" value="' + escapeAttribute(uiState.calibrationActor) + '" placeholder="姓名或角色"></label>',
      '<label>審閱者<input data-field="r4b1-calibration-reviewer" value="' + escapeAttribute(uiState.calibrationReviewer) + '" placeholder="姓名或角色"></label>',
      '</div>',
      '<div class="r4b1-endpoint-status">校正端點：' + uiState.calibrationPoints.length + ' / 2</div>',
      '<div class="r4b1-endpoint-grid"><span>來源端點一</span><label>X<input type="number" step="0.1" data-field="r4b1-endpoint-from-x" value="' + escapeAttribute(uiState.calibrationPoints[0]?.x ?? selected?.sourceBBox?.[0] ?? "") + '"></label><label>Y<input type="number" step="0.1" data-field="r4b1-endpoint-from-y" value="' + escapeAttribute(uiState.calibrationPoints[0]?.y ?? selected?.sourceBBox?.[1] ?? "") + '"></label><span>來源端點二</span><label>X<input type="number" step="0.1" data-field="r4b1-endpoint-to-x" value="' + escapeAttribute(uiState.calibrationPoints[1]?.x ?? selected?.sourceBBox?.[2] ?? "") + '"></label><label>Y<input type="number" step="0.1" data-field="r4b1-endpoint-to-y" value="' + escapeAttribute(uiState.calibrationPoints[1]?.y ?? selected?.sourceBBox?.[3] ?? "") + '"></label></div>',
      '<div class="inspector-actions"><button class="secondary-btn" type="button" data-action="start-calibration">選取兩個端點</button><button class="toolbar-btn primary" type="button" data-action="r4b1-submit-calibration">送出校正資料</button><button class="secondary-btn" type="button" data-action="r4b1-accept-calibration" ' + (receipt?.status === "pending_review" ? '' : 'disabled') + '>接受校正紀錄</button></div>',
      receipt ? '<div class="r4b1-receipt-status">目前狀態：' + escapeHTML(receipt.status === "pending_review" ? "等待審閱者接受" : calibrated && receipt.status === "accepted_for_promotion_review" ? "已接受，可逐筆審查" : "比例資料待重新確認") + '</div>' : '<div class="r4b1-receipt-status">尚未送出校正資料</div>',
      '</details>',
      '<div class="r4b1-footer-actions"><button class="secondary-btn" type="button" data-action="r4b1-restore-session">還原本輪審查</button><span>每個動作都會留下案例紀錄；本輪不做自動升格。</span></div>',
      '</section>'
    ].join("");
  }

  function renderWallWorkflowCard() {
    return [
      '<div class="status-card"><b>畫牆流程</b><div class="status-grid">',
      '<div class="status-row"><span>模式</span><span>' + escapeHTML(getModeLabel(uiState.mode)) + '</span></div>',
      '<div class="status-row"><span>牆線</span><span>' + project.walls.length + '</span></div>',
      '<div class="status-row"><span>狀態</span><span>' + escapeHTML(getWallStatusLabel(uiState.currentWallStatus)) + '</span></div>',
      '<div class="status-row"><span>類型</span><span>' + escapeHTML(getWallTypeLabel(uiState.currentWallType)) + '</span></div>',
      '<div class="status-row"><span>厚度</span><span>' + uiState.currentWallThickness + ' mm</span></div>',
      '<div class="status-row"><span>吸附</span><span>' + (uiState.snapEnabled ? '開啟' : '關閉') + '</span></div>',
      '<div class="status-row"><span>正交</span><span>' + (uiState.orthogonalEnabled ? '開啟' : '關閉') + '</span></div>',
      '</div></div>'
    ].join("");
  }

  function renderZoneWorkflowCard() {
    return [
      '<div class="status-card"><b>空間標籤流程</b><div class="status-grid">',
      '<div class="status-row"><span>模式</span><span>' + escapeHTML(getModeLabel(uiState.mode)) + '</span></div>',
      '<div class="status-row"><span>空間</span><span>' + project.zones.length + '</span></div>',
      '<div class="status-row"><span>類型</span><span>' + escapeHTML(getZoneTypeLabel(uiState.currentZoneType)) + '</span></div>',
      '<div class="status-row"><span>名稱</span><span>' + escapeHTML(uiState.currentZoneName || ZONE_TYPE_LABELS[uiState.currentZoneType]) + '</span></div>',
      '<div class="status-row"><span>邊界</span><span>待確認</span></div>',
      '</div><div class="inspector-actions" style="margin-top: 12px;"><button class="secondary-btn" type="button" data-action="start-place-zone">放置空間標籤</button></div></div>'
    ].join("");
  }

  function renderFurnitureWorkflowCard() {
    const template = getFurnitureTemplate(uiState.currentFurnitureTemplateId);
    const sourceLabel = template.svgBlockCandidate ? "圖塊庫物件" : "內建物件";
    return [
      '<div class="status-card"><b>物件放置流程</b><div class="status-grid">',
      '<div class="status-row"><span>模式</span><span>' + escapeHTML(getModeLabel(uiState.mode)) + '</span></div>',
      '<div class="status-row"><span>樣板</span><span>' + escapeHTML(template.name || template.label || template.type) + '</span></div>',
      '<div class="status-row"><span>物件</span><span>' + project.furniture.length + '</span></div>',
      '<div class="status-row"><span>來源</span><span>' + escapeHTML(sourceLabel) + '</span></div>',
      '<div class="status-row"><span>狀態</span><span>待確認</span></div>',
      '</div><div class="inspector-actions" style="margin-top: 12px;"><button class="secondary-btn" type="button" data-action="start-place-furniture">放置物件</button></div></div>'
    ].join("");
  }

  function renderWallGraphCard() {
    const graph = project.wallGraph || createInitialWallGraph();
    const issues = graph.issues || [];
    const issueList = issues.length
      ? '<div class="issue-list">' + issues.map(renderIssueButton).join("") + '</div>'
      : '<div class="inline-message">目前牆線關係沒有待處理問題。</div>';
    return [
      '<div class="status-card">',
      '<b>牆線關係</b>',
      '<div class="status-grid">',
      '<div class="status-row"><span>牆線</span><span>' + project.walls.length + '</span></div>',
      '<div class="status-row"><span>節點</span><span>' + graph.nodes.length + '</span></div>',
      '<div class="status-row"><span>待處理</span><span>' + issues.length + '</span></div>',
      '<div class="status-row"><span>更新時間</span><span>' + (graph.lastBuiltAt ? escapeHTML(graph.lastBuiltAt) : '-') + '</span></div>',
      '</div>',
      '<div class="inspector-actions" style="margin-top: 12px;"><button class="secondary-btn" type="button" data-action="clean-wall-endpoints">整理牆線接點</button></div>',
      issueList,
      '</div>'
    ].join("");
  }

  function renderNodeGraphCard() {
    const graph = project.nodeGraph || createInitialNodeGraph();
    const intersectionCount = graph.nodes.filter((node) => node.kind === "intersection").length;
    const unsplitIntersectionCount = (project.wallGraph?.issues || []).filter((issue) => issue.type === "wall-intersection").length;
    const selectedIssue = getSelectedIssue();
    const canSplitSelectedIssue = selectedIssue?.type === "wall-intersection";
    const selectedNode = uiState.selectedNodeId ? graph.nodes.find((node) => node.id === uiState.selectedNodeId) : null;
    return [
      '<div class="status-card">',
      '<b>節點關係</b>',
      '<div class="status-grid">',
      '<div class="status-row"><span>節點</span><span>' + graph.nodes.length + '</span></div>',
      '<div class="status-row"><span>連線</span><span>' + graph.edges.length + '</span></div>',
      '<div class="status-row"><span>交點</span><span>' + intersectionCount + '</span></div>',
      '<div class="status-row"><span>未分割</span><span>' + unsplitIntersectionCount + '</span></div>',
      selectedNode ? '<div class="status-row"><span>選取節點</span><span>' + escapeHTML(selectedNode.id) + '</span></div>' : '',
      '</div>',
      canSplitSelectedIssue
        ? '<div class="inspector-actions" style="margin-top: 12px;"><button class="toolbar-btn primary" type="button" data-action="split-wall-intersection">分割牆線交點</button></div>'
        : '<div class="inline-message" style="margin-top: 12px;">請先選取交點問題，再分割候選牆線。</div>',
      '</div>'
    ].join("");
  }

  function renderStyleVisualPanel() {
    const statusClass = "is-" + styleVisualTask.status;
    const statusText = getStyleVisualStatusText(styleVisualTask.status);
    const statusBadgeText = getStyleVisualStatusBadgeText(styleVisualTask.status);
    const promptPreview = styleVisualTask.status === "ready" ? styleVisualTask.promptPreview : buildStylePromptPreview(styleVisualRequest);
    const sanitizedPrompt = styleVisualTask.sanitizedPrompt || buildSanitizedVisualPrompt(styleVisualRequest);
    const briefText = styleVisualTask.status === "ready" ? styleVisualTask.visualBrief : getStyleVisualPlaceholderBrief(styleVisualTask.status);
    const isDrafting = styleVisualTask.status === "drafting";
    const referenceImagePolicy = styleVisualTask.referenceImagePolicy || getStyleVisualReferenceImagePolicy();
    return [
      '<section class="status-card visual-sim-panel" aria-label="風格參考草稿">',
      '<div class="visual-sim-heading"><div><b>風格參考草稿</b><p>僅供人工確認與設計討論；正式視覺文件需另行審核。</p></div><span class="visual-sim-status ' + escapeAttribute(statusClass) + '">' + escapeHTML(statusBadgeText) + '</span></div>',
      '<div class="sandbox-label-row" aria-label="草稿使用邊界"><span class="sandbox-label">討論草稿</span><span class="sandbox-label">人工審核</span><span class="sandbox-label is-warning">非正式文件</span><span class="sandbox-label">本次案件參考</span></div>',
      '<div class="visual-field-grid" aria-label="風格參考欄位">',
      renderStyleVisualField("空間類型", "style-visual-room-type", styleVisualRequest.roomType),
      renderStyleVisualField("主要風格", "style-visual-primary-style", styleVisualRequest.primaryStyle),
      renderStyleVisualField("輔助風格", "style-visual-secondary-style", styleVisualRequest.secondaryStyle),
      renderStyleVisualField("色彩方向", "style-visual-color-tone", styleVisualRequest.colorTone),
      renderStyleVisualField("材質方向", "style-visual-material-tone", styleVisualRequest.materialTone, true),
      renderStyleVisualField("預算層級", "style-visual-budget-level", styleVisualRequest.budgetLevel),
      '</div>',
      '<div class="status-grid" style="margin-top: 12px;">',
      '<div class="status-row"><span>狀態</span><span>' + escapeHTML(statusText) + '</span></div>',
      '<div class="status-row"><span>草稿編號</span><span>' + escapeHTML(styleVisualTask.id) + '</span></div>',
      '<div class="status-row"><span>視覺整理</span><span>' + escapeHTML(getStyleVisualProxyStatusText(styleVisualTask.proxyStatus)) + '</span></div>',
      '<div class="status-row"><span>用途</span><span>' + escapeHTML(styleVisualRequest.purpose) + '</span></div>',
      '<div class="status-row"><span>參考圖片</span><span>' + (referenceImagePolicy.allowed ? '可使用' : '不可使用') + '</span></div>',
      '</div>',
      '<div class="reference-image-notice">' + escapeHTML(referenceImagePolicy.notice) + '</div>',
      renderStyleTags(),
      '<div class="prompt-preview"><strong>風格描述</strong>' + escapeHTML(promptPreview) + '</div>',
      '<div class="prompt-preview sandbox-prompt-preview"><strong>整理後描述</strong>' + escapeHTML(sanitizedPrompt) + '</div>',
      '<div class="visual-action-row"><span class="visual-brief">' + escapeHTML(isDrafting ? '正在整理風格草稿...' : briefText) + '</span><button class="secondary-btn" type="button" data-action="generate-style-visual" ' + (isDrafting ? 'disabled' : '') + '>' + (isDrafting ? '整理中...' : '整理風格草稿') + '</button></div>',
      renderStyleVisualPreviewCard(briefText, promptPreview, styleVisualTask.generatedPreview),
      '<div class="visual-disclaimer">' + escapeHTML(styleVisualTask.disclaimer) + '</div>',
      '</section>'
    ].join("");
  }

  function renderStyleVisualField(label, id, value, isFullWidth) {
    return '<div class="field-row' + (isFullWidth ? ' full' : '') + '"><label for="' + escapeAttribute(id) + '">' + escapeHTML(label) + '</label><input id="' + escapeAttribute(id) + '" data-field="' + escapeAttribute(id) + '" type="text" value="' + escapeAttribute(value) + '"></div>';
  }

  function renderStyleTags(request = styleVisualRequest) {
    const sanitized = buildSanitizedStyleVisualRequest(request);
    const tags = [
      sanitized.roomType,
      sanitized.primaryStyle,
      sanitized.secondaryStyle,
      sanitized.colorTone,
      sanitized.materialTone,
      sanitized.budgetLevel
    ].filter(Boolean);
    return '<div class="tag-row" aria-label="Style tags">' + tags.map((tag) => '<span class="style-tag">' + escapeHTML(tag) + '</span>').join("") + '</div>';
  }

  function renderStyleVisualPreviewCard(briefText, promptPreview, generatedPreview) {
    const isReady = styleVisualTask.status === "ready";
    const isDrafting = styleVisualTask.status === "drafting";
    const moodLabel = isReady ? "草稿已整理" : isDrafting ? "整理中" : "尚未整理";
    const previewState = generatedPreview?.status || styleVisualTask.proxyStatus || "disabled";
    const previewMessage = generatedPreview?.message || STYLE_VISUAL_PROXY_DISABLED_MESSAGE;
    const storageLabel = generatedPreview ? "本次草稿" : "尚未建立";
    const temporaryImageUrl = generatedPreview?.temporaryImageUrl || "尚未建立圖片";
    const cardBrief = isReady ? briefText : isDrafting
      ? "正在整理風格草稿。"
      : "風格視覺目前僅供人工確認與討論。";
    return [
      '<article class="visual-preview-card" aria-label="風格參考預覽">',
      '<div class="visual-mock-image sandbox-generated-frame' + (previewState === 'disabled' ? ' is-disabled' : '') + '" aria-label="風格參考框">',
      '<div class="visual-mock-overlay"><span class="mood-label">' + escapeHTML(moodLabel) + '</span><span class="disclaimer-badge">討論草稿</span></div>',
      '<div class="sandbox-fallback-message">' + escapeHTML(previewMessage) + '</div>',
      '</div>',
      '<div class="visual-preview-body">',
      '<div class="sandbox-label-row" aria-label="草稿使用邊界"><span class="sandbox-label">討論草稿</span><span class="sandbox-label">人工審核</span><span class="sandbox-label is-warning">非正式文件</span></div>',
      '<div class="status-row"><span>空間</span><span>' + escapeHTML(styleVisualRequest.roomType) + '</span></div>',
      '<div class="status-row"><span>狀態</span><span>' + escapeHTML(getStyleVisualProxyStatusText(previewState)) + '</span></div>',
      '<div class="status-row"><span>保存狀態</span><span>' + escapeHTML(storageLabel) + '</span></div>',
      '<div class="status-row"><span>圖片狀態</span><span>' + escapeHTML(temporaryImageUrl) + '</span></div>',
      renderStyleTags(),
      '<p class="visual-brief">' + escapeHTML(cardBrief) + '</p>',
      '<div class="prompt-preview"><strong>風格描述</strong>' + escapeHTML(promptPreview) + '</div>',
      '<span class="disclaimer-badge" style="width: fit-content;">僅供討論</span>',
      '</div></article>'
    ].join("");
  }

  function getStyleVisualPlaceholderBrief(status) {
    if (status === "drafting") {
      return "正在整理風格草稿。";
    }
    return "風格視覺目前僅供人工確認與討論。";
  }

  function getStyleVisualStatusText(status) {
    if (status === "drafting") {
      return "整理中";
    }
    if (status === "ready") {
      return "草稿已整理";
    }
    return "尚未整理";
  }

  function getStyleVisualStatusBadgeText(status) {
    if (status === "ready") {
      return "已整理";
    }
    return getReviewStatusText(status);
  }

  function getStyleVisualProxyStatusText(status) {
    if (status === "drafting") {
      return "正在整理...";
    }
    if (status === "mock_ready") {
      return "草稿已整理";
    }
    if (status === "error") {
      return "需處理";
    }
    return STYLE_VISUAL_PROXY_DISABLED_MESSAGE;
  }

  function renderIssueButton(issue) {
    const active = issue.id === uiState.selectedIssueId;
    return '<button class="issue-button' + (active ? ' is-active' : '') + '" type="button" data-action="select-issue" data-issue-id="' + escapeAttribute(issue.id) + '"><strong>' + escapeHTML(getIssueTypeLabel(issue.type)) + '</strong>' + escapeHTML(issue.message) + '</button>';
  }

  function renderZoneBoundaryIssue(issue) {
    return '<div class="issue-button" role="status"><strong>' + escapeHTML(getZoneBoundaryIssueLabel(issue.type)) + '</strong>' + escapeHTML(issue.message) + '</div>';
  }

  function renderMessageBlocks(forcedMessage) {
    const blocks = [];
    if (uiState.resetConfirmationPending) {
      blocks.push(renderResetConfirmationCard());
    }
    const message = forcedMessage || uiState.message;
    if (message) {
      blocks.push('<div class="inline-message">' + escapeHTML(message) + '</div>');
    }
    if (uiState.error) {
      blocks.push('<div class="error-message">' + escapeHTML(uiState.error) + '</div>');
    }
    return blocks.join("");
  }

  function renderResetConfirmationCard() {
    return [
      '<section class="status-card" id="loop74-reset-confirmation" data-testid="loop74-reset-confirmation" aria-label="清除本機草稿確認" tabindex="-1">',
      '<b>確認清除本機草稿</b>',
      '<p>清除後會移除目前草稿中的牆線、開口、標籤、家具、材料與備註。</p>',
      '<label class="confirm-row"><input type="checkbox" data-field="confirm-reset-project-understood"><span>我了解這會清除目前的本機草稿。</span></label>',
      '<div class="inspector-actions"><button class="secondary-btn" type="button" data-action="cancel-reset-project">取消</button><button class="danger-btn" type="button" data-action="confirm-reset-project" disabled aria-disabled="true">清除本機草稿</button></div>',
      '</section>'
    ].join("");
  }

  function revealResetConfirmationCard() {
    window.requestAnimationFrame(() => {
      const card = document.getElementById("loop74-reset-confirmation");
      if (!card) {
        return;
      }
      const scrollContainer = inspectorBody || card.closest(".panel-body");
      if (scrollContainer && typeof scrollContainer.scrollTo === "function") {
        scrollContainer.scrollTo({
          top: Math.max(0, card.offsetTop - 8),
          behavior: "auto"
        });
      }
      card.scrollIntoView({ block: "nearest", inline: "nearest" });
      card.focus({ preventScroll: true });
    });
  }

  function syncResetConfirmationButton(checked) {
    const button = document.querySelector("[data-action='confirm-reset-project']");
    if (!(button instanceof HTMLButtonElement)) {
      return;
    }
    button.disabled = !checked;
    button.setAttribute("aria-disabled", checked ? "false" : "true");
  }

  function ensurePlanPuzzleGuideState() {
    if (!project.guide) {
      project.guide = createInitialGuideState();
    }
    if (!Array.isArray(project.guideLog)) {
      project.guideLog = [];
    }
    if (typeof project.requirementNotes !== "string") {
      project.requirementNotes = "";
    }
    if (typeof project.guideSummary !== "string") {
      project.guideSummary = "";
    }
  }

  function appendPlanPuzzleGuideLog(type, text) {
    ensurePlanPuzzleGuideState();
    project.guideLog.push({
      id: createId("guide-log"),
      type,
      text,
      candidateOnly: true,
      createdAt: new Date().toISOString()
    });
    project.guide.updatedAt = new Date().toISOString();
  }

  function getPlanPuzzleGuideInputValue() {
    const input = document.getElementById("plan-guide-input");
    return input instanceof HTMLTextAreaElement ? input.value.trim() : (project.guide?.pendingInput || "").trim();
  }

  function startPlanPuzzleGuide() {
    ensurePlanPuzzleGuideState();
    project.guide.status = "started";
    project.guide.step = Math.max(1, Number(project.guide.step || 0) || 1);
    project.guide.currentPrompt = "Describe your room goal, key dimensions, and any unclear requirements.";
    appendPlanPuzzleGuideLog("start", "Guide started in local candidate mode.");
    uiState.inspectorTab = "properties";
    uiState.message = "需求整理已開始，請新增需求或待確認問題。";
    syncBridge();
    render();
  }

  function submitPlanPuzzleGuideInput() {
    ensurePlanPuzzleGuideState();
    const value = getPlanPuzzleGuideInputValue();
    if (!value) {
      uiState.error = "請先輸入需求或問題，再加入整理紀錄。";
      render();
      return;
    }
    project.guide.status = "collecting";
    project.guide.pendingInput = "";
    project.requirementNotes = [project.requirementNotes, value].filter(Boolean).join("\n");
    appendPlanPuzzleGuideLog("submit", value);
    uiState.error = "";
    uiState.message = "需求備註已記錄在目前草稿。";
    syncBridge();
    render();
  }

  function continuePlanPuzzleGuide() {
    ensurePlanPuzzleGuideState();
    project.guide.status = "collecting";
    project.guide.step = Number(project.guide.step || 0) + 1;
    project.guide.currentPrompt = "下一步：確認空間用途、牆線與門窗需求，以及固定設備。";
    appendPlanPuzzleGuideLog("next_step", project.guide.currentPrompt);
    uiState.error = "";
    uiState.message = "已進入下一個需求整理步驟。";
    syncBridge();
    render();
  }

  function recordPlanPuzzleGuideQuestion() {
    ensurePlanPuzzleGuideState();
    const value = getPlanPuzzleGuideInputValue() || "已記錄待確認問題，後續需人工追蹤。";
    project.guide.status = "question_recorded";
    project.guide.pendingInput = "";
    appendPlanPuzzleGuideLog("question", value);
    project.requirementNotes = [project.requirementNotes, "待確認問題：" + value].filter(Boolean).join("\n");
    uiState.error = "";
    uiState.message = "已記錄待確認問題。";
    syncBridge();
    render();
  }

  function generatePlanPuzzleGuideSummary() {
    ensurePlanPuzzleGuideState();
    const facts = createPlanPuzzleQuantityFacts();
    project.guide.status = "summary_ready";
    project.guideSummary = [
      "平面拼圖需求摘要",
      project.requirementNotes || "尚未記錄需求筆記。",
      "草稿統計：" + facts.wallCount + " 段牆、" + facts.openingCount + " 個開口、" + facts.zoneCount + " 個空間、" + facts.furnitureCount + " 個物件。",
      "此摘要仍需人工確認後，才能作正式討論依據。"
    ].join("\n");
    appendPlanPuzzleGuideLog("summary", project.guideSummary);
    uiState.error = "";
    uiState.message = "已整理需求摘要。";
    syncBridge();
    render();
  }

  function createPlanPuzzleQuantityFacts(currentProject = project) {
    const sourceProject = currentProject || project;
    const walls = excludePdfDerivedExistingObjects(sourceProject?.walls || []);
    const openings = excludePdfDerivedExistingObjects(sourceProject?.openings || []);
    const zones = excludePdfDerivedExistingObjects(sourceProject?.zones || []);
    const furniture = excludePdfDerivedExistingObjects(sourceProject?.furniture || []);
    const structures = excludePdfDerivedExistingObjects(sourceProject?.structures || []);
    const layoutObjects = sourceProject?.layoutObjects || furniture.map(createFurnitureLayoutObject);
    const toolCatalogItems = sourceProject?.toolCatalogItems || createToolCatalogFurnitureItems();
    const edges = getQuantityFactEdges(sourceProject);
    const wallFacts = createCandidateWallFacts(walls, edges);
    const openingFacts = createCandidateOpeningFacts(openings, edges);
    const zoneFacts = createCandidateZoneFacts(zones);
    const layoutObjectFacts = createCandidateLayoutObjectFacts(layoutObjects);
    const structureFacts = createCandidateStructureFacts(structures);
    const materialFacts = createCandidateMaterialFacts(furniture, layoutObjects, toolCatalogItems);
    const validation = createCandidateQuantityFactsValidation({
      zones: zoneFacts,
      walls: wallFacts,
      openings: openingFacts,
      layoutObjects: layoutObjectFacts,
      structures: structureFacts,
      materials: materialFacts
    });
    const reviewerRequiredReasons = uniqueIdsPreserveOrder([
      ...zoneFacts.flatMap((zone) => zone.reviewReasons || []),
      ...wallFacts.reviewReasons,
      ...openingFacts.reviewReasons,
      ...layoutObjectFacts.reviewReasons,
      ...structureFacts.reviewReasons,
      ...materialFacts.reviewReasons,
      ...validation.schemaWarnings
    ]);

    return {
      contractVersion: "loop94-budget-quantity-candidate-v1",
      plan_id: sourceProject?.id || sourceProject?.planId || "plan-puzzle-local-candidate",
      plan_quantity_facts_id: "plan-puzzle-quantity-facts-" + (sourceProject?.id || "local") + "-" + Date.now(),
      quantity_context_status: validation.reviewer_required ? "review_required" : "candidate",
      candidateOnly: true,
      formalEstimate: false,
      budgetEngineCalled: false,
      productionReady: false,
      units: {
        sourceLength: "mm",
        length: "m",
        areaSource: "mm2",
        area: "m2",
        furnitureWidth: "mm/cm",
        wardrobe_length_chi: "candidate_only_width_cm_div_30_3",
        rounding: {
          length_m: 3,
          area_m2: 3,
          width_cm: 1,
          wardrobe_length_chi: 2
        }
      },
      roundingPolicy: "Candidate facts round display values only; source mm values remain available for reviewer audit.",
      zones: zoneFacts,
      walls: wallFacts,
      openings: openingFacts,
      layoutObjects: layoutObjectFacts,
      structures: structureFacts,
      structuralObjects: structureFacts,
      materials: materialFacts,
      presetCatalogs: {
        walls: [...LOOP99_WALL_PRESETS, ...WALL_PRESET_OPTIONS].map((preset) => ({ ...preset })),
        openings: [...LOOP99_OPENING_PRESETS, ...OPENING_PRESET_OPTIONS].map((preset) => ({ ...preset }))
      },
      validation,
      schemaWarnings: validation.schemaWarnings,
      reviewer_required: validation.reviewer_required,
      reviewerRequiredReasons,
      wallCount: wallFacts.wall_count,
      openingCount: openingFacts.opening_count_total,
      zoneCount: zoneFacts.length,
      furnitureCount: furniture.length,
      layoutObjectCount: layoutObjectFacts.total_count,
      structureCount: structureFacts.total_count,
      columnCount: structureFacts.column_count,
      beamCount: structureFacts.beam_count,
      materialTaggedFurnitureCount: materialFacts.tagged_object_count,
      guideLogCount: sourceProject?.guideLog?.length || 0,
      requirementNotesLength: sourceProject?.requirementNotes?.length || 0,
      generatedAt: new Date().toISOString()
    };
  }

  function createAllowedWallIdSet(walls) {
    return new Set((walls || []).map((wall) => wall && wall.id).filter(Boolean));
  }

  function createFilteredNodeGraphForAllowedWalls(sourceProject, allowedWalls) {
    const allowedWallIds = createAllowedWallIdSet(allowedWalls);
    const sourceGraph = sourceProject?.nodeGraph || createInitialNodeGraph();
    const filteredEdges = (Array.isArray(sourceGraph.edges) ? sourceGraph.edges : [])
      .filter((edge) => edge && edge.sourceWallId && allowedWallIds.has(edge.sourceWallId))
      .map((edge) => ({ ...edge }));
    const allowedEdgeIds = new Set(filteredEdges.map((edge) => edge.id).filter(Boolean));
    const filteredNodes = (Array.isArray(sourceGraph.nodes) ? sourceGraph.nodes : [])
      .map((node) => {
        const edgeIds = (Array.isArray(node.edgeIds) ? node.edgeIds : []).filter((edgeId) => allowedEdgeIds.has(edgeId));
        return edgeIds.length ? { ...node, edgeIds } : null;
      })
      .filter(Boolean);
    return {
      nodes: filteredNodes,
      edges: filteredEdges,
      issues: [],
      closureDiagnostics: {
        sourceWallCount: allowedWallIds.size,
        edgeCount: filteredEdges.length,
        pdfDerivedExistingEdgesExcluded: true,
        orphanEdgesRejected: true
      },
      lastBuiltAt: sourceGraph.lastBuiltAt || null
    };
  }

  function getQuantityFactEdges(sourceProject) {
    const allowedWalls = excludePdfDerivedExistingObjects(sourceProject?.walls || []);
    const allowedWallIds = createAllowedWallIdSet(allowedWalls);
    if (Array.isArray(sourceProject?.nodeGraph?.edges) && sourceProject.nodeGraph.edges.length) {
      return sourceProject.nodeGraph.edges.filter((edge) => {
        return Boolean(edge && edge.sourceWallId && allowedWallIds.has(edge.sourceWallId));
      });
    }
    return allowedWalls.map((wall) => {
      const presetFields = createWallPresetFields(wall);
      return {
        id: createEdgeId(wall),
        sourceWallId: wall.id,
        from: wall.from,
        to: wall.to,
        length: getDistance(wall.from, wall.to),
        wallPreset: presetFields.wallPreset,
        wallPresetKey: presetFields.wallPresetKey,
        wallLabel: presetFields.wallLabel,
        thickness: presetFields.thickness,
        status: normalizeWallStatus(wall.status),
        wallType: presetFields.wallType,
        structural: Boolean(wall.structural || presetFields.wallType === "bearing_wall"),
        layer: wall.layer || "walls"
      };
    });
  }

  function createCandidateWallFacts(walls, edges) {
    const sourceEdges = edges.length ? edges : (walls || []).map((wall) => {
      const presetFields = createWallPresetFields(wall);
      return {
        id: createEdgeId(wall),
        sourceWallId: wall.id,
        from: wall.from,
        to: wall.to,
        length: getDistance(wall.from, wall.to),
        wallPreset: presetFields.wallPreset,
        wallPresetKey: presetFields.wallPresetKey,
        wallLabel: presetFields.wallLabel,
        thickness: presetFields.thickness,
        status: wall.status,
        wallType: presetFields.wallType,
        structural: wall.structural
      };
    });
    const byStatus = {};
    const byType = {};
    const reviewReasons = [];
    const items = sourceEdges.map((edge, index) => {
      const lengthMm = Number.isFinite(Number(edge.length)) ? Number(edge.length) : getDistance(edge.from || { x: 0, y: 0 }, edge.to || { x: 0, y: 0 });
      const status = normalizeWallStatus(edge.status);
      const wallType = normalizeWallType(edge.wallType);
      const presetFields = createWallPresetFields({
        wallPreset: edge.wallPreset,
        wallPresetKey: edge.wallPresetKey,
        wallLabel: edge.wallLabel,
        wallType,
        thickness: edge.thickness
      });
      byStatus[status] = (byStatus[status] || 0) + 1;
      byType[presetFields.wallType] = (byType[presetFields.wallType] || 0) + 1;
      const itemReviewReasons = [];
      if (!Number.isFinite(lengthMm) || lengthMm <= 0) {
        itemReviewReasons.push("wall_length_missing_or_invalid");
      }
      if (edge.structural === true || presetFields.wallType === "bearing_wall" || presetFields.wallType === "rc_wall") {
        itemReviewReasons.push("structural_wall_requires_professional_review");
      }
      reviewReasons.push(...itemReviewReasons);
      return {
        wall_id: edge.sourceWallId || edge.wallId || "wall-" + (index + 1),
        edge_id: edge.id || null,
        length_mm: Number.isFinite(lengthMm) && lengthMm > 0 ? Math.round(lengthMm) : 0,
        length_m: roundQuantityFactNumber((Number.isFinite(lengthMm) && lengthMm > 0 ? lengthMm : 0) / 1000, 3),
        wallPreset: presetFields.wallPreset,
        wallPresetKey: presetFields.wallPresetKey,
        wallLabel: presetFields.wallLabel,
        thickness_mm: Number.isFinite(Number(presetFields.thickness)) ? Number(presetFields.thickness) : null,
        status,
        wallType: presetFields.wallType,
        structural: Boolean(edge.structural || presetFields.wallType === "bearing_wall" || presetFields.wallType === "rc_wall"),
        sourceUnits: "mm",
        confidence: itemReviewReasons.length ? "review_required" : "candidate",
        reviewer_required: itemReviewReasons.length > 0,
        reviewReasons: itemReviewReasons
      };
    });
    const totalLengthMm = items.reduce((sum, item) => sum + item.length_mm, 0);
    return {
      wall_count: items.length,
      total_length_mm: totalLengthMm,
      total_length_m: roundQuantityFactNumber(totalLengthMm / 1000, 3),
      byStatus,
      byType,
      units: { length_mm: "mm", length_m: "m", thickness_mm: "mm" },
      items,
      confidence: reviewReasons.length ? "review_required" : "candidate",
      reviewer_required: reviewReasons.length > 0,
      reviewReasons: uniqueIdsPreserveOrder(reviewReasons)
    };
  }

  function createCandidateOpeningFacts(openings, edges) {
    const edgeMap = new Map((edges || []).map((edge) => [edge.id, edge]));
    const byKind = {
      door: createOpeningKindSummary(),
      window: createOpeningKindSummary(),
      opening: createOpeningKindSummary()
    };
    const byOpeningType = {};
    const reviewReasons = [];
    const items = (openings || []).map((opening, index) => {
      const kind = normalizeOpeningKind(opening.kind);
      const openingType = normalizeOpeningType(kind, opening.openingType);
      const widthMm = Number.isFinite(Number(opening.width)) ? Math.max(0, Number(opening.width)) : 0;
      const offsetMm = Number.isFinite(Number(opening.offset)) ? Number(opening.offset) : null;
      const presetFields = createOpeningPresetFields({
        openingPreset: opening.openingPreset,
        openingPresetKey: opening.openingPresetKey,
        openingLabel: opening.openingLabel,
        label: opening.label,
        doorType: opening.doorType,
        doorSubtype: opening.doorSubtype,
        windowType: opening.windowType,
        openingMode: opening.openingMode,
        kind,
        openingType,
        width: widthMm,
        swing: opening.swing
      });
      const heightMm = Number.isFinite(Number(opening.height)) ? Math.max(0, Number(opening.height)) : null;
      const sillHeightMm = Number.isFinite(Number(opening.sillHeight)) ? Math.max(0, Number(opening.sillHeight)) : null;
      const edge = opening.edgeId ? edgeMap.get(opening.edgeId) : null;
      const edgeLength = edge && Number.isFinite(Number(edge.length)) ? Number(edge.length) : null;
      const itemReviewReasons = [];
      if (!edge) {
        itemReviewReasons.push("opening_host_wall_missing");
      }
      if (edgeLength !== null && offsetMm !== null && offsetMm + widthMm > edgeLength + GEOMETRY_EPSILON) {
        itemReviewReasons.push("opening_exceeds_host_wall_length");
      }
      if (!Number.isFinite(widthMm) || widthMm <= 0) {
        itemReviewReasons.push("opening_width_missing_or_invalid");
      }
      byKind[kind].count += 1;
      byKind[kind].width_total_mm += Math.round(widthMm);
      byOpeningType[presetFields.openingType] = byOpeningType[presetFields.openingType] || createOpeningKindSummary();
      byOpeningType[presetFields.openingType].count += 1;
      byOpeningType[presetFields.openingType].width_total_mm += Math.round(presetFields.width);
      reviewReasons.push(...itemReviewReasons);
      return {
        opening_id: opening.id || "opening-" + (index + 1),
        kind,
        openingPreset: presetFields.openingPreset,
        openingPresetKey: presetFields.openingPresetKey,
        openingType: presetFields.openingType,
        openingLabel: presetFields.openingLabel,
        label: presetFields.label || presetFields.openingLabel,
        doorType: kind === "door" ? presetFields.doorType : null,
        doorSubtype: kind === "door" ? presetFields.doorSubtype : null,
        windowType: kind === "window" ? presetFields.windowType : null,
        openingMode: kind === "window" ? presetFields.openingMode : null,
        edge_id: opening.edgeId || null,
        host_wall_id: opening.sourceWallId || edge?.sourceWallId || getWallIdFromEdgeId(opening.edgeId) || null,
        offset_mm: offsetMm,
        width_mm: Math.round(presetFields.width),
        width_m: roundQuantityFactNumber(presetFields.width / 1000, 3),
        height_mm: heightMm === null ? null : Math.round(heightMm),
        sill_height_mm: kind === "window" ? sillHeightMm : null,
        swing: presetFields.swing || "none",
        candidateOnly: true,
        productionReady: false,
        formalEstimate: false,
        budgetEngineCalled: false,
        sourceUnits: "mm",
        confidence: itemReviewReasons.length ? "review_required" : "candidate",
        reviewer_required: itemReviewReasons.length > 0,
        reviewReasons: itemReviewReasons
      };
    });
    Object.keys(byKind).forEach((kind) => {
      byKind[kind].width_total_m = roundQuantityFactNumber(byKind[kind].width_total_mm / 1000, 3);
    });
    Object.keys(byOpeningType).forEach((openingType) => {
      byOpeningType[openingType].width_total_m = roundQuantityFactNumber(byOpeningType[openingType].width_total_mm / 1000, 3);
    });
    const widthTotalMm = items.reduce((sum, item) => sum + item.width_mm, 0);
    return {
      opening_count_total: items.length,
      byKind,
      byOpeningType,
      width_total_mm: widthTotalMm,
      width_total_m: roundQuantityFactNumber(widthTotalMm / 1000, 3),
      units: { width_mm: "mm", width_m: "m", height_mm: "mm", sill_height_mm: "mm", offset_mm: "mm" },
      items,
      confidence: reviewReasons.length ? "review_required" : "candidate",
      reviewer_required: reviewReasons.length > 0,
      reviewReasons: uniqueIdsPreserveOrder(reviewReasons)
    };
  }

  function createOpeningKindSummary() {
    return {
      count: 0,
      width_total_mm: 0,
      width_total_m: 0
    };
  }

  function createCandidateStructureFacts(structures = []) {
    const items = (structures || []).map((structure, index) => {
      const category = structure.category === "beam" || structure.kind === "beam" ? "beam" : "column";
      const lengthMm = category === "beam"
        ? Math.round(Number(structure.lengthMm || structure.length_mm || getDistance(structure.from || { x: 0, y: 0 }, structure.to || { x: 0, y: 0 })) || 0)
        : null;
      return {
        structural_object_id: structure.structural_object_id || structure.id || "structure-" + (index + 1),
        kind: structure.kind || category,
        category,
        label: getStructureLabel?.(structure) || structure.label || structure.kind || category,
        x_mm: Number.isFinite(Number(structure.x_mm ?? structure.x)) ? Math.round(Number(structure.x_mm ?? structure.x)) : null,
        y_mm: Number.isFinite(Number(structure.y_mm ?? structure.y)) ? Math.round(Number(structure.y_mm ?? structure.y)) : null,
        width_mm: Number.isFinite(Number(structure.width_mm ?? structure.widthMm)) ? Math.round(Number(structure.width_mm ?? structure.widthMm)) : null,
        depth_mm: Number.isFinite(Number(structure.depth_mm ?? structure.depthMm)) ? Math.round(Number(structure.depth_mm ?? structure.depthMm)) : null,
        height_mm: Number.isFinite(Number(structure.height_mm ?? structure.heightMm)) ? Math.round(Number(structure.height_mm ?? structure.heightMm)) : null,
        length_mm: lengthMm,
        candidateOnly: true,
        productionReady: false,
        formalEstimate: false,
        budgetEngineCalled: false,
        reviewer_required: true,
        reviewReasons: ["structure_candidate_requires_professional_review"]
      };
    });
    return {
      total_count: items.length,
      column_count: items.filter((item) => item.category === "column").length,
      beam_count: items.filter((item) => item.category === "beam").length,
      units: { x_mm: "mm", y_mm: "mm", width_mm: "mm", depth_mm: "mm", height_mm: "mm", length_mm: "mm" },
      items,
      candidateOnly: true,
      productionReady: false,
      formalEstimate: false,
      budgetEngineCalled: false,
      confidence: items.length ? "review_required" : "candidate",
      reviewer_required: items.length > 0,
      reviewReasons: items.length ? ["structure_candidate_requires_professional_review"] : []
    };
  }

  function createCandidateZoneFacts(zones) {
    return (zones || []).map((zone, index) => {
      const polygon = Array.isArray(zone.polygon) ? zone.polygon : [];
      const reviewReasons = [];
      const isClosed = zone.boundaryStatus === "closed" && polygon.length >= 3;
      let areaMm2 = null;
      let areaM2 = null;
      let areaSource = "not_available";
      let areaConfidence = "review_required";
      const areaConfirmed = zone.areaConfirmed === true && Number.isFinite(Number(zone.area)) && Number(zone.area) > 0;
      if (areaConfirmed) {
        areaMm2 = Number(zone.area);
        areaM2 = roundQuantityFactNumber(areaMm2 / 1000000, 3);
        areaSource = zone.areaSource || "closed_boundary_polygon_user_confirmed";
        areaConfidence = "user_confirmed";
      } else if (isClosed) {
        areaMm2 = calculatePolygonAreaMm2(polygon);
        if (areaMm2 > 0) {
          areaM2 = roundQuantityFactNumber(areaMm2 / 1000000, 3);
          areaSource = "closed_boundary_polygon_shoelace";
          areaConfidence = "candidate";
          reviewReasons.push("candidate_area_requires_human_review");
        } else {
          reviewReasons.push("zone_area_zero_or_invalid");
        }
      } else {
        if (polygon.length < 3) {
          reviewReasons.push("zone_polygon_insufficient_points");
        }
        if (zone.boundaryStatus !== "closed") {
          reviewReasons.push("zone_boundary_" + (zone.boundaryStatus || "missing"));
        }
      }
      (zone.boundaryIssues || []).forEach((issue) => {
        if (issue?.type) {
          reviewReasons.push(issue.type);
        }
      });
      return {
        zone_id: zone.id || "zone-" + (index + 1),
        name: zone.name || "",
        type: normalizeZoneType(zone.type),
        boundaryStatus: zone.boundaryStatus || "none",
        boundaryEdgeIds: [...(zone.boundaryEdgeIds || [])],
        polygonPointCount: polygon.length,
        area_mm2: areaMm2 !== null ? Math.round(areaMm2) : null,
        area_m2: areaM2,
        areaSource,
        areaConfidence,
        reviewer_required: !areaConfirmed,
        reviewReasons: areaConfirmed ? [] : uniqueIdsPreserveOrder(reviewReasons.length ? reviewReasons : ["candidate_zone_requires_reviewer_confirmation"])
      };
    });
  }

  function calculatePolygonAreaMm2(polygon) {
    if (!Array.isArray(polygon) || polygon.length < 3) {
      return 0;
    }
    let sum = 0;
    for (let index = 0; index < polygon.length; index += 1) {
      const current = polygon[index];
      const next = polygon[(index + 1) % polygon.length];
      sum += Number(current.x || 0) * Number(next.y || 0) - Number(next.x || 0) * Number(current.y || 0);
    }
    return Math.abs(sum) / 2;
  }

  function formatZoneAreaM2(areaMm2) {
    const value = Number(areaMm2) / 1000000;
    return Number.isFinite(value)
      ? value.toLocaleString("zh-TW", { minimumFractionDigits: 2, maximumFractionDigits: 2 }) + " m²"
      : "待確認";
  }

  function getZoneAreaReview(zone, polygon = zone?.polygon, boundaryStatus = zone?.boundaryStatus) {
    const scaleTransformId = acceptedScaleTransformId(project);
    const scaleAccepted = Boolean(scaleTransformId);
    const closedBoundary = boundaryStatus === "closed" && Array.isArray(polygon) && polygon.length >= 3;
    const candidateMm2 = scaleAccepted && closedBoundary ? calculatePolygonAreaMm2(polygon) : 0;
    const candidateValid = Number.isFinite(candidateMm2) && candidateMm2 > 0;
    const confirmed = Boolean(
      zone?.areaConfirmed === true &&
      Number.isFinite(Number(zone?.area)) &&
      Number(zone.area) > 0 &&
      zone?.areaConfirmedTransformId === scaleTransformId
    );
    let blockerLabel = "待確認";
    if (!scaleAccepted) blockerLabel = "比例尚未確認";
    else if (!closedBoundary) blockerLabel = "邊界尚未封閉";
    else if (!candidateValid) blockerLabel = "邊界面積無法計算";
    return {
      scaleTransformId,
      confirmed,
      canConfirm: !confirmed && scaleAccepted && closedBoundary && candidateValid,
      candidateMm2: candidateValid ? candidateMm2 : null,
      candidateLabel: candidateValid ? formatZoneAreaM2(candidateMm2) : "",
      confirmedLabel: confirmed ? formatZoneAreaM2(zone.area) : "",
      blockerLabel,
      basisLabel: scaleAccepted && closedBoundary ? "已確認比例＋封閉邊界" : blockerLabel
    };
  }

  function invalidateZoneAreaConfirmation(zone) {
    if (!zone || typeof zone !== "object") return;
    zone.area = null;
    zone.areaConfirmed = false;
    delete zone.areaConfirmedAt;
    delete zone.areaConfirmedTransformId;
    delete zone.areaSource;
  }

  function createCandidateLayoutObjectFacts(layoutObjects) {
    const byType = {};
    const byCategory = {};
    const reviewReasons = [];
    const objects = (layoutObjects || []).map((object, index) => {
      const type = object.type || object.objectType || "unknown";
      const category = object.category || "unknown";
      const subtype = object.subtype || type;
      const widthMm = Number(object.sizeMm?.width ?? object.widthMm ?? 0);
      const widthCm = Number.isFinite(widthMm) ? roundQuantityFactNumber(widthMm / 10, 1) : null;
      const isCabinetLike = category === "cabinet" || category === "fixed_furniture" || /cabinet|wardrobe|closet|shoe/i.test(type);
      const isEquipmentLike = category === "kitchen_equipment" || category === "bathroom_equipment";
      const objectReviewReasons = ["candidate_layout_object_requires_budget_adapter_review"];
      if (isCabinetLike) {
        objectReviewReasons.push("candidate_chi_unit_policy_uncertain");
      }
      byType[type] = (byType[type] || 0) + 1;
      byCategory[category] = (byCategory[category] || 0) + 1;
      reviewReasons.push(...objectReviewReasons);
      return {
        layout_object_id: object.id || "layout-object-" + (index + 1),
        objectType: object.objectType || "parametric_furniture_candidate",
        type,
        subtype,
        label: object.label || object.name || getFurnitureTypeLabel(type),
        category,
        classification: category === "furniture" ? "loose_furniture_reference" : isEquipmentLike ? "fixed_equipment_candidate" : "fixed_fixture_or_cabinet_candidate",
        width_mm: Number.isFinite(widthMm) ? Math.round(widthMm) : null,
        width_cm: widthCm,
        depth_mm: Number.isFinite(Number(object.sizeMm?.depth ?? object.depthMm)) ? Math.round(Number(object.sizeMm?.depth ?? object.depthMm)) : null,
        height_mm: Number.isFinite(Number(object.sizeMm?.height ?? object.heightMm)) ? Math.round(Number(object.sizeMm?.height ?? object.heightMm)) : null,
        dimensions: object.dimensions || object.sizeMm || null,
        resizePolicy: object.resizePolicy || "free",
        wardrobe_length_chi: isCabinetLike && widthCm !== null ? roundQuantityFactNumber(widthCm / 30.3, 2) : null,
        materialTags: [...(object.materialTags || [])],
        materialRules: object.materialRules || null,
        candidateOnly: true,
        noPricingIdentifiers: true,
        reviewer_required: true,
        reviewReasons: uniqueIdsPreserveOrder(objectReviewReasons)
      };
    });
    return {
      total_count: objects.length,
      byType,
      byCategory,
      objects,
      units: {
        width_mm: "mm",
        width_cm: "cm",
        wardrobe_length_chi: "candidate_only_width_cm_div_30_3"
      },
      prohibitedPricingIdentifiers: ["pricing_identifiers_blocked_by_candidate_guard"],
      confidence: objects.length ? "review_required" : "candidate_empty",
      reviewer_required: objects.length > 0,
      reviewReasons: uniqueIdsPreserveOrder(reviewReasons)
    };
  }

  function createCandidateStructureFacts(structures) {
    const normalized = (structures || []).map(normalizeStructureForExport);
    const byType = {};
    const reviewReasons = [];
    const columns = [];
    const beams = [];

    normalized.forEach((structure, index) => {
      const typeKey = structure.structureType || structure.columnType || structure.beamType || structure.kind;
      byType[typeKey] = (byType[typeKey] || 0) + 1;
      const reasons = ["candidate_structure_requires_professional_review"];
      if (structure.category === "beam") {
        if (!Number.isFinite(Number(structure.lengthMm)) || Number(structure.lengthMm) <= 0) {
          reasons.push("beam_length_missing_or_invalid");
        }
        reviewReasons.push(...reasons);
        beams.push({
          structural_object_id: structure.structural_object_id || structure.id || "beam-" + (index + 1),
          structure_id: structure.id || "beam-" + (index + 1),
          kind: "beam",
          beamType: structure.beamType || structure.structureType || "rc_beam",
          beamLabel: structure.label || getStructureTypeLabel(structure.structureType || structure.beamType, "beam"),
          from: structure.from,
          to: structure.to,
          length_mm: Math.round(Number(structure.lengthMm) || 0),
          length_m: roundQuantityFactNumber((Number(structure.lengthMm) || 0) / 1000, 3),
          width_mm: Math.round(Number(structure.widthMm) || 0),
          depth_mm: Math.round(Number(structure.depthMm) || 0),
          candidateOnly: true,
          noPricingIdentifiers: true,
          reviewer_required: true,
          reviewReasons: uniqueIdsPreserveOrder(reasons)
        });
        return;
      }

      if (!Number.isFinite(Number(structure.widthMm)) || Number(structure.widthMm) <= 0) {
        reasons.push("column_width_missing_or_invalid");
      }
      if (!Number.isFinite(Number(structure.depthMm)) || Number(structure.depthMm) <= 0) {
        reasons.push("column_depth_missing_or_invalid");
      }
      reviewReasons.push(...reasons);
      columns.push({
        structural_object_id: structure.structural_object_id || structure.id || "column-" + (index + 1),
        structure_id: structure.id || "column-" + (index + 1),
        kind: "column",
        columnType: structure.columnType || structure.structureType || "square_column",
        columnLabel: structure.label || getStructureTypeLabel(structure.structureType || structure.columnType, "column"),
        shape: structure.shape || "square",
        x_mm: Math.round(Number(structure.x_mm ?? structure.x) || 0),
        y_mm: Math.round(Number(structure.y_mm ?? structure.y) || 0),
        positionMm: { x: Math.round(Number(structure.x_mm ?? structure.x) || 0), y: Math.round(Number(structure.y_mm ?? structure.y) || 0) },
        width_mm: Math.round(Number(structure.widthMm) || 0),
        depth_mm: Math.round(Number(structure.depthMm) || 0),
        diameter_mm: structure.shape === "round" ? Math.round(Number(structure.widthMm) || 0) : null,
        height_mm: Math.round(Number(structure.heightMm) || 0),
        candidateOnly: true,
        noPricingIdentifiers: true,
        reviewer_required: true,
        reviewReasons: uniqueIdsPreserveOrder(reasons)
      });
    });

    const totalBeamLengthMm = beams.reduce((sum, beam) => sum + (beam.length_mm || 0), 0);
    return {
      total_count: normalized.length,
      column_count: columns.length,
      beam_count: beams.length,
      byType,
      columns,
      beams,
      total_beam_length_mm: totalBeamLengthMm,
      total_beam_length_m: roundQuantityFactNumber(totalBeamLengthMm / 1000, 3),
      units: {
        position: "mm",
        dimensions: "mm",
        beam_length_mm: "mm",
        beam_length_m: "m"
      },
      candidateOnly: true,
      noPricingIdentifiers: true,
      prohibitedPricingIdentifiers: ["pricing_identifiers_blocked_by_candidate_guard"],
      confidence: normalized.length ? "review_required" : "candidate_empty",
      reviewer_required: normalized.length > 0,
      reviewReasons: uniqueIdsPreserveOrder(reviewReasons)
    };
  }

  function createCandidateMaterialFacts(furniture, layoutObjects, toolCatalogItems) {
    const tagCounts = {};
    const collectTags = (tags) => {
      (tags || []).forEach((tag) => {
        const normalized = normalizeFurnitureMaterialTag(tag);
        tagCounts[normalized] = (tagCounts[normalized] || 0) + 1;
      });
    };
    const materialObjectSource = (layoutObjects || []).length ? layoutObjects : (furniture || []);
    materialObjectSource.forEach((item) => collectTags(item.materialTags));
    const catalogTags = {};
    (toolCatalogItems || []).forEach((item) => {
      (item.materialTags || []).forEach((tag) => {
        const normalized = normalizeFurnitureMaterialTag(tag);
        catalogTags[normalized] = (catalogTags[normalized] || 0) + 1;
      });
    });
    return {
      displayCandidateTagsOnly: true,
      notPriceSpecIdentifiers: true,
      tagCounts,
      catalogTagCounts: catalogTags,
      tagged_object_count: Object.values(tagCounts).reduce((sum, count) => sum + count, 0),
      reviewer_required: Object.keys(tagCounts).length > 0,
      reviewReasons: Object.keys(tagCounts).length ? ["material_tags_are_display_candidates_not_price_specs"] : []
    };
  }

  function createCandidateQuantityFactsValidation(parts) {
    const schemaWarnings = [];
    if (!Array.isArray(parts.zones)) {
      schemaWarnings.push("zones_facts_missing");
    }
    if (!parts.walls || !parts.walls.units) {
      schemaWarnings.push("wall_units_missing");
    }
    if (!parts.openings || !parts.openings.units) {
      schemaWarnings.push("opening_units_missing");
    }
    if (!parts.structures || !parts.structures.units) {
      schemaWarnings.push("structure_units_missing");
    }
    (parts.walls?.items || []).forEach((wall) => {
      if (!wall.wallPreset) {
        schemaWarnings.push("wall_preset_missing:" + wall.wall_id);
      }
      if (!wall.wallLabel) {
        schemaWarnings.push("wall_label_missing:" + wall.wall_id);
      }
    });
    (parts.openings?.items || []).forEach((opening) => {
      if (!opening.openingType) {
        schemaWarnings.push("opening_type_missing:" + opening.opening_id);
      }
      if (!opening.openingLabel) {
        schemaWarnings.push("opening_label_missing:" + opening.opening_id);
      }
      if (!opening.host_wall_id) {
        schemaWarnings.push("opening_host_wall_missing:" + opening.opening_id);
      }
    });
    (parts.structures?.columns || []).forEach((column) => {
      if (!column.columnType) {
        schemaWarnings.push("column_type_missing:" + column.structure_id);
      }
    });
    (parts.structures?.beams || []).forEach((beam) => {
      if (!beam.beamType) {
        schemaWarnings.push("beam_type_missing:" + beam.structure_id);
      }
    });
    if (!parts.layoutObjects || !parts.layoutObjects.units) {
      schemaWarnings.push("layout_object_units_missing");
    }
    if (!parts.materials || parts.materials.displayCandidateTagsOnly !== true) {
      schemaWarnings.push("material_candidate_boundary_missing");
    }
    const nullReviewReasons = [];
    (parts.zones || []).forEach((zone) => {
      if (zone.area_m2 === null) {
        nullReviewReasons.push("zone_area_null:" + zone.zone_id);
      }
    });
    return {
      candidateOnly: true,
      productionReady: false,
      formalEstimate: false,
      budgetEngineCalled: false,
      requiredTopLevelFactsPresent: schemaWarnings.length === 0,
      unitsDeclared: Boolean(parts.walls?.units && parts.openings?.units && parts.layoutObjects?.units && parts.structures?.units),
      nullsAllowedWithReviewReasons: true,
      schemaWarnings: uniqueIdsPreserveOrder([...schemaWarnings, ...nullReviewReasons]),
      reviewer_required: schemaWarnings.length > 0 || nullReviewReasons.length > 0 || Boolean(parts.zones?.some((zone) => zone.reviewer_required)) || Boolean(parts.openings?.reviewer_required) || Boolean(parts.walls?.reviewer_required) || Boolean(parts.layoutObjects?.reviewer_required) || Boolean(parts.structures?.reviewer_required) || Boolean(parts.materials?.reviewer_required)
    };
  }

  function roundQuantityFactNumber(value, digits) {
    const numeric = Number(value);
    if (!Number.isFinite(numeric)) {
      return null;
    }
    const factor = 10 ** digits;
    return Math.round(numeric * factor) / factor;
  }

  function createPlanPuzzleGuideModelEvidence(facts = createPlanPuzzleQuantityFacts()) {
    ensurePlanPuzzleGuideState();
    const hasWindowHandle = (name) => {
      try {
        return Boolean(Object.getOwnPropertyDescriptor(window, name));
      } catch (error) {
        return false;
      }
    };
    return {
      candidateOnly: true,
      formalEstimate: false,
      budgetEngineCalled: false,
      productionReady: false,
      hasGuide: Boolean(project.guide),
      hasGuideLog: Array.isArray(project.guideLog),
      guideLogCount: Array.isArray(project.guideLog) ? project.guideLog.length : 0,
      requirementNotesLength: typeof project.requirementNotes === "string" ? project.requirementNotes.length : 0,
      guideSummaryLength: typeof project.guideSummary === "string" ? project.guideSummary.length : 0,
      quantityFacts: facts,
      windowHandlesDeclared: {
        laibePlanPuzzleProject: hasWindowHandle("laibePlanPuzzleProject"),
        laibePlancraftPlusProject: hasWindowHandle("laibePlancraftPlusProject"),
        PlanPuzzleQuantityFacts: hasWindowHandle("PlanPuzzleQuantityFacts")
      }
    };
  }

