  function renderWorkflowStepper() {
    const stepper = document.querySelector("[data-plan-workflow-stepper]");
    if (!stepper) return;
    const workflow = derivePlanWorkflowState();
    stepper.dataset.workflowState = workflow.key;
    stepper.dataset.workflowStep = String(workflow.workflowStep);
    stepper.querySelectorAll("[data-workflow-step]").forEach((item) => {
      const itemStep = Number(item.dataset.workflowStep);
      const active = itemStep === workflow.workflowStep;
      item.classList.toggle("active", active);
      item.classList.toggle("completed", itemStep < workflow.workflowStep);
      if (active) item.setAttribute("aria-current", "step");
      else item.removeAttribute("aria-current");
    });
  }

