    const metadata = getScenePolicyMetadata(scene, options);
    const sourceObjectId = getSceneSourceObjectId(item);
    const sourceObjectIds = getSceneSourceObjectIds(item);
    target.source_object_id = sourceObjectId || null;
    target.source_object_ids = sourceObjectIds;
    target.sourceId = sourceObjectId || target.sourceId || null;
    target.sourceRegionId = item.sourceRegionId || target.sourceRegionId || null;
    target.sourceRegionSemanticStatus = item.sourceRegionSemanticStatus || target.sourceRegionSemanticStatus || null;
    target.page = metadata.page;
