    target.sourcePageHeightPt = Number(
      scene?.page?.rect?.height ??
      scene?.page?.height ??
      scene?.page?.viewportHeight ??
      target.sourcePageHeightPt
    ) || null;
    target.sourceGeometryPdfPt = {
      p1: item.p1 && Number.isFinite(Number(item.p1.x)) && Number.isFinite(Number(item.p1.y))
        ? { x: Number(item.p1.x), y: Number(item.p1.y) }
        : null,
      p2: item.p2 && Number.isFinite(Number(item.p2.x)) && Number.isFinite(Number(item.p2.y))
        ? { x: Number(item.p2.x), y: Number(item.p2.y) }
        : null,
      bbox: item.sourceBBox || item.bbox || null
    };
    target.sourcePdfSha256 = metadata.sourcePdfSha256;
    target.pdfSha256 = metadata.sourcePdfSha256;
    target.sourceProfileHash = item.sourceProfileHash || metadata.sourceProfileHash || null;
    target.sourceSceneHash = metadata.sourceSceneHash;
    target.acceptedTransformId = null;
    target.acceptedTransformStatus = "not-established";
    target.transform_status = "not-established";
    target.importSessionId = metadata.importSessionId;
    target.qaRunId = metadata.qaRunId;
    target.source_kind = "pdf";
    target.object_status = "existing";
    target.work_action = "none";
    target.budget_trigger = "none";
    target.dbspec_projection = "excluded";
    target.mapping_state = "not_accepted";
    target.objectState = role;
    target.candidateOnly = true;
    target.reviewRequired = true;
    target.budgetExcluded = true;
    target.noBudgetTrigger = true;
    target.formalOutput = false;
    target.formalEstimate = false;
    target.productionReady = false;
