          openingStyleLabel: "木作房門",
          openingStyleSource: "svg-blocks3-index",
          blockMetadataId: "src_2880dd90993eb448",
          newExistingStatus: "existing",
          assetRel: "svg-blocks3/結構工具/既有門窗/木作房門/0570_uncategorized_木作房門_90房門_90x98mm.svg",
          assetUrl: "./svg-blocks3/b0570.svg",
