    (project.walls || []).forEach(function(w){ if (isUserGroupableObject(w)) { ids.walls.add(w.id); } });
    (project.structures || []).forEach(function(s){ if (isUserGroupableObject(s)) { ids.structures.add(s.id); } });
    (project.furniture || []).forEach(function(fn){ if (isUserGroupableObject(fn)) { ids.furniture.add(fn.id); } });
    (project.zones || []).forEach(function(z){ if (isUserGroupableObject(z)) { ids.zones.add(z.id); } });
    ids.total = ids.walls.size + ids.structures.size + ids.furniture.size + ids.zones.size;
